INSERT INTO study_course(code, title, category, summary, source, icon, sort_no) VALUES
('design-patterns',        '设计模式（大话设计模式）',              '编程基础', '从 6 大设计原则到 23 种 GoF 模式，用故事化例子讲清"为什么这样设计"。', '《大话设计模式》程杰',            'pattern', 1),
('java-basics',            'Java 语言基础入门',                     'Java',      'JDK/JVM、面向对象、集合、泛型、IO、多线程与 JDBC 的入门主线。',   '《Java 基础入门》第三版',        'coffee',  1),
('javaee-ssm',             'Java EE 企业级开发（Spring/Spring MVC/MyBatis）', 'Java', 'SSM 三框架整合与企业级 Web 开发主线，含请求处理、事务与动态 SQL。', '《Java EE 企业级应用开发教程》第二版', 'leaf', 2),
('mybatis',                'MyBatis 框架深入',                      'Java',      '映射文件、动态 SQL、关联映射、缓存与 Spring 整合的实现细节。', '《MyBatis 框架》',               'layers', 3),
('data-structures-c',      '数据结构（C 语言版）',                  '编程基础', '线性表到图、查找排序，含复杂度分析与 C 语言实现要点。',       '《数据结构（C 语言版）》第 2 版', 'tree',   2),
('cpp-programming',        'C++ 程序设计',                          '编程基础', '类与对象、继承多态、模板与 STL、异常与 C++11 新特性。',       '《C++ 程序设计》第 3 版',        'cpu',    3),
('python-programming',     'Python 程序设计',                       '编程基础', '语法、容器、函数式特性、模块包、文件异常与面向对象。',       '《Python 程序设计》第 4 版',     'snake',  4),
('linux-ops',              'Linux 运维基础',                        '运维',      '命令、权限、Shell 三剑客、软件包、服务、日志与排障。',           'Linux 运维讲义 + Shell 语料',    'terminal', 1),
('redis-design',            'Redis 设计与实现',                      '存储',      'SDS、字典、跳表、quicklist 到 RDB/AOF、哨兵与集群的源码级原理。', '《Redis 设计与实现》黄健宏',     'database', 1),
('redis-action',            'Redis 实战',                            '存储',      '五大类型用法、缓存与会话、事务管道、复制与分片的服务端实践。',   '《Redis 实战》',                 'database', 2),
('db-system-concepts',     '数据库系统概论',                        '数据库',    '关系模型、SQL、规范化、事务并发与恢复的理论主干。',             '《数据库系统概论》第 6 版',      'database', 1),
('mysql-intro',            'MySQL 数据库入门',                      '数据库',    '库表操作、索引执行计划、事务、备份还原与主从复制。',             '《MySQL 数据库入门》',           'database', 2),
('secondhand-book-platform','校园二手书交易平台实战',               '项目',      'SSM + MySQL 的二手书平台：需求、模块、表设计与业务流程。',       '《校园二手书交易平台》课程设计', 'cart',   1),
('xuexitong-protocol',     '学习通协议分析笔记',                    '项目',      '客户端-服务端交互、签名与防重放、抓包方法与合规红线。',         '《学习通协议》技术笔记',        'shield', 2),
('hcna-ensp',              '网络设备安装与调试（华为 eNSP）',        '网络',      'eNSP 环境、VLAN、RIP、OSPF、BGP 的实验步骤与配置速查。',         'eNSP 官方样例 + VLAN 实验讲义',  'network', 1),
('ai-perf-engineering',    'AI Systems 性能工程实验',               'AI',        'GPU/CUDA/vLLM/KV Cache 与并行策略、Benchmark 与压测观测。',    'AI Systems 性能工程实验逐字稿',  'chip',   1)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('design-patterns', 1, '第 1 章 设计模式概述', 'design-patterns:1:1', '设计模式的定义', '设计模式的定义：【补充】设计模式是在特定环境下对通用设计问题的可复用解决方案，包含问题上下文（Context）、被反复使用的约束与力量、解决方案（Solution）及其效果（Consequences）四要素，本质是前人经验的「套路化总结」，不是银弹，用错场景反而增加复杂度。', 'MEDIUM', 2, 1),
('design-patterns', 1, '第 1 章 设计模式概述', 'design-patterns:1:2', '从小菜看模式起源', '从小菜看模式起源：【补充】书中以「小菜」和「大鸟」对话串联知识点，用小菜重构工资系统、网吧计费系统、图片浏览器、电商平台等真实小项目，演示「烂代码 → 应用原则与模式 → 优雅代码」的重构过程，强调模式是重构的目标而非起点。', 'MEDIUM', 2, 2),
('design-patterns', 1, '第 1 章 设计模式概述', 'design-patterns:1:3', '软件为什么要可维护可扩展', '软件为什么要可维护可扩展：【补充】需求变化是常态，若把易变部分硬编码进核心逻辑，改一处牵动全身；设计模式通过封装变化点（把易变行为抽成独立类或接口），让新需求以「加代码」而非「改老代码」的方式满足，这正是 OCP 的工程价值。', 'MEDIUM', 2, 3),
('design-patterns', 1, '第 1 章 设计模式概述', 'design-patterns:1:4', '模式的学习层次', '模式的学习层次：【补充】第一层能说出定义，第二层能在给定场景中识别该用哪个模式，第三层能动手写出结构正确的 UML 类图与最小代码，第四层能在已有框架源码（Spring、JDK）中认出现实案例，面试主要考到第二、三层。', 'MEDIUM', 2, 4),
('design-patterns', 1, '第 1 章 设计模式概述', 'design-patterns:1:5', 'UML 类图基本符号', 'UML 类图基本符号：【补充】类用矩形分三层（类名、属性、方法），接口用 «interface» 标注；关联是实线箭头，依赖是虚线空心箭头，泛化（继承）是实线空心三角箭头，实现是虚线空心三角箭头，聚合是空心菱形（弱拥有），组合是实心菱形（强拥有、同生共死）。', 'MEDIUM', 2, 5),
('design-patterns', 1, '第 1 章 设计模式概述', 'design-patterns:1:6', '面向对象的三大特性', '面向对象的三大特性：【补充】封装隐藏内部实现只暴露接口，继承复用父类代码但破坏封装性，多态让不同子类对同一消息做出不同响应；设计模式大量利用「多态 + 组合」替代「继承 + 条件判断」，这是理解全部 23 种模式的底层视角。', 'MEDIUM', 2, 6),
('design-patterns', 1, '第 1 章 设计模式概述', 'design-patterns:1:7', '重构与模式的关系', '重构与模式的关系：【补充】重构是「在不改变外在行为的前提下改善代码内部结构」，模式是重构的目标形态；发现代码有重复分支、过长方法、类职责过多等坏味道时，优先考虑用原则与模式去消除它，而不是推倒重写。', 'MEDIUM', 2, 7),
('design-patterns', 2, '第 2 章 面向对象的设计原则', 'design-patterns:2:8', '单一职责原则 SRP', '单一职责原则 SRP：【补充】一个类应该只有一个引起它变化的原因；反例是既负责数据存取又负责界面渲染的 DAO+UI 混合类，一旦需求变更两处互相牵连。实现手段是把职责拆到不同类，由上层协调，判断标准是「有没有多于一个动机让你修改这个类」。', 'MEDIUM', 2, 8),
('design-patterns', 2, '第 2 章 面向对象的设计原则', 'design-patterns:2:9', '开放封闭原则 OCP', '开放封闭原则 OCP：【补充】软件实体应对扩展开放、对修改封闭；做法是把易变逻辑抽象成接口或抽象类，新增行为通过新增实现类完成（如新增「满减促销」只加一个 Promotion 实现类而不改结算主流程）。OCP 是模式体系的指导思想，工厂、策略、装饰器等都是它的落地工具。', 'MEDIUM', 2, 9),
('design-patterns', 2, '第 2 章 面向对象的设计原则', 'design-patterns:2:10', '依赖倒转原则 DIP', '依赖倒转原则 DIP：【补充】高层模块不应依赖低层模块，二者都应依赖抽象；抽象不应依赖细节，细节应依赖抽象。典型例子是主板 CPU 依赖「内存接口」而非金士顿内存条，换厂商无需改主板代码；Java 中体现为面向接口/抽象类编程，配合 IOC 容器做依赖注入。', 'MEDIUM', 2, 10),
('design-patterns', 2, '第 2 章 面向对象的设计原则', 'design-patterns:2:11', '里氏替换原则 LSP', '里氏替换原则 LSP：【补充】子类型必须能替换掉它们的父类型而不影响程序正确性；反例是「正方形继承长方形」导致 setWidth 语义失效，或子类抛父类未声明的异常、加强前置条件、削弱后置条件。违反 LSP 的继承会让基于父类的通用调用在换成子类后崩溃。', 'MEDIUM', 2, 11),
('design-patterns', 2, '第 2 章 面向对象的设计原则', 'design-patterns:2:12', '接口隔离原则 ISP', '接口隔离原则 ISP：【补充】客户端不应被迫依赖它用不到的方法；应把臃肿接口拆成多个小而专的接口（如把 Worker 拆成 Workable 与 Eatable，机器人只实现前者），避免实现类被迫写一堆空方法，Java 8 的 default 方法与角色接口是其现代延伸。', 'MEDIUM', 2, 12),
('design-patterns', 2, '第 2 章 面向对象的设计原则', 'design-patterns:2:13', '迪米特法则 LoD（最少知识原则）', '迪米特法则 LoD（最少知识原则）：【补充】一个对象应对其他对象保持最少的了解，只与直接朋友通信（本类成员、参数、返回值、创建的实例），不要跟「陌生人」耦合；典型反例是通过 a.getB().getC().doSomething() 跨三层调用，外观模式和中介者模式是 LoD 的系统级实现。', 'MEDIUM', 2, 13),
('design-patterns', 2, '第 2 章 面向对象的设计原则', 'design-patterns:2:14', '合成/聚合复用原则 CARP', '合成/聚合复用原则 CARP：【补充】优先使用对象组合（has-a）而非类继承（is-a）来获得复用，继承是静态的、编译期确定且破坏了封装，组合是动态的、运行期可替换；装饰器、策略、组合模式都遵循此原则，继承仅在真正符合 is-a 且不违反 LSP 时使用。', 'MEDIUM', 2, 14),
('design-patterns', 2, '第 2 章 面向对象的设计原则', 'design-patterns:2:15', '原则之间的优先级', '原则之间的优先级：【补充】实际项目中六原则不可能同时完美满足，常见取舍是：为性能牺牲部分 SRP（适度合并）、为进度牺牲部分 OCP（先硬编码后重构）、用 ISP 换实现便利；面试答题时应说明「权衡」而非教条，体现工程判断力。', 'MEDIUM', 2, 15),
('design-patterns', 3, '第 3 章 创建型模式（5 种）', 'design-patterns:3:16', '工厂方法模式 Factory Method', '工厂方法模式 Factory Method：【补充】定义一个用于创建对象的接口/抽象方法，让子类决定实例化哪一个类，把对象的实例化推迟到子类。结构包含 Product 抽象产品、ConcreteProduct 具体产品、Creator 抽象工厂、ConcreteCreator 具体工厂；JDBC 的 Connection.getMetaData() 与集合的 Iterator() 都是其变体。', 'MEDIUM', 2, 16),
('design-patterns', 3, '第 3 章 创建型模式（5 种）', 'design-patterns:3:17', '工厂方法的优点', '工厂方法的优点：【补充】符合 OCP，新增产品只需新增具体产品类和具体工厂类，无需改已有代码；符合 SRP，每个工厂只负责一类产品的创建逻辑；客户端只依赖抽象产品和抽象工厂，解耦彻底，是最常用的创建型模式。', 'MEDIUM', 2, 17),
('design-patterns', 3, '第 3 章 创建型模式（5 种）', 'design-patterns:3:18', '工厂方法的代价', '工厂方法的代价：【补充】每增加一个产品就要增加一个具体工厂，类数量成倍增长，简单场景用它显得啰嗦；抽象工厂正是为解决「一个工厂要创建一族相关产品」而生，选型时先问「是单个产品变还是整族产品变」。', 'MEDIUM', 2, 18),
('design-patterns', 3, '第 3 章 创建型模式（5 种）', 'design-patterns:3:19', '抽象工厂模式 Abstract Factory', '抽象工厂模式 Abstract Factory：【补充】提供一个创建「相关或相互依赖的对象族」的接口，而无需指定它们的具体类；结构是 AbstractFactory 声明多个 CreateXXX 方法，ConcreteFactory1/2 分别产出配套的产品 A1+B1 与 A2+B2，保证同族产品兼容（如 WinButton+WinTextBox 不会混出 MacButton）。', 'MEDIUM', 2, 19),
('design-patterns', 3, '第 3 章 创建型模式（5 种）', 'design-patterns:3:20', '抽象工厂 vs 工厂方法', '抽象工厂 vs 工厂方法：【补充】工厂方法只有一个抽象产品等级、靠子类造一种产品，抽象工厂有多个产品等级、一次造一族产品；抽象工厂常内部用工厂方法实现每个 Create 方法，可以说它是「工厂方法的组合」；新增产品种类（如再加 ScrollBar 接口）会破坏抽象工厂，这是它最大的缺点。', 'MEDIUM', 2, 20),
('design-patterns', 3, '第 3 章 创建型模式（5 种）', 'design-patterns:3:21', '单例模式 Singleton', '单例模式 Singleton：【补充】保证一个类仅有一个实例并提供全局访问点；要点是构造函数私有化、自身持有静态唯一实例、对外提供 getInstance()；常见写法有饿汉式（类加载即创建，线程安全但可能浪费）、懒汉式（首次访问才创建，需同步）。', 'MEDIUM', 2, 21),
('design-patterns', 3, '第 3 章 创建型模式（5 种）', 'design-patterns:3:22', '单例的线程安全与双检锁', '单例的线程安全与双检锁：【补充】多线程下懒汉式要用双重检查锁 Double-Checked Locking：先判空再加锁、加锁后再判空，且实例字段必须用 volatile 修饰以防指令重排导致拿到半初始化对象；更优方案是静态内部类 Holder 或枚举单例，既懒加载又天然线程安全。', 'MEDIUM', 2, 22),
('design-patterns', 3, '第 3 章 创建型模式（5 种）', 'design-patterns:3:23', '单例的适用与滥用', '单例的适用与滥用：【补充】适合线程池、缓存、日志对象、配置中心、设备驱动对象等「逻辑上只能有一个」的场景；滥用会把全局状态当垃圾桶，造成测试困难与隐藏耦合，现代实践中常用依赖注入容器的单例生命周期替代手写单例类。', 'MEDIUM', 2, 23),
('design-patterns', 3, '第 3 章 创建型模式（5 种）', 'design-patterns:3:24', '建造者模式 Builder', '建造者模式 Builder：【补充】将一个复杂对象的构建与表示分离，使同样的构建过程可以创建不同的表示；角色有 Builder 抽象建造者、ConcreteBuilder 具体建造者、Director 指挥者、Product 产品。经典例子是肯德基套餐制作：指挥者固定「先炸鸡再装盒」的流程，不同建造者产出不同口味的套餐。', 'MEDIUM', 2, 24),
('design-patterns', 3, '第 3 章 创建型模式（5 种）', 'design-patterns:3:25', '建造者 vs 抽象工厂', '建造者 vs 抽象工厂：【补充】抽象工厂关注「造哪一族产品」且通常一步到位返回成品，建造者关注「如何分步骤逐步组装一个复杂产品」并可由不同 Director 编排不同流程；阅读源码时 StringBuilder.append 链式调用、Guava 的 ImmutableMap.builder()、MyBatis 的 SqlSessionFactoryBean 都是 Builder 风格。', 'MEDIUM', 2, 25),
('design-patterns', 3, '第 3 章 创建型模式（5 种）', 'design-patterns:3:26', '原型模式 Prototype', '原型模式 Prototype：【补充】用原型实例指定创建对象的种类，并通过拷贝这些原型创建新对象；Java 中实现 Cloneable 接口重写 clone()（浅拷贝复制字段引用，深拷贝需递归 clone 引用对象）；适合创建成本大或需要保存历史快照的场景，克隆比 new 更便宜时用它，注意原型注册表的管理。', 'MEDIUM', 2, 26),
('design-patterns', 4, '第 4 章 结构型模式（7 种）', 'design-patterns:4:27', '适配器模式 Adapter', '适配器模式 Adapter：【补充】将一个类的接口转换成客户希望的另一个接口，使原本接口不兼容的类可以一起工作；类适配器用多重继承（Java 不适用，多用对象适配器——持有 Adaptee 引用并实现 Target 接口）。实例：把老旧的 MP3 播放器适配到新接口，或 JDK 中 Arrays.asList() 把数组适配成 List。', 'MEDIUM', 2, 27),
('design-patterns', 4, '第 4 章 结构型模式（7 种）', 'design-patterns:4:28', '适配器 vs 装饰器 vs 代理', '适配器 vs 装饰器 vs 代理：【补充】三者都包装对象，但意图不同：适配器改变接口（接口转换）、装饰器增强职责且接口不变（可叠加多层）、代理控制访问（权限、延迟、远程）；面试常考「为什么不只用继承」——因为适配器要适配多个不相关类且符合组合复用原则。', 'MEDIUM', 2, 28),
('design-patterns', 4, '第 4 章 结构型模式（7 种）', 'design-patterns:4:29', '桥接模式 Bridge', '桥接模式 Bridge：【补充】将抽象部分与实现部分分离，使二者可独立变化；结构是 Abstraction 聚合 Implementor，两个继承体系可各自扩展（如形状 × 颜色，新增形状不影响颜色维度）。JDBC 的 DriverManager 与驱动、日志框架 Log4j 的分层都是桥接思想，它比多层继承更省类爆炸。', 'MEDIUM', 2, 29),
('design-patterns', 4, '第 4 章 结构型模式（7 种）', 'design-patterns:4:30', '组合模式 Composite', '组合模式 Composite：【补充】将对象组合成树形结构以表示「部分-整体」层次，使客户端对单个对象和组合对象的使用具有一致性；角色有 Component 抽象构件、Leaf 叶子、Composite 容器（持子节点集合），经典案例是杀毒软件遍历文件夹杀毒、公司组织架构图与文件系统目录树。', 'MEDIUM', 2, 30),
('design-patterns', 4, '第 4 章 结构型模式（7 种）', 'design-patterns:4:31', '组合模式的透明式 vs 安全式', '组合模式的透明式 vs 安全式：【补充】透明式把 add/remove/getChild 声明在 Component 上，客户端统一调用但叶子节点会有空实现或抛异常；安全式只在 Composite 上声明子节点管理方法，叶子不污染接口但客户端需区分类型。JDK 的 Swing 组件树、XML DOM 解析普遍采用组合模式。', 'MEDIUM', 2, 31),
('design-patterns', 4, '第 4 章 结构型模式（7 种）', 'design-patterns:4:32', '装饰器模式 Decorator', '装饰器模式 Decorator：【补充】动态地给对象添加一些额外职责，比继承更灵活；结构是 ConcreteComponent、Decorator 抽象装饰器（实现同一接口且聚合 Component）、ConcreteDecoratorA/B 层层包裹。Java IO 的 new BufferedReader(new InputStreamReader(new FileInputStream(f))) 是最经典例子，可无限嵌套叠加功能。', 'MEDIUM', 2, 32),
('design-patterns', 4, '第 4 章 结构型模式（7 种）', 'design-patterns:4:33', '装饰器的代价', '装饰器的代价：【补充】会产生大量细小类，层数多时调试与理解成本高，且装饰顺序可能影响结果（如先加密再压缩 vs 先压缩再加密）；它与 AOP、函数式编程的组合子思想同源，实际项目可用动态代理简化装饰器样板代码。', 'MEDIUM', 2, 33),
('design-patterns', 4, '第 4 章 结构型模式（7 种）', 'design-patterns:4:34', '外观模式 Facade', '外观模式 Facade：【补充】为子系统中的一组接口提供一个一致的高层接口，定义一个更易用的入口，降低客户端与子系统的耦合；例如一键「装机」Facade 封装 CPU、内存、硬盘多个子模块的启动顺序。外观只是「简化入口」，并不封装子系统，子系统仍可被直接访问，微服务网关也体现了这一思想。', 'MEDIUM', 2, 34),
('design-patterns', 4, '第 4 章 结构型模式（7 种）', 'design-patterns:4:35', '享元模式 Flyweight', '享元模式 Flyweight：【补充】运用共享技术高效支持大量细粒度对象；把对象状态分为内部状态（可共享、不变，如字符 ''a'' 的 Unicode）与外部状态（不可共享、随环境变，如字体大小），工厂缓存共享对象池。Java 的 Integer.valueOf(-128~127) 缓存、String 常量池、数据库连接池都是享元思想的产物。', 'MEDIUM', 2, 35),
('design-patterns', 4, '第 4 章 结构型模式（7 种）', 'design-patterns:4:36', '代理模式 Proxy', '代理模式 Proxy：【补充】为其他对象提供一种代理以控制对这个对象的访问；代理类与真实主题实现同一接口，持有 RealSubject 引用，在调用前后插入额外逻辑。常见用途：远程代理（RPC stub）、虚拟代理（大图延迟加载）、保护代理（权限校验）、Spring AOP 的动态代理（JDK 接口代理 / CGLIB 子类代理）。', 'MEDIUM', 2, 36),
('design-patterns', 4, '第 4 章 结构型模式（7 种）', 'design-patterns:4:37', '静态代理 vs 动态代理', '静态代理 vs 动态代理：【补充】静态代理需手写代理类，一个接口一个代理，代码冗余；动态代理在运行期生成代理对象，JDK Proxy 基于接口实现 InvocationHandler，CGLIB 基于继承生成子类（不能代理 final 类），Spring 默认优先 JDK 动态代理，无接口时回退 CGLIB。', 'MEDIUM', 2, 37),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:38', '观察者模式 Observer', '观察者模式 Observer：【补充】定义对象间一对多的依赖，当一个对象状态改变时所有依赖者自动收到通知并更新；角色有 Subject（注册/移除/通知）、Observer（update）、ConcreteSubject、ConcreteObserver。Java 可用 java.util.Observable（已废弃）或自己维护监听器列表，事件机制、MVVM 数据绑定、消息队列消费端都是观察者思想。', 'MEDIUM', 2, 38),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:39', '观察者 vs 发布订阅', '观察者 vs 发布订阅：【补充】观察者是主题直接调用观察者方法（强耦合于主题，同步居多），发布订阅引入事件中心/消息中间件（Broker）做解耦，发布者与订阅者互不知晓，可异步、可过滤、可跨进程；Redis Pub/Sub、Kafka、Guava EventBus 属于后者，面试需说明二者「耦合度与中间人」的差别。', 'MEDIUM', 2, 39),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:40', '策略模式 Strategy', '策略模式 Strategy：【补充】定义一系列算法并把每个算法封装起来，使它们可互相替换，算法的变化不影响使用算法的客户；角色有 Context（持有 Strategy）、Strategy 接口、ConcreteStrategyA/B/C。商场打折（正常/打折/满减）切换不同策略即典型案例，符合 OCP，消除大量 if-else/switch 分支。', 'MEDIUM', 2, 40),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:41', '策略模式 vs 状态模式', '策略模式 vs 状态模式：【补充】策略模式强调「多个平行算法可互换、客户端主动选择策略」，策略之间无状态转移关系；状态模式强调「对象内部状态改变时行为随之改变，状态之间有迁移规则」，由状态对象自己切换下一状态（如订单 待支付→已支付→已发货）。二者代码结构几乎一样（都是 Context + 接口 + 多实现），区别在语义与谁触发切换。', 'MEDIUM', 2, 41),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:42', '状态模式 State', '状态模式 State：【补充】允许对象在内部状态改变时改变它的行为，看起来好像修改了它的类；角色有 Context、State 接口、ConcreteState。好处是把各状态的局部行为与转移逻辑分散到小类中，避免巨型 switch，符合 SRP 与 OCP；缺点是增加类数量，状态极少的小逻辑用它反而过度设计。', 'MEDIUM', 2, 42),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:43', '命令模式 Command', '命令模式 Command：【补充】将请求封装为对象，从而可用不同请求对客户参数化，支持请求排队、记录日志、撤销/重做；角色有 Command（execute/undo）、ConcreteCommand（持有 Receiver）、Invoker（调用命令）、Receiver（真正干活的人）。遥控器按钮绑定命令、事务型数据库、线程池 Runnable 都是命令模式，GUI 撤销栈是其杀手级应用。', 'MEDIUM', 2, 43),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:44', '命令模式撤销的实现要点', '命令模式撤销的实现要点：【补充】undo 需要命令对象在 execute 时记录足够的状态（或采用备忘录保存快照），多次撤销要维护命令历史栈；也可用「反向命令」方式实现 redo，注意命令对象本身要轻量，避免把大对象复制进栈。', 'MEDIUM', 2, 44),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:45', '职责链模式 Chain of Responsibility：【补充】使多个对象都', '职责链模式 Chain of Responsibility：【补充】使多个对象都有机会处理请求，从而避免请求发送者与接收者的耦合，把这些对象连成一条链并沿链传递，直到有对象处理它；角色有 Handler（持有 next）、ConcreteHandler。Java Web 的 Filter 过滤器链、Netty 的 Pipeline、审批流逐级上报都是其应用，优点是增删处理者灵活，风险是请求可能无人处理且链路调试困难。', 'MEDIUM', 2, 45),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:46', '迭代器模式 Iterator', '迭代器模式 Iterator：【补充】提供一种方法顺序访问聚合对象中的各个元素，而不暴露其内部表示；角色有 Aggregate、Iterator（hasNext/next）、ConcreteAggregate。几乎所有语言的标准库都已内建迭代器（Java Iterator/ListIterator、C++ STL iterator），现代开发中很少手写，但它是理解集合框架与 foreach 语法糖的钥匙。', 'MEDIUM', 2, 46),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:47', '中介者模式 Mediator', '中介者模式 Mediator：【补充】用一个中介对象封装一系列对象的交互，使各对象不需显式相互引用，耦合松散且可独立改变交互；角色有 Mediator、Colleague。反例是同事对象两两互相调用形成网状耦合，改造后都只跟中介者说话；MVC 中的 Controller 就是中介者，聊天室服务器转发消息、机场调度塔台也是现实类比。', 'MEDIUM', 2, 47),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:48', '备忘录模式 Memento', '备忘录模式 Memento：【补充】在不破坏封装性的前提下捕获一个对象的内部状态，并在对象之外保存该状态，以便日后恢复；角色有 Originator（生成/恢复快照）、Memento（只读状态载体）、Caretaker（保管但不修改）。游戏存档、编辑器撤销、数据库事务回滚都用到它，注意 Memento 应对 Caretaker 只读，避免破坏 Originator 的封装。', 'MEDIUM', 2, 48),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:49', '访问者模式 Visitor', '访问者模式 Visitor：【补充】表示一个作用于某对象结构中各元素的操作，使你可以在不改变各元素的类的前提下定义作用于这些元素的新操作；角色有 Visitor（visit(ConcreteElement)）、Element（accept(Visitor)），典型应用是编译器 AST 遍历、报表导出多种格式。代价是新增元素类会迫使所有 Visitor 改动，因此只适合「元素类稳定、操作频繁新增」的场景。', 'MEDIUM', 2, 49),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:50', '模板方法模式 Template Method', '模板方法模式 Template Method：【补充】在抽象类中定义算法骨架（把某些步骤延迟到子类实现），子类可以不改变算法结构就重定义某些步骤；用 final 修饰模板方法防止篡改，用钩子方法 Hook 提供可选扩展点。Java 的 HttpServlet.doGet/doPost、JdbcTemplate、Spring 的 TransactionTemplate 都是模板方法，继承+多态的经典协作。', 'MEDIUM', 2, 50),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:51', '模板方法 vs 策略模式', '模板方法 vs 策略模式：【补充】模板方法用继承在编译期固定算法骨架、只替换个别步骤；策略用组合在运行期整体替换算法，更灵活且可随时切换。二者常混合使用：策略负责可变算法，模板方法负责组织调用时序，Spring 事务管理是典型融合。', 'MEDIUM', 2, 51),
('design-patterns', 5, '第 5 章 行为型模式（11 种）', 'design-patterns:5:52', '解释器模式 Interpreter', '解释器模式 Interpreter：【补充】给定一个语言，定义它的文法的一种表示，并定义一个解释器来解释语言中的句子；角色有 AbstractExpression、TerminalExpression、NonterminalExpression、Context。适合规则引擎、正则表达式、SQL 解析、简单 DSL，但文法复杂时类膨胀严重、性能差，实际项目多用现成解析框架（ANTLR）而非手写。', 'MEDIUM', 2, 52),
('design-patterns', 6, '第 6 章 模式组合与架构级应用', 'design-patterns:6:53', 'MVC 模式的角色分工', 'MVC 模式的角色分工：【补充】Model 负责业务数据与规则（Observable），View 负责展示（Observer，订阅 Model 变化刷新），Controller 接收用户输入并调度 Model 与 View，三者构成观察者 + 策略 + 组合的复合应用；Web 开发的 Spring MVC、前端 React/Vue 的状态管理都是其演化形态。', 'MEDIUM', 2, 53),
('design-patterns', 6, '第 6 章 模式组合与架构级应用', 'design-patterns:6:54', '工厂 + 策略 + 装饰的经典组合', '工厂 + 策略 + 装饰的经典组合：【补充】电商结算系统中，策略模式封装各类促销算法（满减、折扣、赠品），工厂模式按配置创建对应策略对象，装饰器模式在基础结算外加叠优惠券、积分抵扣、运费计算；三者在 OCP 指导下协同，避免了「if 促销类型 else」的巨石分支。', 'EASY', 2, 54),
('design-patterns', 6, '第 6 章 模式组合与架构级应用', 'design-patterns:6:55', '抽象工厂 + 反射 + 配置文件', '抽象工厂 + 反射 + 配置文件：【补充】传统抽象工厂每新增一族产品都要改工厂代码，结合反射（Class.forName 读取配置项）可实现「数据访问层可切换 SQL Server / Oracle 而不改代码」，这是早期 .NET PetShop 与 Java 开源框架常用的factory配置技巧，Spring 的 IOC 容器把它进一步自动化。', 'MEDIUM', 2, 55),
('design-patterns', 6, '第 6 章 模式组合与架构级应用', 'design-patterns:6:56', '分层架构中的模式落点', '分层架构中的模式落点：【补充】表现层用外观 + 控制器（MVC），业务层用策略 + 状态 + 职责链，领域层用组合 + 装饰，基础设施层用适配器（对接第三方 SDK）+ 代理（缓存/权限），数据层用工厂方法 + 抽象工厂；模式与分层不是绑定关系，但每层总有几个最契合的模式。', 'EASY', 2, 56),
('design-patterns', 6, '第 6 章 模式组合与架构级应用', 'design-patterns:6:57', 'JDK 与 Spring 中的模式速查', 'JDK 与 Spring 中的模式速查：【补充】JDK 中 Calendar.getInstance() 是工厂方法，Runtime.getRuntime() 是单例，Collections.unmodifiableList() 是装饰器，java.lang.reflect.Proxy 是代理，Comparable/Comparator 是策略，PropertyChangeSupport 是观察者；Spring 中 BeanFactory 是工厂，ApplicationContext 单例作用域，AOP 是代理，JdbcTemplate 是模板方法，@EventListener 是观察者，面试常让举例佐证。', 'MEDIUM', 2, 57),
('design-patterns', 6, '第 6 章 模式组合与架构级应用', 'design-patterns:6:58', '模式不是越多越好', '模式不是越多越好：【补充】过度设计是初学者最容易犯的病：为小需求硬套模式会导致类数量爆炸、可读性下降；经验法则是「三次法则」——第一次直接写，第二次复制容忍，第三次再考虑抽象为模式，配合重构逐步演进比一开始追求完美架构更稳。', 'MEDIUM', 2, 58),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:59', '高频简答', '高频简答：什么是设计模式：【补充】应答模板 = 定义（可复用的通用设计方案）+ 背景（1994 年 GoF《Design Patterns》收录 23 种）+ 目的（复用经验、统一沟通词汇、提高可维护性）+ 辩证（模式有适用场景，误用会增加复杂度），控制在 90 秒内说完。', 'MEDIUM', 4, 59),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:60', '高频简答', '高频简答：三大类模式各举两例并说用途：【补充】创建型举工厂方法（延迟实例化到子类）与单例（全局唯一实例）；结构型举适配器（接口转换）与装饰器（动态增强）；行为型举观察者（一对多通知）与策略（算法族互换），每例补一句真实场景即可得分。', 'MEDIUM', 4, 60),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:61', '高频代码', '高频代码：手写单例（双检锁）：【补充】要点三件套：私有构造、volatile 静态实例、双重判空 + synchronized 代码块；补一句「更推荐静态内部类或枚举写法」显示深度；若能顺带说明序列化攻击与 readResolve 防护则加分。', 'MEDIUM', 4, 61),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:62', '高频代码', '高频代码：手写策略模式：【补充】先定义 Strategy 接口声明算法方法，再写两个实现类，最后 Context 持有接口引用并提供 setStrategy；答题时强调「符合 OCP、新增算法不改老代码、消除条件分支」，并指出可用 Map<String,Strategy> 注册表替代工厂。', 'MEDIUM', 4, 62),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:63', '高频代码', '高频代码：手写观察者模式：【补充】Subject 内部维护 List<Observer>，提供 attach/detach/notify；notify 遍历调用 update；说明 Java 自带 Observable 已废弃、可改用 PropertyChangeSupport 或 EventBus；若追问异步，答「notify 丢入线程池或 MQ 即演变为发布订阅」。', 'MEDIUM', 4, 63),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:64', '高频代码', '高频代码：手写装饰器模式：【补充】定义 Component 接口，ConcreteComponent 实现之，Decorator 实现同一接口并聚合 Component，ConcreteDecorator 在 super.operation() 前后加逻辑；现场举例 Java IO 流的三层包装，证明「接口不变、职责叠加」。', 'MEDIUM', 4, 64),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:65', '高频画图', '高频画图：工厂方法 UML 类图：【补充】画四个框 Product、ConcreteProduct、Creator（含 factoryMethod() 返回 Product）、ConcreteCreator，Creator 与 Product 之间是依赖虚线空心箭头，ConcreteCreator 与 Creator、ConcreteProduct 与 Product 分别是实现与泛化关系；注明「箭头方向」是评分点。', 'MEDIUM', 4, 65),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:66', '高频画图', '高频画图：装饰器 UML 类图：【补充】Component 接口在上，ConcreteComponent 与 Decorator 实现它，Decorator 用聚合空心菱形指向 Component，ConcreteDecorator 继承 Decorator；务必画出「Decorator 既实现 Component 又包含 Component」的双重身份，这是得分的关键差异点。', 'MEDIUM', 4, 66),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:67', '高频辨析', '高频辨析：继承 vs 组合：【补充】一句话记忆：继承是 is-a、编译期确定、白盒复用、破坏封装；组合是 has-a、运行期可替换、黑盒复用；设计原则要求优先组合，但真正稳定的 is-a 关系（如 Animal-Dog）用继承更自然，回答要给场景而非绝对化。', 'MEDIUM', 4, 67),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:68', '高频辨析', '高频辨析：重载 vs 重写：【补充】重载是编译期多态，同类中同名不同参；重写是运行期多态，子类覆盖父类同签名方法，受 LSP 约束；设计模式中「模板方法 + 钩子方法」「策略的多实现」分别利用了这两点，是常见的连环追问。', 'MEDIUM', 4, 68),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:69', '项目经验表达模板', '项目经验表达模板：【补充】用 STAR 结构讲述一次重构：S 老代码充满 if-else 促销分支导致每次上新就改老逻辑还出 bug；T 目标是让新增促销不动老代码；A 引入策略接口 + 工厂注册 + 配置化；R 需求交付从 2 天降到半天、回归缺陷归零，最后补一句「模式的价值在于封装变化点」。', 'MEDIUM', 2, 69),
('design-patterns', 7, '第 7 章 面试与实战', 'design-patterns:7:70', '上机实验建议清单', '上机实验建议清单：【补充】至少亲手实现五个可运行 demo：单例（对比四种写法线程安全性）、工厂方法 + 反射配置、策略 + 工厂做薪资计算、装饰器模拟 Java IO、观察者做事件通知，每个 demo 都要附 UML 类图与「适用场景 / 优缺点」两行总结，直接沉淀为面试作品。', 'MEDIUM', 2, 70)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('redis-design', 1, '第 1 章 SDS 简单动态字符串', 'redis-design:1:1', 'SDS 结构定义', 'SDS 结构定义：sds.h 中 sdshdr 由 len（已用长度）、alloc（分配字节数）、flags（类型，如 SDS_TYPE_5/8/16/32/64）与柔性数组 buf[] 组成；sdshdr8/16/32/64 按最大长度选最小头，长字符串才用 sdshdr64，节省内存。', 'MEDIUM', 2, 1),
('redis-design', 1, '第 1 章 SDS 简单动态字符串', 'redis-design:1:2', 'O(1) 获取长度', 'O(1) 获取长度：因 len 字段直接记录长度，strlen 级别复杂度；而 C 字符串需遍历到 \0，复杂度 O(N)，且二进制不安全。', 'MEDIUM', 2, 2),
('redis-design', 1, '第 1 章 SDS 简单动态字符串', 'redis-design:1:3', '杜绝缓冲区溢出', '杜绝缓冲区溢出：拼接前调用 sdsMakeRoomFor 检查空间并自动扩容，避免 C 字符串 strcat 的经典越界问题；sdsRemoveFreeSpace 可回收多余预留空间。', 'MEDIUM', 2, 3),
('redis-design', 1, '第 1 章 SDS 简单动态字符串', 'redis-design:1:4', '空间预分配策略', '空间预分配策略：修改后 len < 1MB 时分配 2 倍大小（alloc = 2×len）；len ≥ 1MB 时额外多留 1MB，降低连续 append 的 realloc 次数。', 'MEDIUM', 2, 4),
('redis-design', 1, '第 1 章 SDS 简单动态字符串', 'redis-design:1:5', '惰性空间释放', '惰性空间释放：缩短字符串时不立即缩容，只更新 len 并把空闲字节留给后续 append 使用，避免内存重分配开销。', 'MEDIUM', 2, 5),
('redis-design', 1, '第 1 章 SDS 简单动态字符串', 'redis-design:1:6', '二进制安全', '二进制安全：以 len 而非 \0 判定结尾，buf 内可存图片、序列化对象等任意二进制数据，sdslen 与 strlen 语义不同。', 'MEDIUM', 2, 6),
('redis-design', 1, '第 1 章 SDS 简单动态字符串', 'redis-design:1:7', '与 C 字符串兼容', '与 C 字符串兼容：buf 末尾仍保留 \0，可直接复用 printf 等 C 库函数打印 SDS 内容。', 'MEDIUM', 2, 7),
('redis-design', 1, '第 1 章 SDS 简单动态字符串', 'redis-design:1:8', '编码映射', '编码映射：OBJ_ENCODING_EMBSTR 短字符串（≤44 字节）把 robj 与 sdshdr 放在同一次 malloc 的连续内存（embstr），减少内存碎片与两次分配开销【补充】。', 'MEDIUM', 2, 8),
('redis-design', 2, '第 2 章 双端链表', 'redis-design:2:9', 'listNode 结构', 'listNode 结构：adlist.h 中节点含 prev、next 指针与 void *value，本身不持有头尾信息。', 'MEDIUM', 2, 9),
('redis-design', 2, '第 2 章 双端链表', 'redis-design:2:10', 'list 结构', 'list 结构：封装 head、tail、len 以及 dup/free/match 三个函数指针，实现多态复制、释放与查找比较。', 'MEDIUM', 2, 10),
('redis-design', 2, '第 2 章 双端链表', 'redis-design:2:11', '无环双端链表', '无环双端链表：表头 prev 与表尾 next 均指向 NULL，插入删除边界判断简单，listLength O(1)。', 'MEDIUM', 2, 11),
('redis-design', 2, '第 2 章 双端链表', 'redis-design:2:12', '迭代器', '迭代器：listGetIterator 创建带 direction 的迭代器，支持 AL_START_HEAD / AL_START_TAIL 双向遍历，用于 listTypeNext 等遍历场景。', 'MEDIUM', 2, 12),
('redis-design', 2, '第 2 章 双端链表', 'redis-design:2:13', '应用位置', '应用位置：列表键底层（Redis 2.x 为 ziplist+linkedlist，3.2 后改为 quicklist）、发布订阅频道字典值、慢查询日志记录、监视器客户端列表等【补充】。', 'MEDIUM', 2, 13),
('redis-design', 2, '第 2 章 双端链表', 'redis-design:2:14', '链表的局限', '链表的局限：节点的内存分散、额外指针开销大，因此 Redis 3.2 后用 quicklist（ziplist/listpack 组成的链表）替代纯双端链表作为列表底层。', 'MEDIUM', 2, 14),
('redis-design', 3, '第 3 章 字典 dict 与渐进式 rehash', 'redis-design:3:15', '哈希表结构', '哈希表结构：dict 由两个 dictht 哈希表、rehashidx、iterators 计数组成；每个 dicthht 含 table 数组、size（2 的幂）、sizemask（size-1）、used（已有节点数）。', 'MEDIUM', 2, 15),
('redis-design', 3, '第 3 章 字典 dict 与渐进式 rehash', 'redis-design:3:16', '链地址法解决冲突', '链地址法解决冲突：桶内用 dictEntry 单链表串接，新节点插入表头（头插法），时间 O(1)。', 'MEDIUM', 2, 16),
('redis-design', 3, '第 3 章 字典 dict 与渐进式 rehash', 'redis-design:3:17', 'MurmurHash2 + SipHash', 'MurmurHash2 + SipHash：键哈希使用 murmurhash2，配合随机种子（hashseed）防哈希攻击；SipHash 用于防止 HashDoS（Redis 4.0 起 hash 字段类型）【补充】。', 'MEDIUM', 2, 17),
('redis-design', 3, '第 3 章 字典 dict 与渐进式 rehash', 'redis-design:3:18', '负载因子与扩容阈值', '负载因子与扩容阈值：当 used/size ≥ 1（无 BGSAVE）或 ≥ 5（有 BGSAVE/BGREWRITEAOF）时触发扩容；收缩在 used/size < 0.1 时进行。', 'MEDIUM', 2, 18),
('redis-design', 3, '第 3 章 字典 dict 与渐进式 rehash', 'redis-design:3:19', '渐进式 rehash 机制', '渐进式 rehash 机制：设置 rehashidx = -1→0 标记开始，之后每次增删改查、以及定时任务 _dictRehashStep 各迁移一个桶，避免一次性迁移阻塞主线程；期间新写只写 ht[1]，查找需查两张表。', 'MEDIUM', 2, 19),
('redis-design', 3, '第 3 章 字典 dict 与渐进式 rehash', 'redis-design:3:20', 'dictRehash 批量迁移', 'dictRehash 批量迁移：dictRehash(d, n) 一次最多迁移 n 个桶，但会跳过空桶直到遇到非空桶或完成 n 次有效迁移，empty_visits = n*10 限制空桶扫描。', 'MEDIUM', 2, 20),
('redis-design', 3, '第 3 章 字典 dict 与渐进式 rehash', 'redis-design:3:21', 'rehash 期间的规则', 'rehash 期间的规则：禁止在 rehash 期间做 rehash、禁止 ht[0] 与 ht[1] 的键值交叉，rehash 完成后释放 ht[0] 并将 ht[1] 置为 ht[0]、rehashidx 复位 -1。', 'MEDIUM', 2, 21),
('redis-design', 3, '第 3 章 字典 dict 与渐进式 rehash', 'redis-design:3:22', '定时任务触发', '定时任务触发：serverCron 每 100ms 执行 incrementallyRehash，保证空闲时也持续推进，避免长期停留在中间状态。', 'MEDIUM', 2, 22),
('redis-design', 3, '第 3 章 字典 dict 与渐进式 rehash', 'redis-design:3:23', '字典应用', '字典应用：全局键空间（db->dict）、过期字典（db->expires）、哈希键底层（元素少时 listpack）、pubsub 频道表、数据库字典等【补充】。', 'MEDIUM', 2, 23),
('redis-design', 4, '第 4 章 跳跃表 skiplist', 'redis-design:4:24', '跳表结构', '跳表结构：zskiplist 含头尾指针、层数 level、长度 length；zskiplistNode 含 robj *obj、double score、backward 后退指针、以及 zskiplistLevel {forward, span} 数组。', 'MEDIUM', 2, 24),
('redis-design', 4, '第 4 章 跳跃表 skiplist', 'redis-design:4:25', '多层索引加速', '多层索引加速：节点随机生成 1—32 层（ZSKIPLIST_MAXLEVEL=32，概率因子 1/4），查找从最高层向低层推进，平均 O(logN)，最差 O(N)。', 'MEDIUM', 2, 25),
('redis-design', 4, '第 4 章 跳跃表 skiplist', 'redis-design:4:26', '范围查询优势', '范围查询优势：相比平衡树实现简单且无需旋转；zslFirstInRange / zslLastInRange 支持 ZRANGEBYSCORE 高效区间定位。', 'MEDIUM', 2, 26),
('redis-design', 4, '第 4 章 跳跃表 skiplist', 'redis-design:4:27', '有序集合底层', '有序集合底层：元素少且短时用 listpack（7.0 前 ziplist）编码，超过 zset-max-listpack-entries（默认 128）或 zset-max-listpack-value（默认 64 字节）转为 skiplist+dict 组合。', 'MEDIUM', 2, 27),
('redis-design', 4, '第 4 章 跳跃表 skiplist', 'redis-design:4:28', '字典与跳表双结构', '字典与跳表双结构：dict 提供 O(1) 的 ZSCORE 单点查询，skiplist 负责排序与范围扫描，二者共享同一份元素引用。', 'MEDIUM', 2, 28),
('redis-design', 4, '第 4 章 跳跃表 skiplist', 'redis-design:4:29', '跨度 span 字段', '跨度 span 字段：每层 forward 指针记录跨越的节点数，用于计算排名 ZRANK，实现 O(logN) 的 rank 计算。', 'MEDIUM', 2, 29),
('redis-design', 4, '第 4 章 跳跃表 skiplist', 'redis-design:4:30', '后退指针 backward', '后退指针 backward：仅最底层保留反向指针，支撑 ZREVRANGE 逆序遍历。', 'MEDIUM', 2, 30),
('redis-design', 4, '第 4 章 跳跃表 skiplist', 'redis-design:4:31', '随机层数算法', '随机层数算法：幂次定律随机，while (random() < ZSKIPLIST_P && level < MAXLEVEL) level++，保证高层节点稀疏、查询效率稳定。', 'MEDIUM', 2, 31),
('redis-design', 5, '第 5 章 整数集合 intset', 'redis-design:5:32', 'intset 结构', 'intset 结构：typedef struct { uint32_t encoding; uint32_t length; int8_t contents[]; }，encoding 取 INTSET_ENC_INT16/INT32/64，contents 按值从小到大有序存储。', 'MEDIUM', 2, 32),
('redis-design', 5, '第 5 章 整数集合 intset', 'redis-design:5:33', '升级机制', '升级机制：插入超出当前编码范围的整数时执行 intsetUpgradeAndAdd，整体升级为更大编码并把所有元素转换为同一类型，避免数据截断。', 'MEDIUM', 2, 33),
('redis-design', 5, '第 5 章 整数集合 intset', 'redis-design:5:34', '只升不降', '只升不降：删除小值后不会回退到更小编码，编码一旦升级永久保持，简化实现。', 'MEDIUM', 2, 34),
('redis-design', 5, '第 5 章 整数集合 intset', 'redis-design:5:35', '二分查找', '二分查找：intsetSearch 使用二分定位值，O(logN) 查找；插入/删除为 O(N) 内存搬移。', 'MEDIUM', 2, 35),
('redis-design', 5, '第 5 章 整数集合 intset', 'redis-design:5:36', '编码选择优化', '编码选择优化：contents 数组声明为 int8_t 但实际按 encoding 解释，配合 memmove 完成插入删除位移。', 'MEDIUM', 2, 36),
('redis-design', 5, '第 5 章 整数集合 intset', 'redis-design:5:37', '集合键编码切换', '集合键编码切换：元素均为整数且数量 ≤ set-max-intset-entries（默认 512）时使用 intset，否则转为 hashtable/listpack（7.0 起 set 也可 listpack）【补充】。', 'MEDIUM', 2, 37),
('redis-design', 6, '第 6 章 压缩列表 ziplist 与 listpack', 'redis-design:6:38', 'ziplist 布局', 'ziplist 布局：<zlbytes><zltail><zllen><entry...><zlend>，entry 由 prevlen（前驱长度，1 或 5 字节）、encoding、data 组成，zlbytes/zltail 支持 O(1) 定位尾部。', 'MEDIUM', 2, 38),
('redis-design', 6, '第 6 章 压缩列表 ziplist 与 listpack', 'redis-design:6:39', 'entry 级联更新', 'entry 级联更新：当 prevlen 从 1 字节变为 5 字节（或反向收缩）时可能触发连锁扩展/收缩，最坏 O(N²)，是 ziplist 的主要性能隐患。', 'MEDIUM', 2, 39),
('redis-design', 6, '第 6 章 压缩列表 ziplist 与 listpack', 'redis-design:6:40', 'listpack 改进', 'listpack 改进：Redis 7.0 以 listpack 取代 ziplist，每个 entry 自带 totallen 消除级联更新，listpack 由 <totallistpacklen><num-elements><entry...><lend> 组成。', 'MEDIUM', 2, 40),
('redis-design', 6, '第 6 章 压缩列表 ziplist 与 listpack', 'redis-design:6:41', '哈希/列表/有序集合编码', '哈希/列表/有序集合编码：hash-max-listpack-entries（默认 128）、hash-max-listpack-value（默认 64 字节）、list 的 quicklist 节点内即 listpack/ziplist。', 'MEDIUM', 2, 41),
('redis-design', 6, '第 6 章 压缩列表 ziplist 与 listpack', 'redis-design:6:42', 'quicklist 快速列表', 'quicklist 快速列表：双向链表 + 每节点一个 ziplist/listpack，list-compress-depth 控制两端压缩节点数；节点大小由 list-max-listpack-size（负值 -1~-5 指定每节点 KB，正值指定元素个数）控制。', 'MEDIUM', 2, 42),
('redis-design', 6, '第 6 章 压缩列表 ziplist 与 listpack', 'redis-design:6:43', '内存与 CPU 权衡', '内存与 CPU 权衡：小节点省内存但增加指针与遍历开销，大节点减少指针开销但 realloc 成本上升；quicklist 用 LZF 压缩中间节点平衡两者。', 'MEDIUM', 2, 43),
('redis-design', 6, '第 6 章 压缩列表 ziplist 与 listpack', 'redis-design:6:44', 'ziplist 遍历接口', 'ziplist 遍历接口：ziplistIndex / ziplistNext / ziplistGet / ziplistFind 等函数供 listTypePush、hashTypeSet 等命令调用。', 'MEDIUM', 2, 44),
('redis-design', 7, '第 7 章 对象系统与五大类型', 'redis-design:7:45', 'robj 对象结构', 'robj 对象结构：typedef struct redisObject { unsigned type:4; unsigned encoding:4; int refcount; void *ptr; }，type 表示逻辑类型，encoding 表示底层实现。', 'MEDIUM', 2, 45),
('redis-design', 7, '第 7 章 对象系统与五大类型', 'redis-design:7:46', '对象类型与编码对照', '对象类型与编码对照：string → int/embstr/raw；list → quicklist；hash → listpack/hashtable；set → intset/listpack/hashtable；zset → listpack/skiplist。', 'MEDIUM', 2, 46),
('redis-design', 7, '第 7 章 对象系统与五大类型', 'redis-design:7:47', '类型检查与多态', '类型检查与多态：命令执行前先做类型检查（如 LLEN 对非 list 返回 WRONGTYPE），再依据 encoding 分派具体实现，实现「同命令多编码」。', 'MEDIUM', 2, 47),
('redis-design', 7, '第 7 章 对象系统与五大类型', 'redis-design:7:48', '引用计数与共享', '引用计数与共享：refcount 记录引用数，OBJECT REFCOUNT 可查看；共享对象池（如 0—9999 整数字符串）降低内存。', 'MEDIUM', 2, 48),
('redis-design', 7, '第 7 章 对象系统与五大类型', 'redis-design:7:49', '对象销毁', '对象销毁：引用归零时按 encoding 调用对应 free 函数（如 zfree、dictRelease），并回收内存。', 'MEDIUM', 2, 49),
('redis-design', 7, '第 7 章 对象系统与五大类型', 'redis-design:7:50', '字符串对象', '字符串对象：整数用 long 直接存 ptr（int 编码）；≤44 字节用 embstr；其余为 raw；SET 时若值可转整数且未设 OBJ_ENCODING_RAW 会优先 int 编码。', 'MEDIUM', 2, 50),
('redis-design', 7, '第 7 章 对象系统与五大类型', 'redis-design:7:51', '编码转换触发点', '编码转换触发点：APPEND 使 embstr 变 raw；修改元素导致 intset 升级或超阈值转 hashtable；OBJECT ENCODING key 可直接观察编码。', 'MEDIUM', 2, 51),
('redis-design', 7, '第 7 章 对象系统与五大类型', 'redis-design:7:52', '共享与空转时间', '共享与空转时间：OBJECT IDLETIME 返回秒级空闲时间（近似 LRU），用于调试连接与键的空闲淘汰行为。', 'MEDIUM', 2, 52),
('redis-design', 8, '第 8 章 数据库与键空间', 'redis-design:8:53', 'redisDb 结构', 'redisDb 结构：id、dict *dict（键空间）、dict *expires（过期字典）、blocking_keys、ready_keys、watched_keys 等字段组成。', 'MEDIUM', 2, 53),
('redis-design', 8, '第 8 章 数据库与键空间', 'redis-design:8:54', 'SELECT 切换库', 'SELECT 切换库：SELECT n 切换 db->id，默认 16 个数据库（databases 配置项），Cluster 模式下仅 db0。', 'MEDIUM', 2, 54),
('redis-design', 8, '第 8 章 数据库与键空间', 'redis-design:8:55', '键的增删改查', '键的增删改查：写操作先写键空间 dict 再写过期字典 expires；读操作查 dict；设置 EXPIRE 会把键加入 expires 并以 UNIX 时间戳为值。', 'MEDIUM', 2, 55),
('redis-design', 8, '第 8 章 数据库与键空间', 'redis-design:8:56', '过期键判定', '过期键判定：访问时先查 expires 判断是否过期（惰性删除），过期则返回 nil 并删除键。', 'MEDIUM', 2, 56),
('redis-design', 8, '第 8 章 数据库与键空间', 'redis-design:8:57', '定期删除策略', '定期删除策略：serverCron 每秒执行 activeExpireCycle，每次从各库随机抽取若干带过期时间的键，删除其中已过期的，占比超 25% 继续循环（ACTIVE_EXPIRE_CYCLE_LOOKUPS_PER_LOOP 默认 20）。', 'MEDIUM', 2, 57),
('redis-design', 8, '第 8 章 数据库与键空间', 'redis-design:8:58', '键空间通知', '键空间通知：notify-keyspace-events 配置如 Ex、Kg$ 等，通过 pubsub 广播 expired/evicted/set 等事件，用于监控与失效感知。', 'MEDIUM', 2, 58),
('redis-design', 8, '第 8 章 数据库与键空间', 'redis-design:8:59', 'FLUSHDB/FLUSHALL', 'FLUSHDB/FLUSHALL：清空当前库或全部库，大库执行会产生阻塞，可用 FLUSHALL ASYNC（4.0+）异步释放。', 'MEDIUM', 2, 59),
('redis-design', 9, '第 9 章 RDB 持久化', 'redis-design:9:60', 'SAVE 与 BGSAVE', 'SAVE 与 BGSAVE：SAVE 由主进程直接写 RDB 会阻塞所有请求；BGSAVE fork 子进程写快照，父进程继续处理命令，fork 期间会短暂阻塞。', 'MEDIUM', 2, 60),
('redis-design', 9, '第 9 章 RDB 持久化', 'redis-design:9:61', 'fork + COW', 'fork + COW：fork 后父子共享物理内存页，父进程写操作触发写时复制生成副本，保证子进程看到的是 fork 时刻的一致性数据视图。', 'MEDIUM', 2, 61),
('redis-design', 9, '第 9 章 RDB 持久化', 'redis-design:9:62', '自动保存触发', '自动保存触发：save 配置如 save 900 1、save 300 10、save 60 10000，serverCron 检查 dirty 计数与 lastsave 判断是否触发 BGSAVE。', 'MEDIUM', 2, 62),
('redis-design', 9, '第 9 章 RDB 持久化', 'redis-design:9:63', 'RDB 文件结构', 'RDB 文件结构：REDIS 魔数、db_version、数据库编号、键值对（带类型/编码/过期时间）、EOF、8 字节 CRC64 校验和；支持多库分段。', 'MEDIUM', 2, 63),
('redis-design', 9, '第 9 章 RDB 持久化', 'redis-design:9:64', 'rdbSave / rdbLoad', 'rdbSave / rdbLoad：写时用 rio 抽象逐项输出字符串对象、压缩列表等；读时反序列化并重建对象，遇损坏校验错误拒绝加载。', 'MEDIUM', 2, 64),
('redis-design', 9, '第 9 章 RDB 持久化', 'redis-design:9:65', 'RDB 优缺点', 'RDB 优缺点：文件紧凑、加载快、适合备份与灾备；但两次快照间数据可能丢失，fork 大实例时存在毫秒级卡顿风险【补充】。', 'MEDIUM', 2, 65),
('redis-design', 9, '第 9 章 RDB 持久化', 'redis-design:9:66', 'AOF 与 RDB 混合持久化', 'AOF 与 RDB 混合持久化：Redis 4.0 起 aof-use-rdb-preamble yes 让 AOF 重写写出 RDB 头 + 增量 AOF 尾，兼顾恢复速度与数据安全。', 'MEDIUM', 2, 66),
('redis-design', 10, '第 10 章 AOF 持久化与重写', 'redis-design:10:67', 'AOF 追加流程', 'AOF 追加流程：命令执行后调用 feedAppendOnlyFile，按 aof-write-fsync-always/everysec/no 决定同步策略，写入 aof_buf。', 'MEDIUM', 2, 67),
('redis-design', 10, '第 10 章 AOF 持久化与重写', 'redis-design:10:68', 'fsync 三策略权衡', 'fsync 三策略权衡：always 每条都 fsync（最安全最慢）；everysec 每秒一次（默认，最多丢 1 秒）；no 交给 OS（性能最好但不可控）。', 'MEDIUM', 2, 68),
('redis-design', 10, '第 10 章 AOF 持久化与重写', 'redis-design:10:69', 'AOF 重写动机', 'AOF 重写动机：AOF 只增不减，文件膨胀且恢复慢；重写通过读取当前内存状态生成最小等价命令集。', 'MEDIUM', 2, 69),
('redis-design', 10, '第 10 章 AOF 持久化与重写', 'redis-design:10:70', 'BGREWRITEAOF 机制', 'BGREWRITEAOF 机制：fork 子进程写新 AOF 文件，父进程把新写命令同时追加到 aof_rewrite_buf_blocks，重写完成后追加差量并原子 rename 替换。', 'MEDIUM', 2, 70),
('redis-design', 10, '第 10 章 AOF 持久化与重写', 'redis-design:10:71', '重写触发条件', '重写触发条件：auto-aof-rewrite-percentage（默认 100，即比上次重写后增大 100%）与 auto-aof-rewrite-min-size（默认 64MB）同时满足。', 'MEDIUM', 2, 71),
('redis-design', 10, '第 10 章 AOF 持久化与重写', 'redis-design:10:72', 'AOF 损坏修复', 'AOF 损坏修复：redis-check-aof --fix 截断文件尾部不完整命令；加载时遇到非法内容会拒绝启动以保证一致性。', 'MEDIUM', 2, 72),
('redis-design', 10, '第 10 章 AOF 持久化与重写', 'redis-design:10:73', 'AOF 与 RDB 选型', 'AOF 与 RDB 选型：追求数据安全选 AOF everysec 或 always；追求加载速度选 RDB；生产常用「AOF+RDB 双开」组合。', 'MEDIUM', 2, 73),
('redis-design', 11, '第 11 章 事件循环与多路复用', 'redis-design:11:74', 'ae 事件循环', 'ae 事件循环：aeMain 在 while 循环中调用 aeProcessEvents，处理文件事件与时间事件；事件循环是 Redis 单线程模型核心。', 'MEDIUM', 2, 74),
('redis-design', 11, '第 11 章 事件循环与多路复用', 'redis-design:11:75', 'I/O 多路复用封装', 'I/O 多路复用封装：编译期选择 epoll（Linux）、kqueue（BSD/macOS）、select（兜底），统一为 aeApiCreate/aeApiPoll 接口。', 'MEDIUM', 2, 75),
('redis-design', 11, '第 11 章 事件循环与多路复用', 'redis-design:11:76', '文件事件处理器', '文件事件处理器：连接应答处理器 acceptTcpHandler、命令请求处理器 readQueryFromClient、命令回复处理器 sendReplyToClient，分别注册 READABLE/WRITABLE 事件。', 'MEDIUM', 2, 76),
('redis-design', 11, '第 11 章 事件循环与多路复用', 'redis-design:11:77', '时间事件', '时间事件：serverCron（100ms 周期）负责更新统计、过期键清理、rehash 推进、AOF/RDB 检查；aeCreateTimeEvent 可创建一次性定时任务。', 'MEDIUM', 2, 77),
('redis-design', 11, '第 11 章 事件循环与多路复用', 'redis-design:11:78', '事件调度策略', '事件调度策略：aeProcessEvents 返回前计算最近时间事件的 wait 时间作为 poll 超时；AE_FILE_EVENTS/AE_TIME_EVENTS/AE_DONT_WAIT 标志控制处理顺序。', 'MEDIUM', 2, 78),
('redis-design', 11, '第 11 章 事件循环与多路复用', 'redis-design:11:79', '读写缓冲区', '读写缓冲区：每个客户端有 querybuf（输入缓冲）与 buf/output list（输出缓冲），client-output-buffer-limit 限制大小防 OOM。', 'MEDIUM', 2, 79),
('redis-design', 11, '第 11 章 事件循环与多路复用', 'redis-design:11:80', '单线程的含义', '单线程的含义：命令处理在单线程完成，避免锁竞争；网络 I/O 也是同一线程通过非阻塞 + 多路复用完成，因此 6.0 引入 I/O 多线程仅并行 socket 读写【补充】。', 'MEDIUM', 2, 80),
('redis-design', 11, '第 11 章 事件循环与多路复用', 'redis-design:11:81', 'beforeSleep 钩子', 'beforeSleep 钩子：每次 poll 前调用 handleClientsWithPendingWrites 处理可写客户端，降低延迟。', 'MEDIUM', 2, 81),
('redis-design', 12, '第 12 章 客户端与服务端通信', 'redis-design:12:82', 'RESP 协议', 'RESP 协议：请求以多批量字符串数组（*N\r\n$len\r\n...）编码，回复分简单字符串 +、错误 -、整数 :、批量 $、数组 * 五种类型。', 'MEDIUM', 2, 82),
('redis-design', 12, '第 12 章 客户端与服务端通信', 'redis-design:12:83', '管道与内联命令', '管道与内联命令：客户端可连续发送多条命令而不必等待回复，服务端按序处理并批量回复；telnet/netcat 可直接发 RESP。', 'MEDIUM', 2, 83),
('redis-design', 12, '第 12 章 客户端与服务端通信', 'redis-design:12:84', '客户端状态结构', '客户端状态结构：redisClient 含 fd、name、flags、argc/argv、bufpos、reply 链表、lastinteraction、authenticated 等字段。', 'MEDIUM', 2, 84),
('redis-design', 12, '第 12 章 客户端与服务端通信', 'redis-design:12:85', 'CLIENT 命令族', 'CLIENT 命令族：CLIENT LIST、CLIENT KILL ip:port、CLIENT SETNAME、CLIENT PAUSE ms 用于运维控制；CLIENT REPLY ON/OFF/SKIP 控制回复。', 'MEDIUM', 2, 85),
('redis-design', 12, '第 12 章 客户端与服务端通信', 'redis-design:12:86', '输入缓冲限制', '输入缓冲限制：querybuf 无硬上限但 client-query-buffer-limit（默认 1GB）与 proto-max-bulk-len（默认 512MB）限制单条命令体积。', 'MEDIUM', 2, 86),
('redis-design', 12, '第 12 章 客户端与服务端通信', 'redis-design:12:87', '慢查询日志', '慢查询日志：slowlog-log-slower-than（默认 10000 微秒）与 slowlog-max-len（默认 128）记录执行超时的命令，SLOWLOG GET n 查看。', 'MEDIUM', 2, 87),
('redis-design', 12, '第 12 章 客户端与服务端通信', 'redis-design:12:88', '监视器', '监视器：MONITOR 命令把当前实例所有命令实时转发给监控客户端，生产慎用（显著增加 CPU 开销）。', 'MEDIUM', 2, 88),
('redis-design', 13, '第 13 章 主从复制', 'redis-design:13:89', '全量同步 SYNC', '全量同步 SYNC：从库发送 SYNC，主库 BGSAVE 生成 RDB 并发送，期间缓存新命令，发完后补发缓存命令；简单但每次都全量、开销大。', 'MEDIUM', 2, 89),
('redis-design', 13, '第 13 章 主从复制', 'redis-design:13:90', 'PSYNC 部分重同步', 'PSYNC 部分重同步：Redis 2.8 引入，携带 offset 与 runid；主库 repl_backlog（环形缓冲）保留最近命令，offset 命中则只补差异部分，否则退化为全量。', 'MEDIUM', 2, 90),
('redis-design', 13, '第 13 章 主从复制', 'redis-design:13:91', '命令传播', '命令传播：主库执行写命令后调用 propagate 把命令写入 repl_backlog 并发送给所有从库，从库重放保持数据一致。', 'MEDIUM', 2, 91),
('redis-design', 13, '第 13 章 主从复制', 'redis-design:13:92', '心跳检测', '心跳检测：主库周期性给从库发 REPLCONF ACK offset，从库默认每秒上报一次偏移量；repl-ping-slave-period（默认 10s）控制探测间隔。', 'MEDIUM', 2, 92),
('redis-design', 13, '第 13 章 主从复制', 'redis-design:13:93', '复制积压缓冲区', '复制积压缓冲区：repl-backlog-size（默认 1MB，可加大到百 MB）太小会导致从库频繁全量同步；生产建议 ≥ 100MB。', 'MEDIUM', 2, 93),
('redis-design', 13, '第 13 章 主从复制', 'redis-design:13:94', '从库只读', '从库只读：slave-read-only yes（默认）禁止从库写；从库可有自己从库形成链式复制。', 'MEDIUM', 2, 94),
('redis-design', 13, '第 13 章 主从复制', 'redis-design:13:95', '无盘复制', '无盘复制：repl-diskless-sync yes 时通过 socket 直接发送 RDB，避免落盘 I/O，适合慢磁盘；repl-diskless-load 控制加载方式【补充】。', 'MEDIUM', 2, 95),
('redis-design', 13, '第 13 章 主从复制', 'redis-design:13:96', '复制偏移量与延迟', '复制偏移量与延迟：master_repl_offset 与从库上报 offset 之差即复制延迟，INFO replication 中 master_repl_offset/second_repl_offset 是核心监控指标。', 'MEDIUM', 2, 96),
('redis-design', 14, '第 14 章 Sentinel 哨兵', 'redis-design:14:97', '哨兵职责', '哨兵职责：监控（周期 PING/INFO）、通知（向订阅者发布 +switch-master）、自动故障转移（选主并切换）、配置提供者（客户端从哨兵获取当前主库地址）。', 'MEDIUM', 2, 97),
('redis-design', 14, '第 14 章 Sentinel 哨兵', 'redis-design:14:98', '启动与初始化', '启动与初始化：redis-sentinel sentinel.conf，配置形如 sentinel monitor mymaster 127.0.0.1 6379 2，其中 2 为 quorum 法定人数。', 'MEDIUM', 2, 98),
('redis-design', 14, '第 14 章 Sentinel 哨兵', 'redis-design:14:99', '主观下线 SDOWN', '主观下线 SDOWN：单个哨兵在 down-after-milliseconds（默认 30000ms）内未收到有效回复即判定主库主观下线。', 'MEDIUM', 2, 99),
('redis-design', 14, '第 14 章 Sentinel 哨兵', 'redis-design:14:100', '客观下线 ODOWN', '客观下线 ODOWN：足够数量（quorum）的哨兵通过 SENTINEL is-master-down-by-addr 投票确认后转客观下线，触发故障转移。', 'MEDIUM', 2, 100),
('redis-design', 14, '第 14 章 Sentinel 哨兵', 'redis-design:14:101', '领导者选举', '领导者选举：哨兵间用类似 Raft 的纪元机制，先发现 ODOWN 的哨兵向其他哨兵发起 leader 投票，得票超过半数成为领导者执行故障转移。', 'MEDIUM', 2, 101),
('redis-design', 14, '第 14 章 Sentinel 哨兵', 'redis-design:14:102', '新主选择条件', '新主选择条件：排除下线/断连从库（down-after-milliseconds*10）、按 slave-priority（默认 100，设 0 不参与选主）、复制偏移量最大、runid 字典序最小的顺序挑选。', 'MEDIUM', 2, 102),
('redis-design', 14, '第 14 章 Sentinel 哨兵', 'redis-design:14:103', '故障转移步骤', '故障转移步骤：选主 → SLAVEOF NO ONE 提正 → 对其他从库发 SLAVEOF <newmaster> → 旧主恢复后降级为从库（或等待重启）。', 'MEDIUM', 2, 103),
('redis-design', 14, '第 14 章 Sentinel 哨兵', 'redis-design:14:104', '纪元 epoch', '纪元 epoch：每次故障转移递增 configEpoch，用于版本化配置；哨兵也会在故障转移后广播新的 master 配置。', 'MEDIUM', 2, 104),
('redis-design', 15, '第 15 章 Cluster 集群', 'redis-design:15:105', 'slot 分片', 'slot 分片：键空间划分为 16384 个 slot，HASH_SLOT = crc16(key) % 16384；cluster-enabled yes 开启，节点负责部分槽位。', 'MEDIUM', 2, 105),
('redis-design', 15, '第 15 章 Cluster 集群', 'redis-design:15:106', '哈希标签 hash tag', '哈希标签 hash tag：key 中 {...} 内的内容才参与 CRC16，保证 user:{1000}:a 与 user:{1000}:b 落同一槽，支持多键事务/Lua。', 'MEDIUM', 2, 106),
('redis-design', 15, '第 15 章 Cluster 集群', 'redis-design:15:107', 'gossip 协议', 'gossip 协议：节点间通过 PING/PONG/MEET/FAIL 消息交换状态，每秒随机 ping 若干节点，消息含 ping_sent/pong_received/fail? 等元数据。', 'MEDIUM', 2, 107),
('redis-design', 15, '第 15 章 Cluster 集群', 'redis-design:15:108', 'MEET 与拓扑', 'MEET 与拓扑：CLUSTER MEET ip port 把新节点加入集群，信息经 gossip 扩散；节点保存 clusterNode 结构记录所有已知节点。', 'MEDIUM', 2, 108),
('redis-design', 15, '第 15 章 Cluster 集群', 'redis-design:15:109', '故障检测', '故障检测：超过 cluster-node-timeout（默认 15000ms）未收到 PONG 标记疑似下线 PFAIL，达到 quorum（多数派）确认后广播 FAIL，所有节点立即将该节点标记为下线。', 'MEDIUM', 2, 109),
('redis-design', 15, '第 15 章 Cluster 集群', 'redis-design:15:110', '故障转移', '故障转移：从节点发起选举，向主节点请求投票；获得多数主节点投票后 CLUSTER FAILOVER TAKEOVER 可强制提升；cluster-require-full-coverage yes 保证任一槽不可用则整集群不可写。', 'MEDIUM', 2, 110),
('redis-design', 15, '第 15 章 Cluster 集群', 'redis-design:15:111', 'ASK 与 MOVED 重定向', 'ASK 与 MOVED 重定向：MOVED 表示槽永久迁移到新节点；ASK 表示槽正在迁移中，客户端先发 ASKING 再发命令，避免迁移丢数据。', 'MEDIUM', 2, 111),
('redis-design', 15, '第 15 章 Cluster 集群', 'redis-design:15:112', '槽迁移状态', '槽迁移状态：源节点标记 MIGRATING，目标节点标记 IMPORTING，逐 key 用 MIGRATE 搬迁，迁移期间 CLUSTERSLOTS 可能返回重叠结果。', 'MEDIUM', 2, 112),
('redis-design', 15, '第 15 章 Cluster 集群', 'redis-design:15:113', '集群限制', '集群限制：多键操作要求同槽；SELECT 仅支持 db0；Lua 脚本涉及的多键必须同槽。', 'MEDIUM', 2, 113),
('redis-design', 16, '第 16 章 发布订阅与 Lua', 'redis-design:16:114', 'PUBLISH/SUBSCRIBE', 'PUBLISH/SUBSCRIBE：频道模式，发布者发 PUBLISH channel msg，订阅者 SUBSCRIBE ch1 ch2 接收；模式订阅 PSUBSCRIBE news.* 支持 glob 匹配。', 'MEDIUM', 2, 114),
('redis-design', 16, '第 16 章 发布订阅与 Lua', 'redis-design:16:115', 'PubSub 数据结构', 'PubSub 数据结构：server.pubsub_channels 字典（频道 → 客户端 list），server.pubsub_patterns 链表（模式 → 客户端）；退订时相应清理。', 'MEDIUM', 2, 115),
('redis-design', 16, '第 16 章 发布订阅与 Lua', 'redis-design:16:116', '消息不持久化', '消息不持久化：发布订阅不进入 AOF/RDB，客户端离线期间消息丢失；需要可靠传递应使用 Stream（5.0+）【补充】。', 'MEDIUM', 2, 116),
('redis-design', 16, '第 16 章 发布订阅与 Lua', 'redis-design:16:117', 'Redis 与 Lua 集成', 'Redis 与 Lua 集成：Lua 5.1 解释器嵌入，EVAL script numkeys key... arg...；脚本内用 redis.call 调用命令，redis.pcall 容错版。', 'MEDIUM', 2, 117),
('redis-design', 16, '第 16 章 发布订阅与 Lua', 'redis-design:16:118', '脚本原子性', '脚本原子性：整个脚本执行期间不会插入其他命令（单线程 + EVAL 独占），可用作分布式锁与原子多步操作。', 'MEDIUM', 2, 118),
('redis-design', 16, '第 16 章 发布订阅与 Lua', 'redis-design:16:119', 'SCRIPT LOAD / EVALSHA', 'SCRIPT LOAD / EVALSHA：先 SCRIPT LOAD 得到 SHA1，再用 EVALSHA sha numkeys ... 复用脚本，减少网络传输。', 'MEDIUM', 2, 119),
('redis-design', 16, '第 16 章 发布订阅与 Lua', 'redis-design:16:120', 'SCRIPT FLUSH 与 NO-SCRIPT 模式：从库默认 don''t-a', 'SCRIPT FLUSH 与 NO-SCRIPT 模式：从库默认 don''t-allow-scripts 相关策略，主从切换后脚本缓存可能失效，需注意 EVALSHA NOSCRIPT 回退。', 'MEDIUM', 2, 120),
('redis-design', 17, '第 17 章 过期键与内存淘汰', 'redis-design:17:121', '过期时间存储', '过期时间存储：EXPIRE/PEXPIRE 在 db->expires 中以 key → UNIX 毫秒时间戳形式登记；TTL 返回剩余秒数（负值 -1 表示键存在无过期，-2 表示不存在）。', 'MEDIUM', 2, 121),
('redis-design', 17, '第 17 章 过期键与内存淘汰', 'redis-design:17:122', '惰性删除', '惰性删除：访问键时先调用 expireIfNeeded 检查是否过期，过期则删除键空间与过期字典条目后返回 nil。', 'MEDIUM', 2, 122),
('redis-design', 17, '第 17 章 过期键与内存淘汰', 'redis-design:17:123', '定期删除', '定期删除：serverCron 每 100ms 触发 activeExpireCycle，按快慢两种模式随机抽样带过期键并删除其中过期者，控制单次耗时不超过 CPU 时间片。', 'MEDIUM', 2, 123),
('redis-design', 17, '第 17 章 过期键与内存淘汰', 'redis-design:17:124', '主从复制中的过期', '主从复制中的过期：由主库负责惰性/定期删除并传播 DEL 命令给从库；从库收到读请求时若发现键已过期会返回 nil 但不主动删，等主库下发 DEL（Redis 3.2 起行为）【补充】。', 'MEDIUM', 2, 124),
('redis-design', 17, '第 17 章 过期键与内存淘汰', 'redis-design:17:125', 'maxmemory 与 8 种淘汰策略', 'maxmemory 与 8 种淘汰策略：noeviction（默认，写报错）、allkeys-lru、volatile-lru、allkeys-lfu（4.0+）、volatile-lfu、allkeys-random、volatile-random、volatile-ttl。', 'MEDIUM', 2, 125),
('redis-design', 17, '第 17 章 过期键与内存淘汰', 'redis-design:17:126', '近似 LRU 实现', '近似 LRU 实现：不维护全局链表，而是在池中采样 N 个键（maxmemory-samples 默认 5）选最久未访问者淘汰，以极小开销逼近真实 LRU。', 'MEDIUM', 2, 126),
('redis-design', 17, '第 17 章 过期键与内存淘汰', 'redis-design:17:127', 'LFU 实现', 'LFU 实现：用 Morris 计数器 + 衰减因子（lfu-decay-time 默认 1 分钟）统计访问频率，lfu-log-factor 默认 10 控制计数上限，访问越多越难被淘汰。', 'MEDIUM', 2, 127),
('redis-design', 17, '第 17 章 过期键与内存淘汰', 'redis-design:17:128', '淘汰触发时机', '淘汰触发时机：每次执行命令前 performEvictions 检查 used_memory 是否超 maxmemory，超则循环淘汰直至降到阈值以下。', 'MEDIUM', 2, 128),
('redis-design', 17, '第 17 章 过期键与内存淘汰', 'redis-design:17:129', '主动过期淘汰', '主动过期淘汰：即使配置 noeviction，过期的键仍会被惰性/定期删除，不会因此 OOM。', 'MEDIUM', 2, 129),
('redis-design', 18, '第 18 章 内存管理与优化', 'redis-design:18:130', 'jemalloc 分配器', 'jemalloc 分配器：Redis 默认使用 jemalloc 管理内存，减少碎片；INFO memory 中 used_memory_human 为实际占用，allocator_frag_ratio 反映碎片率。', 'MEDIUM', 2, 130),
('redis-design', 18, '第 18 章 内存管理与优化', 'redis-design:18:131', '对象共享池', '对象共享池：0—9999 的整数对象预先创建并共享，OBJECT REFCOUNT 可查看引用计数（多客户端共享同一对象时计数大于 1）。', 'MEDIUM', 2, 131),
('redis-design', 18, '第 18 章 内存管理与优化', 'redis-design:18:132', '内存碎片整理', '内存碎片整理：activedefrag yes 开启主动碎片整理，通过迁移内存页降低碎片率，需注意对延迟的影响。', 'MEDIUM', 2, 132),
('redis-design', 18, '第 18 章 内存管理与优化', 'redis-design:18:133', '大 key 危害', '大 key 危害：单个 key 体积过大导致删除阻塞、网络拥塞、数据倾斜；可用 --bigkeys、MEMORY USAGE 排查。', 'MEDIUM', 2, 133),
('redis-design', 18, '第 18 章 内存管理与优化', 'redis-design:18:134', '键名设计', '键名设计：使用简洁且可归类的命名如 user:{id}:profile，兼顾可读性与哈希标签需求。', 'MEDIUM', 2, 134),
('redis-design', 19, '第 19 章 事务与 WATCH', 'redis-design:19:135', 'MULTI/EXEC/DISCARD', 'MULTI/EXEC/DISCARD：MULTI 开启事务，命令入队不立即执行，EXEC 原子执行队列，DISCARD 清空队列；不支持回滚。', 'MEDIUM', 2, 135),
('redis-design', 19, '第 19 章 事务与 WATCH', 'redis-design:19:136', '入队错误 vs 运行错误', '入队错误 vs 运行错误：语法/不存在命令在 MULTI 阶段报 QUEUE 前错误并拒绝整个事务；运行期类型错误（如 LPUSH 到字符串）只影响该条命令，其余继续。', 'MEDIUM', 2, 136),
('redis-design', 19, '第 19 章 事务与 WATCH', 'redis-design:19:137', 'WATCH 乐观锁', 'WATCH 乐观锁：WATCH key 监视后若键被改动，EXEC 返回 nil 表示事务放弃；基于 CAS 语义实现 check-and-set。', 'MEDIUM', 2, 137),
('redis-design', 19, '第 19 章 事务与 WATCH', 'redis-design:19:138', 'UNWATCH', 'UNWATCH：取消对所有键的监视；EXEC/DISCARD 后自动 unwatch。', 'MEDIUM', 2, 138),
('redis-design', 19, '第 19 章 事务与 WATCH', 'redis-design:19:139', '集群下的限制', '集群下的限制：WATCH 与 MULTI 涉及多键时必须同槽，否则报 CROSSSLOT 错误。', 'MEDIUM', 2, 139),
('redis-design', 20, '第 20 章 性能相关参数', 'redis-design:20:140', '超时与连接', '超时与连接：timeout 控制空闲客户端断连（0 禁用）；tcp-keepalive 发送 SO_KEEPALIVE 探测死连接。', 'MEDIUM', 2, 140),
('redis-design', 20, '第 20 章 性能相关参数', 'redis-design:20:141', '输出缓冲区限制', '输出缓冲区限制：client-output-buffer-limit class hard soft seconds（如 normal 0 0 0、slave 256mb 64mb 60、pubsub 32mb 8mb 60），超限断开客户端防 OOM。', 'MEDIUM', 2, 141),
('redis-design', 20, '第 20 章 性能相关参数', 'redis-design:20:142', 'THP 与 fork', 'THP 与 fork：透明大页 THP 会放大 COW 内存开销，建议关闭（never）并在 redis.conf 提示；INFO 的 rss 更反映真实内存。', 'MEDIUM', 2, 142),
('redis-design', 20, '第 20 章 性能相关参数', 'redis-design:20:143', '慢查询与基准', '慢查询与基准：redis-benchmark -t set,get -n 1000000 -c 50 压测；SLOWLOG GET 定位慢命令。', 'MEDIUM', 2, 143)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('redis-action', 1, '第 1 章 初识 Redis 与数据模型', 'redis-action:1:1', '安装与启动', '安装与启动：源码 make && make install，redis-server redis.conf 启动；生产建议显式配置 daemonize yes、bind、port、dir、logfile、requirepass/masterauth。', 'MEDIUM', 2, 1),
('redis-action', 1, '第 1 章 初识 Redis 与数据模型', 'redis-action:1:2', '通用键命令', '通用键命令：SET/GET、MSET/MGET、INCR/DECR（原子计数）、EXISTS/DEL、TYPE、EXPIRE/TTL、KEYS *（慎用）、SCAN 0 COUNT 100（安全遍历）。', 'MEDIUM', 2, 2),
('redis-action', 1, '第 1 章 初识 Redis 与数据模型', 'redis-action:1:3', '字符串适用场景', '字符串适用场景：缓存对象 JSON、页面片段、计数器、分布式 ID 生成器（INCR global:id）、位图（BITCOUNT/BITOP）。', 'MEDIUM', 2, 3),
('redis-action', 1, '第 1 章 初识 Redis 与数据模型', 'redis-action:1:4', '列表适用场景', '列表适用场景：消息队列/任务列表（LPUSH+BRPOP）、最新 N 条时间线（LPUSH+LTRIM）、RPOPLPUSH 可靠队列（配合 backup 列表）。', 'MEDIUM', 2, 4),
('redis-action', 1, '第 1 章 初识 Redis 与数据模型', 'redis-action:1:5', '哈希适用场景', '哈希适用场景：存储结构化对象（用户资料、商品属性），支持 HGET/HSET/HMGET/HINCRBY 字段级更新，避免整个对象序列化读写。', 'MEDIUM', 2, 5),
('redis-action', 1, '第 1 章 初识 Redis 与数据模型', 'redis-action:1:6', '集合适用场景', '集合适用场景：去重标签、共同好友（SINTER）、是否存在（SISMEMBER）、随机抽取（SRANDMEMBER/SPOP）。', 'MEDIUM', 2, 6),
('redis-action', 1, '第 1 章 初识 Redis 与数据模型', 'redis-action:1:7', '有序集合适用场景', '有序集合适用场景：排行榜（ZADD+ZREVRANGE）、按权重调度、范围查询（ZRANGEBYSCORE）、延时任务（score=执行时间戳 + ZRANGEBYSCORE 轮询）。', 'MEDIUM', 2, 7),
('redis-action', 1, '第 1 章 初识 Redis 与数据模型', 'redis-action:1:8', '键命名规范', '键命名规范：统一 业务:实体:id 前缀，如 user:1001:profile，便于 MONITOR/SCAN/metrics 分类统计与权限隔离。', 'MEDIUM', 2, 8),
('redis-action', 2, '第 2 章 安全与访问控制', 'redis-action:2:9', 'requirepass 认证', 'requirepass 认证：redis.conf 设 requirepass <pwd>，客户端 AUTH pwd；CONFIG SET requirepass 可动态修改，立即生效。', 'MEDIUM', 2, 9),
('redis-action', 2, '第 2 章 安全与访问控制', 'redis-action:2:10', 'masterauth', 'masterauth：从库连接主库时需配置 masterauth <pwd>，否则复制中断报 NOAUTH。', 'MEDIUM', 2, 10),
('redis-action', 2, '第 2 章 安全与访问控制', 'redis-action:2:11', '命令重命名', '命令重命名：rename-command FLUSHALL ""、rename-command CONFIG "" 隐藏危险命令；置空表示禁用该命令。', 'MEDIUM', 2, 11),
('redis-action', 2, '第 2 章 安全与访问控制', 'redis-action:2:12', 'bind 与保护模式', 'bind 与保护模式：bind 127.0.0.1 或内网地址 + protected-mode yes 防止裸奔公网；生产必须关闭 0.0.0.0 暴露。', 'MEDIUM', 2, 12),
('redis-action', 2, '第 2 章 安全与访问控制', 'redis-action:2:13', 'TLS 加密', 'TLS 加密：Redis 6.0+ 原生 TLS，配置 tls-port、tls-cert-file、tls-key-file；低版本可用 stunnel 代理【补充】。', 'MEDIUM', 2, 13),
('redis-action', 2, '第 2 章 安全与访问控制', 'redis-action:2:14', 'ACL 访问控制', 'ACL 访问控制：Redis 6.0 ACL 支持多用户、命令白名单、key pattern 限制（如 user alice on >pass ~* +@all -@dangerous）【补充】。', 'MEDIUM', 2, 14),
('redis-action', 2, '第 2 章 安全与访问控制', 'redis-action:2:15', '慢查询日志', '慢查询日志：slowlog-log-slower-than 10000（微秒）、slowlog-max-len 128，SLOWLOG GET n 查看，排查热点命令与阻塞源。', 'MEDIUM', 2, 15),
('redis-action', 3, '第 3 章 数据操作与批处理', 'redis-action:3:16', '管道 Pipeline', '管道 Pipeline：一次性发送多条命令（redis-cli --pipe、客户端 pipeline 接口），减少 RTT；批量过大占用内存且阻塞其他客户端，建议每批 ≤ 1000 条【补充】。', 'MEDIUM', 2, 16),
('redis-action', 3, '第 3 章 数据操作与批处理', 'redis-action:3:17', 'MULTI/EXEC 事务', 'MULTI/EXEC 事务：命令入队后原子执行，不支持回滚；运行期错误只影响单条命令，入队语法错误则整个事务放弃。', 'MEDIUM', 2, 17),
('redis-action', 3, '第 3 章 数据操作与批处理', 'redis-action:3:18', 'Lua 脚本原子性', 'Lua 脚本原子性：EVAL script numkeys keys... args...，期间不被其他命令插入；SCRIPT LOAD + EVALSHA 复用脚本，减少网络开销。', 'MEDIUM', 2, 18),
('redis-action', 3, '第 3 章 数据操作与批处理', 'redis-action:3:19', 'SCAN 家族', 'SCAN 家族：SCAN/HSCAN/SSCAN/ZSCAN 以游标方式遍历，不阻塞服务；Count 参数只是提示，结果可能为空或多于 count；遍历时可能返回重复元素，需客户端去重。', 'MEDIUM', 2, 19),
('redis-action', 3, '第 3 章 数据操作与批处理', 'redis-action:3:20', 'TYPE 与编码自适应', 'TYPE 与编码自适应：同一逻辑类型有多编码（intset/hashtable、listpack/hashtable、listpack/skiplist），写路径会自动升级，删除大量元素后编码不会自动降级。', 'MEDIUM', 2, 20),
('redis-action', 3, '第 3 章 数据操作与批处理', 'redis-action:3:21', '批量删除', '批量删除：UNLINK key [key ...] 异步释放大 key，避免 DEL 阻塞；4.0+ 推荐替代 DEL 处理大体积键。', 'MEDIUM', 2, 21),
('redis-action', 3, '第 3 章 数据操作与批处理', 'redis-action:3:22', '批量导入', '批量导入：--pipe 配合 protocol 文本或 redis-cli -x 读 stdin；大数据量导入用生成 RESP 流比逐条命令快 10 倍以上【补充】。', 'MEDIUM', 2, 22),
('redis-action', 4, '第 4 章 缓存模式与三大典型问题', 'redis-action:4:23', 'Cache-Aside 旁路缓存', 'Cache-Aside 旁路缓存：读先查 Redis，miss 再查 DB 并回填；写先更新 DB 再删缓存（而非更新缓存），是业务最常用模式。', 'MEDIUM', 2, 23),
('redis-action', 4, '第 4 章 缓存模式与三大典型问题', 'redis-action:4:24', '缓存穿透', '缓存穿透：请求不存在的 key 每次打到 DB；对策：空值也缓存（设较短 TTL 如 60s）、布隆过滤器预判、参数合法性校验拦截。', 'MEDIUM', 2, 24),
('redis-action', 4, '第 4 章 缓存模式与三大典型问题', 'redis-action:4:25', '布隆过滤器', '布隆过滤器：BF.ADD/BF.EXISTS（RedisBloom 模块）以极小内存判断元素不存在，允许可控误判率；用于防止恶意遍历 ID 打库【补充】。', 'MEDIUM', 2, 25),
('redis-action', 4, '第 4 章 缓存模式与三大典型问题', 'redis-action:4:26', '缓存击穿', '缓存击穿：热点 key 过期瞬间高并发同时回源 DB；对策：互斥锁（SET NX 只让一个线程回源）、逻辑过期异步刷新、热点 key 永不过期。', 'MEDIUM', 2, 26),
('redis-action', 4, '第 4 章 缓存模式与三大典型问题', 'redis-action:4:27', '缓存雪崩', '缓存雪崩：大量 key 同时过期或 Redis 宕机导致请求全部落 DB；对策：TTL 加随机抖动、多级缓存（本地+Redis）、熔断限流、高可用部署。', 'MEDIUM', 2, 27),
('redis-action', 4, '第 4 章 缓存模式与三大典型问题', 'redis-action:4:28', '缓存一致性', '缓存一致性：先更 DB 后删缓存在「读旧值再删」窗口仍可能脏读；强一致场景可延迟双删或基于 binlog 订阅（Canal）失效。', 'MEDIUM', 2, 28),
('redis-action', 4, '第 4 章 缓存模式与三大典型问题', 'redis-action:4:29', 'Write Through / Write Behind：前者同步写缓存与 DB', 'Write Through / Write Behind：前者同步写缓存与 DB，后者先写缓存异步落库（性能高但有丢失风险），按业务容忍度选型。', 'MEDIUM', 2, 29),
('redis-action', 4, '第 4 章 缓存模式与三大典型问题', 'redis-action:4:30', '缓存预热', '缓存预热：启动时用 MGET/pipeline 批量加载热点数据，避免冷启动压垮 DB；大流量系统应在发布流程中加入预热步骤。', 'MEDIUM', 2, 30),
('redis-action', 4, '第 4 章 缓存模式与三大典型问题', 'redis-action:4:31', '序列化选型', '序列化选型：JSON 通用但体积大；msgpack/protobuf/snappy 压缩后更小更快；JDK 原生序列化兼容性差，不推荐跨语言共享【补充】。', 'MEDIUM', 2, 31),
('redis-action', 4, '第 4 章 缓存模式与三大典型问题', 'redis-action:4:32', '缓存 key 设计', '缓存 key 设计：包含维度参数（如 goods:detail:{skuId}:{lang}），避免不同维度共用同一 key 造成串数据。', 'MEDIUM', 2, 32),
('redis-action', 5, '第 5 章 会话、令牌与分布式锁', 'redis-action:5:33', 'Session 存储', 'Session 存储：HSET session:{token} uid 1001 expire_at ...，配合 EXPIRE session:{token} 1800 自动过期；相比粘滞会话更易横向扩展。', 'MEDIUM', 2, 33),
('redis-action', 5, '第 5 章 会话、令牌与分布式锁', 'redis-action:5:34', '滑动过期', '滑动过期：每次访问执行 EXPIRE session:{token} ttl，实现活跃会话延长、闲置会话到期。', 'MEDIUM', 2, 34),
('redis-action', 5, '第 5 章 会话、令牌与分布式锁', 'redis-action:5:35', '令牌桶限流', '令牌桶限流：用 hash 存 tokens/last_time，Lua 脚本原子补 token 并判断是否放行，支持突发流量控制。', 'MEDIUM', 2, 35),
('redis-action', 5, '第 5 章 会话、令牌与分布式锁', 'redis-action:5:36', '漏桶限流', '漏桶限流：用 list/zset 记录请求时间戳，超出速率则丢弃或排队；zset score 为时间戳，ZRANGEBYSCORE 统计窗口内数量。', 'MEDIUM', 2, 36),
('redis-action', 5, '第 5 章 会话、令牌与分布式锁', 'redis-action:5:37', '分布式锁基本实现', '分布式锁基本实现：SET lock:key uuid EX 30 NX 获取，释放用 Lua 比对 value（uuid）再 DEL，避免误删他人锁。', 'MEDIUM', 2, 37),
('redis-action', 5, '第 5 章 会话、令牌与分布式锁', 'redis-action:5:38', '锁续期 watchdog', '锁续期 watchdog：长任务需定期 EXPIRE lock:key 30 续期（看门狗线程），防业务未执行完锁已过期；Redisson 客户端内置该机制【补充】。', 'MEDIUM', 2, 38),
('redis-action', 5, '第 5 章 会话、令牌与分布式锁', 'redis-action:5:39', 'Redlock 算法', 'Redlock 算法：向 N 个独立主节点依次加锁，多数成功且总耗时小于锁有效期才算获取成功，用于多实例容错；争议点在于依赖时钟【补充】。', 'MEDIUM', 2, 39),
('redis-action', 5, '第 5 章 会话、令牌与分布式锁', 'redis-action:5:40', '幂等与去重', '幂等与去重：SET idempotent:{bizId} 1 NX EX 86400 保证同一业务操作只处理一次，用于支付回调、消息消费去重。', 'MEDIUM', 2, 40),
('redis-action', 5, '第 5 章 会话、令牌与分布式锁', 'redis-action:5:41', '计数器与排行榜', '计数器与排行榜：INCR page:view:{id} 统计 PV/UV 近似值；ZADD + ZINCRBY 维护实时榜单，ZREVRANGE 0 9 WITHSCORES 取 Top10。', 'MEDIUM', 2, 41),
('redis-action', 5, '第 5 章 会话、令牌与分布式锁', 'redis-action:5:42', '全局唯一 ID', '全局唯一 ID：INCR global:order_id 简单高效，但单点故障需配合号段模式（一次取 1000 个，本地分发）降低 Redis 压力。', 'MEDIUM', 2, 42),
('redis-action', 6, '第 6 章 事务、管道与 Lua 深入', 'redis-action:6:43', '事务使用注意', '事务使用注意：不要在 MULTI/EXEC 中做重逻辑循环（阻塞主线程）；集群下多键事务必须同 slot。', 'MEDIUM', 2, 43),
('redis-action', 6, '第 6 章 事务、管道与 Lua 深入', 'redis-action:6:44', 'WATCH 乐观锁', 'WATCH 乐观锁：WATCH account:{id} 后若 balance 被改，EXEC 返回 nil 需重试；CAS 语义适合库存扣减等竞争场景。', 'MEDIUM', 2, 44),
('redis-action', 6, '第 6 章 事务、管道与 Lua 深入', 'redis-action:6:45', 'Pipeline 与事务组合', 'Pipeline 与事务组合：pipeline 中嵌入 MULTI/EXEC 可减少 RTT 又保证批次原子；部分客户端用 multi() + exec() 即可。', 'MEDIUM', 2, 45),
('redis-action', 6, '第 6 章 事务、管道与 Lua 深入', 'redis-action:6:46', 'Lua 脚本规范', 'Lua 脚本规范：脚本要短平快，避免死循环；可用 redis.call(''SET'', KEYS[1], ARGV[1])，报错会中止脚本；复杂逻辑可拆多个 EVALSHA。', 'MEDIUM', 2, 46),
('redis-action', 6, '第 6 章 事务、管道与 Lua 深入', 'redis-action:6:47', 'SHA1 复用与 NOSCRIPT 回退', 'SHA1 复用与 NOSCRIPT 回退：EVALSHA 若返回 NOSCRIPT 错误，说明脚本未缓存（主从切换/重启后），需降级重新 EVAL 或 SCRIPT LOAD。', 'MEDIUM', 2, 47),
('redis-action', 6, '第 6 章 事务、管道与 Lua 深入', 'redis-action:6:48', '集群 Lua 限制', '集群 Lua 限制：脚本内访问的所有 key 必须声明在 numkeys 中且同槽，否则报 CROSSSLOT；用 hash tag 保证落同一槽。', 'MEDIUM', 2, 48),
('redis-action', 6, '第 6 章 事务、管道与 Lua 深入', 'redis-action:6:49', '监控脚本开销', '监控脚本开销：INFO commandstats 中 eval 调用次数与耗时占比可评估脚本对吞吐影响；慢查询日志同样覆盖 Lua 执行时长。', 'MEDIUM', 2, 49),
('redis-action', 7, '第 7 章 扩展数据结构与典型应用', 'redis-action:7:50', '位图 Bitmap', '位图 Bitmap：SETBIT/BITCOUNT/BITOP/BITPOS，省内存做签到、在线状态（SETBIT online:2024-01-01 uid 1）、用户行为布尔特征。', 'MEDIUM', 2, 50),
('redis-action', 7, '第 7 章 扩展数据结构与典型应用', 'redis-action:7:51', 'HyperLogLog', 'HyperLogLog：PFADD/PFCOUNT/PFMERGE，固定 12KB 统计 UV 近似值（误差约 0.81%），适合大流量去重计数。', 'MEDIUM', 2, 51),
('redis-action', 7, '第 7 章 扩展数据结构与典型应用', 'redis-action:7:52', 'GEO 地理位置', 'GEO 地理位置：GEOADD key lon lat member、GEOSEARCH FROMLONLAT ... BYRADIUS ...，底层 zset 编码；支持附近的人/门店搜索【补充】。', 'MEDIUM', 2, 52),
('redis-action', 7, '第 7 章 扩展数据结构与典型应用', 'redis-action:7:53', 'Bitfield', 'Bitfield：BITFIELD key SET u8 0 100、GET/OVERFLOW SAT，把多个小整数打包进一个 string key，极致省内存。', 'MEDIUM', 2, 53),
('redis-action', 7, '第 7 章 扩展数据结构与典型应用', 'redis-action:7:54', 'Stream 消息队列', 'Stream 消息队列：XADD/XREAD/XGROUP/XACK/XPENDING，消费者组 + PEL 待处理列表实现可靠消息与回溯，优于 list/pubsub 方案【补充】。', 'MEDIUM', 2, 54),
('redis-action', 7, '第 7 章 扩展数据结构与典型应用', 'redis-action:7:55', '二级索引构建', '二级索引构建：用 set/zset 维护「属性→id 集合」（如 idx:tag:vip -> {1,2,3}），SINTER/ZINTERSTORE 组合多条件查询。', 'MEDIUM', 2, 55),
('redis-action', 7, '第 7 章 扩展数据结构与典型应用', 'redis-action:7:56', '全文检索思路', '全文检索思路：RediSearch 模块或自建倒排索引（term → zset of docId），支持排序与过滤【补充】。', 'MEDIUM', 2, 56),
('redis-action', 7, '第 7 章 扩展数据结构与典型应用', 'redis-action:7:57', '日志与时间序列', '日志与时间序列：zset score=时间戳存事件，按范围 ZRANGEBYSCORE 拉取；量大时按天分 key（log:2024-01-01）便于清理。', 'MEDIUM', 2, 57),
('redis-action', 7, '第 7 章 扩展数据结构与典型应用', 'redis-action:7:58', 'Feed 流', 'Feed 流：LPUSH 新动态 + LTRIM 保留最近 N 条，避免 list 无限增长；主动推 vs 拉模式按社交关系设计。', 'MEDIUM', 2, 58),
('redis-action', 8, '第 8 章 主从复制与哨兵部署', 'redis-action:8:59', '复制配置', '复制配置：主库 requirepass，从库配置 replicaof <masterip> <masterport> + masterauth；或运行时执行 REPLICAOF ip port。', 'MEDIUM', 2, 59),
('redis-action', 8, '第 8 章 主从复制与哨兵部署', 'redis-action:8:60', '全量与增量同步', '全量与增量同步：首次同步 RDB + 命令缓存（SYNC），后续 PSYNC 基于 offset+runid 断点续传；offset 不在 repl-backlog 区间则退化为全量。', 'MEDIUM', 2, 60),
('redis-action', 8, '第 8 章 主从复制与哨兵部署', 'redis-action:8:61', 'repl-backlog-size', 'repl-backlog-size：默认 1MB 易导致全量同步，建议生产设为 64MB—256MB；可用 INFO replication 的 repl_backlog_active 观测。', 'MEDIUM', 2, 61),
('redis-action', 8, '第 8 章 主从复制与哨兵部署', 'redis-action:8:62', '读写分离', '读写分离：从库设 replica-read-only yes，业务按「写主读从」拆分；注意从库延迟（master_repl_offset - slave offset）会影响一致性。', 'MEDIUM', 2, 62),
('redis-action', 8, '第 8 章 主从复制与哨兵部署', 'redis-action:8:63', 'Sentinel 最小部署', 'Sentinel 最小部署：3 个哨兵 + 1 主 2 从为常见生产拓扑；sentinel.conf 中 sentinel monitor mymaster <ip> <port> 2 设置 quorum=2。', 'MEDIUM', 2, 63),
('redis-action', 8, '第 8 章 主从复制与哨兵部署', 'redis-action:8:64', 'down-after-milliseconds', 'down-after-milliseconds：默认 30s 判定主观下线；网络抖动敏感场景可调小但需配合 quorum，避免误切换。', 'MEDIUM', 2, 64),
('redis-action', 8, '第 8 章 主从复制与哨兵部署', 'redis-action:8:65', 'slave-priority', 'slave-priority：设为 0 表示该从库不参与选主，适合专用只读节点或备份节点。', 'MEDIUM', 2, 65),
('redis-action', 8, '第 8 章 主从复制与哨兵部署', 'redis-action:8:66', '故障转移验证', '故障转移验证：手动 redis-cli -p 26379 sentinel failover mymaster 演练，观察客户端切换耗时与数据丢失窗口。', 'MEDIUM', 2, 66),
('redis-action', 8, '第 8 章 主从复制与哨兵部署', 'redis-action:8:67', '双机房部署注意', '双机房部署注意：哨兵需跨机房多数派部署，否则单机房故障可能无法完成选主；脑裂会导致两主并存，应靠 quorum + 最小从库数防护。', 'MEDIUM', 2, 67),
('redis-action', 8, '第 8 章 主从复制与哨兵部署', 'redis-action:8:68', 'WAIT 命令', 'WAIT 命令：WAIT numreplicas timeout_ms 阻塞直到指定数量从库确认写入，用于需要强一致读的场景。', 'MEDIUM', 2, 68),
('redis-action', 9, '第 9 章 Cluster 集群分片实践', 'redis-action:9:69', '分片规划', '分片规划：16384 slot，节点数通常 3/6/9... 起步；单节点槽位数过多会增加 gossip 与迁移复杂度。', 'MEDIUM', 2, 69),
('redis-action', 9, '第 9 章 Cluster 集群分片实践', 'redis-action:9:70', 'hash tag 强制同槽', 'hash tag 强制同槽：{user:1000}:name、{user:1000}:orders 落同一槽，支撑多键操作；同一业务实体统一使用相同 tag。', 'MEDIUM', 2, 70),
('redis-action', 9, '第 9 章 Cluster 集群分片实践', 'redis-action:9:71', 'ASK/MOVED 处理', 'ASK/MOVED 处理：客户端需实现重定向逻辑（Jedis/Lettuce 已内置）；MOVED 更新本地 slot 映射，ASK 只临时重试一次。', 'MEDIUM', 2, 71),
('redis-action', 9, '第 9 章 Cluster 集群分片实践', 'redis-action:9:72', 'slot 迁移流程', 'slot 迁移流程：CLUSTER SETSLOT slot MIGRATING/IMPORTING nodeid → 逐 key MIGRATE host port key db timeout → 全部完成后广播新配置。', 'MEDIUM', 2, 72),
('redis-action', 9, '第 9 章 Cluster 集群分片实践', 'redis-action:9:73', 'cluster-node-timeout', 'cluster-node-timeout：默认 15s，影响故障检测速度；集群规模大时过小会误判，过大则故障感知变慢，需权衡。', 'MEDIUM', 2, 73),
('redis-action', 9, '第 9 章 Cluster 集群分片实践', 'redis-action:9:74', 'CLUSTER REQUIRE-FULL-COVERAGE：默认 yes，任一槽', 'CLUSTER REQUIRE-FULL-COVERAGE：默认 yes，任一槽不可用整个集群拒绝写；允许部分可用可设 no，但会牺牲一致性。', 'MEDIUM', 2, 74),
('redis-action', 9, '第 9 章 Cluster 集群分片实践', 'redis-action:9:75', '代理方案对比', '代理方案对比：Twemproxy/Codis 在客户端与节点间做分片与路由，兼容旧客户端；Redis 7 原生 Cluster 可直连，代理非必需。', 'MEDIUM', 2, 75),
('redis-action', 9, '第 9 章 Cluster 集群分片实践', 'redis-action:9:76', '扩缩容步骤', '扩缩容步骤：先 CLUSTER ADDSLOTS / reshard 迁移数据，再上下线节点；扩容优先加从库再提升为主，减少抖动。', 'MEDIUM', 2, 76),
('redis-action', 9, '第 9 章 Cluster 集群分片实践', 'redis-action:9:77', '跨 slot 限制规避', '跨 slot 限制规避：MGET/MSET/Lua 多键要求同槽；用 hash tag 或拆成多次请求 + 聚合，避免 CROSSSLOT。', 'MEDIUM', 2, 77),
('redis-action', 9, '第 9 章 Cluster 集群分片实践', 'redis-action:9:78', '监控分片均衡', '监控分片均衡：CLUSTER NODES 检查各节点 slot 分布，redis-cli --cluster rebalance 自动再平衡，避免热点倾斜。', 'MEDIUM', 2, 78),
('redis-action', 10, '第 10 章 性能基准与慢查询优化', 'redis-action:10:79', 'redis-benchmark 用法', 'redis-benchmark 用法：redis-benchmark -h host -p port -t set,get,lpush,lrange,hset,zadd -n 200000 -c 100 -q；-c 控制并发连接数，-n 请求总数，--csv 输出便于对比。', 'MEDIUM', 2, 79),
('redis-action', 10, '第 10 章 性能基准与慢查询优化', 'redis-action:10:80', '基准测试注意点', '基准测试注意点：与生产同机同网络环境测，避免跨网段；先跑预热再取均值；关注 P99/P95 而非只看平均 QPS。', 'MEDIUM', 2, 80),
('redis-action', 10, '第 10 章 性能基准与慢查询优化', 'redis-action:10:81', 'INFO stats 关键指标', 'INFO stats 关键指标：instantaneous_ops_per_sec（实时 QPS）、keyspace_hits/misses（命中率 = hits/(hits+misses)，低于 95% 需查缓存策略）、expired_keys、evicted_keys、rejected_connections。', 'MEDIUM', 2, 81),
('redis-action', 10, '第 10 章 性能基准与慢查询优化', 'redis-action:10:82', '内存指标', '内存指标：used_memory_human（实际数据+开销）、mem_fragmentation_ratio（RSS/used，>1.5 说明碎片高或分配器预留）、maxmemory 剩余。', 'MEDIUM', 2, 82),
('redis-action', 10, '第 10 章 性能基准与慢查询优化', 'redis-action:10:83', '大 key 排查', '大 key 排查：redis-cli --bigkeys 采样各类型最大元素；MEMORY USAGE key 精确统计单键内存；大 hash/set 用 HSCAN/SSCAN 分批处理。', 'MEDIUM', 2, 83),
('redis-action', 10, '第 10 章 性能基准与慢查询优化', 'redis-action:10:84', '慢查询定位', '慢查询定位：SLOWLOG GET 配合 slowlog-log-slower-than 微秒阈值；常见慢命令包括 KEYS *、LRANGE 0 -1、HGETALL 超大 hash、SMEMBERS 大集合、无索引 ZREVRANGE 大范围。', 'MEDIUM', 2, 84),
('redis-action', 10, '第 10 章 性能基准与慢查询优化', 'redis-action:10:85', '阻塞点排查', '阻塞点排查：redis-cli --latency、--intrinsic-latency 100 测固有延迟（排除网络与负载）；BLOCKED 客户端由 MONITOR 辅助观察。', 'MEDIUM', 2, 85),
('redis-action', 10, '第 10 章 性能基准与慢查询优化', 'redis-action:10:86', '热点 key 与连接倾斜', '热点 key 与连接倾斜：redis-cli --hotkeys（需 LFU 策略）识别热 key；多线程 I/O（io-threads）可缓解单核网络瓶颈【补充】。', 'MEDIUM', 2, 86),
('redis-action', 10, '第 10 章 性能基准与慢查询优化', 'redis-action:10:87', 'Pipeline 批量大小调优', 'Pipeline 批量大小调优：每批过小 RTT 占比高，过大则单次执行时间长、易触发 output buffer 限制；建议 100—1000 条为一批。', 'MEDIUM', 2, 87),
('redis-action', 10, '第 10 章 性能基准与慢查询优化', 'redis-action:10:88', '持久化对性能影响', '持久化对性能影响：AOF everysec 每秒 fsync 抖动明显时可考虑 no-appendfsync-on-rewrite yes；RDB fork 期间写操作延迟会短暂上升。', 'MEDIUM', 2, 88),
('redis-action', 11, '第 11 章 部署、备份与故障排查', 'redis-action:11:89', '持久化选型', '持久化选型：纯缓存可关 AOF/RDB；作存储建议 RDB+AOF 双开，或至少开 AOF everysec + 定时 RDB 快照。', 'MEDIUM', 2, 89),
('redis-action', 11, '第 11 章 部署、备份与故障排查', 'redis-action:11:90', '备份恢复', '备份恢复：直接复制 dump.rdb / appendonly.aof 文件；恢复前停服务，拷贝到 dir 目录后启动；校验 CRC 防损坏文件。', 'MEDIUM', 2, 90),
('redis-action', 11, '第 11 章 部署、备份与故障排查', 'redis-action:11:91', '主从切换演练', '主从切换演练：定期执行哨兵 failover 或手动 REPLICAOF NO ONE + 客户端重连验证，确保切换时长满足 SLA。', 'MEDIUM', 2, 91),
('redis-action', 11, '第 11 章 部署、备份与故障排查', 'redis-action:11:92', '内存溢出排查', '内存溢出排查：看 evicted_keys 是否激增、used_memory 逼近 maxmemory；若 noeviction 则出现 OOM 报错，应扩容或调整策略。', 'MEDIUM', 2, 92),
('redis-action', 11, '第 11 章 部署、备份与故障排查', 'redis-action:11:93', '复制中断排查', '复制中断排查：INFO replication 看 master_link_status=down、master_last_io_seconds_ago；常见原因密码错、网络断、backlog 不足、主库 too many clients。', 'MEDIUM', 2, 93),
('redis-action', 11, '第 11 章 部署、备份与故障排查', 'redis-action:11:94', '慢命令处理流程', '慢命令处理流程：SLOWLOG 拿到慢命令 → EXPLAIN/索引优化 → 改写为批量/SCAN → 复核基准；必要时限流保护。', 'MEDIUM', 2, 94),
('redis-action', 11, '第 11 章 部署、备份与故障排查', 'redis-action:11:95', '拒绝连接 rejected_connections：通常是 maxclients', '拒绝连接 rejected_connections：通常是 maxclients 达到上限或 fd 资源耗尽；排查 CLIENT LIST 中异常长连接与未释放客户端。', 'MEDIUM', 2, 95),
('redis-action', 11, '第 11 章 部署、备份与故障排查', 'redis-action:11:96', '时钟与过期异常', '时钟与过期异常：主从/集群节点时钟漂移会导致 TTL 判断异常，NTP 校时是基础要求。', 'EASY', 2, 96),
('redis-action', 11, '第 11 章 部署、备份与故障排查', 'redis-action:11:97', '升级与平滑发布', '升级与平滑发布：低峰期滚动升级从库 → 提升为哨兵接管 → 升级原主；保留回滚包与配置版本。', 'MEDIUM', 2, 97),
('redis-action', 11, '第 11 章 部署、备份与故障排查', 'redis-action:11:98', '容量规划', '容量规划：按「峰值 QPS × 单请求内存 × 副本系数 × 1.5 冗余」估算内存；监控 ops、带宽、CPU 三件套决定是否分片。', 'MEDIUM', 2, 98)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('java-basics', 1, '第 1 章 Java 概述与开发环境搭建', 'java-basics:1:1', 'JDK、JRE、JVM 的关系', 'JDK、JRE、JVM 的关系：JVM（Java Virtual Machine）是执行字节码的虚拟机，是"一次编译、到处运行"的核心；JRE（Java Runtime Environment）= JVM + 核心类库，用于运行 Java 程序；JDK（Java Development Kit）= JRE + 编译器 javac、打包 jar、调试 jdb 等开发工具，开发者安装的是 JDK。三者关系为 JDK ⊃ JRE ⊃ JVM。', 'MEDIUM', 2, 1),
('java-basics', 1, '第 1 章 Java 概述与开发环境搭建', 'java-basics:1:2', '跨平台原理', '跨平台原理：Java 源码经 javac Hello.java 编译为与平台无关的 .class 字节码，再由不同平台的 JVM（Windows/Linux/macOS 各自的 JVM 实现）解释或即时编译（JIT）执行，从而屏蔽底层操作系统差异；但 JVM 本身是与平台相关的，因此需下载对应版本的 JDK。【补充】', 'MEDIUM', 2, 2),
('java-basics', 1, '第 1 章 Java 概述与开发环境搭建', 'java-basics:1:3', '环境变量 path 与 classpath', '环境变量 path 与 classpath：path 让操作系统能在任意目录找到 java、javac 命令，指向 JDK 的 bin 目录；classpath（JDK 1.5 之后通常可省略）告诉 JVM 到哪里查找 .class 文件，如 -cp .;lib/mysql.jar。配置后在命令行执行 java -version、javac -version 验证。', 'MEDIUM', 2, 3),
('java-basics', 1, '第 1 章 Java 概述与开发环境搭建', 'java-basics:1:4', '第一个 Java 程序', '第一个 Java 程序：定义 public class HelloWorld，其中 main 方法签名必须为 public static void main(String[] args)（入口方法），用 System.out.println("Hello World") 输出；编译运行步骤为 javac HelloWorld.java 生成 HelloWorld.class，再 java HelloWorld（注意不带 .class 后缀）。', 'MEDIUM', 2, 4),
('java-basics', 1, '第 1 章 Java 概述与开发环境搭建', 'java-basics:1:5', '常见命名与规范约定', '常见命名与规范约定：类名采用大驼峰（HelloWorld），变量/方法名采用小驼峰（userName）、常量全大写加下划线（MAX_SIZE）、包名全小写并用点号分层（com.atguigu.java）；源文件名必须与 public class 同名且区分大小写。', 'MEDIUM', 2, 5),
('java-basics', 1, '第 1 章 Java 概述与开发环境搭建', 'java-basics:1:6', '集成开发环境与常用插件', '集成开发环境与常用插件：IntelliJ IDEA 与 Eclipse 是最常用的两种 IDE；IDEA 用 Project→Module→Package 层级组织，快捷键 Alt+Enter 快速修复、Ctrl+Alt+L 格式化；Eclipse 用 Workspace→Project→Package。掌握断点调试（Debug 模式下的 Step Over/Step Into/Resume）比单纯会写代码更重要。【补充】', 'MEDIUM', 2, 6),
('java-basics', 2, '第 2 章 Java 基本语法与流程控制', 'java-basics:2:7', '标识符与关键字', '标识符与关键字：标识符由字母、数字、_、$ 组成，不能以数字开头，不能使用关键字和保留字（如 class、public、static、void、int），严格区分大小写；goto、const 是保留但未使用的关键字。命名应见名知意。', 'MEDIUM', 2, 7),
('java-basics', 2, '第 2 章 Java 基本语法与流程控制', 'java-basics:2:8', '常量与变量', '常量与变量：常量用 final 修饰（如 final double PI = 3.14159;），赋值后不可变；变量是内存中一个带名字的存储区域，使用前必须声明并初始化。变量按位置分为成员变量（类内方法外，有默认值）和局部变量（方法/代码块内，无默认值、必须先赋值再用）。', 'MEDIUM', 2, 8),
('java-basics', 2, '第 2 章 Java 基本语法与流程控制', 'java-basics:2:9', '八种基本数据类型', '八种基本数据类型：整型 byte(1B,-128~127)、short(2B)、int(4B，默认)、long(8B，字面量加 L)；浮点型 float(4B，字面量加 F)、double(8B，默认)；字符型 char(2B，单引号 ''A''、支持 Unicode)；布尔型 boolean(true/false)。注意 long 字面量 10L、float 字面量 3.14F。', 'MEDIUM', 2, 9),
('java-basics', 2, '第 2 章 Java 基本语法与流程控制', 'java-basics:2:10', '基本类型转换', '基本类型转换：自动（隐式）转换按容量从小到大：byte→short→char→int→long→float→double；强制（显式）转换用小括号 (int)3.9 得到 3（直接截断小数，不四舍五入），可能丢失精度；表达式中不同类型运算会自动提升到最大类型。', 'MEDIUM', 2, 10),
('java-basics', 2, '第 2 章 Java 基本语法与流程控制', 'java-basics:2:11', '运算符与优先级', '运算符与优先级：算术 + - * / % ++ --、关系 == != > < >= <=、逻辑 && || ! & | ^、位运算 & | ^ ~ << >> >>>、赋值 = += -= *= /= %=、三元 条件?值1:值2；特别注意 && 短路而 & 非短路，|| 与 | 同理。', 'MEDIUM', 2, 11),
('java-basics', 2, '第 2 章 Java 基本语法与流程控制', 'java-basics:2:12', 'if / switch 分支', 'if / switch 分支：if...else if...else 用于区间/条件判断；switch(表达式) 支持 byte/short/int/char/枚举/String(JDK7+)/包装类，每个 case 一般要 break，否则发生"穿透"；JDK12+ 支持 switch 箭头语法与返回值。', 'MEDIUM', 2, 12),
('java-basics', 2, '第 2 章 Java 基本语法与流程控制', 'java-basics:2:13', 'for / while / do-while 循环：for(初始化;条件;迭代)', 'for / while / do-while 循环：for(初始化;条件;迭代) 适合已知次数；while 先判断后执行；do...while 至少执行一次；增强 for（for(int x : arr)）用于遍历数组与集合，不能修改集合结构。', 'MEDIUM', 2, 13),
('java-basics', 2, '第 2 章 Java 基本语法与流程控制', 'java-basics:2:14', 'break、continue 与循环标签', 'break、continue 与循环标签：break 结束当前循环或 switch，continue 跳过本次进入下一轮；带标签的 break outer; 可跳出多重循环；return 直接结束方法。避免死循环与在循环内重复创建对象。', 'MEDIUM', 2, 14),
('java-basics', 3, '第 3 章 数组', 'java-basics:3:15', '数组的定义与声明', '数组的定义与声明：数组是长度固定的相同类型元素集合；声明方式 int[] arr; 或 int arr[];，动态初始化 arr = new int[5];（元素取默认值 0/null/false），静态初始化 int[] arr = {1,2,3}; 或 new int[]{1,2,3}；数组长度通过 arr.length 获取。', 'MEDIUM', 2, 15),
('java-basics', 3, '第 3 章 数组', 'java-basics:3:16', '一维数组的内存模型', '一维数组的内存模型：引用变量 arr 存放堆中数组对象的首地址（栈→堆），数组元素在堆中连续存放；null 表示引用未指向任何对象，直接调用其 length 或元素会抛 NullPointerException。【补充】', 'MEDIUM', 2, 16),
('java-basics', 3, '第 3 章 数组', 'java-basics:3:17', '二维数组', '二维数组：本质是"数组的数组"，int[][] matrix = new int[3][4]; 或 {{1,2},{3,4,5}}（每行长度可不等，即锯齿数组）；访问 matrix[i][j]，遍历需双重循环，外层 matrix.length 为行数、内层 matrix[i].length 为列数。', 'MEDIUM', 2, 17),
('java-basics', 3, '第 3 章 数组', 'java-basics:3:18', 'Arrays 工具类常用方法', 'Arrays 工具类常用方法：Arrays.toString(arr) 打印数组、Arrays.sort(arr) 升序（自然排序）、Arrays.binarySearch(arr,key) 折半查找（要求有序，返回下标）、Arrays.copyOf(arr,newLen) 复制、Arrays.equals(a,b) 判等、Arrays.fill(arr,val) 填充。', 'MEDIUM', 2, 18),
('java-basics', 3, '第 3 章 数组', 'java-basics:3:19', '数组常见算法', '数组常见算法：冒泡排序（相邻比较交换，平均 O(n²)）、选择排序、插入排序；折半查找（前提是已排序，O(log n)）；数组反转（首尾对调 swap(arr,i,len-1-i)）。这些算法是理解时间复杂度与指针移动的基础训练。', 'EASY', 2, 19),
('java-basics', 3, '第 3 章 数组', 'java-basics:3:20', '数组中的常见异常', '数组中的常见异常：ArrayIndexOutOfBoundsException（下标越界，如访问 arr[arr.length]）、NullPointerException（数组或其元素为 null）；避免方式：循环用 < length 而非 <=，访问前做非空判断。', 'MEDIUM', 2, 20),
('java-basics', 3, '第 3 章 数组', 'java-basics:3:21', '数组与面向对象的关系', '数组与面向对象的关系：数组只能存同一类型且长度不可变，当需要"长度可变 + 多种类型 + 增删改查"时，就过渡到 Java 集合框架（ArrayList 底层正是 Object[] 数组 + 扩容机制）。', 'MEDIUM', 2, 21),
('java-basics', 4, '第 4 章 封装与类与对象', 'java-basics:4:22', '类与对象的概念', '类与对象的概念：类是对一类事物的抽象描述（属性 + 行为），对象是类的实例；定义类用 class 类名 { 成员变量; 方法; }，创建对象用 new 关键字，如 Person p = new Person();，通过 p.属性、p.方法() 访问。', 'MEDIUM', 2, 22),
('java-basics', 4, '第 4 章 封装与类与对象', 'java-basics:4:23', '成员变量与成员方法', '成员变量与成员方法：成员变量描述对象的属性（有默认值：数值 0、char ''\u0000''、boolean false、引用 null）；成员方法描述对象的行为；方法由"修饰词 返回值类型 方法名(参数列表) 方法体"构成，无返回值用 void，return 用于结束方法并返回结果。', 'MEDIUM', 2, 23),
('java-basics', 4, '第 4 章 封装与类与对象', 'java-basics:4:24', '构造方法', '构造方法：构造方法与类同名、无返回值类型（连 void 都不写），用于创建对象时初始化成员变量；若未定义任何构造方法，编译器提供默认无参构造，一旦自定义构造方法则默认构造消失；可通过 this() 调用本类其他构造方法（必须放在首行）。', 'MEDIUM', 2, 24),
('java-basics', 4, '第 4 章 封装与类与对象', 'java-basics:4:25', 'this 关键字', 'this 关键字：this 代表当前对象引用，用途有三：① 区分同名局部变量与成员变量（this.name = name;）；② 在成员方法中调用本类其他方法；③ 在构造方法首行调用本类其他构造方法 this(参数);。', 'MEDIUM', 2, 25),
('java-basics', 4, '第 4 章 封装与类与对象', 'java-basics:4:26', 'static 关键字与类成员', 'static 关键字与类成员：static 修饰的成员变量（静态变量/类变量）与方法（静态方法）属于类而不属于某个对象，可通过 类名.成员 直接访问；静态方法中不能直接使用非静态成员（因为无 this）；静态代码块 static{} 在类加载时执行一次，常用于初始化资源。', 'MEDIUM', 2, 26),
('java-basics', 4, '第 4 章 封装与类与对象', 'java-basics:4:27', '封装与权限修饰符', '封装与权限修饰符：封装是"隐藏内部实现细节、对外仅暴露安全接口"的思想，通过给成员变量加 private 并提供 public 的 getXxx()/setXxx() 实现；四种权限从小到大为 private（仅本类）＜ 缺省/默认（同包）＜ protected（同包 + 子类）＜ public（所有类）。', 'MEDIUM', 2, 27),
('java-basics', 4, '第 4 章 封装与类与对象', 'java-basics:4:28', '方法重载与参数传递', '方法重载与参数传递：方法重载要求方法名相同、参数列表不同（类型/个数/顺序），与返回值和权限无关；Java 的方法参数传递只有值传递——基本类型传副本，引用类型传地址副本，因此方法内修改基本类型形参不影响实参，修改引用所指对象会影响实参对象。', 'MEDIUM', 2, 28),
('java-basics', 5, '第 5 章 继承、多态、抽象类与接口', 'java-basics:5:29', '继承（extends）', '继承（extends）：子类 class B extends A 拥有父类非 private 的全部成员，实现代码复用；Java 只支持单继承（一个类只能有一个直接父类），但可以多级继承（A←B←C）；子类可以扩展自己的成员，也可以通过 super.属性/super.方法() 访问父类成员，构造方法中用 super(...) 调用父类构造（必须首行，且与 this() 二者只能选一）。', 'MEDIUM', 2, 29),
('java-basics', 5, '第 5 章 继承、多态、抽象类与接口', 'java-basics:5:30', '方法重写（Override）', '方法重写（Override）：子类重新定义父类方法，要求方法名、参数列表、返回值（子类返回值须是父类返回值的子类/相同）一致；重写方法权限不能更严格（不能缩小），抛出的异常不能更多；调用时"编译看左边、运行看右边"——父类引用指向子类对象时执行子类重写的方法。@Override 注解用于让编译器帮助检查。', 'MEDIUM', 2, 30),
('java-basics', 5, '第 5 章 继承、多态、抽象类与接口', 'java-basics:5:31', '多态（Polymorphism）', '多态（Polymorphism）：多态的前提是具有继承/实现关系和方法重写；表现形式为"父类引用指向子类对象"（Animal a = new Dog();），运行时根据实际对象类型调用对应方法，从而实现"一个接口、多种形态"，使程序易于扩展；多态不能调用子类特有的方法，需要时用 instanceof 判断后强转 (Dog)a。', 'MEDIUM', 2, 31),
('java-basics', 5, '第 5 章 继承、多态、抽象类与接口', 'java-basics:5:32', 'instanceof 与向下转型', 'instanceof 与向下转型：对象 instanceof 类/接口 用于判断该对象是否为某类型的实例，避免强转抛 ClassCastException；用法 if(a instanceof Dog){ Dog d = (Dog)a; d.watchDoor(); }。JDK14+ 支持模式匹配 if(a instanceof Dog d){ ... }。', 'MEDIUM', 2, 32),
('java-basics', 5, '第 5 章 继承、多态、抽象类与接口', 'java-basics:5:33', 'final 关键字', 'final 关键字：修饰类表示不能被继承（如 String、Integer）；修饰方法表示不能被子类重写；修饰变量表示常量（只能赋值一次）。三处含义均与"不可变"相关。', 'MEDIUM', 2, 33),
('java-basics', 5, '第 5 章 继承、多态、抽象类与接口', 'java-basics:5:34', '抽象类（abstract class）', '抽象类（abstract class）：用 abstract 修饰的类不能被实例化，可包含抽象方法（只有声明无方法体 public abstract void eat();）、非抽象方法与成员变量；适用于"不完整但有共性"的父类场景，子类必须重写全部抽象方法或自己也声明为抽象类。', 'MEDIUM', 2, 34),
('java-basics', 5, '第 5 章 继承、多态、抽象类与接口', 'java-basics:5:35', '接口（interface）', '接口（interface）：接口是纯粹的抽象契约，用 interface 定义，方法默认 public abstract、属性默认 public static final；类用 implements 实现接口，可实现多个接口以弥补单继承不足；JDK8 后接口可含 default 默认方法与 static 方法，JDK9 后可含 private 方法。抽象类强调"是什么"（is-a），接口强调"能做什么"（can-do）。', 'MEDIUM', 2, 35),
('java-basics', 5, '第 5 章 继承、多态、抽象类与接口', 'java-basics:5:36', 'Object 类与常用方法', 'Object 类与常用方法：所有类默认继承 java.lang.Object；重要方法有 toString()（默认返回类名@哈希，常重写）、equals(Object obj)（默认比较地址，String/包装类已重写为比较内容，一般与 hashCode() 一起重写）、getClass()、hashCode()、clone()、finalize()。', 'MEDIUM', 2, 36),
('java-basics', 5, '第 5 章 继承、多态、抽象类与接口', 'java-basics:5:37', '包（package）与导入（import）', '包（package）与导入（import）：package com.xxx.yyy; 声明类所属包（放在文件首行），包名对应目录结构；import java.util.ArrayList; 导入其他包的类，import java.util.*; 导入包下全部类；java.lang 包自动导入无需书写。', 'MEDIUM', 2, 37),
('java-basics', 6, '第 6 章 内部类与常用类', 'java-basics:6:38', '成员内部类', '成员内部类：定义在类中、方法外的类，可用 private/public/protected/缺省 修饰，能访问外部类全部成员（含 private），外部访问需先建外部对象 Outer.Inner in = new Outer().new Inner();；适用于内部类只为外部类服务的场景。', 'MEDIUM', 2, 38),
('java-basics', 6, '第 6 章 内部类与常用类', 'java-basics:6:39', '局部内部类与匿名内部类', '局部内部类与匿名内部类：局部内部类定义在方法内，作用域限于该方法；匿名内部类是没有名字的内部类，语法 new 接口/父类(){ 重写方法 };，常用于事件监听、线程创建（new Thread(new Runnable(){ public void run(){...} }).start();），是 Lambda 出现前回调的标准写法。', 'MEDIUM', 2, 39),
('java-basics', 6, '第 6 章 内部类与常用类', 'java-basics:6:40', '静态内部类', '静态内部类：用 static 修饰的内部类，不持有外部类实例引用，可直接 new Outer.StaticInner()；常用于与外部类关系弱但需逻辑内聚的场景。', 'MEDIUM', 2, 40),
('java-basics', 6, '第 6 章 内部类与常用类', 'java-basics:6:41', 'String 类的特点', 'String 类的特点：String 是不可变字符序列（底层 private final char[] value，JDK9 后为 byte[]），字面量 String s = "abc" 存于字符串常量池，相同字面量共享同一对象；new String("abc") 则在堆中新建对象。常用方法 length()、charAt(i)、equals()、equalsIgnoreCase()、indexOf()、substring()、replace()、split()、trim()、toCharArray()。', 'MEDIUM', 2, 41),
('java-basics', 6, '第 6 章 内部类与常用类', 'java-basics:6:42', 'StringBuilder 与 StringBuffer：二者是可变字符序列，适', 'StringBuilder 与 StringBuffer：二者是可变字符序列，适用于频繁拼接场景；StringBuilder 非线程安全、速度快，StringBuffer 线程安全（方法加 synchronized）、速度略慢；常用方法 append()、insert()、delete()、reverse()、toString()。循环中拼串务必用 StringBuilder 而非 +。', 'MEDIUM', 2, 42),
('java-basics', 6, '第 6 章 内部类与常用类', 'java-basics:6:43', '包装类与装箱拆箱', '包装类与装箱拆箱：8 个基本类型对应 8 个包装类（Integer、Double、Boolean 等），用于集合泛型、数据库映射等场景；Integer.valueOf(i)、intValue() 完成装箱/拆箱，JDK5 起支持自动装箱 Integer a = 10; 与自动拆箱；Integer 缓存 -128~127，故 Integer a=127,b=127; a==b 为 true，而 128 时为 false，比较内容应用 equals()。', 'MEDIUM', 2, 43),
('java-basics', 6, '第 6 章 内部类与常用类', 'java-basics:6:44', 'BigDecimal 与数值计算', 'BigDecimal 与数值计算：float/double 是二进制浮点，无法精确表示 0.1 等小数，金融计算必须用 java.math.BigDecimal，通过 new BigDecimal("0.1")（避免用 double 构造）与 add/subtract/multiply/divide(scale, RoundingMode) 运算，divide 需指定精度与舍入模式。', 'MEDIUM', 2, 44),
('java-basics', 6, '第 6 章 内部类与常用类', 'java-basics:6:45', '日期时间类（旧与新）', '日期时间类（旧与新）：旧式 Date（毫秒时间戳，new Date()、getTime()）、Calendar（getInstance()、get(Calendar.YEAR)、set/add）、SimpleDateFormat（线程不安全）；JDK8 起推荐 LocalDate/LocalTime/LocalDateTime、DateTimeFormatter、Instant、Duration/Period，新 API 不可变且线程安全。', 'MEDIUM', 2, 45),
('java-basics', 6, '第 6 章 内部类与常用类', 'java-basics:6:46', 'System、Math 与 Random', 'System、Math 与 Random：System.currentTimeMillis()/System.nanoTime() 取时间戳、System.arraycopy() 高效复制数组、System.exit() 退出；Math.random() 生成 [0,1) 随机小数、Math.pow/sqrt/abs/round；Random r = new Random(); r.nextInt(bound) 生成指定范围随机整数。', 'MEDIUM', 2, 46),
('java-basics', 6, '第 6 章 内部类与常用类', 'java-basics:6:47', '枚举 enum', '枚举 enum：enum Season { SPRING, SUMMER, AUTUMN, WINTER } 定义一组有限常量，可带构造、字段、方法；相比 public static final 常量，枚举更安全、可读性更好、天然单例。', 'MEDIUM', 2, 47),
('java-basics', 7, '第 7 章 异常处理', 'java-basics:7:48', '异常体系结构', '异常体系结构：Throwable 是所有错误与异常的顶层父类，直接子类为 Error（严重系统错误如 OutOfMemoryError、StackOverflowError，程序不应捕获）与 Exception（可处理异常）；Exception 又分编译时异常（受检，如 IOException、SQLException）和运行时异常（非受检，如 NullPointerException、ArithmeticException、ArrayIndexOutOfBoundsException）。', 'MEDIUM', 2, 48),
('java-basics', 7, '第 7 章 异常处理', 'java-basics:7:49', 'try-catch-finally 基本用法', 'try-catch-finally 基本用法：try{ 可能出错代码 } catch(异常类型 e){ 处理 } finally{ 一定执行 }；finally 常用于释放资源（关闭流、数据库连接），即使 try/catch 中有 return 也会执行（除非 System.exit）；一个 try 可有多个 catch，子类异常必须写在父类之前。', 'MEDIUM', 2, 49),
('java-basics', 7, '第 7 章 异常处理', 'java-basics:7:50', 'catch 的高级写法', 'catch 的高级写法：JDK7+ 支持多异常捕获 catch(IOException | SQLException e)；catch 块中可用 e.getMessage() 取描述、e.printStackTrace() 打印堆栈；不要写空的 catch 块吞掉异常。', 'MEDIUM', 2, 50),
('java-basics', 7, '第 7 章 异常处理', 'java-basics:7:51', 'throw 与 throws', 'throw 与 throws：throw 用于在方法体内主动抛出异常对象 throw new IllegalArgumentException("参数非法");；throws 写在方法签名上声明可能抛出的异常类型（多个用逗号分隔），调用者必须处理（继续 throws 或 try-catch）；RuntimeException 及其子类属于非受检异常，可不声明。', 'MEDIUM', 2, 51),
('java-basics', 7, '第 7 章 异常处理', 'java-basics:7:52', '异常处理原则', '异常处理原则：① 能处理就处理，不能处理就向上抛；② 用具体异常类型而非笼统的 Exception；③ 不忽略异常、不打印后继续；④ 异常不要用于正常流程控制（性能开销大、语义差）。', 'MEDIUM', 2, 52),
('java-basics', 7, '第 7 章 异常处理', 'java-basics:7:53', '自定义异常', '自定义异常：继承 Exception（受检）或 RuntimeException（非受检），类名以 Exception 结尾，提供无参构造与带 message 的构造，例如 class AgeException extends RuntimeException { public AgeException(String msg){ super(msg); } }，便于业务层给出语义化错误。', 'MEDIUM', 2, 53),
('java-basics', 7, '第 7 章 异常处理', 'java-basics:7:54', 'try-with-resources 与异常链', 'try-with-resources 与异常链：JDK7 引入 try(资源){}，实现 AutoCloseable 的资源自动关闭，避免 finally 中重复关闭；可通过 Throwable 的构造参数或 initCause() 保存异常链，保留原始异常便于定位根因。', 'MEDIUM', 2, 54),
('java-basics', 8, '第 8 章 泛型', 'java-basics:8:55', '为什么需要泛型', '为什么需要泛型：没有泛型时集合中存 Object，取出需强转，编译期无法发现类型错误，易抛 ClassCastException；泛型把类型检查提前到编译期，实现"类型安全 + 代码复用"。', 'MEDIUM', 2, 55),
('java-basics', 8, '第 8 章 泛型', 'java-basics:8:56', '泛型类与泛型接口', '泛型类与泛型接口：class Box<T>{ private T item; public void set(T t){...} public T get(){...} }，T 为类型参数，使用时 Box<String> box = new Box<>();；接口 interface Info<T>{ T get(); } 的实现方式有两种：实现类继续保留泛型，或实现类直接指定具体类型。', 'MEDIUM', 2, 56),
('java-basics', 8, '第 8 章 泛型', 'java-basics:8:57', '泛型方法', '泛型方法：泛型方法在返回值前声明类型参数 public <E> E getFirst(List<E> list){ return list.get(0); }；调用时由实参推断类型，与泛型类独立。', 'MEDIUM', 2, 57),
('java-basics', 8, '第 8 章 泛型', 'java-basics:8:58', '通配符 ?、extends 与 super', '通配符 ?、extends 与 super：List<?> 表示任意类型、只能读不能写未知类型；List<? extends Number>（上界通配符）可读出 Number、不能写入（生产者 PECS 的 Producer）；List<? super Integer>（下界通配符）可写入 Integer、只能按 Object 读出（消费者 Consumer）。记忆口诀：PECS = Producer Extends, Consumer Super。', 'MEDIUM', 2, 58),
('java-basics', 8, '第 8 章 泛型', 'java-basics:8:59', '类型擦除', '类型擦除：泛型只在编译期存在，编译后字节码中 T 被替换为上界（无界为 Object）并插入强制转换，因此运行时无法用反射获取泛型的具体类型参数，List<String> 与 List<Integer> 的 getClass() 相同；这是实现泛型的方式带来的固有限制。', 'MEDIUM', 2, 59),
('java-basics', 8, '第 8 章 泛型', 'java-basics:8:60', '泛型与数组、静态成员的限制', '泛型与数组、静态成员的限制：不能 new T()、new T[10]，不能用基本类型作类型参数（需用包装类），泛型类的静态成员不能使用类的类型参数（静态成员属于类而非实例）。', 'MEDIUM', 2, 60),
('java-basics', 9, '第 9 章 集合框架', 'java-basics:9:61', '集合框架两大体系', '集合框架两大体系：Collection 存储"单个对象"（List 有序可重复、Set 无序不可重复），Map 存储"键值对"；顶层接口 Iterable/Collection/Map，实现类 ArrayList/LinkedList/Vector、HashSet/TreeSet/LinkedHashSet、HashMap/TreeMap/Hashtable。所有集合都可通过 size()、isEmpty()、contains()、remove() 操作。', 'MEDIUM', 2, 61),
('java-basics', 9, '第 9 章 集合框架', 'java-basics:9:62', 'Iterator 迭代器', 'Iterator 迭代器：Iterator it = list.iterator(); while(it.hasNext()){ Object o = it.next(); }，迭代器提供了统一遍历方式；遍历时不能直接用集合的 remove 增删元素，否则抛 ConcurrentModificationException，应使用 it.remove() 或用并发集合。增强 for 底层就是 Iterator。', 'MEDIUM', 2, 62),
('java-basics', 9, '第 9 章 集合框架', 'java-basics:9:63', 'ArrayList 与 LinkedList', 'ArrayList 与 LinkedList：ArrayList 底层是动态数组，按下标随机访问快 O(1)、中间插入删除慢 O(n)、默认容量 10、扩容 1.5 倍；LinkedList 底层是双向链表，头尾插入删除快 O(1)、按下标访问慢 O(n)，同时实现了 Deque 可作队列/双端队列；查询多用 ArrayList、频繁增删多用 LinkedList。', 'MEDIUM', 2, 63),
('java-basics', 9, '第 9 章 集合框架', 'java-basics:9:64', 'HashSet、TreeSet 与去重原理', 'HashSet、TreeSet 与去重原理：HashSet 基于 HashMap，add 时按 hashCode() 定位桶、再用 equals() 判等，因此放入 HashSet 的对象必须重写 hashCode() 与 equals() 且二者保持一致；TreeSet 基于红黑树，按自然排序或 Comparator 排序、元素不重复且有序，放入对象需"可比较"。', 'MEDIUM', 2, 64),
('java-basics', 9, '第 9 章 集合框架', 'java-basics:9:65', 'LinkedHashSet 与顺序', 'LinkedHashSet 与顺序：LinkedHashSet 在 HashSet 基础上用链表维护插入顺序，迭代顺序稳定，适合需要"既去重又保持输入顺序"的场景。', 'EASY', 2, 65),
('java-basics', 9, '第 9 章 集合框架', 'java-basics:9:66', 'HashMap 的存储与使用', 'HashMap 的存储与使用：HashMap 存键值对，允许一个 null 键与多个 null 值，通过 put(k,v)、get(k)、containsKey、keySet、values、entrySet 操作；JDK8 底层为数组 + 链表 + 红黑树（链表长度≥8 且数组长度≥64 时转红黑树），默认容量 16、负载因子 0.75、扩容 2 倍，用 hashCode 扰动减少冲突。', 'MEDIUM', 2, 66),
('java-basics', 9, '第 9 章 集合框架', 'java-basics:9:67', 'TreeMap 与 Hashtable', 'TreeMap 与 Hashtable：TreeMap 基于红黑树、按键排序，可传 Comparator；Hashtable 是早期线程安全的 Map（方法加 synchronized），不允许 null 键值，现已被 ConcurrentHashMap 取代。遍历时优先用 entrySet() 而非先 keySet() 再 get()（后者会重复哈希）。', 'MEDIUM', 2, 67),
('java-basics', 9, '第 9 章 集合框架', 'java-basics:9:68', 'Collections 工具类与排序', 'Collections 工具类与排序：Collections.sort(list)、Collections.sort(list, Comparator)、Collections.reverse/list、Collections.shuffle、Collections.max/min、Collections.frequency、Collections.synchronizedList；对象要实现排序可实现 Comparable 并重写 compareTo()，或传入 Comparator 并重写 compare()。', 'MEDIUM', 2, 68),
('java-basics', 9, '第 9 章 集合框架', 'java-basics:9:69', '集合的选择策略', '集合的选择策略：查多写少选 ArrayList、写多选 LinkedList；去重选 HashSet、有序选 TreeSet/LinkedHashSet；键值映射选 HashMap、需排序选 TreeMap、并发选 ConcurrentHashMap。', 'MEDIUM', 2, 69),
('java-basics', 10, '第 10 章 IO 流与 NIO 入门', 'java-basics:10:70', 'IO 流的分类', 'IO 流的分类：按方向分输入流（InputStream/Reader）与输出流（OutputStream/Writer）；按单位分字节流（InputStream/OutputStream，处理二进制与一切数据）与字符流（Reader/Writer，处理文本、自动按编码转换）；按功能分节点流（直接接数据源）与处理流/过滤流（包装别的流，如缓冲流）。', 'MEDIUM', 2, 70),
('java-basics', 10, '第 10 章 IO 流与 NIO 入门', 'java-basics:10:71', '字节流读写', '字节流读写：FileInputStream fis = new FileInputStream("a.txt"); int b; while((b=fis.read())!=-1){...} 单字节读效率低；FileOutputStream fos = new FileOutputStream("b.txt", true); fos.write(bytes);（第二参数 true 表示追加）；用完必须在 finally 或 try-with-resources 中 close()。', 'MEDIUM', 2, 71),
('java-basics', 10, '第 10 章 IO 流与 NIO 入门', 'java-basics:10:72', '缓冲流与转换流', '缓冲流与转换流：BufferedInputStream/BufferedOutputStream、BufferedReader/BufferedWriter 内部维护缓冲区，显著提升读写效率，BufferedReader.readLine()、BufferedWriter.newLine() 是文本处理常用方法；InputStreamReader/OutputStreamWriter 在字节流与字符流之间转换并可指定编码（如 UTF-8），用于解决中文乱码。', 'MEDIUM', 2, 72),
('java-basics', 10, '第 10 章 IO 流与 NIO 入门', 'java-basics:10:73', '对象序列化', '对象序列化：实现 Serializable 接口的类可用 ObjectOutputStream.writeObject(obj) 写入文件、ObjectInputStream.readObject() 读回；transient 修饰的字段不参与序列化，serialVersionUID 用于版本兼容校验，不显式声明会在类改动后导致反序列化失败。', 'MEDIUM', 2, 73),
('java-basics', 10, '第 10 章 IO 流与 NIO 入门', 'java-basics:10:74', 'File 类与目录操作', 'File 类与目录操作：File f = new File("d:/test.txt"); 可用 exists()、isFile()、isDirectory()、mkdirs()、listFiles()、delete()、getName()、getAbsolutePath() 进行文件与目录管理；注意 File 只表示路径信息，不表示文件真实存在。', 'MEDIUM', 2, 74),
('java-basics', 10, '第 10 章 IO 流与 NIO 入门', 'java-basics:10:75', 'NIO 三大组件入门', 'NIO 三大组件入门：JDK1.4 引入 NIO（New IO），核心是 Channel（通道，双向）、Buffer（缓冲区，存数据）、Selector（选择器，多路复用）；常用 Paths.get("a.txt") 得到 Path、Files.readAllLines(path)、Files.write(path, lines)、Files.copy/move/delete，NIO 适合高并发网络 IO。', 'EASY', 2, 75),
('java-basics', 10, '第 10 章 IO 流与 NIO 入门', 'java-basics:10:76', 'NIO 的 Buffer 使用要点', 'NIO 的 Buffer 使用要点：Buffer 有 capacity、position、limit、mark 四个指针；写入模式 put() 后需 flip() 切换为读模式才能 get()；读完后 clear() 或 compact() 复用；直接缓冲区（allocateDirect）减少一次内存拷贝，效率高但分配成本高。', 'MEDIUM', 2, 76),
('java-basics', 10, '第 10 章 IO 流与 NIO 入门', 'java-basics:10:77', 'IO 使用原则与乱码排查', 'IO 使用原则与乱码排查：① 字节流处理二进制（图片、音频、视频）、字符流处理文本；② 大量数据务必包一层 Buffered；③ 明确指定 UTF-8 编码读写；④ 所有流用完必须关闭（try-with-resources 最稳）；⑤ 乱码多为"写用什么编码、读用什么编码不一致"导致。', 'MEDIUM', 2, 77),
('java-basics', 11, '第 11 章 多线程', 'java-basics:11:78', '进程与线程', '进程与线程：进程是资源分配的最小单位，线程是 CPU 调度的最小单位；一个进程至少有一个主线程（main 线程），Java 中可通过继承 Thread 类或实现 Runnable/Callable 接口创建线程；推荐实现接口以避免单继承限制。', 'MEDIUM', 2, 78),
('java-basics', 11, '第 11 章 多线程', 'java-basics:11:79', '创建线程的两种方式', '创建线程的两种方式：① class MyThread extends Thread{ public void run(){...} }，new MyThread().start();；② class Task implements Runnable{ public void run(){...} }，new Thread(new Task()).start();；注意调用 start() 才会新建线程，直接调 run() 只是普通方法调用。', 'MEDIUM', 2, 79),
('java-basics', 11, '第 11 章 多线程', 'java-basics:11:80', '线程的生命周期', '线程的生命周期：新建（NEW）→ 就绪（RUNNABLE，调 start 后等待 CPU）→ 运行（RUNNING）→ 阻塞（BLOCKED/WAITING/TIMED_WAITING，等待锁、wait、sleep）→ 终止（TERMINATED）。sleep(ms) 让出 CPU 但不释放锁，yield() 提示调度器让出，join() 等待目标线程结束。', 'MEDIUM', 2, 80),
('java-basics', 11, '第 11 章 多线程', 'java-basics:11:81', '线程同步与 synchronized', '线程同步与 synchronized：多个线程共享数据时会出竞态条件；用 synchronized 修饰方法或同步代码块 synchronized(锁对象){...} 保证同一时刻只有一个线程进入临界区；锁对象可以是 this、类对象（静态同步）、任意专用对象，但不可用局部变量或 null。', 'MEDIUM', 2, 81),
('java-basics', 11, '第 11 章 多线程', 'java-basics:11:82', 'volatile 关键字', 'volatile 关键字：volatile 修饰的变量保证可见性（一处修改立即刷新到主存、他处读取立即可见）与禁止指令重排，但不保证原子性（i++ 仍不安全）；适用于状态标志位、单例双重检查锁等场景。', 'MEDIUM', 2, 82),
('java-basics', 11, '第 11 章 多线程', 'java-basics:11:83', 'wait / notify 机制', 'wait / notify 机制：在 synchronized 块内调用 wait() 释放锁并进入等待，notify()/notifyAll() 唤醒等待线程，被唤醒线程需重新竞争锁；生产消费模型必须用 while 而非 if 判断条件以防虚假唤醒；JDK5 后推荐用 Lock/Condition 替代。', 'MEDIUM', 2, 83),
('java-basics', 11, '第 11 章 多线程', 'java-basics:11:84', 'Lock 与线程池', 'Lock 与线程池：ReentrantLock 需手动 lock()/unlock()（unlock 放 finally），支持 tryLock()、公平锁、Condition 多条件；线程池 Executors.newFixedThreadPool(n) 等复用线程、控制并发数，任务实现 Runnable/Callable 并通过 submit() 提交、用 Future 取回结果。', 'MEDIUM', 2, 84),
('java-basics', 11, '第 11 章 多线程', 'java-basics:11:85', '线程安全集合', '线程安全集合：Vector、Hashtable 为早期线程安全实现但粒度粗；现代开发用 Collections.synchronizedList 包装或 java.util.concurrent 下的 CopyOnWriteArrayList、ConcurrentHashMap，后者分段/CAS 并发度高。', 'MEDIUM', 2, 85),
('java-basics', 11, '第 11 章 多线程', 'java-basics:11:86', '常见并发问题', '常见并发问题：死锁（互相持有对方需要的锁）、活锁、饥饿；排查可用 jstack、ThreadMXBean.findDeadlockedThreads()，避免在锁中嵌套获取多把锁、尽量减小同步范围。', 'MEDIUM', 2, 86),
('java-basics', 12, '第 12 章 网络编程与 JDBC 入门', 'java-basics:12:87', '网络编程三要素', '网络编程三要素：IP 地址（InetAddress.getLocalHost()、getByName("www.xxx.com")）、端口号（标识主机上的应用，0~65535，1024 以下为知名端口）、传输协议（TCP 可靠面向连接、UDP 快但不可靠无连接）。', 'MEDIUM', 2, 87),
('java-basics', 12, '第 12 章 网络编程与 JDBC 入门', 'java-basics:12:88', 'TCP 通信模型', 'TCP 通信模型：基于 Socket；服务器端 ServerSocket ss = new ServerSocket(8888); Socket s = ss.accept(); 获得连接，通过 s.getInputStream()/s.getOutputStream() 收发数据；客户端 Socket s = new Socket("127.0.0.1", 8888);；TCP 是字节流，收发完记得关流与 Socket。', 'MEDIUM', 2, 88),
('java-basics', 12, '第 12 章 网络编程与 JDBC 入门', 'java-basics:12:89', 'UDP 与 URL 通信', 'UDP 与 URL 通信：UDP 用 DatagramSocket 与 DatagramPacket 发送/接收数据包，无连接、可广播；URL url = new URL("http://..."); InputStream in = url.openStream(); 可直接抓取网页内容，是爬虫雏形。', 'MEDIUM', 2, 89),
('java-basics', 12, '第 12 章 网络编程与 JDBC 入门', 'java-basics:12:90', 'JDBC 概述与驱动', 'JDBC 概述与驱动：JDBC 是 Java 访问关系数据库的标准 API，位于 java.sql/javax.sql；核心接口 DriverManager、Connection、Statement、PreparedStatement、ResultSet；使用前需加载驱动 Class.forName("com.mysql.cj.jdbc.Driver")（JDBC 4.0 后可自动加载），并引入对应数据库驱动 jar。', 'EASY', 2, 90),
('java-basics', 12, '第 12 章 网络编程与 JDBC 入门', 'java-basics:12:91', 'JDBC 六步开发流程', 'JDBC 六步开发流程：① 注册驱动；② DriverManager.getConnection(url,user,password) 获取 Connection；③ 创建 Statement/PreparedStatement；④ 执行 SQL（executeQuery 返回 ResultSet、executeUpdate 返回影响行数）；⑤ 处理 ResultSet（next() 移动游标、getString("列名") 取值）；⑥ 逆序关闭 ResultSet→Statement→Connection。', 'MEDIUM', 2, 91),
('java-basics', 12, '第 12 章 网络编程与 JDBC 入门', 'java-basics:12:92', 'PreparedStatement 与防注入', 'PreparedStatement 与防注入：PreparedStatement 用占位符 ? 预编译 SQL，如 ps = conn.prepareStatement("select * from user where id=?"); ps.setInt(1,1001);，既提高重复执行效率，又从根本防止 SQL 注入，实际项目一律优先使用 PreparedStatement。', 'MEDIUM', 2, 92),
('java-basics', 12, '第 12 章 网络编程与 JDBC 入门', 'java-basics:12:93', '事务与连接池', '事务与连接池：JDBC 默认自动提交，需 conn.setAutoCommit(false); 后显式 commit()/rollback() 实现事务；生产环境用连接池（HikariCP、Druid、DBCP）复用连接，配合 try-with-resources 确保归还。', 'MEDIUM', 2, 93),
('java-basics', 13, '第 13 章 反射与注解及 JDK8+ 新特性', 'java-basics:13:94', '反射机制', '反射机制：反射是在运行时动态获取类信息并操作类成员的能力，核心类 java.lang.Class 及 java.lang.reflect 下的 Constructor、Method、Field；通过 Class.forName("全限定类名")、obj.getClass()、类名.class 三种方式获取 Class 对象。', 'MEDIUM', 2, 94),
('java-basics', 13, '第 13 章 反射与注解及 JDK8+ 新特性', 'java-basics:13:95', '反射的常用操作', '反射的常用操作：clazz.getConstructors() 取构造、clazz.getMethods() 取方法、clazz.getDeclaredFields() 取全部字段；method.invoke(obj,args) 调用方法、field.setAccessible(true) 突破 private 访问、field.set/get 读写属性；反射是 Spring IOC/AOP、MyBatis 映射、序列化框架的底层基础。', 'EASY', 2, 95),
('java-basics', 13, '第 13 章 反射与注解及 JDK8+ 新特性', 'java-basics:13:96', '注解与元注解', '注解与元注解：注解（Annotation）是源码中的元数据，可标在类、方法、字段上，编译或运行期生效；内置 @Override、@Deprecated、@SuppressWarnings；元注解 @Target（作用位置）、@Retention（保留到 SOURCE/CLASS/RUNTIME）、@Documented、@Inherited 用于自定义注解，运行期可读的注解必须声明 @Retention(RetentionPolicy.RUNTIME)。', 'MEDIUM', 2, 96),
('java-basics', 13, '第 13 章 反射与注解及 JDK8+ 新特性', 'java-basics:13:97', 'Lambda 表达式', 'Lambda 表达式：JDK8 引入的函数式语法，用于简化"只有一个抽象方法的接口"（函数式接口）实现，如 Runnable r = () -> System.out.println("hi");、Comparator<Integer> c = (a,b) -> a-b;；可替代匿名内部类，语法为 (参数) -> {方法体}。', 'MEDIUM', 2, 97),
('java-basics', 13, '第 13 章 反射与注解及 JDK8+ 新特性', 'java-basics:13:98', '函数式接口与常用内置接口', '函数式接口与常用内置接口：java.util.function 提供 Predicate<T>（判定，test）、Function<T,R>（转换，apply）、Consumer<T>（消费，accept）、Supplier<T>（供给，get），以及 andThen/compose 等组合方法，是 Stream 操作的基石。', 'MEDIUM', 2, 98),
('java-basics', 13, '第 13 章 反射与注解及 JDK8+ 新特性', 'java-basics:13:99', 'Stream 流式编程', 'Stream 流式编程：list.stream().filter(x->x>0).map(String::valueOf).sorted().collect(Collectors.toList())；流分中间操作（惰性，如 filter/map/sorted/distinct/limit）与终结操作（触发计算，如 forEach/count/collect/reduce）；Collectors.toList/toSet/toMap/joining/groupingBy 是最常用收集器。', 'MEDIUM', 2, 99),
('java-basics', 13, '第 13 章 反射与注解及 JDK8+ 新特性', 'java-basics:13:100', 'Optional 与空安全', 'Optional 与空安全：Optional<T> 容器用于表达"可能有值也可能为空"，Optional.ofNullable(obj).orElse(default)、map、filter、ifPresent 等 API 引导写出显式处理 null 的代码，减少 NullPointerException；不要用 Optional 做字段类型或方法参数。', 'MEDIUM', 2, 100),
('java-basics', 13, '第 13 章 反射与注解及 JDK8+ 新特性', 'java-basics:13:101', 'JDK 新特性速览（时间线）', 'JDK 新特性速览（时间线）：JDK5 泛型/枚举/注解/自动装箱；JDK7 try-with-resources、switch 支持 String、泛型菱形 <>；JDK8 Lambda、Stream、Optional、新日期 API、接口 default 方法；JDK9 模块化、接口 private 方法；JDK10 var 局部变量类型推断；后续版本持续增强 Record、Sealed Class、虚拟线程（JDK21）等。【补充】', 'MEDIUM', 2, 101)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('javaee-ssm', 1, '第 1 章 Java EE 与 Web 开发基础', 'javaee-ssm:1:1', 'C/S 与 B/S 架构对比', 'C/S 与 B/S 架构对比：C/S（Client/Server）需在客户端安装专用程序，升级维护成本高；B/S（Browser/Server）以浏览器为统一客户端，业务逻辑集中在服务器端，通过 HTTP 协议通信，具备"零部署、易维护"优势。Java EE 的 Web 开发即构建在 B/S 之上，理解这一演进是学习 Servlet/Spring MVC 的前提。【补充】', 'MEDIUM', 2, 1),
('javaee-ssm', 1, '第 1 章 Java EE 与 Web 开发基础', 'javaee-ssm:1:2', 'HTTP 协议的三要素与请求响应模型', 'HTTP 协议的三要素与请求响应模型：一次 HTTP 交互由请求行（方法 + URL + 版本）、请求头（Host/User-Agent/Content-Type/Cookie 等）、请求体（POST 数据）与服务器的状态行（如 HTTP/1.1 200 OK）、响应头、响应体构成；HTTP 是无状态协议，每个请求相互独立，这是会话技术产生的根本原因。', 'MEDIUM', 2, 2),
('javaee-ssm', 1, '第 1 章 Java EE 与 Web 开发基础', 'javaee-ssm:1:3', '常用请求方法与状态码语义', '常用请求方法与状态码语义：GET 用于获取资源、参数附在 URL 查询串中且长度受限；POST 用于提交数据、参数放请求体中更安全且可传大文件；常见状态码 200 成功、302 临时重定向、404 资源不存在、405 方法不允许、500 服务器内部异常、503 服务不可用，排错时应先看状态码定位问题层级。', 'MEDIUM', 2, 3),
('javaee-ssm', 1, '第 1 章 Java EE 与 Web 开发基础', 'javaee-ssm:1:4', 'URL、端口与 Web 应用目录结构', 'URL、端口与 Web 应用目录结构：URL 形如 http://主机:端口/上下文路径/资源路径，例如 http://localhost:8080/ch06/login.do；Web 应用标准目录为 WEB-INF/（含 web.xml、classes/、lib/，其下资源不可被浏览器直接访问）与静态资源目录，Tomcat 中一个上下文对应一个应用。', 'MEDIUM', 2, 4),
('javaee-ssm', 1, '第 1 章 Java EE 与 Web 开发基础', 'javaee-ssm:1:5', 'Tomcat 的安装、启动与核心目录', 'Tomcat 的安装、启动与核心目录：解压 Apache Tomcat 后关键目录为 bin/（startup.bat/shutdown.bat）、conf/（server.xml 配置端口与连接器、web.xml 全局默认配置）、webapps/（部署目录，放入 war 或展开目录即被扫描部署）、logs/（catalina.out 查看启动与运行日志）；默认端口 8080，可在 server.xml 的 <Connector port="8080"> 修改。', 'MEDIUM', 2, 5),
('javaee-ssm', 1, '第 1 章 Java EE 与 Web 开发基础', 'javaee-ssm:1:6', '手工创建并部署第一个 Web 应用', '手工创建并部署第一个 Web 应用：建立 HelloServlet 项目，写继承 HttpServlet 的类并在 web.xml 中用 <servlet>+<servlet-mapping> 注册（<url-pattern>/hello</url-pattern>），将编译产物放到 WEB-INF/classes，把整个应用复制到 webapps/ 下重启 Tomcat，浏览器访问 /项目名/hello 看到输出，从而建立"Servlet ↔ URL 映射"的直观认识。', 'MEDIUM', 2, 6),
('javaee-ssm', 1, '第 1 章 Java EE 与 Web 开发基础', 'javaee-ssm:1:7', '动态网页技术演进', '动态网页技术演进：从 CGI、ASP、PHP、JSP/Servlet 到 Spring MVC/前后端分离，本质都是"服务器生成内容返回浏览器"；Java EE 以 Servlet 为基石，JSP 作为视图模板，Spring MVC 在其上提供更强的分层与注解化能力，学习时应把握"请求驱动"这一主线而非死记 API。【补充】', 'MEDIUM', 2, 7),
('javaee-ssm', 2, '第 2 章 Servlet 技术', 'javaee-ssm:2:8', 'javax.servlet.Servlet 接口与生命周期：所有 Servlet', 'javax.servlet.Servlet 接口与生命周期：所有 Servlet 实现 Servlet 接口（通常继承 HttpServlet），生命周期由容器管理：加载类 → 调用无参构造 → init(ServletConfig)（仅一次，做初始化）→ 多次 service()（按请求方法分派到 doGet/doPost）→ 容器关闭时 destroy()（释放资源）。理解"init/destroy 只执行一次、service 每次请求执行"是并发问题分析的基础。', 'EASY', 2, 8),
('javaee-ssm', 2, '第 2 章 Servlet 技术', 'javaee-ssm:2:9', 'GenericServlet、HttpServlet 与模板方法模式：Gener', 'GenericServlet、HttpServlet 与模板方法模式：GenericServlet 实现了与协议无关的 service(ServletRequest,ServletResponse)；HttpServlet 覆写为按 request.getMethod() 分发到 doGet/doPost/doPut/doDelete，未覆写的方法默认返回 405 错误。这体现了模板方法设计模式——父类定骨架、子类填细节。', 'MEDIUM', 2, 9),
('javaee-ssm', 2, '第 2 章 Servlet 技术', 'javaee-ssm:2:10', 'HttpServletRequest 常用 API：getParameter(n', 'HttpServletRequest 常用 API：getParameter(name) 取单个请求参数、getParameterValues(name) 取复选框等多值参数、getParameterMap() 取全部参数；getHeader()、getCookies()、getSession()、getRequestURI()/getContextPath() 定位资源；setCharacterEncoding("UTF-8") 必须在取参数前调用才能正确处理中文 POST。', 'MEDIUM', 2, 10),
('javaee-ssm', 2, '第 2 章 Servlet 技术', 'javaee-ssm:2:11', 'HttpServletResponse 与输出写出：setContentType', 'HttpServletResponse 与输出写出：setContentType("text/html;charset=UTF-8") 设置响应类型与编码，getWriter() 获得字符流 PrintWriter 输出文本，getOutputStream() 获得字节流输出二进制（二者不可同时使用）；也可通过 setStatus() 与 sendError() 控制状态码与错误页。', 'MEDIUM', 2, 11),
('javaee-ssm', 2, '第 2 章 Servlet 技术', 'javaee-ssm:2:12', '转发（forward）与重定向（redirect）的区别：转发通过 reques', '转发（forward）与重定向（redirect）的区别：转发通过 request.getRequestDispatcher("/target").forward(request,response) 实现，属服务器内部跳转，地址栏不变、共享同一 request 域，可访问 WEB-INF 下资源；重定向通过 response.sendRedirect(request.getContextPath()+"/target") 实现，返回 302 让浏览器重新发起请求，地址栏变化、丢失 request 属性，可跳到外部站点。', 'MEDIUM', 2, 12),
('javaee-ssm', 2, '第 2 章 Servlet 技术', 'javaee-ssm:2:13', 'ServletConfig 与 ServletContext：ServletCo', 'ServletConfig 与 ServletContext：ServletConfig 作用于单个 Servlet，可读取该 Servlet 的 <init-param>；ServletContext 作用于整个 Web 应用（唯一实例），可读取全局 <context-param>、获取真实路径 getRealPath("/")、作为全局属性域共享数据、获取 MIME 类型与流式的资源读取。注意 ServletContext 存放大对象会常驻内存。', 'MEDIUM', 2, 13),
('javaee-ssm', 2, '第 2 章 Servlet 技术', 'javaee-ssm:2:14', 'Servlet 映射的三种写法与优先级', 'Servlet 映射的三种写法与优先级：精确匹配 /login、扩展名匹配 *.do、目录匹配 /admin/*（以及默认 /）。配置冲突时精确匹配优先于路径匹配，路径匹配优先于扩展名，扩展名优先于默认 Servlet；@WebServlet(urlPatterns={"/user"}) 注解可等价替代 XML 声明。', 'MEDIUM', 2, 14),
('javaee-ssm', 2, '第 2 章 Servlet 技术', 'javaee-ssm:2:15', 'Servlet 中的线程安全问题', 'Servlet 中的线程安全问题：Servlet 是单例多线程，容器对同一 Servlet 只创建一个实例，多个请求线程并发执行 service()。因此不能把可变状态放在成员变量里（应放方法局部变量或 ThreadLocal），否则出现数据错乱；若需单例资源应加锁或改用无状态设计。', 'MEDIUM', 2, 15),
('javaee-ssm', 2, '第 2 章 Servlet 技术', 'javaee-ssm:2:16', '会话跟踪与会话域的引入', '会话跟踪与会话域的引入：因 HTTP 无状态，需要借助 Cookie/Session 在多请求间维持状态；request.getSession() 返回 HttpSession，可 setAttribute/getAttribute 存储登录用户、购物车等数据。Servlet 层的"取参 → 调业务 → 放域 → 转发"四步是后续 Spring MVC 处理流程的原始雏形。', 'MEDIUM', 2, 16),
('javaee-ssm', 2, '第 2 章 Servlet 技术', 'javaee-ssm:2:17', '【补充】Servlet 3.0 注解与异步支持', '【补充】Servlet 3.0 注解与异步支持：@WebServlet/@WebFilter/@WebListener 注解免去 web.xml 配置；asyncSupported = true 结合 AsyncContext 可把耗时操作交给容器线程池，释放请求线程，适用于长轮询/大报表导出；web-fragment.xml 支持模块化装配，是理解 Spring Boot 内嵌容器自动配置的铺垫。', 'MEDIUM', 2, 17),
('javaee-ssm', 3, '第 3 章 JSP 与会话技术', 'javaee-ssm:3:18', 'JSP 的本质与生命周期', 'JSP 的本质与生命周期：JSP（JavaServer Pages）在第一次被访问时被翻译成 HttpServlet 的子类（.jsp → .java → .class），随后按 Servlet 生命周期执行；它把"HTML 中嵌入 Java"反过来，适合做视图层，但业界已共识"复杂逻辑不应写在 JSP 里"，最终演变为前后端分离下的模板引擎/JSON 接口。', 'MEDIUM', 2, 18),
('javaee-ssm', 3, '第 3 章 JSP 与会话技术', 'javaee-ssm:3:19', 'JSP 脚本元素与指令', 'JSP 脚本元素与指令：脚本片段 <% ... %>、表达式 <%= ... %>、声明 <%! ... %>；三大指令 page（contentType/import/errorPage/isELIgnored）、include（静态包含，编译期合并）、taglib（引入标签库）。指令影响翻译后的 Servlet 结构，而脚本只影响 _jspService 方法体。', 'MEDIUM', 2, 19),
('javaee-ssm', 3, '第 3 章 JSP 与会话技术', 'javaee-ssm:3:20', 'JSP 九个内置对象', 'JSP 九个内置对象：request、response、session、application(=ServletContext)、out(JspWriter)、config、pageContext、page(≈this)、exception（仅 isErrorPage="true" 页面可用）。其中 pageContext 可同时操作其余八个对象及四种作用域属性，是理解 JSP 到 Servlet 桥梁的关键。', 'MEDIUM', 2, 20),
('javaee-ssm', 3, '第 3 章 JSP 与会话技术', 'javaee-ssm:3:21', '四种作用域与 pageContext', '四种作用域与 pageContext：page（当前页）、request（同一次请求，转发可传递）、session（同一用户会话）、application（整个应用全局）。<% pageContext.setAttribute("u", obj, PageContext.SESSION_SCOPE) %> 可显式指定域；实际开发中遵循"最小作用域原则"以避免内存浪费与并发问题。', 'MEDIUM', 2, 21),
('javaee-ssm', 3, '第 3 章 JSP 与会话技术', 'javaee-ssm:3:22', 'EL 表达式与隐式对象', 'EL 表达式与隐式对象：EL（Expression Language）以 ${} 语法简化取值，如 ${sessionScope.user.name}、${param.id}、${empty list}；支持算术/关系/逻辑运算与三元运算符，能自动做 null 处理并调 toString，配合 JSTL 可完全替代脚本片段。', 'MEDIUM', 2, 22),
('javaee-ssm', 3, '第 3 章 JSP 与会话技术', 'javaee-ssm:3:23', 'JSTL 核心标签库', 'JSTL 核心标签库：<c:if test="${...}">、<c:forEach items="${list}" var="it" varStatus="s">（status.index/count）、<c:set>、<c:choose>/<c:when>、<fmt:formatDate>、<sql:query>（了解即可）。引入方式 %@ taglib prefix="c" uri="http://java.sun.com/jsp/jstl/core" %，是 JSP 页面的标准做法。', 'MEDIUM', 2, 23),
('javaee-ssm', 3, '第 3 章 JSP 与会话技术', 'javaee-ssm:3:24', 'Cookie 的原理与使用', 'Cookie 的原理与使用：服务器通过 response.addCookie(new Cookie("token", v)) 下发，浏览器在后续请求头自动携带，Servlet 用 request.getCookies() 遍历取值；Cookie 有大小（约 4KB）与条数限制、默认随浏览器会话存在（设 setMaxAge(秒) 持久化），且明文存储不可放敏感信息，需防篡改与 XSS 窃取。', 'MEDIUM', 2, 24),
('javaee-ssm', 3, '第 3 章 JSP 与会话技术', 'javaee-ssm:3:25', 'Session 的原理、API 与销毁', 'Session 的原理、API 与销毁：首次 request.getSession() 时容器创建 HttpSession 并生成 JSESSIONID（默认以 Cookie 保存）；可 setAttribute/getAttribute/removeAttribute/invalidate()，用 setMaxInactiveInterval(1800) 设超时；实现分布式会话需 HttpSessionListener 或把 Session 存入 Redis。', 'MEDIUM', 2, 25),
('javaee-ssm', 3, '第 3 章 JSP 与会话技术', 'javaee-ssm:3:26', '会话跟踪的三种补充手段', '会话跟踪的三种补充手段：当浏览器禁用 Cookie 时，用 URL 重写 response.encodeURL(url) 把 JSESSIONID 追加到 URL；或用隐藏表单域 <input type="hidden" name="jsessionid">；实际以 Cookie 为主、URL 重写兜底，encodeRedirectURL 用于重定向场景。', 'MEDIUM', 2, 26),
('javaee-ssm', 3, '第 3 章 JSP 与会话技术', 'javaee-ssm:3:27', 'MVC 思想在 JSP+Servlet 中的落地', 'MVC 思想在 JSP+Servlet 中的落地：典型模式为 Servlet 作控制器（接收参数、调用 JavaBean/DAO、写入 request 域）、JSP 作视图（用 EL/JSTL 渲染）、JavaBean/POJO 作模型，即 JavaWeb 版 MVC；这正是后续 Spring MVC "Controller 返回视图名、Model 承载数据"的直接原型。', 'MEDIUM', 2, 27),
('javaee-ssm', 3, '第 3 章 JSP 与会话技术', 'javaee-ssm:3:28', 'JSP 的局限与被淘汰原因', 'JSP 的局限与被淘汰原因：脚本与 HTML 混杂导致职责不清、难以协作与测试；模板编译带来首次请求延迟；无法很好支撑前后端分离。教材在讲完 JSP 后通常会转向纯 JSON 接口，本纲亦按此脉络把重点放在 Spring MVC 与 MyBatis。', 'MEDIUM', 4, 28),
('javaee-ssm', 4, '第 4 章 过滤器与监听器', 'javaee-ssm:4:29', 'Filter 接口与开发三步骤', 'Filter 接口与开发三步骤：实现 javax.servlet.Filter 接口，覆写 init(FilterConfig)、doFilter(ServletRequest,ServletResponse,FilterChain)、destroy()；在 web.xml 用 <filter>+<filter-mapping> 注册，或用 @WebFilter(urlPatterns="/*") 注解注册，实现"编码过滤/登录校验/日志记录"等横切功能。', 'MEDIUM', 2, 29),
('javaee-ssm', 4, '第 4 章 过滤器与监听器', 'javaee-ssm:4:30', 'FilterChain 与责任链模式', 'FilterChain 与责任链模式：chain.doFilter(request,response) 把请求传给下一个 Filter 或目标资源；调用前的代码在请求阶段执行，调用后的代码在响应阶段执行，形成"前置处理—放行—后置处理"结构；不调用 doFilter 即可中断请求（如未登录直接重定向），这是拦截器/过滤器的通用骨架。', 'MEDIUM', 2, 30),
('javaee-ssm', 4, '第 4 章 过滤器与监听器', 'javaee-ssm:4:31', '@WebFilter 与 Filter 映射顺序', '@WebFilter 与 Filter 映射顺序：urlPatterns 支持 /*、/admin/*、*.jsp 等形式；web.xml 中 Filter 的执行顺序按 <filter-mapping> 声明先后，注解方式可用 @Order（Servlet 3.0+ 部分容器支持）或排序过滤器，编码过滤器应尽量靠前以免后续组件已按错误编码读取参数。', 'MEDIUM', 2, 31),
('javaee-ssm', 4, '第 4 章 过滤器与监听器', 'javaee-ssm:4:32', '编码过滤器的正确姿势', '编码过滤器的正确姿势：request.setCharacterEncoding("UTF-8") 只对请求体有效，须放在取参前；response.setContentType("text/html;charset=UTF-8") 或 setCharacterEncoding 需在拿到 Writer/OutputStream 之前设置，否则编码不生效；GET 参数乱码需在 server.xml 的 <Connector> 加 URIEncoding="UTF-8"。', 'MEDIUM', 2, 32),
('javaee-ssm', 4, '第 4 章 过滤器与监听器', 'javaee-ssm:4:33', '登录校验过滤器的实现要点', '登录校验过滤器的实现要点：定义无需登录的白名单（/login.jsp、/css/**、/login.do），对不在白名单内的请求判断 session.getAttribute("user") 是否为空，为空则 response.sendRedirect(request.getContextPath()+"/login.jsp")；注意放行静态资源、避免 Ajax 请求被重定向导致拿到 HTML 的问题（可返回 401 状态码）。', 'MEDIUM', 2, 33),
('javaee-ssm', 4, '第 4 章 过滤器与监听器', 'javaee-ssm:4:34', 'HttpServletRequestWrapper 包装增强：当需要修改请求参数', 'HttpServletRequestWrapper 包装增强：当需要修改请求参数（如统一 trim、XSS 过滤、重复读 body）时，继承 HttpServletRequestWrapper 覆写 getParameter* 方法，并在 Filter 里把包装后的对象传给 chain.doFilter(wrapped,response)，是装饰器模式在 Web 层的经典应用。', 'MEDIUM', 2, 34),
('javaee-ssm', 4, '第 4 章 过滤器与监听器', 'javaee-ssm:4:35', '监听器体系与常见 API', '监听器体系与常见 API：ServletContextListener（contextInitialized/contextDestroyed，用于初始化缓存、启动定时任务、释放连接池）、ServletContextAttributeListener（域属性增删改）、HttpSessionListener（会话创建/销毁，统计在线人数）、HttpSessionAttributeListener、ServletRequestListener 等，均需在 web.xml 用 <listener> 或 @WebListener 注册。', 'MEDIUM', 2, 35),
('javaee-ssm', 4, '第 4 章 过滤器与监听器', 'javaee-ssm:4:36', 'HttpSessionBindingListener 与钝化活化：实现该接口的对', 'HttpSessionBindingListener 与钝化活化：实现该接口的对象被放入/移出 Session 时会收到 valueBound/valueUnbound 回调，无需注册监听器；配合 HttpSessionActivationListener 可实现 Session 的钝化（序列化到磁盘/Redis）与活化（恢复），用于大 Session 或集群场景。', 'MEDIUM', 2, 36),
('javaee-ssm', 4, '第 4 章 过滤器与监听器', 'javaee-ssm:4:37', '用监听器+上下文属性构建"在线人数"', '用监听器+上下文属性构建"在线人数"：在 HttpSessionListener.sessionCreated 中给 ServletContext 的计数属性 +1，sessionDestroyed 中 -1，页面用 EL ${onlineCount} 显示；注意集群环境下单机计数不准确，应改用集中存储，这是监听器最典型的实战案例。', 'MEDIUM', 2, 37),
('javaee-ssm', 4, '第 4 章 过滤器与监听器', 'javaee-ssm:4:38', '【补充】Filter 与 Spring 拦截器的边界：Filter 属 Serv', '【补充】Filter 与 Spring 拦截器的边界：Filter 属 Servlet 规范，早于 Spring MVC，能拦截静态资源且可包装 request/response；Spring 的 HandlerInterceptor 属框架层，能拿到 HandlerMethod、支持依赖注入但拦不到静态资源；项目中常组合使用——Filter 管编码与跨域，拦截器管登录态与权限。', 'MEDIUM', 2, 38),
('javaee-ssm', 5, '第 5 章 MVC 模式与 Struts2 过渡【补充】', 'javaee-ssm:5:39', 'MVC 与 JavaWeb 版 MVC 的对应', 'MVC 与 JavaWeb 版 MVC 的对应：Model 由 JavaBean/Service/DAO 承担，View 由 JSP（EL+JSTL）承担，Controller 由 Servlet 承担；请求先到 Controller，经业务处理后把数据放入 request/session 域并转发或重定向到 View。理解"控制器不写 SQL、视图不写业务"是后续所有框架分层的总纲。', 'MEDIUM', 2, 39),
('javaee-ssm', 5, '第 5 章 MVC 模式与 Struts2 过渡【补充】', 'javaee-ssm:5:40', '为什么引入框架', '为什么引入框架：原生 Servlet 需手工取参、类型转换、流程分发，代码重复且难维护；Struts2/Spring MVC 通过"声明式映射 + 拦截器栈 + 结果视图解析"把重复劳动配置化，使开发者聚焦业务逻辑，这是从 JavaWeb 到 SSM 的动机所在。', 'MEDIUM', 2, 40),
('javaee-ssm', 5, '第 5 章 MVC 模式与 Struts2 过渡【补充】', 'javaee-ssm:5:41', 'Struts2 的核心组件与执行流程', 'Struts2 的核心组件与执行流程：请求先经 StrutsPrepareAndExecuteFilter（前端过滤器）→ ActionMapper 找到对应 Action → 依次执行拦截器栈（params/modelDriven/validation 等）→ 调用 Action 方法返回逻辑视图名（如 success）→ Result 按配置跳转 JSP 或链式 Action。其本质是"过滤器 + 拦截器 + 反射调用 + 结果渲染"。', 'MEDIUM', 2, 41),
('javaee-ssm', 5, '第 5 章 MVC 模式与 Struts2 过渡【补充】', 'javaee-ssm:5:42', 'struts.xml 关键配置', 'struts.xml 关键配置：<package name="default" extends="struts-default" namespace="/user"> 定义命名空间；<action name="login" class="com.xxx.LoginAction" method="execute"> 声明动作与调用的方法；<result name="success">/welcome.jsp</result> 配置结果视图，type 可选 dispatcher/redirect/chain；<interceptor-ref> 组装拦截器栈。', 'MEDIUM', 2, 42),
('javaee-ssm', 5, '第 5 章 MVC 模式与 Struts2 过渡【补充】', 'javaee-ssm:5:43', '值栈（ValueStack）与 OGNL', '值栈（ValueStack）与 OGNL：Struts2 把 Action 及其属性压入值栈，页面用 OGNL 表达式 %{user.name} 直接取值，<s:property value="user.name"/> 输出；<s:iterator value="list"> 遍历集合。这与 Spring MVC 的 Model+EL 目标一致，只是实现方式不同，理解值栈有助于读懂遗留系统。', 'MEDIUM', 2, 43),
('javaee-ssm', 5, '第 5 章 MVC 模式与 Struts2 过渡【补充】', 'javaee-ssm:5:44', '从 Struts2 到 Spring MVC 的迁移要点：两者都采用"前端控制器', '从 Struts2 到 Spring MVC 的迁移要点：两者都采用"前端控制器 + 处理器映射 + 视图解析"结构；Spring MVC 以 DispatcherServlet 取代 StrutsPrepareAndExecuteFilter，以 @RequestMapping 注解取代 struts.xml 的 <action>，以 Model 取代值栈；迁移时重点替换"配置映射、参数绑定、视图跳转"三块即可。【补充】', 'MEDIUM', 4, 44),
('javaee-ssm', 5, '第 5 章 MVC 模式与 Struts2 过渡【补充】', 'javaee-ssm:5:45', '本章在 SSM 教材中的定位', '本章在 SSM 教材中的定位：多数教材用它承接 JSP/Servlet 并过渡到 Spring，考点多为 MVC 三层职责、Struts2 流程、拦截器与值栈概念；实际工程已普遍转向 Spring MVC/前后端分离，学习时以"建立分层与前端控制器思想"为目标，不必深挖 Struts2 细节。【补充】', 'MEDIUM', 4, 45),
('javaee-ssm', 6, '第 6 章 Spring 概述与 IoC 入门', 'javaee-ssm:6:46', 'Spring 框架的体系结构', 'Spring 框架的体系结构：核心容器（spring-core/spring-beans/spring-context/spring-expression）提供 IoC 与依赖注入；AOP 模块（spring-aop/spring-aspects）提供面向切面能力；数据访问模块（spring-jdbc/spring-tx/spring-orm）整合 JDBC/Hibernate/MyBatis；Web 模块（spring-web/spring-webmvc）提供 MVC 与 REST 支持；另有测试与消息等模块，SSM 用到的正是"容器 + AOP + tx + webmvc"。', 'MEDIUM', 2, 46),
('javaee-ssm', 6, '第 6 章 Spring 概述与 IoC 入门', 'javaee-ssm:6:47', '反转控制（IoC）与依赖注入（DI）', '反转控制（IoC）与依赖注入（DI）：IoC 指对象的创建与依赖关系的组装不再由使用方 new，而交给容器统一管理；DI 是 IoC 的实现手段，容器在创建 Bean 时把依赖对象"注入"进来。其价值在于解耦——业务类只声明"我需要一个 UserDao"，具体实现可替换，便于测试与扩展。', 'MEDIUM', 2, 47),
('javaee-ssm', 6, '第 6 章 Spring 概述与 IoC 入门', 'javaee-ssm:6:48', 'BeanFactory 与 ApplicationContext：BeanFac', 'BeanFactory 与 ApplicationContext：BeanFactory 是最顶层容器接口，采用懒加载，首次 getBean 才实例化；ApplicationContext 是其子接口，容器启动即预实例化单例 Bean 并额外提供事件发布、国际化、资源加载等企业能力。实际开发几乎都用 ClassPathXmlApplicationContext（classpath 下 XML）或 AnnotationConfigApplicationContext（注解配置）。', 'MEDIUM', 2, 48),
('javaee-ssm', 6, '第 6 章 Spring 概述与 IoC 入门', 'javaee-ssm:6:49', 'XML 方式的 bean 装配', 'XML 方式的 bean 装配：在 applicationContext.xml 中 <bean id="userDao" class="com.xxx.dao.impl.UserDaoImpl"/> 声明组件；构造器注入用 <constructor-arg ref="userDao"/> 或 value；Setter 注入用 <property name="userDao" ref="userDao"/>，要求类提供无参构造与 setter；由 <context:component-scan base-package="com.xxx"/> 扫描注解 Bean。', 'MEDIUM', 2, 49),
('javaee-ssm', 6, '第 6 章 Spring 概述与 IoC 入门', 'javaee-ssm:6:50', '第一个 Spring 程序的步骤', '第一个 Spring 程序的步骤：导入 spring-context 等 jar → 编写 UserDao 接口与实现 → 在 XML 声明两个 Bean 并通过 <property> 注入 → 编写测试类 new ClassPathXmlApplicationContext("applicationContext.xml") 后 ctx.getBean("userService", UserService.class) 取得对象并调用方法 → 关闭容器 ctx.close()，体会"容器负责 new，我只负责取"。', 'MEDIUM', 2, 50),
('javaee-ssm', 6, '第 6 章 Spring 概述与 IoC 入门', 'javaee-ssm:6:51', '两种注入方式的取舍', '两种注入方式的取舍：构造器注入在对象创建时即具备完整依赖，能保证不可变（配合 final）与线程安全，推荐用于强依赖；Setter 注入灵活、支持可选依赖与重新注入，适合可覆盖的配置项；集合注入可用 <list>/<set>/<map>/<props>，为批量依赖（如多数据源路由）提供手段。', 'MEDIUM', 2, 51),
('javaee-ssm', 6, '第 6 章 Spring 概述与 IoC 入门', 'javaee-ssm:6:52', '容器对 Bean 的识别', '容器对 Bean 的识别：id 与 class：id 是容器内唯一标识，class 必须是全限定类名；可省略 id（容器自动生成），也可用 name 起别名（支持多个，用空格/分号分隔）；getBean 既可按 id/name 也可按类型获取，按类型获取时若同类型多个 Bean 会抛 NoUniqueBeanDefinitionException，需用 @Qualifier 指定。', 'MEDIUM', 2, 52),
('javaee-ssm', 6, '第 6 章 Spring 概述与 IoC 入门', 'javaee-ssm:6:53', 'pom.xml 中 Spring 的最小坐标', 'pom.xml 中 Spring 的最小坐标：SSM 项目常用 spring-context、spring-webmvc、spring-jdbc、spring-tx、mybatis-spring 与 spring-test；版本建议统一在 <properties> 用 spring.version 管理，避免各模块版本不一致导致的 NoSuchMethodError。', 'MEDIUM', 2, 53),
('javaee-ssm', 6, '第 6 章 Spring 概述与 IoC 入门', 'javaee-ssm:6:54', 'Spring 与 Java EE 规范的关系', 'Spring 与 Java EE 规范的关系：Spring 并非取代 Servlet/JSP，而是"增强"——它接管的是对象创建、依赖组装、事务与 AOP 等横切逻辑；Web 层仍以 Servlet 规范为底座（DispatcherServlet 本身就是一个 Servlet），这解释了为什么 SSM 整合要先配 web.xml 再配 Spring 容器。', 'MEDIUM', 2, 54),
('javaee-ssm', 6, '第 6 章 Spring 概述与 IoC 入门', 'javaee-ssm:6:55', '【补充】Spring 5/6 与 Jakarta 命名空间：Spring 6 起', '【补充】Spring 5/6 与 Jakarta 命名空间：Spring 6 起包名由 javax.* 迁移到 jakarta.*（如 jakarta.servlet），旧项目升级时需同步替换 servlet、validation 等 API 并升级 Tomcat 10+；SSM 课程项目如仍基于 javax，建议固定 JDK 8 + Tomcat 9 + Spring 5 的组合以保证依赖兼容。', 'MEDIUM', 2, 55),
('javaee-ssm', 7, '第 7 章 Bean 的生命周期与作用域', 'javaee-ssm:7:56', 'Bean 生命周期的四个阶段', 'Bean 生命周期的四个阶段：实例化（容器通过反射调用构造器，把 Bean 定义转成 BeanDefinition 后由工厂创建）→ 属性填充（完成 DI，注入依赖与基本属性）→ 初始化（依次执行 BeanNameAware/BeanFactoryAware/ApplicationContextAware 回调、@PostConstruct、InitializingBean.afterPropertiesSet()、XML init-method）→ 使用 → 销毁（@PreDestroy、DisposableBean.destroy()、XML destroy-method）。', 'MEDIUM', 2, 56),
('javaee-ssm', 7, '第 7 章 Bean 的生命周期与作用域', 'javaee-ssm:7:57', 'BeanPostProcessor 与 AOP 代理插入点：BeanPostPr', 'BeanPostProcessor 与 AOP 代理插入点：BeanPostProcessor.postProcessBeforeInitialization / postProcessAfterInitialization 在初始化前后对每个 Bean 加工，Spring AOP 的自动代理创建器正是借此在 Bean 初始化后判断是否需要生成代理对象，从而让业务类拿到的是代理而非原对象；这是 @Transactional、@Aspect 生效的底层机制。', 'MEDIUM', 2, 57),
('javaee-ssm', 7, '第 7 章 Bean 的生命周期与作用域', 'javaee-ssm:7:58', '五种作用域', '五种作用域：singleton 与 prototype：singleton（默认）在容器中仅一个实例，容器启动即创建并缓存于 singletonObjects，线程不安全需自行处理状态；prototype 每次获取都新建，容器不管理其销毁回调，适合有状态的会话对象；两者混用要注意原型注入单例时的"依赖逃逸"问题。', 'MEDIUM', 2, 58),
('javaee-ssm', 7, '第 7 章 Bean 的生命周期与作用域', 'javaee-ssm:7:59', '三种 Web 相关作用域', '三种 Web 相关作用域：request（每个 HTTP 请求一个实例，存于 request 属性）、session（每个 HttpSession 一个）、application（每个 ServletContext 一个）；需在 XML 中 <bean scope="request"> 并配合 scoped-proxy，或用注解 @Scope("session")，Spring MVC 中常用于在多请求间共享同一业务对象。', 'MEDIUM', 2, 59),
('javaee-ssm', 7, '第 7 章 Bean 的生命周期与作用域', 'javaee-ssm:7:60', '延迟加载 lazy-init 与 @Lazy', '延迟加载 lazy-init 与 @Lazy：设置 lazy-init="true" 后容器启动不立即实例化该 Bean，首次 getBean 时才创建，可用于加速启动；但若是其它单例的依赖则会被强制提前创建，且可能掩盖配置错误（运行期才报错），应谨慎使用。', 'MEDIUM', 2, 60),
('javaee-ssm', 7, '第 7 章 Bean 的生命周期与作用域', 'javaee-ssm:7:61', 'depends-on 与隐式依赖顺序', 'depends-on 与隐式依赖顺序：多数情况下 Spring 能根据依赖关系推断创建顺序（被依赖者先建）；无法推断时（如只想确保某初始化监听器先执行）用 depends-on="beanId" 显式指定；循环依赖在单例 + Setter 注入下可通过三级缓存解决，构造器循环依赖则会抛 BeanCurrentlyInCreationException。', 'MEDIUM', 2, 61),
('javaee-ssm', 7, '第 7 章 Bean 的生命周期与作用域', 'javaee-ssm:7:62', '单例 Bean 的成员变量陷阱', '单例 Bean 的成员变量陷阱：单例 Bean 被所有请求线程共享，若在成员变量上保存请求级状态（如当前用户），必然串数据；正确做法是把状态放方法局部变量、ThreadLocal 或改用 request/session 作用域。这也是 Service 层必须"无状态"的原因。', 'HARD', 2, 62),
('javaee-ssm', 7, '第 7 章 Bean 的生命周期与作用域', 'javaee-ssm:7:63', '@PostConstruct 与 afterPropertiesSet 的执行次', '@PostConstruct 与 afterPropertiesSet 的执行次序：JSR-250 的 @PostConstruct 最先，其次 InitializingBean#afterPropertiesSet，最后自定义 init-method；销毁顺序相反（@PreDestroy → DisposableBean → destroy-method）。掌握次序有助于安排"先建连接池再建 SqlSessionFactory"这类有依赖的初始化。', 'MEDIUM', 2, 63),
('javaee-ssm', 7, '第 7 章 Bean 的生命周期与作用域', 'javaee-ssm:7:64', 'ApplicationContext 的 close() 与优雅停机：close', 'ApplicationContext 的 close() 与优雅停机：close() 会发布 ContextClosedEvent 并触发单例 Bean 的销毁回调，释放数据库连接池与线程池；web 项目中由 ContextLoaderListener 在应用停止时自动关闭根容器，长生命周期进程应注册 JVM 关闭钩子 registerShutdownHook() 做兜底。', 'MEDIUM', 2, 64),
('javaee-ssm', 7, '第 7 章 Bean 的生命周期与作用域', 'javaee-ssm:7:65', '【补充】FactoryBean 与 BeanFactory 的区别：BeanFa', '【补充】FactoryBean 与 BeanFactory 的区别：BeanFactory 是容器本身；FactoryBean（如 SqlSessionFactoryBean、MapperScannerConfigurer）是一个特殊的 Bean，getBean 返回的是它生产的产品而非工厂本身，用 &factoryBeanName 才能拿到工厂自身。MyBatis 整合的关键组件都是 FactoryBean，理解它有助于排查"拿到了 null"的整合问题。', 'MEDIUM', 2, 65),
('javaee-ssm', 8, '第 8 章 注解装配与 Java Config', 'javaee-ssm:8:66', '四大组件注解的语义分工', '四大组件注解的语义分工：@Component 为通用组件；@Repository 标注持久层，会把 JDBC 异常转换为 Spring 的 DataAccessException 体系；@Service 标注业务层；@Controller/@RestController 标注控制层。四者本质相同，区别在于语义与额外的异常转换/AOP 约定，分层注解能让切面与异常处理有的放矢。', 'MEDIUM', 2, 66),
('javaee-ssm', 8, '第 8 章 注解装配与 Java Config', 'javaee-ssm:8:67', '@ComponentScan 与包扫描规则', '@ComponentScan 与包扫描规则：<context:component-scan base-package="com.xxx" use-default-filters="false"> 或 @ComponentScan(basePackages="com.xxx", includeFilters=..., excludeFilters=...)；默认过滤 @Component 及其派生注解；通常"根容器扫 Service/Repository、Web 容器扫 Controller"以避免 Bean 重复创建导致事务失效。', 'MEDIUM', 2, 67),
('javaee-ssm', 8, '第 8 章 注解装配与 Java Config', 'javaee-ssm:8:68', '@Autowired 的装配规则与歧义处理', '@Autowired 的装配规则与歧义处理：默认按类型装配（required=true），同类型多个候选时报错；可用 @Qualifier("userDaoImpl") 指定 Bean 名，或在候选 Bean 上标 @Primary 设为首选；允许 required=false 或字段为 @Nullable 表示可选注入；能用于字段、setter、构造器，构造器注入是官方推荐写法。', 'MEDIUM', 2, 68),
('javaee-ssm', 8, '第 8 章 注解装配与 Java Config', 'javaee-ssm:8:69', '@Resource 与 @Inject 的差异', '@Resource 与 @Inject 的差异：@Resource（JSR-250）默认按名称装配（@Resource(name="...")），找不到再按类型；@Inject（JSR-330）类似 @Autowired 但无 required 属性；@Autowired 是 Spring 专有，测试与文档中优先使用以减少对特定注解的耦合。', 'MEDIUM', 2, 69),
('javaee-ssm', 8, '第 8 章 注解装配与 Java Config', 'javaee-ssm:8:70', '基本类型与集合注入', '基本类型与集合注入：@Value("${jdbc.url}") 注入 properties 中的字符串并自动转换类型（int/boolean）；@Value("#{''${app.codes}''.split('','')}") 用 SpEL 注入数组；集合类型可用 @Autowired List<UserDao> 收集同类型全部 Bean（有序用 @Order），比 XML 的 <list> 更简洁。', 'MEDIUM', 2, 70),
('javaee-ssm', 8, '第 8 章 注解装配与 Java Config', 'javaee-ssm:8:71', '@Configuration 与 @Bean', '@Configuration 与 @Bean：@Configuration 标注的类是配置类，会被 CGLIB 增强以保证 @Bean 方法之间的调用返回同一单例（@Bean 方法默认 singleton）；@Bean(name="dataSource", initMethod="init", destroyMethod="close") 可完全替代 XML 的 <bean>；proxyBeanMethods=false（Lite 模式）可去掉增强以提升启动速度。', 'MEDIUM', 2, 71),
('javaee-ssm', 8, '第 8 章 注解装配与 Java Config', 'javaee-ssm:8:72', '@PropertySource 与 PropertySourcesPlaceho', '@PropertySource 与 PropertySourcesPlaceholderConfigurer：@PropertySource("classpath:jdbc.properties") 把外部配置载入环境，配合 @Value("${...}") 使用；XML 侧用 <context:property-placeholder location="classpath:jdbc.properties"/>；${} 取值失败会抛异常，可提供默认值 ${jdbc.username:root}，多环境可用 application-{profile}.yml 风格的 profile 切换【补充】。', 'MEDIUM', 2, 72),
('javaee-ssm', 8, '第 8 章 注解装配与 Java Config', 'javaee-ssm:8:73', '@Profile 与条件装配 @Conditional：@Profile("de', '@Profile 与条件装配 @Conditional：@Profile("dev") 只在激活对应 profile 时装配（spring.profiles.active=dev）；@ConditionalOnClass/@ConditionalOnMissingBean 等是 Spring Boot 自动配置的基石，理解它们有助于读懂"为什么加了某个 starter 就自动配好了 Bean"。', 'MEDIUM', 2, 73),
('javaee-ssm', 8, '第 8 章 注解装配与 Java Config', 'javaee-ssm:8:74', '注解与 XML 共存策略', '注解与 XML 共存策略：SSM 项目常见做法是"XML 管数据源与 SqlSessionFactory 等基础设施，注解管组件扫描与依赖注入"，或用纯 Java Config 完全替代；原则是避免同一段配置在两处重复，否则出现"两个容器/两套 Bean"导致 @Transactional 不生效或请求 404 等诡异问题。', 'EASY', 2, 74),
('javaee-ssm', 8, '第 8 章 注解装配与 Java Config', 'javaee-ssm:8:75', '【补充】 Lombok 与 final 构造器注入：@RequiredArgsC', '【补充】 Lombok 与 final 构造器注入：@RequiredArgsConstructor 可生成含 final 字段的构造器，配合 spring-boot-starter 常用 Lombok 减少样板代码；但传统 SSM 教学中仍以显式 setter/XML 为主，写代码时不要因引入 Lombok 而忽略对 DI 本质的理解。', 'MEDIUM', 2, 75),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:76', 'AOP 要解决的问题', 'AOP 要解决的问题：日志、事务、权限、性能监控等逻辑会在多个业务方法中重复出现，若直接写在业务里会造成"业务代码与横切关注点混杂"。AOP（面向切面编程）把这些逻辑抽成"切面（Aspect）"，在运行时织入到目标方法周围，实现业务纯净与复用。', 'MEDIUM', 2, 76),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:77', '核心术语对照', '核心术语对照：Target（被代理的目标对象）、JoinPoint（程序执行点，Spring 中特指方法调用）、Pointcut（用表达式筛选出哪些方法要拦截）、Advice（在切点处执行的动作）、Aspect（切点 + 通知的模块）、Weaving（把切面应用到目标并生成代理的过程）、Proxy（织入后生成的代理对象）。', 'MEDIUM', 2, 77),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:78', 'JDK 动态代理与 CGLIB 代理', 'JDK 动态代理与 CGLIB 代理：JDK 代理基于 java.lang.reflect.Proxy + InvocationHandler，要求目标实现接口，代理类实现同接口并在 invoke 中插入增强；CGLIB 通过生成目标类的子类覆写方法实现，无需接口但不能代理 final 类/方法。Spring 默认策略是"目标有接口用 JDK，否则用 CGLIB"，可用 proxyTargetClass=true 强制 CGLIB。', 'MEDIUM', 2, 78),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:79', 'Advisor 与代理工厂', 'Advisor 与代理工厂：org.springframework.aop.framework.ProxyFactoryBean 可在 XML 中为目标 Bean 声明 target/interceptorNames，容器中实际注入的是代理对象；<aop:config> + <aop:pointcut expression="execution(* com.xxx.service.*.*(..))"/> + <aop:aspect ref="logAspect"> 可注解化配置，最终由 AnnotationAwareAspectJAutoProxyCreator 自动织入。', 'MEDIUM', 2, 79),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:80', '切点表达式 execution 语法', '切点表达式 execution 语法：execution(修饰符? 返回类型 包.类.方法(参数) 异常?)，如 execution(public * com.xxx.service..*.*(..)) 匹配 service 及其子包下所有 public 方法；支持 within()、@annotation(com.xxx.Log)、args()、bean() 等指示器，能精确圈定"给 Service 层所有方法加日志"或"带某注解的方法才记录"。', 'MEDIUM', 2, 80),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:81', '五种通知类型与执行顺序', '五种通知类型与执行顺序：@Before（方法前）、@AfterReturning（正常返回后，可取 returning 值）、@AfterThrowing（抛异常后，可取 throwing）、@After（finally 语义）、@Around（环绕，最强大，需显式 proceed() 放行并可改写入参/返回值）。执行链顺序为 Around 前段 → Before → 目标 → AfterReturning/AfterThrowing → After → Around 后段。', 'MEDIUM', 2, 81),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:82', '@Around 手写简易重试或耗时统计', '@Around 手写简易重试或耗时统计：Object result = joinPoint.proceed(); long cost = System.currentTimeMillis() - start;，可捕获异常决定是否重试；注意若忘记 proceed() 则目标方法不执行、返回值需原样返回，这是初学者最常见的两个坑。', 'MEDIUM', 2, 82),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:83', 'ProceedingJoinPoint 与 JoinPoint API：getS', 'ProceedingJoinPoint 与 JoinPoint API：getSignature() 拿到方法签名、getArgs() 拿入参数组、getTarget() 拿目标对象、getThis() 拿代理对象；环绕通知必须用 ProceedingJoinPoint，其余通知用 JoinPoint 即可；修改入参可用 joinPoint.getArgs() 副本替换后传入 proceed(newArgs)。', 'MEDIUM', 2, 83),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:84', '引入（Introduction）与 declare-parents：可为已有类动', '引入（Introduction）与 declare-parents：可为已有类动态"实现"某接口（如给一批 Service 加 Lockable），XML 用 <aop:declare-parents types-matching="com.xxx..*" implement-interface="Lockable" default-impl="..."/>，属于对类结构层面的增强，实际项目用得较少但能体现 AOP 的表达力。', 'MEDIUM', 2, 84),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:85', 'AspectJ 与 Spring AOP 的能力差异：Spring AOP 仅支', 'AspectJ 与 Spring AOP 的能力差异：Spring AOP 仅支持方法级连接点且只能代理 Spring 容器中的 Bean；AspectJ 支持构造器/字段/静态初始化等更广连接点、编译期或加载期织入（LTW），能力更强但配置复杂。SSM 项目中一般用 Spring AOP + AspectJ 注解即可满足日志/事务需求。', 'MEDIUM', 2, 85),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:86', 'proxyTargetClass、exposeProxy 与自调用失效：同类内部', 'proxyTargetClass、exposeProxy 与自调用失效：同类内部 this.methodB() 调用 @Transactional 方法 B 时，因 this 是原始对象而非代理，增强不生效——这就是"事务/缓存注解自调用失效"的根源；解法包括注入自身代理（AopContext.currentProxy()，需 exposeProxy=true）、拆分到另一个 Bean、改用 AspectJ LTW。', 'MEDIUM', 2, 86),
('javaee-ssm', 9, '第 9 章 Spring AOP 面向切面编程', 'javaee-ssm:9:87', '【补充】AOP 与声明式事务的关系', '【补充】AOP 与声明式事务的关系：@Transactional 本质是一个环绕通知 TransactionInterceptor，在进入方法前 TransactionManager.getTransaction() 开启事务，正常返回则 commit()，抛异常按回滚规则 rollback()；因此理解 AOP 是理解"事务为什么能加在一个普通方法上"的前提。', 'MEDIUM', 2, 87),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:88', 'JdbcTemplate 的价值', 'JdbcTemplate 的价值：原生 JDBC 需要手工获取 Connection、创建 PreparedStatement、遍历 ResultSet、处理受检异常并逐层关闭资源，代码冗长易漏关；JdbcTemplate 以模板方法封装这些固定步骤，只暴露"SQL + 参数 + 行映射"，并把 SQL 异常统一转为非受检的 DataAccessException 体系。', 'MEDIUM', 2, 88),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:89', '数据源的配置与选型', '数据源的配置与选型：常用 org.apache.commons.dbcp2.BasicDataSource 或 Druid/HikariCP；核心属性 driverClassName（MySQL 8 为 com.mysql.cj.jdbc.Driver）、url（jdbc:mysql://localhost:3306/db?useSSL=false&serverTimezone=Asia/Shanghai）、username/password；生产应配 initialSize/maxActive/maxWait 并开启 testWhileIdle 保活。', 'MEDIUM', 2, 89),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:90', 'JdbcTemplate 常用方法', 'JdbcTemplate 常用方法：update(sql, args...) 执行增删改并返回影响行数；queryForObject(sql, new BeanPropertyRowMapper<>(User.class), args) 查单条并自动按列名/属性名映射；query(sql, RowMapper, args) 查列表；queryForList、batchUpdate 批处理；占位符一律用 ?，杜绝字符串拼接导致 SQL 注入。', 'MEDIUM', 2, 90),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:91', 'NamedParameterJdbcTemplate 命名参数：用 :name ', 'NamedParameterJdbcTemplate 命名参数：用 :name 风格的命名参数替代 ?，可读性与维护性更好（尤其参数多时），可传 Map 或 SqlParameterSource；SSM 项目里更常用 MyBatis，但 Spring 自带的这套模板仍是轻量 DAO 的备选方案。', 'MEDIUM', 2, 91),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:92', '事务四要素 ACID 与 Spring 的抽象', '事务四要素 ACID 与 Spring 的抽象：原子性（全成功或全回滚）、一致性、隔离性、持久性。Spring 用 PlatformTransactionManager（JDBC 下为 DataSourceTransactionManager）统一事务API，向上暴露 TransactionDefinition（传播行为、隔离级别、超时、只读）与 TransactionStatus，与具体技术（JDBC/JPA/Hibernate）解耦。', 'MEDIUM', 2, 92),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:93', '七种传播行为', '七种传播行为：REQUIRED（默认，有则加入无则新建）、REQUIRES_NEW（挂起当前事务另起新事务）、SUPPORTS（有则加入无则非事务）、NOT_SUPPORTED（挂起当前事务非事务执行）、MANDATORY（必须有事务否则抛异常）、NEVER（必须无事务否则抛异常）、NESTED（在当前事务内建保存点，可独立回滚）。最常用是 REQUIRED 与 REQUIRES_NEW，用于"业务操作 + 独立日志"的场景。', 'MEDIUM', 2, 93),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:94', '四种隔离级别与并发问题', '四种隔离级别与并发问题：DEFAULT（随数据库）、READ_UNCOMMITTED（脏读）、READ_COMMITTED（不可重复读）、REPEATABLE_READ（幻读，MySQL InnoDB 默认）、SERIALIZABLE（串行化）。隔离越高并发越差，ORM 项目一般使用数据库默认，只有强一致场景才提升隔离级别。', 'MEDIUM', 2, 94),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:95', '@Transactional 的完整属性', '@Transactional 的完整属性：propagation（默认 REQUIRED）、isolation、timeout（秒，-1 不限）、readOnly=true（提示优化，增删改会报错）、rollbackFor/noRollbackFor（按异常类型控制回滚）；建议显式写 @Transactional(rollbackFor=Exception.class)，否则默认只回滚 RuntimeException 与 Error，受检异常不回滚是高频坑。', 'MEDIUM', 4, 95),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:96', 'XML 声明式事务配置', 'XML 声明式事务配置：定义 <bean id="transactionManager" class="org.springframework.jdbc.datasource.DataSourceTransactionManager"><property name="dataSource" ref="dataSource"/></bean>，再用 <tx:advice id="txAdvice" transaction-manager="txManager"><tx:attributes><tx:method name="get*" read-only="true" propagation="SUPPORTS"/><tx:method name="*" propagation="REQUIRED"/></tx:attributes></tx:advice> 配合 <aop:config> 把通知绑到 Service 层切点，实现"零侵入"事务。', 'MEDIUM', 2, 96),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:97', '@EnableTransactionManagement 与驱动方式：注解侧用 ', '@EnableTransactionManagement 与驱动方式：注解侧用 @EnableTransactionManagement（Spring Boot 已自动开启）激活 <tx:annotation-driven>，让 @Transactional 生效；若同时存在多数据源/多事务管理器，需用 @Transactional("orderTxManager") 指定名称，否则事务"看起来加了但不生效"。', 'MEDIUM', 2, 97),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:98', '声明式事务失效的常见原因清单', '声明式事务失效的常见原因清单：①方法非 public（CGLIB 代理无法覆写）②同类自调用（未走代理）③异常被 try/catch 吞掉未抛出④抛出的是受检异常但没配 rollbackFor⑤类未被 Spring 管理（手动 new 出来）⑥数据库引擎不支持事务（MyISAM）⑦@Transactional 加在了接口/父类方法而实现未覆盖⑧多线程中调用（事务上下文绑定 ThreadLocal）。排查时先确认"拿到的是不是代理对象"。', 'MEDIUM', 2, 98),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:99', 'TransactionTemplate 编程式事务：对少量需要在方法内精确控制边', 'TransactionTemplate 编程式事务：对少量需要在方法内精确控制边界的场景，用 new TransactionTemplate(transactionManager).execute(status -> { ... }) 比 @Transactional 更直观；它与声明式并存，教学中常以声明式为主、编程式作为补充。', 'MEDIUM', 2, 99),
('javaee-ssm', 10, '第 10 章 Spring JDBC 与声明式事务', 'javaee-ssm:10:100', '【补充】DataSourceUtils.getConnection 与线程绑定：', '【补充】DataSourceUtils.getConnection 与线程绑定：JdbcTemplate 通过 DataSourceUtils 获取连接，使同一线程内多次 DAO 调用共用同一 Connection，从而天然处于同一事务；这也是"同一事务中多次查询结果一致"以及 ThreadLocal 持有连接的原理所在，理解它有助于分析脏读/不可重复读的实际表现。', 'MEDIUM', 2, 100),
('javaee-ssm', 11, '第 11 章 Spring MVC 入门与核心组件', 'javaee-ssm:11:101', 'Spring MVC 的整体定位', 'Spring MVC 的整体定位：它是构建在 Servlet 之上的 Web 框架，用一个前端控制器 DispatcherServlet 统一接收请求，再交给 HandlerMapping 找处理器、HandlerAdapter 执行、ViewResolver 解析视图、ModelAndView 承载数据，整体是"一个入口 + 一组可插拔组件"的设计。', 'MEDIUM', 2, 101),
('javaee-ssm', 11, '第 11 章 Spring MVC 入门与核心组件', 'javaee-ssm:11:102', 'DispatcherServlet 的处理流程（必背）：①HttpServlet', 'DispatcherServlet 的处理流程（必背）：①HttpServletRequest 到达 DispatcherServlet → ②HandlerMapping 依据 @RequestMapping 找到对应 HandlerMethod 及拦截器链 → ③HandlerAdapter 反射调用方法（期间完成参数绑定、数据校验、类型转换）→ ④返回 ModelAndView（或 void/字符串）→ ⑤若 @ResponseBody 则经 HttpMessageConverter 直接写出响应 → ⑥否则 ViewResolver 解析出 View 并 render(model,response) → ⑦DispatcherServlet 清理 request 上下文并触发 afterCompletion。', 'MEDIUM', 2, 102),
('javaee-ssm', 11, '第 11 章 Spring MVC 入门与核心组件', 'javaee-ssm:11:103', '三种 HandlerMapping 实现', '三种 HandlerMapping 实现：RequestMappingHandlerMapping（注解映射，主流）、BeanNameUrlHandlerMapping（URL 与 Bean 名 /xxx 对应）、SimpleControllerHandlerMapping（Bean 实现 Controller 接口）。SSM 中几乎只用注解式，理解另两种有助于读懂旧工程。', 'MEDIUM', 2, 103),
('javaee-ssm', 11, '第 11 章 Spring MVC 入门与核心组件', 'javaee-ssm:11:104', '<mvc', '<mvc:annotation-driven/> 的作用：该标签注册 RequestMappingHandlerMapping/RequestMappingHandlerAdapter/ExceptionHandlerExceptionResolver，并默认装配 ConversionService、Validator、HttpMessageConverter（含 JSON）；缺了它 @RequestMapping/@RequestBody 全部失效，返回 404 是最典型的症状。Java Config 侧对应 @EnableWebMvc。', 'MEDIUM', 2, 104),
('javaee-ssm', 11, '第 11 章 Spring MVC 入门与核心组件', 'javaee-ssm:11:105', 'Spring MVC 的容器父子关系', 'Spring MVC 的容器父子关系：web.xml 中 ContextLoaderListener 加载根容器（applicationContext.xml，装 Service/Dao/数据源/事务），DispatcherServlet 加载子容器（spring-mvc.xml，装 Controller/消息转换器/拦截器）；子容器可引用父容器的 Bean，反之不行。这一设计保证事务与业务 Bean 只存在一份，避免 Controller 被重复实例化导致事务失效。', 'MEDIUM', 2, 105),
('javaee-ssm', 11, '第 11 章 Spring MVC 入门与核心组件', 'javaee-ssm:11:106', 'web.xml 标准整合骨架', 'web.xml 标准整合骨架：配 contextConfigLocation 指向根配置 → listener-class 为 ContextLoaderListener → servlet-name 为 springmvc、servlet-class 为 org.springframework.web.servlet.DispatcherServlet、init-param 指向 spring-mvc.xml → servlet-mapping 用 /（REST 风格）或 *.do；再加 CharacterEncodingFilter 且 filter-mapping 为 /*。', 'MEDIUM', 2, 106),
('javaee-ssm', 11, '第 11 章 Spring MVC 入门与核心组件', 'javaee-ssm:11:107', 'InternalResourceViewResolver 视图解析器：设置 pr', 'InternalResourceViewResolver 视图解析器：设置 prefix="/WEB-INF/views/"、suffix=".jsp"，方法返回 "user/list" 即转发到 /WEB-INF/views/user/list.jsp；放在 WEB-INF 下可防止用户直接访问 JSP；前后端分离项目中改用 FastJsonHttpMessageConverter/MappingJackson2HttpMessageConverter 而不配视图解析器。', 'MEDIUM', 2, 107),
('javaee-ssm', 11, '第 11 章 Spring MVC 入门与核心组件', 'javaee-ssm:11:108', 'RESTful 风格 URL 与 HiddenHttpMethodFilter：', 'RESTful 风格 URL 与 HiddenHttpMethodFilter：浏览器表单只支持 GET/POST，用 HiddenHttpMethodFilter 将带 _method=PUT/DELETE 的 POST 请求转成 PUT/DELETE，使 @RequestMapping(method=RequestMethod.PUT) 可被匹配；DefaultServletHandler（<mvc:default-servlet-handler/>）则把静态资源交回容器默认 Servlet，避免被 DispatcherServlet 拦下。', 'MEDIUM', 2, 108),
('javaee-ssm', 11, '第 11 章 Spring MVC 入门与核心组件', 'javaee-ssm:11:109', 'DispatcherServlet 的 throws 与错误页：处理器方法抛出的', 'DispatcherServlet 的 throws 与错误页：处理器方法抛出的异常由 HandlerExceptionResolver 链解析（ExceptionHandlerExceptionResolver → ResponseStatusExceptionResolver → DefaultHandlerExceptionResolver），未被解析则抛给容器，可用 <error-page> 配置 404/500 友好页面。', 'MEDIUM', 2, 109),
('javaee-ssm', 11, '第 11 章 Spring MVC 入门与核心组件', 'javaee-ssm:11:110', 'Spring MVC 常用注解速览', 'Spring MVC 常用注解速览：@Controller、@RestController（= Controller + ResponseBody）、@RequestMapping（value/method/params/headers/produces/consumes）、@GetMapping/@PostMapping/@PutMapping/@DeleteMapping、@RequestParam、@PathVariable、@RequestHeader、@CookieValue、@SessionAttribute、@ModelAttribute、@RequestBody/@ResponseBody，共同构成"以注解代替 struts.xml"的开发体验。', 'MEDIUM', 2, 110),
('javaee-ssm', 11, '第 11 章 Spring MVC 入门与核心组件', 'javaee-ssm:11:111', '【补充】OncePerRequestFilter 与内容包装：Spring 提供', '【补充】OncePerRequestFilter 与内容包装：Spring 提供的 OncePerRequestFilter 保证一次请求只过滤一次，常用于编码、跨域、JWT 解析；配合 ContentCachingRequestWrapper 可重复读取 body，是前后端分离下做统一鉴权/审计的基础设施。', 'EASY', 2, 111),
('javaee-ssm', 12, '第 12 章 请求参数绑定与数据回显', 'javaee-ssm:12:112', '@RequestParam 的用法与细节', '@RequestParam 的用法与细节：用于接收查询串/表单参数，可 @RequestParam("uname") String name、@RequestParam(defaultValue="1") int page、required=false；未指定名称时默认按形参名匹配（依赖编译保留参数名或 @RequestParam）；基本类型必填，包装类型/required=false 允许为空。', 'MEDIUM', 2, 112),
('javaee-ssm', 12, '第 12 章 请求参数绑定与数据回显', 'javaee-ssm:12:113', 'POJO 自动绑定（命令对象）', 'POJO 自动绑定（命令对象）：把表单字段直接绑定到自定义 User 对象（属性名与 <input name> 一致），支持级联 user.address.city 与集合 List<Order> orders、orders[0].id 这类下标语法；底层是 ServletRequestDataBinder + WebDataBinder，可用 initBinder 注册 CustomDateEditor/PropertyEditor 处理日期等自定义类型。', 'MEDIUM', 2, 113),
('javaee-ssm', 12, '第 12 章 请求参数绑定与数据回显', 'javaee-ssm:12:114', '类型转换与格式化', '类型转换与格式化：Spring 用 ConversionService/PropertyEditor 完成 String→数字/日期/枚举；@DateTimeFormat(pattern="yyyy-MM-dd") 标注在 POJO 字段上，配合 @InitBinder 的 CustomDateEditor；统一异常可在全局处理器里捕获 MethodArgumentTypeMismatchException/BindException。', 'MEDIUM', 2, 114),
('javaee-ssm', 12, '第 12 章 请求参数绑定与数据回显', 'javaee-ssm:12:115', 'Model、ModelMap、ModelAndView 的区别：方法入参声明 M', 'Model、ModelMap、ModelAndView 的区别：方法入参声明 Model model，用 model.addAttribute("user", user) 放入 request 域供视图使用；返回 ModelAndView 可同时携带视图名与模型；三者底层都是把数据合并进 BindingAwareModelMap，转发后在 JSP 中用 ${user.name} 输出。', 'MEDIUM', 2, 115),
('javaee-ssm', 12, '第 12 章 请求参数绑定与数据回显', 'javaee-ssm:12:116', '@ModelAttribute 的两种语义', '@ModelAttribute 的两种语义：标在方法入参上表示"从模型/请求参数绑定出一个对象"（常用于修改前先查库再覆盖部分字段）；标在方法上则该方法会在当前 Controller 所有映射方法前执行，用于预置公共数据（如填充下拉框字典项）。', 'MEDIUM', 2, 116),
('javaee-ssm', 12, '第 12 章 请求参数绑定与数据回显', 'javaee-ssm:12:117', '数据回显的常见方案', '数据回显的常见方案：提交失败需回到表单页并保留用户输入——可直接返回原视图名并把命令对象放回 Model；修改场景更常用"先按 id 查实体回填"，或把 @ModelAttribute("user") 方法返回的实体隐式加入模型，实现编辑页自动回显。', 'MEDIUM', 2, 117),
('javaee-ssm', 12, '第 12 章 请求参数绑定与数据回显', 'javaee-ssm:12:118', '重定向后的数据传递', '重定向后的数据传递：redirect: 前缀触发 RedirectView，地址栏变化且 request 属性丢失；可用 RedirectAttributes.addFlashAttribute("msg","成功") 借助 FlashMap/HttpSession 在一次重定向后临时保存提示信息，防止刷新重复提交。', 'MEDIUM', 2, 118),
('javaee-ssm', 12, '第 12 章 请求参数绑定与数据回显', 'javaee-ssm:12:119', '@RequestHeader 与 @CookieValue：@RequestHe', '@RequestHeader 与 @CookieValue：@RequestHeader("User-Agent") String ua 取请求头，@CookieValue("JSESSIONID") String sid 取 Cookie；常用于记录客户端信息、实现"记住我"或解析多语言 Accept-Language。', 'MEDIUM', 2, 119),
('javaee-ssm', 12, '第 12 章 请求参数绑定与数据回显', 'javaee-ssm:12:120', '乱码治理组合拳', '乱码治理组合拳：CharacterEncodingFilter 设 UTF-8 → Tomcat server.xml 的 URIEncoding="UTF-8" → 响应 Content-Type: text/html;charset=UTF-8 → 数据库连接串加 characterEncoding=utf8 且库表为 utf8mb4；四者缺一不可，否则出现"GET 正常 POST 乱码"或入库乱码的分裂现象。', 'MEDIUM', 2, 120),
('javaee-ssm', 12, '第 12 章 请求参数绑定与数据回显', 'javaee-ssm:12:121', '表单校验', '表单校验：JSR-303 与 @Valid：POJO 字段上标注 @NotNull/@NotBlank/@Size(min=6,max=20)/@Email/@Past，方法入参加 @Valid User user, BindingResult result，当 result.hasErrors() 时返回错误页；需引入 hibernate-validator，并在 spring-mvc.xml 配 <mvc:annotation-driven/> 自动启用校验器。', 'MEDIUM', 2, 121),
('javaee-ssm', 12, '第 12 章 请求参数绑定与数据回显', 'javaee-ssm:12:122', '【补充】@InitBinder 与安全', '【补充】@InitBinder 与安全：WebDataBinder 可通过 setAllowedFields/setDisallowedFields 限定可绑定字段，防止"参数注入"攻击（黑客传入 user.admin=true 越权改字段）；前后端分离下应结合 DTO 白名单而非直接绑定实体，这是企业项目的安全基线之一。', 'MEDIUM', 2, 122),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:123', 'HandlerInterceptor 接口的三个回调：preHandle（控制器', 'HandlerInterceptor 接口的三个回调：preHandle（控制器执行前，返回 false 可中断并自行写响应）、postHandle（控制器执行后、视图渲染前，可改 Model/View）、afterCompletion（请求完全结束后，适合释放资源/记录日志）；顺序为 preHandle(A) → preHandle(B) → 业务 → postHandle(B) → postHandle(A) → afterCompletion(B) → afterCompletion(A)。', 'MEDIUM', 2, 123),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:124', '注册与排除拦截器', '注册与排除拦截器：XML 用 <mvc:interceptors><mvc:interceptor><mvc:mapping path="/user/**"/><mvc:exclude-mapping path="/user/login"/><bean class="com.xxx.LoginInterceptor"/></mvc:interceptor></mvc:interceptors>；Java Config 侧继承 WebMvcConfigurer 覆写 addInterceptors(registry)，注册多个即构成有序拦截器链。', 'MEDIUM', 2, 124),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:125', '登录拦截器的标准实现', '登录拦截器的标准实现：preHandle 中判断 request.getSession().getAttribute("user")，为空则 response.sendRedirect(request.getContextPath()+"/login.jsp") 并返回 false；放行登录页与静态资源；配合白名单可避免 Ajax 被重定向，改为返回 401 让前端跳转。', 'MEDIUM', 2, 125),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:126', '用拦截器实现操作日志/权限校验', '用拦截器实现操作日志/权限校验：可在 preHandle 解析 URL 与用户角色（如 /admin/** 要求 ROLE_ADMIN），不满足返回 403；afterCompletion 记录耗时、IP、URI、结果状态码；注意不要在拦截器里做重量级业务，保持"轻量横切"。', 'MEDIUM', 2, 126),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:127', 'HandlerExceptionResolver 体系：Spring MVC 依', 'HandlerExceptionResolver 体系：Spring MVC 依次尝试 ExceptionHandlerExceptionResolver（处理 @ExceptionHandler）、ResponseStatusExceptionResolver（处理 @ResponseStatus）、DefaultHandlerExceptionResolver（处理框架内置异常如 NoHandlerFoundException），全部失败才抛给容器；理解顺序有助于判断"为什么我的 @ExceptionHandler 没生效"。', 'MEDIUM', 2, 127),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:128', '@ControllerAdvice + @ExceptionHandler 全局', '@ControllerAdvice + @ExceptionHandler 全局异常：定义 @ControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(Exception.class) @ResponseBody public Result handle(Exception e){ return Result.error(e.getMessage()); } }，可统一把异常转为 JSON，避免每个方法 try/catch；@ExceptionHandler 也可写在单个 Controller 内做局部处理。', 'MEDIUM', 2, 128),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:129', '@ResponseStatus 与错误码语义', '@ResponseStatus 与错误码语义：在自定义异常上标 @ResponseStatus(value=HttpStatus.NOT_FOUND)，抛出后 Spring 会把响应状态设为 404；常配合 error-page 或 JSON 结构体使用，保证 REST 接口状态码规范。', 'MEDIUM', 2, 129),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:130', '文件上传三要素', '文件上传三要素：表单必须 method="post" enctype="multipart/form-data" 且 <input type="file" name="upload">；在 Spring 中配置 CommonsMultipartResolver（uploadTempDir/maxUploadSize）或 Servlet 3.0 的 StandardServletMultipartResolver（配 MultipartConfigElement）；控制器方法用 @RequestParam("upload") MultipartFile file 接收。', 'MEDIUM', 2, 130),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:131', 'MultipartFile 的常用 API', 'MultipartFile 的常用 API：getOriginalFilename() 取原始文件名、getSize() 取大小、getContentType() 判类型、getBytes()/getInputStream() 取内容、transferTo(dest) 落盘；生产环境需重命名（UUID+后缀）防覆盖、限制大小与白名单扩展名、避免路径拼接导致的目录穿越。', 'MEDIUM', 2, 131),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:132', '文件下载实现', '文件下载实现：设置响应头 Content-Disposition: attachment; filename*=UTF-8''''xxx.zip（含中文用 RFC 5987 编码）与 Content-Type: application/octet-stream，用 ResponseEntity<byte[]> 或直接向 response.getOutputStream() 写流；大文件建议流式复制并指定缓冲区，避免一次性读入内存。', 'MEDIUM', 2, 132),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:133', 'JSON 与日期格式', 'JSON 与日期格式：@DateTimeFormat 管入参、@JsonFormat(pattern="yyyy-MM-dd HH:mm:ss", timezone="GMT+8") 管 Jackson 出参；全局可在 ObjectMapper 配 setDateFormat，避免前端收到时间戳而抱怨格式不一致。', 'MEDIUM', 2, 133),
('javaee-ssm', 13, '第 13 章 拦截器、异常处理与文件上传', 'javaee-ssm:13:134', '【补充】跨域 CORS 配置', '【补充】跨域 CORS 配置：同源策略下浏览器会拦截 Ajax 跨域，需在服务端声明允许来源/方法/头；Spring 提供 @CrossOrigin 注解与全局 CorsRegistry.addMapping("/**").allowedOrigins("*").allowedMethods("GET","POST")，比在 Filter 里手写 Access-Control-Allow-Origin 更易维护，但生产不宜放开 *。', 'MEDIUM', 2, 134),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:135', 'REST 的六大约束', 'REST 的六大约束：客户端-服务器分离、无状态、可缓存、统一接口、分层系统、按需代码；实践中重点体现为"URL 表示资源（名词复数），HTTP 方法表示动作（GET/POST/PUT/DELETE）"，例如 GET /users/1、PUT /users/1、DELETE /users/1、GET /users?page=1&size=10。', 'MEDIUM', 4, 135),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:136', '@RestController 与 @ResponseBody：@RestCon', '@RestController 与 @ResponseBody：@RestController = @Controller + @ResponseBody，其方法返回值不再走视图解析器，而是经 HttpMessageConverter 序列化为 JSON 写回响应体；这是前后端分离项目的默认选择，配合 Vue/React/Ajax 消费。', 'MEDIUM', 2, 136),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:137', '@RequestBody 与 @ResponseBody 分工：@Request', '@RequestBody 与 @ResponseBody 分工：@RequestBody 把请求体（JSON/XML）反序列化为 Java 对象（由 MappingJackson2HttpMessageConverter 完成）；@ResponseBody 把返回值序列化输出；两者都要 @RestController 上下文或显式标注，若返回字符串且未标注会走视图解析导致 404。', 'MEDIUM', 2, 137),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:138', '@PathVariable 与路径变量', '@PathVariable 与路径变量：@GetMapping("/users/{id}") public User get(@PathVariable("id") Long id) 从 URI 模板取值；支持正则 {id:\\d+} 限定类型；能自然表达"资源 + 标识"，比 ?id= 更符合 REST 语义。', 'MEDIUM', 2, 138),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:139', 'consumes 与 produces 的内容协商：@RequestMappin', 'consumes 与 produces 的内容协商：@RequestMapping(value="/x", consumes="application/json", produces="application/json;charset=UTF-8") 约束只接受/产出特定媒体类型，不匹配返回 415 Unsupported Media Type 或 406 Not Acceptable；produces 中的 charset 会影响响应头编码。', 'MEDIUM', 2, 139),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:140', '分页与排序参数设计', '分页与排序参数设计：约定 page/size（或 current/limit）与 sort=field,asc|desc，后端用 @RequestParam(defaultValue="1") 接收并计算 offset=(page-1)*size；MyBatis 侧配合 PageHelper.startPage(page,size) 或手写 LIMIT，返回结构含 total/list/hasNext。', 'MEDIUM', 2, 140),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:141', '统一响应体与错误码', '统一响应体与错误码：约定 Result<T>{int code; String message; T data}，成功 code=200，业务失败返回具体 code；配合全局异常处理器把异常也转成同一结构，前端只需一套拦截逻辑；避免"有的接口返回字符串、有的返回对象"的不一致。', 'MEDIUM', 2, 141),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:142', 'Jackson 常用注解', 'Jackson 常用注解：@JsonProperty("user_name") 改字段名、@JsonIgnore 忽略密码字段、@JsonInclude(NON_NULL) 空值不输出、@JsonFormat 控制日期、@JsonView 按视图裁剪字段；能解决实体与 JSON 字段的差异，减少专门 DTO 的数量。', 'MEDIUM', 2, 142),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:143', 'FastJsonHttpMessageConverter 与 Jackson 选', 'FastJsonHttpMessageConverter 与 Jackson 选型：SSM 项目中早期常用 Fastjson（配置 4 个 converter 并注册 SerializerFeature），现更推荐 Jackson（Spring Boot 默认、安全性记录更好）；无论哪种，都要注意不要直接序列化带懒加载的实体（Hibernate/MyBatis 延迟字段可能触发异常）。', 'MEDIUM', 2, 143),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:144', '会话与认证的演进', '会话与认证的演进：传统用 HttpSession 存登录态 + Cookie JSESSIONID；前后端分离常用 Token（JWT）放请求头 Authorization: Bearer xxx，由拦截器解析后写入 SecurityContext/ThreadLocal，服务端不再有会话状态，便于横向扩容与跨域。', 'MEDIUM', 2, 144),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:145', '前端对接的常见坑', '前端对接的常见坑：①未设 contentType:"application/json" 导致 @RequestBody 收不到值②响应中文乱码（produces 未带 charset）③跨域预检 OPTIONS 被拦截器拦掉④日期格式不一致⑤HTTP 方法被 HiddenHttpMethodFilter 改写；联调时优先用浏览器 Network 面板看请求头/体，再对号入座。', 'MEDIUM', 2, 145),
('javaee-ssm', 14, '第 14 章 RESTful 风格与前后端分离 JSON', 'javaee-ssm:14:146', '【补充】OpenAPI 文档与 Mock', '【补充】OpenAPI 文档与 Mock：接口确定后用 Swagger/Knife4j（@Api/@ApiOperation）生成在线文档，或至少写 Markdown 约定；前后端并行开发时可用 Mock 数据先行联调，减少互相等待，是工程化协作的常规做法。', 'MEDIUM', 2, 146),
('javaee-ssm', 15, '第 15 章 MyBatis 入门与基本用法', 'javaee-ssm:15:147', 'MyBatis 的定位与优缺点', 'MyBatis 的定位与优缺点：半自动 ORM 框架，只把"SQL 与对象的映射"自动化，SQL 仍由开发者编写，兼顾 JDBC 的灵活与 Hibernate 的映射便利；优点是 SQL 可控、便于优化、学习成本低，缺点是数据库移植性弱、简单 CRUD 也需写语句。SSM 中由它承担持久层。', 'MEDIUM', 2, 147),
('javaee-ssm', 15, '第 15 章 MyBatis 入门与基本用法', 'javaee-ssm:15:148', 'SqlSessionFactory 与 SqlSession：SqlSessio', 'SqlSessionFactory 与 SqlSession：SqlSessionFactory 是重量级对象，全局单例，负责创建 SqlSession（会话级对象，非线程安全，用完即关）；典型获取方式为 SqlSessionFactory.openSession() → getMapper(UserMapper.class) → 调用方法 → close()。配置来源为 mybatis-config.xml 或 Java Config。', 'MEDIUM', 2, 148),
('javaee-ssm', 15, '第 15 章 MyBatis 入门与基本用法', 'javaee-ssm:15:149', 'mybatis-config.xml 核心节点', 'mybatis-config.xml 核心节点：<configuration> 下含 <settings>（mapUnderscoreToCamelCase="true" 开启下划线转驼峰、cacheEnabled、lazyLoadingEnabled）、<typeAliases>（typeAlias/package）、<environments>+<dataSource type="POOLED">、<mappers>（resource/class/package 三种注册方式）。', 'MEDIUM', 2, 149),
('javaee-ssm', 15, '第 15 章 MyBatis 入门与基本用法', 'javaee-ssm:15:150', 'Mapper XML 的基本结构', 'Mapper XML 的基本结构：<mapper namespace="com.xxx.mapper.UserMapper"> 的 namespace 需与 Mapper 接口全限定名一致；语句 <select id="findById" parameterType="long" resultType="com.xxx.entity.User">，id 对应接口方法名，parameterType/resultType 可用别名；#{} 预编译占位、${} 字符串拼接（有注入风险）。', 'MEDIUM', 2, 150),
('javaee-ssm', 15, '第 15 章 MyBatis 入门与基本用法', 'javaee-ssm:15:151', '#{} 与 ${} 的本质区别', '#{} 与 ${} 的本质区别：#{id} 会被编译成 PreparedStatement 的 ?，参数安全且能正确处理引号/日期；${name} 直接拼接进 SQL，仅用于表名、排序字段等无法参数化的场景，且必须白名单校验，绝不能接收用户输入拼值。', 'MEDIUM', 2, 151),
('javaee-ssm', 15, '第 15 章 MyBatis 入门与基本用法', 'javaee-ssm:15:152', 'CRUD 标签与主键回填', 'CRUD 标签与主键回填：<insert id="add" useGeneratedKeys="true" keyProperty="id"> 可在插入后把自增主键回填到实体；<update>/<delete> 返回影响行数；<select> 用 resultType 自动按属性名映射列（可配合 AS 别名），多列别名不一致时改用 resultMap。', 'MEDIUM', 2, 152),
('javaee-ssm', 15, '第 15 章 MyBatis 入门与基本用法', 'javaee-ssm:15:153', 'Mapper 接口与 XML 的绑定契约', 'Mapper 接口与 XML 的绑定契约：接口方法名 = XML id，命名空间 = 接口全名，入参类型与 parameterType 对应（注解模式下可省略），返回类型与 resultType 一致；Spring 通过 MapperScannerConfigurer 扫描接口包并生成代理 Bean， DAO 层只需 @Autowired UserMapper。', 'MEDIUM', 2, 153),
('javaee-ssm', 15, '第 15 章 MyBatis 入门与基本用法', 'javaee-ssm:15:154', 'log4j2/logback 打开 SQL 日志', 'log4j2/logback 打开 SQL 日志：配 mybatis.configuration.log-impl=org.apache.ibatis.logging.stdout.StdOutImpl（或 logback 中 com.xxx.mapper 级别 DEBUG），可打印实际 SQL 与参数绑定结果，是排查"语句对但查不到数据"的第一手段。', 'MEDIUM', 2, 154),
('javaee-ssm', 15, '第 15 章 MyBatis 入门与基本用法', 'javaee-ssm:15:155', '与 Spring 整合的关键组件', '与 Spring 整合的关键组件：SqlSessionFactoryBean（依赖 dataSource、configLocation、mapperLocations）+ MapperScannerConfigurer（basePackage、sqlSessionFactoryBeanName），容器启动即生成所有 Mapper 代理并注入到 Dao/Service，这就是 SSM "注解式 DAO" 的来源。', 'MEDIUM', 2, 155),
('javaee-ssm', 15, '第 15 章 MyBatis 入门与基本用法', 'javaee-ssm:15:156', 'SqlSessionTemplate 的作用', 'SqlSessionTemplate 的作用：MyBatis-Spring 提供的线程安全 SqlSession 模板，内部用动态代理把每次操作委托给与当前事务绑定的 SqlSession（SqlSessionUtils.getSqlSession），从而让 @Transactional 在同一连接中生效——这是理解"MyBatis 如何参与 Spring 事务"的核心。', 'MEDIUM', 2, 156),
('javaee-ssm', 15, '第 15 章 MyBatis 入门与基本用法', 'javaee-ssm:15:157', '【补充】ExecutorType 三种执行器', '【补充】ExecutorType 三种执行器：SIMPLE（默认，每次新建 PreparedStatement）、REUSE（复用 Statement）、BATCH（批量重写 SQL）；批处理应使用 SqlSession.getBatchExecutor() + flushStatements()，而不是循环单条 update，否则性能差距可达数十倍。', 'MEDIUM', 2, 157),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:158', '为什么需要动态 SQL', '为什么需要动态 SQL：查询条件常由多个可选参数组成（如同时按姓名/年龄/城市筛选），若为每种组合写一条语句将爆炸；MyBatis 提供 <if>/<where>/<choose>/<foreach>/<set>/<trim> 等标签在 XML 内按条件拼出最终 SQL，是其相对 JDBC 的最大卖点。', 'MEDIUM', 2, 158),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:159', '<if> 与 OGNL 表达式', '<if> 与 OGNL 表达式：<if test="name != null and name != ''''">AND name = #{name}</if>，test 里是 OGNL 判断，支持 and/or、==/!=、集合 size()、_parameter 等；注意 test="flag" 对字符串 "false" 判真，数值型可用 flag == true。', 'MEDIUM', 2, 159),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:160', '<where> 与 <trim> 消除多余关键字', '<where> 与 <trim> 消除多余关键字：<where> 会自动去掉首个 AND/OR，避免 WHERE AND name=? 语法错误；<trim prefix="WHERE" prefixOverrides="AND |OR "> 可自定义前后缀与覆盖规则，<set> 同理为 update 生成动态 SET 子句并去掉末尾逗号。', 'MEDIUM', 2, 160),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:161', '<choose>/<when>/<otherwise> 互斥分支：相当于 if-', '<choose>/<when>/<otherwise> 互斥分支：相当于 if-else，命中一个 when 即停止；常用于状态机或多类型查询（如按 type 走不同字段），比多个独立 <if> 更严谨，可防止拼出非法 WHERE 组合。', 'MEDIUM', 2, 161),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:162', '<foreach> 的三类用法', '<foreach> 的三类用法：①IN 查询 <foreach collection="ids" item="id" open="(" separator="," close=")">#{id}</foreach> → WHERE id IN (?,?,?)；②批量插入 INSERT INTO t VALUES <foreach ...>(#{item})</foreach>；③批量更新用 CASE WHEN 或 separator=";" 拆多条；collection 支持 list/array/map 的 key。', 'MEDIUM', 2, 162),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:163', '一对一关联', '一对一关联：association：<resultMap id="orderMap" type="Order"><id property="id" column="oid"/><association property="user" javaType="User"><id property="id" column="uid"/><result property="name" column="uname"/></association></resultMap>；支持嵌套结果（一次联表查询，columnPrefix 消歧义）与嵌套查询（select="com.xxx.mapper.UserMapper.findById" + fetchType="lazy"），后者易触发 N+1 问题。', 'MEDIUM', 2, 163),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:164', '一对多关联', '一对多关联：collection：<collection property="items" ofType="OrderItem"><id .../><result .../></collection> 表示一个订单含多个明细；同样分嵌套结果与嵌套查询两种实现，后者要注意分页时 PageHelper 对嵌套查询计数的干扰（可能只统计主表）。', 'MEDIUM', 2, 164),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:165', 'resultMap 与 resultType 的选择原则：列名与属性名一致且无关', 'resultMap 与 resultType 的选择原则：列名与属性名一致且无关联映射时用 resultType + mapUnderscoreToCamelCase 最省事；出现字段别名冲突、类型处理器定制、关联映射、鉴别器 <discriminator> 时必须用 resultMap，也可用 autoMapping="true" 部分自动映射。', 'MEDIUM', 2, 165),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:166', '延迟加载与按需加载', '延迟加载与按需加载：lazyLoadingEnabled=true（全局）+ aggressiveLazyLoading=false（访问任一属性即加载全部改为按需），关联对象在用到的瞬间才发 SQL；配置 fetchType="lazy" 可单独控制；分布式环境下延迟加载要避免 Session 关闭后取值（IllegalStateException: Property...）。', 'MEDIUM', 2, 166),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:167', 'N+1 问题与优化', 'N+1 问题与优化：嵌套查询下查 1 个主对象再逐条查 N 个子对象，共 N+1 次 SQL；解法是改嵌套结果一次联表、或用 <foreach> 批量查子集后在内存中拼装；生产环境还应配合索引与分页，避免深分页 LIMIT 100000,10 的慢查询。', 'MEDIUM', 2, 167),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:168', 'parameterType 省略与多参数接口', 'parameterType 省略与多参数接口：单参数可省略 parameterType；多参数时接口用 @Param("name") String name, @Param("age") Integer age 明确名称，XML 中用 #{name}/#{age}，否则只能用 param1/arg0，可读性差且易错。', 'HARD', 2, 168),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:169', 'resultType 为 Map 的场景', 'resultType 为 Map 的场景：列名不固定或做通用导出时用 resultType="map"，得到 List<Map<String,Object>>；但会失去类型安全与编译期检查，仅适合报表/临时需求，业务实体应坚持强类型。', 'MEDIUM', 2, 169),
('javaee-ssm', 16, '第 16 章 动态 SQL、关联映射与结果封装', 'javaee-ssm:16:170', '【补充】分页插件 PageHelper 的原理与用法：PageHelper.st', '【补充】分页插件 PageHelper 的原理与用法：PageHelper.startPage(pageNum,pageSize) 通过 ThreadLocal 把分页参数传给紧随其后的第一条查询，插件生成 LIMIT 并自动执行 count 语句；务必紧跟查询语句调用，中间插入其它 SQL 会导致分页错位或报错。', 'MEDIUM', 2, 170),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:171', '一级缓存（SqlSession 级）', '一级缓存（SqlSession 级）：同一 SqlSession 内执行相同查询时，第二次直接从缓存取，不再访问数据库；缓存以 statementId+参数为键。SqlSession 关闭即失效，且执行 insert/update/delete 或 commit 会清空缓存；因此在 Spring 中每次调用都是新 SqlSession，一级缓存几乎不生效，这也是"改了数据立刻查却看到旧值"的常见疑问来源。', 'MEDIUM', 2, 171),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:172', '二级缓存（namespace 级）', '二级缓存（namespace 级）：以 mapper 命名空间为单位跨 SqlSession 共享，需在 mybatis-config.xml 配 cacheEnabled=true（默认开）并在 XML 中加 <cache/> 或 @CacheNamespace；实体需实现 Serializable；存在脏读（多表关联跨库时）、更新跨 namespace 不同步等风险，实际项目多改用 Redis 集中缓存，默认关闭二级缓存。', 'MEDIUM', 2, 172),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:173', '缓存的执行顺序', '缓存的执行顺序：先查二级缓存再查一级缓存，最后查库；写入时先更新数据库再失效缓存；自定义缓存可通过实现 org.apache.ibatis.cache.Cache 并指定 <cache type="..."/>（如接入 Ehcache/Redis 客户端）。', 'MEDIUM', 2, 173),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:174', '注解方式的 CRUD', '注解方式的 CRUD：@Select("SELECT * FROM user WHERE id=#{id}")、@Insert("INSERT ...")、@Update、@Delete 可直接写在 Mapper 接口上，省去 XML；复杂 SQL 可用 @SelectProvider(type=UserSqlProvider.class, method="buildQuery") 动态拼接；注解与 XML 可共存，但同一方法不可两处定义。', 'MEDIUM', 2, 174),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:175', '注解方式的局限', '注解方式的局限：动态 SQL 在注解里需用 <script> 包裹（@Select("<script>...<if>...</if>...</script>")），可读性随复杂度急剧下降；关联映射只有 @Results/@Result/@One/@Many（配合 @ResultMap 引用）勉强支撑，因此复杂映射仍以 XML 为主、简单 CRUD 用注解，这与 Spring Data JPA/MyBatis-Plus 的取舍一致。', 'MEDIUM', 2, 175),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:176', '@MapKey 与结果转 Map', '@MapKey 与结果转 Map：@MapKey("id") Map<Long,User> listToMap(); 可把 List 转成以某字段为键的 Map，省去手工遍历，常用于字典缓存构建。', 'MEDIUM', 2, 176),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:177', 'resultMap 复用与继承', 'resultMap 复用与继承：<resultMap id="baseUserMap" type="User">...</resultMap> 可被其它 resultMap 通过 extends="baseUserMap" 继承，减少重复列映射；<sql id="cols">id,name,age</sql> 配合 <include refid="cols"/> 复用列片段，是保持多语句一致的常用技巧。', 'MEDIUM', 2, 177),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:178', '类型处理器 TypeHandler', '类型处理器 TypeHandler：内置 String/Number/Date/Enum 等；自定义需实现 org.apache.ibatis.type.TypeHandler<T> 并注册（全局 <typeHandlers> 或 @MappedTypes/@MappedJdbcTypes），典型场景如枚举存 code、布尔与 0/1 转换、JSON 字段与对象互转。', 'MEDIUM', 2, 178),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:179', 'plugin 插件机制', 'plugin 插件机制：MyBatis 允许对 Executor/StatementHandler/ParameterHandler/ResultSetHandler 四个接口做拦截，PageHelper、MyBatis-Plus 的分页与逻辑删除都基于此；实现 Interceptor + @Intercepts(@Signature(...)) 并在配置中 <plugins><plugin interceptor="..."/></plugins> 注册即可。', 'MEDIUM', 2, 179),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:180', '性能 checklist', '性能 checklist：①避免 SELECT *，只取需要列②高频查询建联合索引并注意最左前缀③批量操作用 BATCH/<foreach>④用 PageHelper 而非内存分页⑤开启 jdbcTypeForNull=OTHER 兼容 Oracle 空串⑥监控慢 SQL（MySQL slow_query_log）⑦懒加载与关联查询权衡 N+1。', 'MEDIUM', 4, 180),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:181', 'MyBatis 与 JDBC 的连接获取', 'MyBatis 与 JDBC 的连接获取：整合后由 SqlSessionTemplate 从 DataSourceUtils 拿连接，使 MyBatis 与 JdbcTemplate 可共用同一事务；若在 Service 中混用两者，务必保证用的是 Spring 管理的 DataSource，而不是各自 new 连接，否则事务不生效。', 'MEDIUM', 2, 181),
('javaee-ssm', 17, '第 17 章 MyBatis 缓存、注解方式与性能', 'javaee-ssm:17:182', '【补充】MyBatis-Plus 的定位', '【补充】MyBatis-Plus 的定位：在 MyBatis 之上增强，提供 BaseMapper/IService/LambdaQueryWrapper/代码生成器/逻辑删除/乐观锁/分页插件，可零 SQL 完成大部分 CRUD；SSM 课程以原生 MyBatis 讲原理，实际新项目常直接用 MP，理解本纲的动态 SQL/缓存原理后能更快定位 MP 生成的 SQL 问题。', 'MEDIUM', 2, 182),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:183', '整合的总体思路', '整合的总体思路：SSM 整合 = 让 Spring 的 IoC 容器统一管理数据源、事务管理器、MyBatis 工厂、Mapper 代理、Service、Controller，并让 Spring MVC 作为 Web 层入口。核心是"两个容器（根 + Web）+ 一份配置分工"，任何 Bean 只应在一个容器里定义一次。', 'MEDIUM', 2, 183),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:184', 'web.xml 的关键配置项', 'web.xml 的关键配置项：①<context-param><param-name>contextConfigLocation</param-name><param-value>classpath:applicationContext.xml</param-value> ②<listener><listener-class>org.springframework.web.context.ContextLoaderListener</listener-class> ③<servlet> 指向 org.springframework.web.servlet.DispatcherServlet 并配 contextConfigLocation=classpath:spring-mvc.xml，load-on-startup=1 ④<servlet-mapping> 用 / ⑤CharacterEncodingFilter 拦截 /*。缺一不可，顺序上 Filter 要在 Servlet 之前声明。', 'MEDIUM', 2, 184),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:185', 'applicationContext.xml（根容器）职责：<context:c', 'applicationContext.xml（根容器）职责：<context:component-scan base-package="com.xxx"> 扫描时排除 @Controller（excludeFilters），避免子容器重复实例化导致事务失效；配置 <context:property-placeholder location="classpath:jdbc.properties"/>、数据源（Druid/DBCP）、DataSourceTransactionManager、<tx:annotation-driven/>、SqlSessionFactoryBean（dataSource/configLocation/mapperLocations）、MapperScannerConfigurer（basePackage）。', 'MEDIUM', 2, 185),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:186', 'spring-mvc.xml（Web 容器）职责', 'spring-mvc.xml（Web 容器）职责：扫描 @Controller/@RestController；<mvc:annotation-driven/> 启用注解映射与消息转换器（可自定义 FastJsonHttpMessageConverter 或 MappingJackson2HttpMessageConverter）；<mvc:default-servlet-handler/> 放行静态资源；InternalResourceViewResolver 前缀后缀；<mvc:interceptors> 注册登录/权限拦截器；文件上传解析器 CommonsMultipartResolver；<mvc:view-controller> 处理纯跳转。', 'MEDIUM', 2, 186),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:187', 'MyBatis 主配置的最小集', 'MyBatis 主配置的最小集：mybatis-config.xml 中通常只保留 <settings>（mapUnderscoreToCamelCase、cacheEnabled、logImpl、jdbcTypeForNull）与 <typeAliases>/<typeHandlers>，数据源与 mapper 注册交给 Spring 管理，避免出现两套 SqlSessionFactory。', 'MEDIUM', 2, 187),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:188', 'Mapper 接口的三种注册方式', 'Mapper 接口的三种注册方式：XML 的 <mappers><mapper resource="..."/></mappers>（精确控制，适合复杂语句）；MapperScannerConfigurer 按包扫描（主流，配合 @Mapper 或接口在约定包下）；@MapperScan("com.xxx.mapper")（Java Config 风格）。同一接口只能被注册一次，否则启动报错。', 'MEDIUM', 2, 188),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:189', '典型项目分层与各层职责', '典型项目分层与各层职责：controller（接收请求、参数校验、调用 Service、返回视图/JSON）→ service（业务编排、事务边界 @Transactional）→ mapper/dao（MyBatis 持久化）→ entity/dto/vo（实体与传输对象）→ common（Result/枚举/异常/工具类）→ interceptor+aspect（横切）。事务注解只加在 Service 层。', 'MEDIUM', 2, 189),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:190', 'druid/HikariCP 连接池与监控', 'druid/HikariCP 连接池与监控：SSM 项目常用 Druid（filters=stat,wall + stat-view-servlet 提供 SQL 监控页），HikariCP 则以高性能著称；关键参数 initialSize/minIdle/maxActive/maxWait/validationQuery=SELECT 1，生产开启 testWhileIdle 防止连接被数据库/防火墙掐断后拿到死连接。', 'MEDIUM', 2, 190),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:191', '日志整合 logback/log4j2', '日志整合 logback/log4j2：引入 slf4j-api + logback-classic（或 log4j-slf4j-impl），配 logback-spring.xml 的 console/rollingFile appender 与按包级别（com.xxx.mapper=DEBUG 看 SQL）；MyBatis 的 logImpl 与日志框架二选一，避免重复输出。', 'MEDIUM', 2, 191),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:192', 'war 打包与部署', 'war 打包与部署：Maven 中 <packaging>war</packaging>，maven-war-plugin 指定 webappDirectory；确认 WEB-INF/classes 含编译产物、WEB-INF/lib 含依赖 jar；部署到 Tomcat 的 webapps/ 或直接放 war 由 autoDeploy 解压；上下文路径决定访问 URL（ROOT.war 即根路径）。', 'MEDIUM', 2, 192),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:193', 'maven 依赖的最小清单与常见冲突', 'maven 依赖的最小清单与常见冲突：spring-context/spring-webmvc/spring-jdbc/spring-tx/spring-test、mybatis+mybatis-spring、mysql-connector-j、druid、jackson-databind、javax.servlet-api(scope=provided)、jstl；冲突多见于 servlet-api 重复引入（ClassNotFoundException 或 NoSuchMethodError）、Jackson/Fastjson 版本共存，排查用 mvn dependency:tree。', 'MEDIUM', 2, 193),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:194', 'ContextLoaderListener 与容器启动顺序：监听器在 Servl', 'ContextLoaderListener 与容器启动顺序：监听器在 Servlet 初始化前启动根容器并放入 ServletContext；若未配 contextConfigLocation 会默认找 /WEB-INF/applicationContext.xml，找不到则报 FileNotFoundException；Spring 5 还提供 ContextLoader 的可定制钩子用于父容器设置。', 'MEDIUM', 2, 194),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:195', '常见整合失败对照表', '常见整合失败对照表：①404 → url-pattern 与访问路径不符、@RequestMapping 拼写错、annotation-driven 缺失、Controller 未被扫描②500 且提示找不到 Bean → 包扫描范围错误或父子容器重复扫描③事务不生效 → 未开 <tx:annotation-driven>/自调用/非 public 方法④MyBatis 查不到数据 → mapper XML 未加载、namespace/id 不一致、列名属性不匹配⑤中文乱码 → 过滤器顺序或 URIEncoding 缺失。', 'MEDIUM', 2, 195),
('javaee-ssm', 18, '第 18 章 SSM 整合与项目分层', 'javaee-ssm:18:196', '【补充】无 web.xml 的 Spring MVC 启动：Servlet 3.', '【补充】无 web.xml 的 Spring MVC 启动：Servlet 3.0 起可用 AbstractAnnotationConfigDispatcherServletInitializer/AbstractDispatcherServletInitializer 以 Java 代码替代 web.xml，Spring Boot 进一步用 SpringApplication + 内嵌 Tomcat 完成自动装配；SSM 传统教学仍以 XML 为主，但应知道"配置等价于编程式注册"。', 'MEDIUM', 2, 196),
('javaee-ssm', 19, '第 19 章 综合实战：权限控制与项目完善【补充】', 'javaee-ssm:19:197', 'RBAC 权限模型入门', 'RBAC 权限模型入门：用户(User)—角色(Role)—权限(Permission) 三张核心表，通过中间表 user_role、role_permission 建立多对多关系；查询某用户可用菜单/按钮权限时，用 SELECT p.code FROM permission p JOIN role_permission rp ... JOIN user_role ur ... WHERE ur.user_id=#{id}，结果集作为拦截器校验依据。', 'EASY', 2, 197),
('javaee-ssm', 19, '第 19 章 综合实战：权限控制与项目完善【补充】', 'javaee-ssm:19:198', '登录流程的落地链路', '登录流程的落地链路：Controller 接 @RequestParam username/password → 调用 userService.login（查询用户、比对密码）→ 成功则 session.setAttribute("user", user) 并 redirect:/index；失败回显 msg；密码必须加盐哈希存储（如 BCrypt），严禁明文入库，这是安全底线。', 'MEDIUM', 2, 198),
('javaee-ssm', 19, '第 19 章 综合实战：权限控制与项目完善【补充】', 'javaee-ssm:19:199', '退出登录与 Session 失效', '退出登录与 Session 失效：session.invalidate() 清空会话并让 JSESSIONID 失效；同时清理 ThreadLocal 中的用户上下文，避免线程复用导致的信息泄漏。', 'MEDIUM', 2, 199),
('javaee-ssm', 19, '第 19 章 综合实战：权限控制与项目完善【补充】', 'javaee-ssm:19:200', '统一权限拦截器的实现思路', '统一权限拦截器的实现思路：维护资源 URL 白名单（登录、静态资源、公共页），其余请求要求会话中存在用户并按需校验角色/权限编码；无权访问返回 403 页或 JSON {code:403}，越权操作要记审计日志。', 'MEDIUM', 2, 200),
('javaee-ssm', 19, '第 19 章 综合实战：权限控制与项目完善【补充】', 'javaee-ssm:19:201', '操作审计与日志切面', '操作审计与日志切面：自定义 @Log(module="用户管理", action="新增") 注解 + AOP 环绕通知，记录操作人、IP、方法入参、耗时、结果；把审计写入异步队列可降低对主流程的性能影响。', 'MEDIUM', 2, 201),
('javaee-ssm', 19, '第 19 章 综合实战：权限控制与项目完善【补充】', 'javaee-ssm:19:202', '分页查询的完整实现', '分页查询的完整实现：前端传 page/size，后端 PageHelper.startPage(page,size) + selectList 得到 PageInfo，返回 total/list/pages/hasNextPage；Mapper 侧 ORDER BY 字段须建索引，深分页改用"上一页最大 id"游标式查询。', 'MEDIUM', 2, 202),
('javaee-ssm', 19, '第 19 章 综合实战：权限控制与项目完善【补充】', 'javaee-ssm:19:203', '批量导入导出', '批量导入导出：导入用 MultipartFile + POI（Excel）逐行校验后批量落库（BATCH Executor 或 insert ... values (...),(...)），支持事务整体回滚；导出用 HttpServletResponse 写流并设 Content-Disposition，注意大数据量分批查询防 OOM。', 'MEDIUM', 2, 203),
('javaee-ssm', 19, '第 19 章 综合实战：权限控制与项目完善【补充】', 'javaee-ssm:19:204', '文件/图片服务与静态化', '文件/图片服务与静态化：上传落盘或对象存储（OSS/MinIO），URL 存库；页面通过 <img src="${ctx}/upload/xxx.png"> 展示；大文件建议分片上传 + 秒传校验（MD5/SHA1），避免重复传输。', 'MEDIUM', 2, 204),
('javaee-ssm', 19, '第 19 章 综合实战：权限控制与项目完善【补充】', 'javaee-ssm:19:205', '全局异常与统一响应体', '全局异常与统一响应体：@ControllerAdvice 捕获 BusinessException（转业务码）、MethodArgumentNotValidException（表单校验失败返回字段错误）、Exception（兜底 500 并记日志）；前端统一拦截 code != 200 弹出提示并跳转登录。', 'MEDIUM', 2, 205),
('javaee-ssm', 19, '第 19 章 综合实战：权限控制与项目完善【补充】', 'javaee-ssm:19:206', '部署优化清单', '部署优化清单：Tomcat 调 maxThreads/acceptCount/连接超时；JVM 设 -Xms/-Xmx 一致并开启 GC 日志；关闭 autoDeploy 改用受控发布；静态资源交由 Nginx 反代并开启 gzip/缓存；数据库加连接池监控告警；敏感配置（密码/密钥）外置到环境变量或配置中心。', 'MEDIUM', 2, 206),
('javaee-ssm', 19, '第 19 章 综合实战：权限控制与项目完善【补充】', 'javaee-ssm:19:207', '【补充】课程设计验收要点', '【补充】课程设计验收要点：能说清"一次请求从浏览器到数据库再返回"的完整链路（DispatcherServlet→Controller→Service→Mapper→SQL→结果映射→JSON/JSP）；能独立排查 404/500/事务失效/乱码四类高频故障；能解释 IoC、AOP、动态 SQL、会话跟踪四个核心概念的实际作用。', 'MEDIUM', 4, 207)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('mybatis', 1, '第 1 章 软件框架技术简介', 'mybatis:1:1', '框架的定义', '框架的定义：软件框架是为实现业界标准或特定基本任务而形成的软件组件规范，也是提供规范所需基础功能的软件产品，其功能类似基础设施，与具体应用无关。', 'EASY', 2, 1),
('mybatis', 1, '第 1 章 软件框架技术简介', 'mybatis:1:2', '为什么需要框架', '为什么需要框架：框架是应用程序的半成品，按一定规则组织一组可复用公共结构，让开发者不再重复思考公共问题、专心业务实现，同时结构统一、易学习维护，新手也能写出较高质量的程序。', 'MEDIUM', 2, 2),
('mybatis', 1, '第 1 章 软件框架技术简介', 'mybatis:1:3', '不重复造轮子', '不重复造轮子：「不要重复造轮子」是开发人员基本原则；Java 世界主流框架包括 Spring、SpringMVC、MyBatis、Struts、Hibernate、SpringBoot 等。', 'MEDIUM', 2, 3),
('mybatis', 1, '第 1 章 软件框架技术简介', 'mybatis:1:4', '课程目标', '课程目标：理解 ORM 思想、掌握 MyBatis 配置数据库步骤、用代理方式实现持久层、完成 CRUD、掌握动态 SQL 与关联查询；重点是 mapper 代理写法、CRUD 与动态 SQL、关联查询。', 'MEDIUM', 4, 4),
('mybatis', 2, '第 2 章 MyBatis 简介', 'mybatis:2:5', 'ORM 思想提出背景', 'ORM 思想提出背景：数据库以表形式存数据，Java 中以对象使用数据，二者转换产生大量无技术含量的纯「体力」型代码，ORM（对象-关系映射）即完成对象数据到关系型数据映射的机制。', 'MEDIUM', 2, 5),
('mybatis', 2, '第 2 章 MyBatis 简介', 'mybatis:2:6', '原生 JDBC 痛点代码', '原生 JDBC 痛点代码：while(rs.next()) 循环里逐个 rs.getInt("businessId")、rs.getString("password")、rs.getDouble("starPrice") 后 list.add(business)，工作量大且单调，正是 ORM 要消除的部分。', 'MEDIUM', 2, 6),
('mybatis', 2, '第 2 章 MyBatis 简介', 'mybatis:2:7', 'MyBatis 是什么', 'MyBatis 是什么：一个 ORM 框架，也是持久层框架；封装 JDBC，将表数据自动封装进对象，使开发工作量变小、代码精简易读，支持普通 SQL 查询、存储过程与高级映射。', 'MEDIUM', 2, 7),
('mybatis', 2, '第 2 章 MyBatis 简介', 'mybatis:2:8', '项目沿革', '项目沿革：MyBatis 本是 apache 开源项目 iBatis，2010 年由 apache software foundation 迁移至 google code 并改名为 MyBatis，即 iBatis 3.0 之后统称 MyBatis。', 'MEDIUM', 2, 8),
('mybatis', 2, '第 2 章 MyBatis 简介', 'mybatis:2:9', '核心能力定位', '核心能力定位：MyBatis 最核心的功能是实现输入映射和输出映射——输入映射解决 SQL 参数注入，输出映射解决结果集到对象的装配。', 'MEDIUM', 2, 9),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:10', 'Maven 依赖清单', 'Maven 依赖清单：org.mybatis:mybatis:3.5.3、mysql:mysql-connector-java:8.0.31、org.projectlombok:lombok:1.18.30、junit:junit:4.13（scope 为 test）。', 'MEDIUM', 2, 10),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:11', '全局配置文件骨架', '全局配置文件骨架：SqlMapConfig.xml 顶部声明 <!DOCTYPE configuration PUBLIC "-//mybatis.org//DTD Config 3.0//EN" "http://mybatis.org/dtd/mybatis-3-config.dtd">，根标签 <configuration>。', 'MEDIUM', 2, 11),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:12', '事务管理器取值', '事务管理器取值：<transactionManager type="JDBC"/> 表示完全使用 jdbc 事务管理；type="MANAGED" 表示不使用事务管理且从不提交（由容器管理）。', 'MEDIUM', 2, 12),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:13', '数据源三种取值', '数据源三种取值：<dataSource type="POOLED"> 使用自带连接池，UNPOOLED 不使用任何连接池，JNDI 以 jndi 形式获取数据库连接。', 'MEDIUM', 2, 13),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:14', '连接池属性写法', '连接池属性写法：POOLED 内用 <property name="driver" value="com.mysql.cj.jdbc.Driver"/>、name="url"（含 serverTimezone=Asia/Shanghai&amp;characterEncoding=utf-8）、name="username"、name="password" 四项配置。', 'MEDIUM', 2, 14),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:15', '多环境与默认值', '多环境与默认值：<environments default="development"> 可配置多个数据源环境，运行时取 default 指定的那个 <environment id="development">。', 'MEDIUM', 2, 15),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:16', 'PO 类设计约定', 'PO 类设计约定：在 com.example.po 包创建 Emp 类并用 Lombok @Data 生成 getter/setter，属性 empno/ename/job/hiredate/sal/deptno 必须与表字段名一致（原书示例将 hiredate 直接定义为 String）。', 'MEDIUM', 2, 16),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:17', '映射文件结构与标签语义', '映射文件结构与标签语义：根标签 <mapper namespace="emp">，namespace 用于对 SQL 分类管理、防止 id 重复；<select id="getEmpById" parameterType="int" resultType="com.example.po.Emp">，其中 id 即 statement 的 id 需唯一。', 'MEDIUM', 2, 17),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:18', 'SQL 占位符规则', 'SQL 占位符规则：#{} 表示 sql 参数占位符；parameterType 为对象类型时 #{} 中写对象属性名且严格区分大小写，为单个值时参数名可任意；本例 SQL 为 select * from emp where empno = #{empno}。', 'MEDIUM', 2, 18),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:19', '输出映射原理', '输出映射原理：MyBatis 依据字段名与实体属性名自动映射，把查询列值注入对象每个属性，这就是输出映射；不需要手写 getXxx 赋值代码。', 'MEDIUM', 2, 19),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:20', '类路径资源打包配置', '类路径资源打包配置：映射文件若放在 src/main/java 下，需在 pom.xml 的 <build><resources> 中声明 <resource><directory>src/main/java</directory><includes><include>**/*.xml</include></includes><filtering>false</filtering></resource>，同时保留 resources 目录。', 'MEDIUM', 2, 20),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:21', '四大核心接口使用', '四大核心接口使用：Resources.getResourceAsStream("SqlMapConfig.xml") 读取配置 → new SqlSessionFactoryBuilder().build(inputStream) 构建工厂 → sf.openSession() 得到会话 → session.selectOne("emp.getEmpById", 7521) 执行并返回 Emp。', 'MEDIUM', 2, 21),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:22', 'selectOne 与 selectList 选型：返回一条记录用 select', 'selectOne 与 selectList 选型：返回一条记录用 selectOne 输出映射为一个 java 对象，返回多条用 selectList 输出映射为集合；两者第一个参数是「命名空间.id」，第二个参数是 SQL 传值。', 'MEDIUM', 2, 22),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:23', '会话生命周期与资源释放', '会话生命周期与资源释放：SqlSession 对应一次数据库会话、线程不安全，测试中必须在 finally 里判断 if (session != null) session.close()，工厂则在 tearDown 中置空。', 'MEDIUM', 2, 23),
('mybatis', 3, '第 3 章 MyBatis 实例（查询工号 7521）', 'mybatis:3:24', '日志集成', '日志集成：MyBatis 默认使用 log4j 输出日志，添加 log4j:log4j:1.2.17 后，在 resources 放 log4j.properties，设 log4j.appender.stdout=org.apache.log4j.ConsoleAppender 与 log4j.rootLogger=debug,stdout 即可看到 Preparing/Parameters/Total 明细。', 'MEDIUM', 2, 24),
('mybatis', 4, '第 4 章 MyBatis 核心接口和类', 'mybatis:4:25', 'SqlSessionFactoryBuilder', 'SqlSessionFactoryBuilder：负责构建 SqlSessionFactory，提供多个 build() 重载，可从 xml 配置文件或从 Configuration 对象来构建；它是一次性对象，用完即可丢弃。', 'MEDIUM', 2, 25),
('mybatis', 4, '第 4 章 MyBatis 核心接口和类', 'mybatis:4:26', 'SqlSessionFactory', 'SqlSessionFactory：创建 SqlSession 实例的工厂，通过 openSession() 获取 SqlSession；一旦被创建就在整个应用程序期间存在，应作为单例（或交给 Spring 容器）持有。', 'MEDIUM', 2, 26),
('mybatis', 4, '第 4 章 MyBatis 核心接口和类', 'mybatis:4:27', 'SqlSession', 'SqlSession：面向程序员的接口，提供面向数据库执行 sql 命令所需的全部方法；对应一次数据库会话且线程不安全，因此每次请求都应新建、用完即关。', 'MEDIUM', 2, 27),
('mybatis', 4, '第 4 章 MyBatis 核心接口和类', 'mybatis:4:28', '执行链路【补充】', '执行链路【补充】：SqlSession 实际委托 Configuration 创建 Executor（SIMPLE/REUSE/BATCH 三型），Executor 通过 StatementHandler 准备语句、ParameterHandler 设置参数、ResultSetHandler 装配结果集。', 'MEDIUM', 2, 28),
('mybatis', 4, '第 4 章 MyBatis 核心接口和类', 'mybatis:4:29', 'Mapper 代理原理【补充】', 'Mapper 代理原理【补充】：sqlSession.getMapper(EmpMapper.class) 走 MapperProxyFactory 生成 JDK 动态代理，方法调用被 MapperMethod 解析为 MappedStatement 后交给上述执行链，无需手写实现类。', 'MEDIUM', 2, 29),
('mybatis', 5, '第 5 章 封装持久层', 'mybatis:5:30', '两种 DAO 开发方式', '两种 DAO 开发方式：原始 dao 方式需自己写 dao 接口与实现类；mapper 代理方式只需 mapper 接口 + mapper.xml，由 Mybatis 自动生成接口实现类的代理对象。', 'MEDIUM', 2, 30),
('mybatis', 5, '第 5 章 封装持久层', 'mybatis:5:31', '原始 dao 方式典型结构', '原始 dao 方式典型结构：先封装 DBUtil 工具类，用静态字段缓存 sqlSessionFactory，内部 Resources.getResourceAsReader("SqlMapConfig.xml") + new SqlSessionFactoryBuilder().build(reader) 惰性初始化。', 'MEDIUM', 2, 31),
('mybatis', 5, '第 5 章 封装持久层', 'mybatis:5:32', '原始 dao 实现类写法', '原始 dao 实现类写法：EmpDaoImpl 每个方法都重复 getSqlSessionFactory().openSession() → selectOne/selectList("emp.xxx", 参数) → close() 三步模板代码。', 'MEDIUM', 2, 32),
('mybatis', 5, '第 5 章 封装持久层', 'mybatis:5:33', '原始 dao 方式的三大问题', '原始 dao 方式的三大问题：一是实现类中存在大量重复代码；二是调用 sqlSession 方法时 statement 的 id 以字符串硬编码，重命名即失效；三是因泛型擦除，传参类型错误在编译阶段不报错。', 'MEDIUM', 2, 33),
('mybatis', 5, '第 5 章 封装持久层', 'mybatis:5:34', 'mapper 代理方式开发规范一', 'mapper 代理方式开发规范一：映射文件中的 namespace 必须是 mapper 接口的全限定地址，例如 <mapper namespace="com.example.mapper.EmpMapper">。', 'MEDIUM', 2, 34),
('mybatis', 5, '第 5 章 封装持久层', 'mybatis:5:35', 'mapper 代理方式开发规范二', 'mapper 代理方式开发规范二：映射文件中 statement 的 id 必须与 mapper 接口中的方法名一致，如 id="listEmpAll" 对应 List<Emp> listEmpAll();。', 'MEDIUM', 2, 35),
('mybatis', 5, '第 5 章 封装持久层', 'mybatis:5:36', 'mapper 代理方式开发规范三', 'mapper 代理方式开发规范三：映射文件的 parameterType 必须与接口方法参数类型一致，resultType 必须与返回值类型一致。', 'MEDIUM', 2, 36),
('mybatis', 5, '第 5 章 封装持久层', 'mybatis:5:37', '代理对象的选型依据', '代理对象的选型依据：代理对象正是根据返回值类型判断该调 selectOne 还是 selectList——返回单个 POJO 走 selectOne，返回 List 走 selectList。', 'MEDIUM', 2, 37),
('mybatis', 5, '第 5 章 封装持久层', 'mybatis:5:38', '目录约定', '目录约定：mapper 接口与映射文件最好同文件夹存放且接口名与文件名一致，便于用 package 批量加载。', 'MEDIUM', 2, 38),
('mybatis', 6, '第 6 章 MyBatis 配置的优化', 'mybatis:6:39', '批量加载映射文件', '批量加载映射文件：若映射文件与 mapper 接口同名且同目录，可用 <mappers><package name="com.example.mapper"/></mappers> 自动加载该包下所有同名映射文件，package 标签可写多个。', 'MEDIUM', 2, 39),
('mybatis', 6, '第 6 章 MyBatis 配置的优化', 'mybatis:6:40', '批量定义类别名', '批量定义类别名：<typeAliases><package name="com.example.po"/></typeAliases> 自动扫描指定包中的类并定义别名，别名就是类名，首字母大写小写均可（如 Emp 可写 Emp 或 emp）。', 'MEDIUM', 2, 40),
('mybatis', 6, '第 6 章 MyBatis 配置的优化', 'mybatis:6:41', '数据库配置外置', '数据库配置外置：把驱动/URL/用户名/密码抽到 db.properties，内容形如 jdbc.driver=com.mysql.cj.jdbc.Driver、jdbc.url=jdbc:mysql://localhost:3306/company?serverTimezone=Asia/Shanghai&characterEncoding=utf-8、jdbc.username=root、jdbc.password=。', 'MEDIUM', 2, 41),
('mybatis', 6, '第 6 章 MyBatis 配置的优化', 'mybatis:6:42', 'properties 引入方式', 'properties 引入方式：在 <configuration> 内写 <properties resource="db.properties"></properties>，随后 dataSource 里以 ${jdbc.driver}、${jdbc.url} 等占位符引用，注意 XML 中 & 需写成 &amp;。', 'MEDIUM', 2, 42),
('mybatis', 6, '第 6 章 MyBatis 配置的优化', 'mybatis:6:43', 'settings 常用开关【补充】', 'settings 常用开关【补充】：<settings> 中 mapUnderscoreToCamelCase=true 可将 user_name 自动映射到 userName；另有 cacheEnabled、lazyLoadingEnabled、aggressiveLazyLoading、defaultExecutorType、logImpl 等。', 'MEDIUM', 2, 43),
('mybatis', 6, '第 6 章 MyBatis 配置的优化', 'mybatis:6:44', 'typeAliases 的两种粒度【补充】', 'typeAliases 的两种粒度【补充】：<package> 整包扫描别名，<typeAlias type="com.example.po.Emp" alias="employee"/> 单个精确定义别名，后者可规避同名类冲突。', 'MEDIUM', 2, 44),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:45', '多条件查询的输入映射', '多条件查询的输入映射：parameterType 只能有一个，多参数时必须用对象传值（即输入映射）；映射文件写 <select id="listEmp" parameterType="Emp" resultType="Emp">，SQL 为 where job like concat(''%'',#{job},''%'') and deptno=#{deptno} order by empno。', 'MEDIUM', 2, 45),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:46', '模糊查询写法', '模糊查询写法：concat(''%'',#{job},''%'') 配合 #{} 既安全又避免字符串拼接注入；测试时 new Emp() 后 setJob("CLERK")、setDeptno(20) 再传给 mapper。', 'MEDIUM', 2, 46),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:47', '转义字符', '转义字符：小于号是 XML 标签关键词，SQL 中须写 &lt;，如 select * from emp where sal &lt; #{sal} order by empno；同理 > 写 &gt;、& 写 &amp;、引号也可用 CDATA 段替代。', 'MEDIUM', 2, 47),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:48', '返回单值的约束', '返回单值的约束：只有「一行一列」时 resultType 才能用基本类型，例如 <select id="listEmpCount" resultType="int">select count(*) from emp</select>，对应接口 public int listEmpCount();。', 'MEDIUM', 2, 48),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:49', '插入不取主键', '插入不取主键：<insert id="insertEmp1" parameterType="Emp">insert into emp(empno,ename,job,hiredate,deptno) values(#{empno},#{ename},#{job},#{hiredate},#{deptno})</insert>，增删改都返回 int 影响行数，但 insert 标签中不能写 resultType。', 'MEDIUM', 2, 49),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:50', '插入后必须提交', '插入后必须提交：原生 SqlSession 事务下，执行 insert/update/delete 后必须 sqlSession.commit()，否则数据不会落库，这是初学者最高频的「保存成功却查不到」原因。', 'MEDIUM', 4, 50),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:51', 'selectKey 取主键', 'selectKey 取主键：<selectKey keyProperty="empno" resultType="int" order="AFTER">select LAST_INSERT_ID()</selectKey>，MyBatis 会把取到的主键自动封装进 keyProperty 指定的属性。', 'MEDIUM', 2, 51),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:52', 'order 的两种取值', 'order 的两种取值：BEFORE 表示先取主键再执行 insert（适用于 Oracle 序列），AFTER 表示先 insert 再取主键（适用于 MySQL 自增列）。', 'MEDIUM', 2, 52),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:53', 'useGeneratedKeys 取主键', 'useGeneratedKeys 取主键：<insert id="insertEmp3" parameterType="Emp" useGeneratedKeys="true" keyProperty="empno">，MyBatis 使用 JDBC 的 getGeneratedKeys 获取数据库自动生成的主键，仅适用于有自增长列的数据库（mysql、sqlserver 等）。', 'MEDIUM', 2, 53),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:54', '修改语句模板', '修改语句模板：<update id="updateEmp" parameterType="Emp">update emp set job=#{job},sal=#{sal} where empno=#{empno}</update>，同样需要 commit 才生效。', 'MEDIUM', 2, 54),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:55', '删除语句模板', '删除语句模板：<delete id="deleteEmp" parameterType="int">delete from emp where empno=#{empno}</delete>，parameterType 为单个值时 #{} 的名字可任意。', 'MEDIUM', 2, 55),
('mybatis', 7, '第 7 章 常用数据库操作', 'mybatis:7:56', '实践作业（在线书店）', '实践作业（在线书店）：books 表含 id(AUTO_INCREMENT)、title、author、price DECIMAL(10,2)、stock，要求创建 PO、编写含「查询所有书籍」的映射文件、并获取 BooksMapper 代理对象调用查询。', 'MEDIUM', 2, 56),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:57', '动态 SQL 的用途', '动态 SQL 的用途：解决查询条件不确定的情况——根据用户是否输入某个值决定是否拼接该条件；主要元素有 if、where、trim、set、foreach、choose 等。', 'MEDIUM', 2, 57),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:58', 'if + where 组合效果', 'if + where 组合效果：<where> 会自动补上 where 关键字、自动去掉首个 and/or、自动处理空格；<if test="job!=null and job!=''''">and job like concat(''%'',#{job},''%'')</if> 是标准多条件查询写法。', 'MEDIUM', 2, 58),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:59', 'OGNL 表达式注意点', 'OGNL 表达式注意点：test 中 job!='''' 只能判空不能判等值，即 job!=''经理'' 这种写法不生效；字符串与单字符比较需写 job != ''CLERK''.toString() 或用 .equals()。', 'MEDIUM', 2, 59),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:60', '无 else/else if', '无 else/else if：MyBatis 动态 SQL 没有 else 和 else if 标签，需要「互斥分支」时使用 choose/when/otherwise 代替。', 'MEDIUM', 2, 60),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:61', 'choose 语义', 'choose 语义：多个 <when test="..."> 中只有一个会被执行，一旦某个 when 命中其余不再判断；全部不满足时执行 <otherwise>，如 and deptno = 10。', 'MEDIUM', 2, 61),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:62', 'if 与 choose 的区别', 'if 与 choose 的区别：if 相当于 Java 的 if 语句（可叠加），choose 相当于 switch 语句（互斥取一）；测试中两个条件都不传时输出 select * from emp WHERE deptno = 10 order by empno。', 'MEDIUM', 2, 62),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:63', 'trim 的四个属性', 'trim 的四个属性：prefix 加前缀、suffix 加后缀、prefixOverrides 忽略开头内容、suffixOverrides 忽略结尾内容；配合使用可拼出一对小括号并去掉末尾逗号。', 'MEDIUM', 2, 63),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:64', 'trim 实现动态列插入', 'trim 实现动态列插入：<trim prefix="(" suffix=")" suffixOverrides=",">empno,ename,deptno,<if test="job!=null and job!=''''">job,</if></trim> 与 values 部分的同构 trim，日志输出为 insert into emp ( empno,ename,deptno, job ) values( ?,?,?,? )。', 'MEDIUM', 2, 64),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:65', 'set 标签', 'set 标签：用于 update，自动补 set 关键词并去掉最后多余的逗号；须保证至少有一个 if 成立，否则生成 update emp set where ... 的非法语句。', 'MEDIUM', 2, 65),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:66', 'set 与 if 组合示例', 'set 与 if 组合示例：<update id="updateEmp" parameterType="Emp">update emp <set>empno=#{empno},<if test="job!=null and job!=''''">job=#{job},</if><if test="sal!=null and sal!=''''">sal=#{sal},</if></set> where empno=#{empno}</update>。', 'MEDIUM', 2, 66),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:67', 'foreach 六属性', 'foreach 六属性：collection（list/array，或 @Param 指定的名字）、item（迭代出的对象名）、open（开始串）、close（结束串）、separator（间隔符）、index（循环索引）。', 'MEDIUM', 2, 67),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:68', 'foreach 批量删除', 'foreach 批量删除：<foreach collection="array" item="empno" open="(" close=")" separator=",">#{empno}</foreach> 拼出 delete from emp where empno in ( ? , ? , ? )，接口参数必须写成 int 数组。', 'MEDIUM', 2, 68),
('mybatis', 8, '第 8 章 动态 SQL', 'mybatis:8:69', 'bind 标签【补充】', 'bind 标签【补充】：<bind name="pattern" value="''%'' + job + ''%''"/> 可在 OGNL 里预拼接模糊串，供后续 like #{pattern} 使用，规避 OGNL 字符串拼接的可读性问题。', 'MEDIUM', 2, 69),
('mybatis', 9, '第 9 章 输入映射与输出映射', 'mybatis:9:70', '单参数输入映射', '单参数输入映射：SQL 只需要一个参数时，接口方法参数为基本数据类型，parameterType 也配该基本类型（如 parameterType="double"）。', 'MEDIUM', 2, 70),
('mybatis', 9, '第 9 章 输入映射与输出映射', 'mybatis:9:71', '多参数输入映射', '多参数输入映射：多个参数时用实体对象传值、parameterType 配实体类；若参数是集合（List/Map），parameterType 要配置集合中元素的类型而非集合本身。', 'MEDIUM', 2, 71),
('mybatis', 9, '第 9 章 输入映射与输出映射', 'mybatis:9:72', '基本类型判空的坑', '基本类型判空的坑：SQL 中要判断某基本类型值是否为空时，类型必须是包装类（Integer 而非 int）；且即使只传一个基本类型也要用实体对象传值，因为 parameterType 配 Integer 后 MyBatis 会去找 getXxx 方法而抛「没有 get 方法」异常。', 'MEDIUM', 2, 72),
('mybatis', 9, '第 9 章 输入映射与输出映射', 'mybatis:9:73', 'resultType 适用场景', 'resultType 适用场景：字段名与属性名一致时用 resultType——返回一条记录可配对象类型，返回多条也配对象类型（表示集合元素类型），返回一行一列可配简单数据类型。', 'MEDIUM', 2, 73),
('mybatis', 9, '第 9 章 输入映射与输出映射', 'mybatis:9:74', 'resultMap 适用场景', 'resultMap 适用场景：字段名与属性名不一致时，用 resultMap 显式书写 SQL 列名到实体属性名的映射关系。', 'MEDIUM', 2, 74),
('mybatis', 9, '第 9 章 输入映射与输出映射', 'mybatis:9:75', 'resultMap 结构定义', 'resultMap 结构定义：<resultMap type="Emp" id="empResultMap"> 中 id 是此 resultMap 的唯一标识，type 是映射的实体对象；子标签 <id> 配置主键、<result> 配置其它字段。', 'MEDIUM', 2, 75),
('mybatis', 9, '第 9 章 输入映射与输出映射', 'mybatis:9:76', 'property 与 column 对应关系', 'property 与 column 对应关系：property 对应实体类中的属性，column 对应 sql 语句中的字段（含别名），例如 <id property="empno" column="empno_0"/>。', 'MEDIUM', 2, 76),
('mybatis', 9, '第 9 章 输入映射与输出映射', 'mybatis:9:77', 'resultMap 的实际使用', 'resultMap 的实际使用：先把查询列起别名（select empno empno_0, ename ename_0, ... from emp order by empno_0），再用 resultMap="empResultMap" 指明使用哪个 resultMap。', 'MEDIUM', 2, 77),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:78', '关联关系分类与实体设计', '关联关系分类与实体设计：表关系有一对一、多对一、一对多、多对多；多对一时在 many 方添加 one 方对象属性（Emp 里加 Dept dept），一对多时在 one 方添加 many 方集合属性（Dept 里加 List&lt;Emp&gt; empList）。', 'MEDIUM', 2, 78),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:79', '两种实现形态', '两种实现形态：多表连接形式（一条 SQL join 一次性取回）与单独查询形式（主查询 + 按需的关联查询，通过 select 属性触发第二条 SQL）。', 'MEDIUM', 2, 79),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:80', 'association 完成多对一嵌套结果映射', 'association 完成多对一嵌套结果映射：<association property="dept" javaType="Dept"><id property="deptno" column="ddeptno"/><result property="dname" column="ddname"/><result property="loc" column="dloc"/></association>，property 是 many 方新增的属性名，javaType 是其类型。', 'MEDIUM', 2, 80),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:81', 'join SQL 的列别名约定', 'join SQL 的列别名约定：select e.*, d.deptno ddeptno, d.dname ddname, d.loc dloc from emp e left join dept d on e.deptno=d.deptno where e.empno = #{empno}，必须给 one 方列起唯一别名以免与 many 方主键冲突。', 'MEDIUM', 2, 81),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:82', 'collection 完成一对多嵌套结果映射', 'collection 完成一对多嵌套结果映射：<collection property="empList" ofType="Emp"><id property="empno" column="eempno"/><result property="ename" column="eename"/>...</collection>，property 是 one 方新增的集合属性名，ofType 是集合元素类型。', 'MEDIUM', 2, 82),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:83', '嵌套结果的缺陷', '嵌套结果的缺陷：一次 join 会返回笛卡尔放大行集，MyBatis 依据 <id> 去重合并成树形结构，因此一对多时 id 标签不可省略。', 'MEDIUM', 2, 83),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:84', '嵌套查询（单独查询形式）写法', '嵌套查询（单独查询形式）写法：<association property="dept" javaType="Dept" select="com.example.mapper.DeptMapper.getDeptByIdLazy" column="deptno"/>，把当前行的 deptno 作为参数传给另一条 statement。', 'MEDIUM', 2, 84),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:85', '嵌套查询的 collection 写法', '嵌套查询的 collection 写法：<collection property="empList" ofType="Emp" select="com.example.mapper.EmpMapper.getEmpByIdLazy" column="deptno"/>，被调用的 getEmpByIdLazy 可以是不在接口中声明方法名的独立 statement。', 'MEDIUM', 2, 85),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:86', '延迟加载开关', '延迟加载开关：使用延迟加载必须先开启两项配置——lazyLoadingEnabled=true（全局延迟加载开关，默认 false）与 aggressiveLazyLoading=false（默认 true 时会整对象延迟，false 表示每个属性按需加载）。', 'MEDIUM', 2, 86),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:87', '延迟加载生效前提与陷阱', '延迟加载生效前提与陷阱：延迟加载只对「单独查询形式」有效；且若 aggressiveLazyLoading 为 true，即使 lazyLoadingEnabled 为 true 也不生效，二者需配套设置。', 'HARD', 2, 87),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:88', '关联映射总结表', '关联映射总结表：association 把关联信息映射到一个 po 对象（javaType/select/column）；collection 映射到一个 list 集合（ofType/select/column），两者都支持嵌套结果与嵌套查询两种装配路径。', 'MEDIUM', 2, 88),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:89', '多对多的处理【补充】', '多对多的处理【补充】：通常用中间表拆成两个一对多/多对一实现（如订单-商品经订单明细表），实体上表现为双向 collection 或两次嵌套 association，并注意 fetchType 避免重复放大查询。', 'MEDIUM', 2, 89),
('mybatis', 10, '第 10 章 MyBatis 关联查询', 'mybatis:10:90', '级联更新风险', '级联更新风险：关联映射只做查询装配，不会自动级联写库；若在 insert/update 中一并提交子集合，必须显式编写多条语句并放在同一事务内，否则出现部分成功的数据不一致。', 'MEDIUM', 2, 90),
('mybatis', 11, '第 11 章 使用注解实现 MyBatis 映射', 'mybatis:11:91', '常用注解清单', '常用注解清单：@Insert 新增、@Update 更新、@Delete 删除、@Select 查询、@Result 单条结果封装、@Results 封装多个结果集、@ResultMap 引用 @Results、@One 一对一、@Many 一对多、@SelectProvider 动态 SQL。', 'MEDIUM', 2, 91),
('mybatis', 11, '第 11 章 使用注解实现 MyBatis 映射', 'mybatis:11:92', '注解与 XML 的关系', '注解与 XML 的关系：映射文件中所有 CRUD 操作都能用注解完成；使用注解映射器接口后不再需要该接口的映射配置文件；实际开发可单独用 XML、单独用注解或二者混用。', 'MEDIUM', 2, 92),
('mybatis', 11, '第 11 章 使用注解实现 MyBatis 映射', 'mybatis:11:93', '注解查询单条 + Results', '注解查询单条 + Results：@Select("select * from emp where empno=#{empno}") 配合 @Results(id="empResult", value={@Result(id=true, property="empno", column="empno"), ...})，其中 id=true 标识主键列。', 'MEDIUM', 2, 93),
('mybatis', 11, '第 11 章 使用注解实现 MyBatis 映射', 'mybatis:11:94', '注解查询多条', '注解查询多条：@Select("select * from emp where deptno=#{deptno}") public List<Emp> listEmpAll1(int deptno);，返回 List 时无需额外配置。', 'MEDIUM', 2, 94),
('mybatis', 11, '第 11 章 使用注解实现 MyBatis 映射', 'mybatis:11:95', '注解插入与主键回填', '注解插入与主键回填：@Insert("insert into emp(empno,ename,job,hiredate) values(#{empno},#{ename},#{job},#{hiredate})")，若需取自增主键可用 @SelectKey(statement="select last_insert_id()", before=false, keyProperty="empno", resultType=Integer.class)。', 'MEDIUM', 2, 95),
('mybatis', 11, '第 11 章 使用注解实现 MyBatis 映射', 'mybatis:11:96', '注解修改与删除', '注解修改与删除：@Update("update emp set job=#{job},sal=#{sal} where empno=#{empno}")、@Delete("delete from emp where empno=#{empno}")，返回值同为 int 影响行数且仍需 commit。', 'MEDIUM', 2, 96),
('mybatis', 11, '第 11 章 使用注解实现 MyBatis 映射', 'mybatis:11:97', '@ResultMap 复用 Results', '@ResultMap 复用 Results：先在某方法上声明 @Results(id="empResult", value={...})，后续方法直接 @ResultMap("empResult") 引用，如 listEmpAll2(Emp emp) 的多条件查询。', 'MEDIUM', 2, 97),
('mybatis', 11, '第 11 章 使用注解实现 MyBatis 映射', 'mybatis:11:98', '注解版一对多', '注解版一对多：@Result(column="deptno", property="emps", many=@Many(select="com.example.mapper.EmpMapper.listEmpAll1", fetchType=FetchType.LAZY))，FetchType 取自 org.apache.ibatis.mapping.FetchType。', 'MEDIUM', 2, 98),
('mybatis', 11, '第 11 章 使用注解实现 MyBatis 映射', 'mybatis:11:99', '传值列必须单独映射', '传值列必须单独映射：一对多关联映射时，一方向多方传值的列（本例 deptno）必须单独配置一个 @Result(column="deptno", property="deptno") 主键映射，否则该列值为 null。', 'MEDIUM', 2, 99),
('mybatis', 11, '第 11 章 使用注解实现 MyBatis 映射', 'mybatis:11:100', '@One 多对一与延迟', '@One 多对一与延迟：@Result(column="deptno", property="dept", one=@One(select="com.example.mapper.DeptMapper.selectDeptById", fetchType=FetchType.LAZY))，日志可见两条 Preparing/Parameters，第二条在访问 dept 时才发出。', 'MEDIUM', 2, 100),
('mybatis', 11, '第 11 章 使用注解实现 MyBatis 映射', 'mybatis:11:101', '注解动态 SQL【补充】', '注解动态 SQL【补充】：复杂条件建议用 @SelectProvider(type=EmpSqlProvider.class, method="listEmp") 返回 SQL 字符串，简单条件可直接用 <script> 包裹 XML 动态标签（@Select({"<script>", "select * from emp", "<where>", ...})）。', 'MEDIUM', 2, 101),
('mybatis', 12, '第 12 章 实践作业与综合演练', 'mybatis:12:102', '在线书店关联查询场景', '在线书店关联查询场景：在 books 之外新增 book_details（book_id 主键 + fk_book_id 外键指向 books.id）与 book_reviews（id、book_id、reviewer_name、review_text TEXT、rating，外键 ON DELETE CASCADE）。', 'MEDIUM', 2, 102),
('mybatis', 12, '第 12 章 实践作业与综合演练', 'mybatis:12:103', '一对一映射任务', '一对一映射任务：一本书对应一个详情，用 resultMap 的 association（property="detail" javaType="BookDetail"）配合 join 或嵌套 select 实现，并注意 books 与 book_details 的主键同名需起别名。', 'MEDIUM', 2, 103),
('mybatis', 12, '第 12 章 实践作业与综合演练', 'mybatis:12:104', '一对多映射任务', '一对多映射任务：一本书有多个评论，用 collection（property="reviews" ofType="BookReview"）实现；若用嵌套查询，把 books.id 作为 column 传给按 book_id 查评论的 statement。', 'MEDIUM', 2, 104),
('mybatis', 12, '第 12 章 实践作业与综合演练', 'mybatis:12:105', '综合校验点', '综合校验点：作业同时考察 PO 字段与列名一致性、resultMap/association/collection 选型、以及 commit 提交与 SqlSession 关闭的资源管理规范。', 'MEDIUM', 2, 105),
('mybatis', 13, '第 13 章 核心机制与进阶专题【补充】', 'mybatis:13:106', '一级缓存（本地缓存）', '一级缓存（本地缓存）：作用域为 SqlSession（PerpetualCache），同一会话内执行相同 statement + 相同参数会直接命中；但期间执行任意 insert/update/delete 或调用 clearCache() 会清空该会话缓存。', 'MEDIUM', 2, 106),
('mybatis', 13, '第 13 章 核心机制与进阶专题【补充】', 'mybatis:13:107', '二级缓存（全局缓存）', '二级缓存（全局缓存）：作用域为 namespace（即一个 Mapper），需在全局配置设 cacheEnabled=true（默认 true）并在映射文件中加 <cache/>；实体须实现 Serializable，且只在会话 commit/close 后才真正写入。', 'MEDIUM', 2, 107),
('mybatis', 13, '第 13 章 核心机制与进阶专题【补充】', 'mybatis:13:108', '脏读与失效策略', '脏读与失效策略：二级缓存在多表联查时易读到关联表变更前的旧值（脏读）；MyBatis 采用「同 namespace 内任写操作即清空该 namespace 缓存」的策略，跨 namespace 需谨慎并用 <cache-ref/> 或关闭缓存。', 'MEDIUM', 2, 108),
('mybatis', 13, '第 13 章 核心机制与进阶专题【补充】', 'mybatis:13:109', '自定义缓存', '自定义缓存：<cache type="org.mybatis.caches.ehcache.EhcacheCache"/> 可接入第三方缓存；<cache/> 上还有 size、readOnly、flushInterval、eviction(LRU/FIFO/SOFT/WEAK) 等属性控制淘汰策略。', 'MEDIUM', 2, 109),
('mybatis', 13, '第 13 章 核心机制与进阶专题【补充】', 'mybatis:13:110', 'Executor 三种类型', 'Executor 三种类型：SIMPLE 每次执行新建 Statement；REUSE 复用 PreparedStatement；BATCH 批量重写 addBatch/executeBatch，配合 <foreach> 拼 values 可实现高效批量插入。', 'MEDIUM', 2, 110),
('mybatis', 13, '第 13 章 核心机制与进阶专题【补充】', 'mybatis:13:111', '插件与分页插件原理', '插件与分页插件原理：通过 org.apache.ibatis.plugin.Interceptor 拦截 Executor/StatementHandler/ParameterHandler/ResultSetHandler 四个接口，用 @Intercepts(@Signature(...)) 声明拦截点，动态代理包装目标对象；PageHelper 即在 Executor 层改写 SQL 追加 limit 并执行 count 查询。', 'MEDIUM', 2, 111),
('mybatis', 13, '第 13 章 核心机制与进阶专题【补充】', 'mybatis:13:112', '类型处理器 TypeHandler', '类型处理器 TypeHandler：负责 Java 类型与 JDBC 类型互转，内置 BooleanTypeHandler、DateTypeHandler、EnumTypeHandler（存枚举 name）等；自定义枚举落库推荐 EnumOrdinalTypeHandler 或自定义 TypeHandler，并在 <typeHandlers> 注册或在 resultMap 上指定 typeHandler=。', 'MEDIUM', 2, 112),
('mybatis', 13, '第 13 章 核心机制与进阶专题【补充】', 'mybatis:13:113', 'MapperScannerConfigurer 整合：Spring 中配置 or', 'MapperScannerConfigurer 整合：Spring 中配置 org.mybatis.spring.mapper.MapperScannerConfigurer 的 basePackage 与 sqlSessionFactoryBeanName，即可批量把 mapper 接口注册为 Bean，无需逐个声明。', 'MEDIUM', 2, 113),
('mybatis', 13, '第 13 章 核心机制与进阶专题【补充】', 'mybatis:13:114', 'SqlSessionTemplate 与线程安全', 'SqlSessionTemplate 与线程安全：org.mybatis.spring.SqlSessionTemplate 是线程安全的 SqlSession 代理，由 Spring 事务管理器统一开闭会话与提交回滚，业务代码不再手写 openSession/commit/close。', 'MEDIUM', 2, 114),
('mybatis', 13, '第 13 章 核心机制与进阶专题【补充】', 'mybatis:13:115', 'Mapper 接口绑定规则回顾', 'Mapper 接口绑定规则回顾：接口全限定名 = XML 的 namespace，方法名 = statement id，参数类型 = parameterType，返回类型决定 selectOne/selectList；@Param("x") 可让多参数在 #{} 中以 x 引用。', 'MEDIUM', 2, 115)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('data-structures-c', 1, '第1章 绪论', 'data-structures-c:1:1', '基本概念层次', '基本概念层次：数据是信息的载体；数据元素是数据的基本单位（记录）；数据项是构成数据元素的不可分割的最小单位；数据对象是具有相同性质的数据元素的集合。四者构成"数据 → 数据元素 → 数据项"和"数据 → 数据对象"两条关系线。', 'MEDIUM', 2, 1),
('data-structures-c', 1, '第1章 绪论', 'data-structures-c:1:2', '数据结构三要素', '数据结构三要素：逻辑结构（集合、线性、树形、图状）、存储结构（顺序、链式、索引、散列）、运算（插入、删除、查找、排序、遍历等）。同一逻辑结构可配不同存储结构，运算的实现随之不同。', 'MEDIUM', 2, 2),
('data-structures-c', 1, '第1章 绪论', 'data-structures-c:1:3', '数据类型与 ADT', '数据类型与 ADT：数据类型是值的集合 + 定义其上的操作集合；抽象数据类型可用 (D, S, P) 三元组刻画（数据对象、关系、基本操作）。ADT 的表示与实现应独立于具体语言，本书一律用类 C 语言描述。', 'MEDIUM', 2, 3),
('data-structures-c', 1, '第1章 绪论', 'data-structures-c:1:4', '算法五特性', '算法五特性：有穷性、确定性、可行性、输入（0 个或多个）、输出（至少一个）。算法不等于程序，程序可以不满足有穷性（如操作系统）。', 'MEDIUM', 2, 4),
('data-structures-c', 1, '第1章 绪论', 'data-structures-c:1:5', '时间复杂度', '时间复杂度：以基本语句频度 f(n) 为基准，T(n)=O(f(n)) 表示渐近上界；求解时抓住最深循环内的基本语句，忽略低次幂与最高次系数。常见数量级递增序：O(1) < O(log₂n) < O(n) < O(nlog₂n) < O(n²) < O(n³) < O(2ⁿ) < O(n!)。', 'MEDIUM', 2, 5),
('data-structures-c', 1, '第1章 绪论', 'data-structures-c:1:6', '最好/最坏/平均复杂度', '最好/最坏/平均复杂度：本书除特别说明外均指最坏情况时间复杂度，因为它给出运行时间的上界；评价算法时也要同时看空间复杂度，二者常相互制约（典型如空间换时间）。', 'MEDIUM', 2, 6),
('data-structures-c', 2, '第2章 线性表', 'data-structures-c:2:7', '定义与特点', '定义与特点：线性表是 n (n≥0) 个类型相同数据元素的有限序列，除首元素外每个元素有且仅有一个直接前驱，除尾元素外有且仅有一个直接后继。n=0 为空表。', 'MEDIUM', 2, 7),
('data-structures-c', 2, '第2章 线性表', 'data-structures-c:2:8', '顺序存储', '顺序存储：用一组地址连续的存储单元依次存放元素，逻辑相邻 ⇒ 物理相邻，因此随机存取，按位查找 Get 时间复杂度 O(1)；但插入/删除需大量移动元素，平均 O(n)。插入伪代码：', 'MEDIUM', 2, 8),
('data-structures-c', 2, '第2章 线性表', 'data-structures-c:2:9', '链式存储', '链式存储：单链表以指针表示逻辑关系，存取只能顺序进行（按位查找 O(n)），但插入删除只需修改指针 O(1)（定位仍需 O(n)）。头插法可逆置建表；头节点能统一空表与非空表的处理，是高频考点。循环链表便于从任一结点出发遍历全表；双向链表支持 O(1) 求前驱，代价是每个结点多一个指针域。', 'MEDIUM', 4, 9),
('data-structures-c', 2, '第2章 线性表', 'data-structures-c:2:10', '顺序表 vs 链表', '顺序表 vs 链表：空间上，顺序表密度高（无指针开销）、需预分配，链表动态灵活但存储密度 < 1；时间上，按位取元素顺序表 O(1) 明显优于链表 O(n)，而插入删除在表尾或已知位置时链表更优。', 'MEDIUM', 2, 10),
('data-structures-c', 2, '第2章 线性表', 'data-structures-c:2:11', '线性表应用', '线性表应用：有序表合并可用"二路归并"一次扫描完成，时间 O(m+n)；若用链表实现，只需改变指针链接，辅助空间 O(1)，这正是链式存储的价值所在。', 'MEDIUM', 2, 11),
('data-structures-c', 2, '第2章 线性表', 'data-structures-c:2:12', '易错点', '易错点：① 数组下标从 0 开始而位序从 1 开始，插入位置判界是 [1, length+1]；② 删除时忘记 --L.length；③ 链表中先修改 p->next 再处理被删结点导致断链，正确顺序是"先接后删再释放"。', 'HARD', 2, 12),
('data-structures-c', 3, '第3章 栈和队列', 'data-structures-c:3:13', '栈的定义', '栈的定义：限定仅在表尾进行插入和删除的线性表，表尾称栈顶、表头称栈底，遵循后进先出（LIFO）。顺序栈的 Push/Pop 均为 O(1)；链栈一般不设头节点，插入删除都在表头进行。', 'MEDIUM', 2, 13),
('data-structures-c', 3, '第3章 栈和队列', 'data-structures-c:3:14', '栈的应用场景', '栈的应用场景：括号匹配、表达式求值、数制转换、迷宫/八皇后回溯等递归型问题；函数调用、中断处理本质上都借助系统栈。', 'MEDIUM', 2, 14),
('data-structures-c', 3, '第3章 栈和队列', 'data-structures-c:3:15', '递归与递归工作栈', '递归与递归工作栈：递归 = 直接或间接调用自身，必须含递归出口与递归体。系统为每次调用建立递归工作栈（保存参数、局部变量、返回地址），因此递归算法空间复杂度等于工作栈的最大深度；斐波那契、阶乘的朴素递归会重复计算，效率可用迭代改进。', 'MEDIUM', 2, 15),
('data-structures-c', 3, '第3章 栈和队列', 'data-structures-c:3:16', '用栈消除递归', '用栈消除递归：对尾递归可直接改写为循环；对非尾递归（如中序遍历、快速排序）须显式定义栈来模拟"进入/返回"过程，这是常考的改写题。', 'MEDIUM', 2, 16),
('data-structures-c', 3, '第3章 栈和队列', 'data-structures-c:3:17', '队列的定义', '队列的定义：限定在一端插入（队尾）、另一端删除（队头）的线性表，遵循先进先出（FIFO）。循环队列用 Q.front == Q.rear 判空，为区分队满采用两种约定之一：牺牲一个单元（队满条件 (Q.rear+1)%MAXSIZE == Q.front），或增设 size/tag 标志；入队出队均为 O(1)。', 'MEDIUM', 2, 17),
('data-structures-c', 3, '第3章 栈和队列', 'data-structures-c:3:18', '链队列', '链队列：带头节点的链表，队头在链头、队尾在链尾，入队出队 O(1)，不会上溢（除非内存耗尽）。', 'MEDIUM', 2, 18),
('data-structures-c', 3, '第3章 栈和队列', 'data-structures-c:3:19', '易错点', '易错点：① 循环队列元素个数公式 (rear - front + MAXSIZE) % MAXSIZE；② 混淆队空与队满条件；③ 递归改写时忘记保存/恢复现场。', 'HARD', 2, 19),
('data-structures-c', 4, '第4章 串、数组和广义表', 'data-structures-c:4:20', '串的基本概念', '串的基本概念：串是由零个或多个字符组成的有限序列，串长指字符个数，空串与空格串不同；子串在主串中的位置以首个字符的位序表示，因此定位子串即模式匹配。', 'MEDIUM', 2, 20),
('data-structures-c', 4, '第4章 串、数组和广义表', 'data-structures-c:4:21', 'BF 算法', 'BF 算法：朴素的"回溯式"匹配，主串指针 i 与模式串指针 j 同步后移，失配时 i 回退到 i-j+2、j 回到 1，最坏 O(n×m)，但因常数小，一般场合近似 O(n+m)。', 'MEDIUM', 2, 21),
('data-structures-c', 4, '第4章 串、数组和广义表', 'data-structures-c:4:22', 'KMP 算法（核心）', 'KMP 算法（核心）：主串指针不回溯，失配时 j = next[j]，利用已匹配信息让模式串尽量右滑，时间复杂度 O(n+m)，其中求 next 数组为 O(m)。', 'MEDIUM', 2, 22),
('data-structures-c', 4, '第4章 串、数组和广义表', 'data-structures-c:4:23', '数组与压缩存储', '数组与压缩存储：数组是定长、随机存取的结构，Loc 由起始地址 + 偏移量计算。特殊矩阵压缩的关键是建立下标映射：对称矩阵存 n(n+1)/2 个元素，a[i][j] 映射到一维下标；三角矩阵、对角矩阵同理；稀疏矩阵用三元组表（行、列、值）或十字链表存储，可节省空间但失去随机存取性。', 'MEDIUM', 2, 23),
('data-structures-c', 4, '第4章 串、数组和广义表', 'data-structures-c:4:24', '广义表', '广义表：广义表是 n≥0 个元素的有限序列，元素可以是原子或子表，具有递归性、有层次、可共享。求表头 head 取第一个元素，求表尾 tail 取除首元素外的剩余部分（表尾必是广义表），深度定义为括号的重数。存储常用链式结构，原子结点与表结点用 tag 区分。', 'MEDIUM', 2, 24),
('data-structures-c', 4, '第4章 串、数组和广义表', 'data-structures-c:4:25', '易错点', '易错点：① head 与 tail 结果类型不同，(a,(b,c)) 的 head 是 a、tail 是 ((b,c))；② 数组压缩后下标换算公式容易记错"第几行前有多少元素"。', 'HARD', 2, 25),
('data-structures-c', 5, '第5章 树和二叉树', 'data-structures-c:5:26', '基本术语', '基本术语：结点、根、叶子、度、深度/层次、孩子/双亲/兄弟、祖先/子孙、有序树/无序树；结点的度是子树个数，树的度是各结点度的最大值。二叉树不是树的特殊情形——它严格区分左右子树，即使只有一棵子树也要说明左/右。', 'MEDIUM', 2, 26),
('data-structures-c', 5, '第5章 树和二叉树', 'data-structures-c:5:27', '二叉树五条性质（高频）', '二叉树五条性质（高频）：① 第 i 层至多有 2^{i-1} 个结点；② 深度为 k 的二叉树至多有 2^k - 1 个结点；③ n₀ = n₂ + 1（叶子数 = 度为 2 的结点数 + 1）；④ 完全二叉树中编号 i 的结点其左孩子 2i、右孩子 2i+1、双亲 ⌊i/2⌋；⑤ n 个结点的完全二叉树深度为 ⌊log₂n⌋ + 1。', 'MEDIUM', 4, 27),
('data-structures-c', 5, '第5章 树和二叉树', 'data-structures-c:5:28', '存储结构', '存储结构：顺序存储适合完全二叉树（按层编号映射，父子下标可互算），一般二叉树顺序存储会产生大量空位；链式存储（二叉链表 lchild/data/rchild）最常用，n 个结点有 2n 个指针域，其中 n+1 个为空，这一事实是线索化的依据。', 'MEDIUM', 2, 28),
('data-structures-c', 5, '第5章 树和二叉树', 'data-structures-c:5:29', '三种遍历及递归实现', '三种遍历及递归实现：先序（根左右）、中序（左根右）、后序（左右根），时间均为 O(n)，空间 O(h)（h 为树高）。由先序 + 中序或后序 + 中序可唯一确定一棵二叉树（必须先找到根）；仅凭先序/后序无法确定。非递归遍历需借助栈（中序最典型）：', 'MEDIUM', 2, 29),
('data-structures-c', 5, '第5章 树和二叉树', 'data-structures-c:5:30', '线索二叉树', '线索二叉树：利用空指针域存放指向前驱/后继的线索（ltag/rtag 标记指针还是线索），目的是加快遍历且不使用栈。中序线索化后，找后继：若 rtag==1 直接取 rchild，否则沿右子树一直向左走到头。注意头节点可使线索二叉树的首尾线索闭合。', 'MEDIUM', 2, 30),
('data-structures-c', 5, '第5章 树和二叉树', 'data-structures-c:5:31', '树与森林', '树与森林：存储结构有双亲表示法（数组存 parent 下标）、孩子表示法、孩子兄弟表示法（左孩子右兄弟）；森林与二叉树可相互转换，遍历对应关系为"树的先根遍历 ↔ 二叉树先序""树的后根遍历 ↔ 二叉树中序"。', 'MEDIUM', 2, 31),
('data-structures-c', 5, '第5章 树和二叉树', 'data-structures-c:5:32', '哈夫曼树与编码', '哈夫曼树与编码：哈夫曼树是带权路径长度 WPL = Σ wᵢ·lᵢ 最小的二叉树（最优二叉树）；构造采用"每次选两个权值最小的合并"的贪心策略，得到前缀编码，译码无歧义，用于数据压缩。', 'MEDIUM', 2, 32),
('data-structures-c', 5, '第5章 树和二叉树', 'data-structures-c:5:33', '易错点', '易错点：① 先序/中序/后序序列的相对顺序判断；② n₀=n₂+1 的推导依据是边数与结点数关系；③ 线索化后仍沿用原遍历方式会出错。', 'HARD', 2, 33),
('data-structures-c', 6, '第6章 图', 'data-structures-c:6:34', '术语与定义', '术语与定义：图 G=(V,E)，顶点集非空、边集可为空；无向图/有向图、完全图、子图、连通与连通分量、强连通与强连通分量、生成树与生成森林、网的权与最短路径。无向完全图边数 n(n-1)/2，有向完全图 n(n-1)。', 'MEDIUM', 2, 34),
('data-structures-c', 6, '第6章 图', 'data-structures-c:6:35', '存储结构', '存储结构：① 邻接矩阵——二维数组，无向图对称，可 O(1) 判邻接，空间 O(n²)，适合稠密图；② 邻接表——顶点数组 + 边链表，空间 O(n+e)，求某顶点出度易、入度难（有向图）；③ 十字链表解决有向图入度统计；④ 邻接多重表用于无向图避免边信息重复。', 'MEDIUM', 2, 35),
('data-structures-c', 6, '第6章 图', 'data-structures-c:6:36', '遍历', '遍历：深度优先 DFS 类似先序遍历，用栈（递归即隐式栈）；广度优先 BFS 用队列，按层推进。邻接矩阵实现均为 O(n²)，邻接表实现均为 O(n+e)；访问标记数组 visited[] 是防止重复访问的关键。DFS/BFS 都可用于求连通分量。', 'MEDIUM', 2, 36),
('data-structures-c', 6, '第6章 图', 'data-structures-c:6:37', '最小生成树', '最小生成树：带权连通图的生成树中权和最小者。Prim 算法从某个顶点出发逐步"把最近顶点并入"，时间 O(n²)（堆优化可到 O(e log n)），适合稠密图；Kruskal 算法按边权升序选边并用并查集判环，时间 O(e log e)，适合稀疏图。伪代码骨架：', 'MEDIUM', 2, 37),
('data-structures-c', 6, '第6章 图', 'data-structures-c:6:38', '最短路径', '最短路径：单源用 Dijkstra（按"未确定最短路的顶点中距离最小者"松弛，O(n²)，堆优化 O((n+e)log n)），要求边权非负；全源用 Floyd（三重循环动态规划，O(n³)），允许负权但不含负回路。Dijkstra 是贪心、不能处理负权；Floyd 的状态 dist[i][j][k] 可滚动掉第一维。', 'MEDIUM', 2, 38),
('data-structures-c', 6, '第6章 图', 'data-structures-c:6:39', '拓扑排序与关键路径', '拓扑排序与关键路径：拓扑排序针对 AOV 网（顶点表示活动），反复输出入度为 0 的顶点并删边，时间 O(n+e)；若失败则有回路。AOE 网（边表示活动、边带权）用关键路径：先求每个事件的最早发生时间 ve 与最迟发生时间 vl，再求活动的最早/最迟开始时间，二者相等（时间余量为 0）的活动为关键活动，由关键活动构成的路径即关键路径，其长度是整个工程的最短工期。缩短关键活动才可能缩短工期。', 'MEDIUM', 2, 39),
('data-structures-c', 6, '第6章 图', 'data-structures-c:6:40', '易错点', '易错点：① Prim 与 Kruskal 的适用场景与贪心策略差异；② Dijkstra 不能用于负权图；③ 拓扑排序只适用于有向无环图，出现回路即无法完成；④ AOE 中 ve 从源点正向推（取 max）、vl 从汇点逆向推（取 min），方向最容易记反。', 'HARD', 2, 40),
('data-structures-c', 7, '第7章 查找', 'data-structures-c:7:41', '基本概念', '基本概念：静态查找（只查不改）与动态查找（可插删改）；主关键字、次关键字；平均查找长度 ASL = Σ pᵢ·cᵢ 是查找效率的量度，等概率时 pᵢ=1/n。', 'MEDIUM', 2, 41),
('data-structures-c', 7, '第7章 查找', 'data-structures-c:7:42', '线性表查找', '线性表查找：顺序查找对有序无序表都适用，成功 ASL 为 (n+1)/2，失败为 n+1，时间 O(n)；折半查找要求顺序存储且有序，判定树是平衡二叉树，成功 ASL 约 log₂(n+1)-1，时间 O(log n)；分块查找是二者折中——块间有序、块内无序，先在索引表折半/顺序定块再块内顺序查找，ASL 介于两者之间。', 'MEDIUM', 2, 42),
('data-structures-c', 7, '第7章 查找', 'data-structures-c:7:43', '二叉排序树（BST）', '二叉排序树（BST）：左子树关键字 < 根 < 右子树，中序遍历即有序序列。查找、插入、删除均为 O(h)，平衡时 O(log n)，但插入有序序列会退化成单支树导致 O(n)，这是引出平衡二叉树的直接原因。删除结点时分"叶子/单支/双支"三种情况处理，双支时通常用前驱或后继替换。', 'MEDIUM', 2, 43),
('data-structures-c', 7, '第7章 查找', 'data-structures-c:7:44', '平衡二叉树（AVL）', '平衡二叉树（AVL）：任意结点左右子树深度差绝对值 ≤ 1，平衡因子只能取 -1/0/1，从而保证树高 O(log n)。失衡时定位最小不平衡子树并做四种旋转：LL（右单旋）、RR（左单旋）、LR（先左旋后右旋）、RL（先右旋后左旋），旋转后子树高度复原，故不影响祖先平衡性。红黑树是同类思想的工业级改进（通过颜色与旋转让树高保持在 2log(n+1) 量级），是工程中最常用的平衡结构。', 'MEDIUM', 2, 44),
('data-structures-c', 7, '第7章 查找', 'data-structures-c:7:45', 'B-树与 B+树（外查找核心）', 'B-树与 B+树（外查找核心）：m 阶 B-树每个结点至多 m 棵子树、非根非叶结点至少 ⌈m/2⌉ 棵，至多 m-1 个关键字，所有叶子（失败结点）同层，因此天然平衡，适用于磁盘索引。B+树与之差异三点：有 n 棵子树则含 n 个关键字；叶子结点包含全部关键字及记录指针并按大小链接；非终端结点只作索引。故 B+树支持高效的范围查询，是现代数据库索引的事实标准。', 'MEDIUM', 2, 45),
('data-structures-c', 7, '第7章 查找', 'data-structures-c:7:46', '散列表', '散列表：把关键字直接映射到地址，理想情况下 O(1)。关键在散列函数（除留余数法 H(key)=key%p 最常用，p 取不大于表长的最大质数）与冲突处理。开放地址法按 Hᵢ=(H(key)+dᵢ)%m 探测：线性探测简单但有"二次聚集"，二次探测与伪随机探测可缓解聚集但不保证找到空位；链地址法把同义词挂在同一链表，实现简单且删除方便。', 'MEDIUM', 2, 46),
('data-structures-c', 7, '第7章 查找', 'data-structures-c:7:47', '装填因子与 ASL', '装填因子与 ASL：α = 填入记录数 / 表长，α 越大冲突越多。等概率下线性探测法的成功 ASL ≈ ½(1 + 1/(1-α))、失败 ASL ≈ ½(1 + 1/(1-α)²)；链地址法成功 ASL ≈ 1 + α/2、失败 ASL ≈ α + e^{-α}。可见当 α 接近 1 时线性探测性能急剧恶化。', 'MEDIUM', 2, 47),
('data-structures-c', 7, '第7章 查找', 'data-structures-c:7:48', '易错点', '易错点：① 折半查找的判定树与 mid 取整方向；② BST 删除双支结点时的替代结点选择；③ AVL 的 LR/RL 需要两次旋转且要正确更新三个结点的平衡因子；④ 散列查找失败的判定依赖"探查到空位即停止"，链地址法则要遍历整条链。', 'HARD', 2, 48),
('data-structures-c', 8, '第8章 排序（含外部排序）', 'data-structures-c:8:49', '基本概念', '基本概念：排序是把记录序列重新排列为按关键字有序序列的操作；稳定性指相等关键字记录的相对次序在排序前后不变。内部排序全程在内存完成，外部排序需内外存交换。排序效率取决于比较次数与移动次数。', 'MEDIUM', 2, 49),
('data-structures-c', 8, '第8章 排序（含外部排序）', 'data-structures-c:8:50', '插入类', '插入类：直接插入排序每趟把一个记录插入已序区，最好 O(n)（已有序）、最坏与平均 O(n²)，稳定、空间 O(1)；折半插入只减少比较次数（比较 O(n log n)），移动次数不变，整体仍 O(n²)，稳定；希尔排序按增量分组插入，突破 O(n²) 但不稳定，性能强烈依赖增量序列。', 'MEDIUM', 2, 50),
('data-structures-c', 8, '第8章 排序（含外部排序）', 'data-structures-c:8:51', '交换类', '交换类：冒泡排序相邻比较交换，最好 O(n)、平均 O(n²)，稳定；快速排序通过一次划分把基准放到最终位置，平均 O(n log n)，是基于比较的排序中平均性能最好的方法，但最坏（已有序）O(n²)、递归栈空间 O(n)，且不稳定。', 'MEDIUM', 2, 51),
('data-structures-c', 8, '第8章 排序（含外部排序）', 'data-structures-c:8:52', '选择类', '选择类：简单选择排序每趟选最小元，比较恒为 O(n²)，移动少、稳定；堆排序借助大/小根堆反复"输出堆顶并调整"，时间稳定 O(n log n)、空间 O(1)，但不稳定；建堆 O(n)，筛选（sift）O(log n)。', 'MEDIUM', 2, 52),
('data-structures-c', 8, '第8章 排序（含外部排序）', 'data-structures-c:8:53', '归并与基数', '归并与基数：2 路归并排序时间恒为 O(n log n)、稳定，但需 O(n) 辅助空间；基数排序按关键字位"分配—收集"，时间 O(d(n+r_d))，可突破比较排序 O(n log n) 下界，稳定，但要求关键字有位结构且范围已知。', 'MEDIUM', 2, 53),
('data-structures-c', 8, '第8章 排序（含外部排序）', 'data-structures-c:8:54', '内部排序综合对比（原书表 8.2 摘要）', '内部排序综合对比（原书表 8.2 摘要）：', 'MEDIUM', 2, 54),
('data-structures-c', 8, '第8章 排序（含外部排序）', 'data-structures-c:8:55', '外部排序', '外部排序：两阶段——先用内部排序把外存文件切成若干有序归并段（顺串），再逐趟归并直到整体有序。k 路归并时趟数 S = ⌈log_k m⌉（m 为初始归并段数），每趟读写各一遍，故总 I/O 次数 ≈ 2N·S。改进手段：① 多路平衡归并增大归并路数；② 用败者树减少每选出一个最小元所需的比较次数（从 k-1 降到 ⌈log₂k⌉）；③ 置换-选择排序借助"败者树 + 可替换最小元"生成更长的初始归并段以减少段数；④ 最佳归并树类比哈夫曼树构造，使各归并段长度不等时的总读写代价最小（需补虚段）。', 'MEDIUM', 2, 55),
('data-structures-c', 8, '第8章 排序（含外部排序）', 'data-structures-c:8:56', '易错点', '易错点：① 快排最坏情形与"三者取中"选取枢轴的优化；② 堆排序中"筛选"方向与堆顶替换后的调整；③ 归并排序的辅助空间容易误写成 O(log n)；④ 外部排序的趟数与读写次数计算常漏乘 2。', 'HARD', 2, 56)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('db-system-concepts', 1, '第1章 绪论', 'db-system-concepts:1:1', '四个基本概念', '四个基本概念：数据（描述事物的符号记录）、数据库（长期存储在计算机内、有组织、可共享的大量数据集合）、数据库管理系统（DBMS，位于用户与 OS 之间的数据管理软件）、数据库系统（DBS = 数据库 + 应用系统 + DBMS + 数据库管理员 + 用户）。', 'MEDIUM', 2, 1),
('db-system-concepts', 1, '第1章 绪论', 'db-system-concepts:1:2', '数据管理三阶段', '数据管理三阶段：人工管理（不保存、无专用软件、不共享）→ 文件系统（可长期保存、共享性差、冗余大、独立性差）→ 数据库系统（结构化、共享性高冗余低、独立性高、统一管理与控制）。', 'MEDIUM', 2, 2),
('db-system-concepts', 1, '第1章 绪论', 'db-system-concepts:1:3', '数据模型三要素', '数据模型三要素：数据结构（静态特征）、数据操作（动态特征）、数据的约束条件（完整性规则）。概念模型按用户观点建模（E-R 图是主要工具）；逻辑/物理模型面向机器实现。', 'MEDIUM', 2, 3),
('db-system-concepts', 1, '第1章 绪论', 'db-system-concepts:1:4', '三类传统数据模型', '三类传统数据模型：层次模型（树形，一对多，代表 IMS）、网状模型（图，多对多，代表 DBTG）、关系模型（二维表，主流）；新型模型包括面向对象、对象关系、NoSQL 及 NewSQL 等。', 'MEDIUM', 2, 4),
('db-system-concepts', 1, '第1章 绪论', 'db-system-concepts:1:5', '三级模式与两级映像', '三级模式与两级映像：外模式（用户视图，可有多个）、模式（全局逻辑结构，唯一）、内模式（物理存储）。外模式/模式映像保证逻辑独立性，模式/内模式映像保证物理独立性——这是数据库优于文件系统的关键机制。', 'MEDIUM', 2, 5),
('db-system-concepts', 2, '第2章 关系模型', 'db-system-concepts:2:6', '关系的形式化', '关系的形式化：关系是笛卡尔积 D1×D2×…×Dn 的有限子集，表现为一张二维表；关系模式是型 (U, D, DOM, F)，关系是值。候选码（能唯一标识元组的极小属性集）、主码、主属性、非主属性、全码等术语要辨析清楚。', 'MEDIUM', 2, 6),
('db-system-concepts', 2, '第2章 关系模型', 'db-system-concepts:2:7', '关系操作', '关系操作：特点是集合操作方式（操作对象与结果都是关系），分为查询（选择、投影、连接、除、并、差、交、笛卡尔积）与更新（插入、删除、修改）。关系数据语言按表达方式分为关系代数（过程化）、关系演算（非过程化，含元组演算 ALPHA 与域演算 QBE）和兼具二者特点的 SQL。', 'MEDIUM', 2, 7),
('db-system-concepts', 2, '第2章 关系模型', 'db-system-concepts:2:8', '三类完整性', '三类完整性：实体完整性（主码非空且唯一）、参照完整性（外码要么为空、要么等于被参照表某主码值）、用户定义完整性（域、列、元组级约束）。前两者是关系的两个不变性，由系统自动支持。', 'MEDIUM', 2, 8),
('db-system-concepts', 2, '第2章 关系模型', 'db-system-concepts:2:9', '关系代数', '关系代数：传统集合运算要求同元且对应属性域相同（并、差、交、笛卡尔积）；专门关系运算中选择是水平分割（选行）、投影是垂直分割（选列，去重）、连接从两关系笛卡尔积中取满足条件的元组（等值连接与自然连接最重要，自然连接要去掉重复列）、除用于"全部/至少"类查询。', 'MEDIUM', 2, 9),
('db-system-concepts', 2, '第2章 关系模型', 'db-system-concepts:2:10', '易错点', '易错点：投影后必去重，可能减少元组数；自然连接结果中同名属性只出现一次；除法 R÷S 的结果是 R 中在 S 全部属性上都出现的那些"剩余属性"组合。', 'HARD', 2, 10),
('db-system-concepts', 3, '第3章 关系数据库标准语言 SQL', 'db-system-concepts:3:11', 'SQL 特点', 'SQL 特点：综合统一（集 DDL/DML/DCL 于一体）、高度非过程化、面向集合操作、以同一种语法提供自含式与嵌入式两种使用方式、语言简洁。基本概念上，SQL 支持三级模式：基本表对应模式、视图对应外模式、存储文件对应内模式。', 'MEDIUM', 2, 11),
('db-system-concepts', 3, '第3章 关系数据库标准语言 SQL', 'db-system-concepts:3:12', '数据定义 DDL', '数据定义 DDL：CREATE/DROP/ALTER SCHEMA|TABLE|INDEX|VIEW。定义基本表要指定列、数据类型与列级/表级约束（PRIMARY KEY、UNIQUE、NOT NULL、CHECK、FOREIGN KEY ... REFERENCES）；索引用 CREATE INDEX 建立、DROP INDEX 删除。数据字典是系统表，存放所有定义信息。', 'MEDIUM', 2, 12),
('db-system-concepts', 3, '第3章 关系数据库标准语言 SQL', 'db-system-concepts:3:13', '数据查询 DQL', '数据查询 DQL：SELECT ... FROM ... WHERE ... GROUP BY ... HAVING ... ORDER BY ...。单表查询含选择列、去重（DISTINCT）、条件（比较、BETWEEN、IN、LIKE、IS NULL、逻辑运算符）；连接查询含等值/自然连接、自身连接、外连接（左/右/全）；嵌套查询分相关子查询（内层引用外层，逐行执行）与不相关子查询（可独立求出一次完成），量词 ANY/ALL 与谓词 EXISTS（常可用 EXISTS 实现"全部"语义）是难点。', 'HARD', 2, 13),
('db-system-concepts', 3, '第3章 关系数据库标准语言 SQL', 'db-system-concepts:3:14', '集合查询与派生表', '集合查询与派生表：UNION/INTERSECT/EXCEPT 要求各查询同元且类型兼容，UNION 自动去重；基于派生表的查询把子查询结果当临时表再查。', 'MEDIUM', 2, 14),
('db-system-concepts', 3, '第3章 关系数据库标准语言 SQL', 'db-system-concepts:3:15', '数据更新与空值', '数据更新与空值：INSERT（单行/多行/INSERT ... SELECT）、UPDATE ... SET ... WHERE、DELETE FROM ... WHERE；未加 WHERE 会作用于整表，是最危险的操作之一。空值 NULL 的算术/比较结果均为 UNKNOWN，判断必须用 IS NULL，聚合函数忽略 NULL，COUNT(*) 计行数而 COUNT(列) 不计空值。', 'MEDIUM', 2, 15),
('db-system-concepts', 3, '第3章 关系数据库标准语言 SQL', 'db-system-concepts:3:16', '视图', '视图：从一个或几个基本表导出的虚表，只存定义不存数据。作用：简化操作、提供逻辑独立性、提供安全保护、重构数据库。视图更新受限——含 DISTINCT、GROUP BY、聚合或来自多表连接并含键保留表之外的列时通常不可更新。', 'MEDIUM', 2, 16),
('db-system-concepts', 4, '第4章 数据库安全性', 'db-system-concepts:4:17', '不安全因素与措施', '不安全因素与措施：非授权访问、数据泄露、安全环境脆弱等；对策包括用户身份鉴别（口令、生物特征、智能卡）、存取控制、视图机制、审计、数据加密。安全标准有 TCSEC（橙皮书）与 CC（通用准则，EAL1~EAL7）。', 'MEDIUM', 2, 17),
('db-system-concepts', 4, '第4章 数据库安全性', 'db-system-concepts:4:18', '自主存取控制（DAC）', '自主存取控制（DAC）：用户通过 GRANT/REVOKE 授予与回收权限。权限分两类：关系数据库操作权限（SELECT/INSERT/UPDATE/DELETE/REFERENCES/TRIGGER/...）与数据库模式操作权限（CREATE/DROP/ALTER/INDEX/...）。授权语句 GRANT <权限> ON <对象> TO <用户> [WITH GRANT OPTION]，后者使被授权者可继续授权，形成授权链；回收时可 CASCADE/RESTRICT。', 'MEDIUM', 2, 18),
('db-system-concepts', 4, '第4章 数据库安全性', 'db-system-concepts:4:19', '角色与强制存取控制（MAC）', '角色与强制存取控制（MAC）：角色是一组权限的命名集合（CREATE ROLE），用于批量授权与职责分离。MAC 给主体与客体标记密级（绝密/机密/可信/公开），遵循两条规则：主体读数只能读密级低于等于自身许可证的记录；主体写数只能写密级高于等于自身的记录（即不上读、不下写），可防止隐通道。', 'MEDIUM', 2, 19),
('db-system-concepts', 4, '第4章 数据库安全性', 'db-system-concepts:4:20', '视图、审计与加密', '视图、审计与加密：视图可实现行/列级安全隔离；审计把用户对数据库的操作记入审计日志（AUDIT/NOAUDIT），事后追责与发现异常；数据加密在传输与存储层保护敏感字段，需注意密钥管理与性能开销。', 'MEDIUM', 2, 20),
('db-system-concepts', 5, '第5章 数据库完整性', 'db-system-concepts:5:21', '完整性三层次', '完整性三层次：实体完整性、参照完整性、用户定义完整性，分别针对主码、外码和具体业务规则；完整性约束可在 CREATE TABLE 时定义，也可后续用 ALTER 添加。', 'MEDIUM', 2, 21),
('db-system-concepts', 5, '第5章 数据库完整性', 'db-system-concepts:5:22', '违约处理', '违约处理：实体完整性违反即拒绝执行；参照完整性违约时的处理方式可选 NO ACTION/CASCADE/SET NULL/SET DEFAULT（定义外码时用 ON DELETE/ON UPDATE 指定）。', 'MEDIUM', 2, 22),
('db-system-concepts', 5, '第5章 数据库完整性', 'db-system-concepts:5:23', '用户定义完整性', '用户定义完整性：属性级（NOT NULL、UNIQUE、CHECK (sex IN (''男'',''女''))、DEFAULT）与元组级（CHECK 引用多列，如 CHECK (sno<>dno)）。', 'MEDIUM', 2, 23),
('db-system-concepts', 5, '第5章 数据库完整性', 'db-system-concepts:5:24', '约束命名与域', '约束命名与域：CONSTRAINT <名> PRIMARY KEY/... 便于后续禁用/修改（ALTER TABLE ... ALTER CONSTRAINT）；CREATE DOMAIN 定义域及其上的约束，可复用于多列。', 'MEDIUM', 2, 24),
('db-system-concepts', 5, '第5章 数据库完整性', 'db-system-concepts:5:25', '触发器', '触发器：CREATE TRIGGER <名> {BEFORE|AFTER} {INSERT|UPDATE|DELETE} ON <表> [FOR EACH ROW] ... EXECUTE PROCEDURE <过程>，用于实现复杂完整性规则与审计。执行时区分 OLD/NEW 记录，删除用 DROP TRIGGER；触发器相互触发需防无限递归。', 'MEDIUM', 2, 25),
('db-system-concepts', 6, '第6章 关系数据理论', 'db-system-concepts:6:26', '问题的提出', '问题的提出：不好的关系模式会产生数据冗余、插入异常、删除异常、修改异常，根源是属性间的数据依赖不合理，解决途径是模式分解。', 'MEDIUM', 2, 26),
('db-system-concepts', 6, '第6章 关系数据理论', 'db-system-concepts:6:27', '函数依赖', '函数依赖：X → Y 表示 X 唯一决定 Y，其中完全函数依赖、部分函数依赖（X→Y 但存在真子集 X''→Y）、传递函数依赖（X→Y, Y→Z, Y↛X）是判范式的关键。由函数依赖集可导出闭包 F⁺ 与属性集闭包 X⁺。', 'MEDIUM', 2, 27),
('db-system-concepts', 6, '第6章 关系数据理论', 'db-system-concepts:6:28', '码：候选码的判定方法——L 类属性（只出现在左边）必在码中，N 类（两边都不出现', '码：候选码的判定方法——L 类属性（只出现在左边）必在码中，N 类（两边都不出现）必在码中，LR 类需组合测试；求码常用"L+N 先行，再补 LR"的策略。', 'MEDIUM', 2, 28),
('db-system-concepts', 6, '第6章 关系数据理论', 'db-system-concepts:6:29', '范式阶梯', '范式阶梯：1NF（属性不可再分，关系型数据库的最低要求）→ 2NF（消除非主属性对码的部分函数依赖）→ 3NF（消除非主属性对码的传递函数依赖）→ BCNF（消除主属性对码的部分与传递依赖，即每个决定因素都含码）。判断时先写出 F，求各属性闭包与候选码，再逐条检查。', 'MEDIUM', 2, 29),
('db-system-concepts', 6, '第6章 关系数据理论', 'db-system-concepts:6:30', '多值依赖与 4NF', '多值依赖与 4NF：X →→ Y 表示对每个 x，有一组与其余属性无关的 y 与之对应；平凡多值依赖不算。4NF 要求非平凡多值依赖的决定因素含码（4NF ⊂ BCNF）。', 'MEDIUM', 2, 30),
('db-system-concepts', 6, '第6章 关系数据理论', 'db-system-concepts:6:31', '公理系统与分解', '公理系统与分解：Armstrong 公理（自反、增广、传递，及导出规则合并、分解、伪传递）用于推理；模式分解追求两个目标——无损连接性（分解后自然连接不丢信息，判定定理：R1∩R2 → R1−R2 或 R1∩R2 → R2−R1 成立）与保持函数依赖性（分解后的依赖集并集的闭包等于原依赖集闭包）。3NF 可同时达到两个目标（合成法：对每个函数依赖造一个关系），BCNF 分解一般保连接但不保依赖。', 'MEDIUM', 2, 31),
('db-system-concepts', 7, '第7章 数据库设计', 'db-system-concepts:7:32', '设计特点与方法', '设计特点与方法：数据库设计是"三分技术、七分管理、十二分基础数据"，涉及结构设计与行为设计；方法有手工设计、规范化方法、CASE 工具辅助，主流是新奥尔良方法（需求分析→概念结构→逻辑结构→物理结构）。', 'EASY', 2, 32),
('db-system-concepts', 7, '第7章 数据库设计', 'db-system-concepts:7:33', '六步流程', '六步流程：需求分析（结果含数据流图、数据字典）→ 概念结构设计（与 DBMS 无关，产出 E-R 图）→ 逻辑结构设计（E-R 转关系模式并优化）→ 物理结构设计（存取方法、存储结构、评价）→ 实施（装载数据、编码调试、试运行）→ 运行与维护。', 'MEDIUM', 2, 33),
('db-system-concepts', 7, '第7章 数据库设计', 'db-system-concepts:7:34', '概念模型与 E-R 图', '概念模型与 E-R 图：实体用矩形、属性用椭圆、联系用菱形；联系的 cardinality（1:1、1:n、m:n）必须标注。扩展 E-R 含弱实体、特殊化/概括；也可用 UML 类图等价表示。集成多个局部 E-R 图时主要处理属性冲突、命名冲突、结构冲突三类冲突。', 'MEDIUM', 2, 34),
('db-system-concepts', 7, '第7章 数据库设计', 'db-system-concepts:7:35', 'E-R 图向关系模式转换', 'E-R 图向关系模式转换：实体→关系模式；1:1 可并入任一方；1:n 把 1 方的主码放入 n 方作外码；m:n 必须单独建关系（主码为两端主码组合）；多元联系同样独立成表。', 'MEDIUM', 2, 35),
('db-system-concepts', 7, '第7章 数据库设计', 'db-system-concepts:7:36', '物理设计与优化', '物理设计与优化：选择存取方法（B+树索引、聚簇、哈希）、确定存储结构（堆文件/顺序/散列/索引）、评价空间与时间效率；数据模型优化含水平/垂直分解与规范化。设计外模式是为不同用户提供视图，兼顾安全与易用。', 'MEDIUM', 2, 36),
('db-system-concepts', 8, '第8章 数据库编程', 'db-system-concepts:8:37', '为什么需要编程', '为什么需要编程：SQL 是声明式的，缺少流程控制与变量，表达能力受限（如循环、异常处理、复杂计算），因此引入过程化 SQL 或宿主语言 + API。', 'MEDIUM', 2, 37),
('db-system-concepts', 8, '第8章 数据库编程', 'db-system-concepts:8:38', '过程化 SQL', '过程化 SQL：块结构 { DECLARE ... BEGIN ... END }，含变量/常量定义、赋值、流程控制（IF/CASE/LOOP/WHILE/REPEAT/FOR）、游标（DECLARE CURSOR / OPEN / FETCH / CLOSE，用于逐行处理查询结果）。', 'MEDIUM', 2, 38),
('db-system-concepts', 8, '第8章 数据库编程', 'db-system-concepts:8:39', '存储过程与存储函数', '存储过程与存储函数：存储过程是一组预编译 SQL 的命名集合，可带输入/输出参数、在服务器端执行，优点是减少网络往返、复用、安全与性能；存储函数必须有返回值，可在 SQL 中直接调用。', 'MEDIUM', 2, 39),
('db-system-concepts', 8, '第8章 数据库编程', 'db-system-concepts:8:40', 'JDBC 与 MVC', 'JDBC 与 MVC：JDBC 通过 DriverManager → Connection → Statement/PreparedStatement → ResultSet 工作；PreparedStatement 可防 SQL 注入；事务通过 setAutoCommit(false) + commit/rollback 控制。基于 MVC 框架（模型-视图-控制器）把数据访问、业务逻辑与界面分离。', 'MEDIUM', 2, 40),
('db-system-concepts', 9, '第9章 关系数据库存储管理', 'db-system-concepts:9:41', '数据组织', '数据组织：数据库在操作系统的表空间—段—区—页—行层级组织；记录用定长/变长方式表示，块（页）是磁盘 I/O 单位，需处理记录跨块与块内指针。', 'MEDIUM', 2, 41),
('db-system-concepts', 9, '第9章 关系数据库存储管理', 'db-system-concepts:9:42', '表的组织方式', '表的组织方式：堆文件（无序）、有序文件（按排序键）、散列文件（按散列桶）、聚簇（把经常一起访问的关系按公共属性物理相邻存放）。', 'MEDIUM', 2, 42),
('db-system-concepts', 9, '第9章 关系数据库存储管理', 'db-system-concepts:9:43', '索引结构', '索引结构：顺序表索引（主索引稠密/稀疏、聚簇索引）；辅助索引（非主属性上的二级索引，需回表）；B+树索引（最常用，叶子链表支持范围扫描）；哈希索引（等值高效、不支持范围）；位图索引（低基数列上高效，适合 OLAP，高并发更新时锁代价大）。选择索引的本质是用空间与写代价换取读性能。', 'MEDIUM', 2, 43),
('db-system-concepts', 10, '第10章 关系查询处理和查询优化', 'db-system-concepts:10:44', '查询处理四步骤', '查询处理四步骤：查询分析（词法/语法）→ 查询检查（语义、权限）→ 查询优化（代数优化 + 物理优化）→ 查询执行（生成执行计划并执行）。', 'MEDIUM', 2, 44),
('db-system-concepts', 10, '第10章 关系查询处理和查询优化', 'db-system-concepts:10:45', '基本操作算法', '基本操作算法：选择可用全表扫描或索引扫描；投影需去重（排序法或哈希法）；连接可用嵌套循环（简单/块嵌套）、排序-归并、哈希连接、索引连接；不同算法的 I/O 与 CPU 代价差异巨大。', 'MEDIUM', 2, 45),
('db-system-concepts', 10, '第10章 关系查询处理和查询优化', 'db-system-concepts:10:46', '代数优化', '代数优化：依据等价变换规则做启发式优化——① 尽早执行选择与投影；② 合并笛卡尔积与选择为连接；③ 把投影提前并合并；④ 找出公共子表达式复用。语法树从"先投影、先选择"的方向改写。', 'MEDIUM', 2, 46),
('db-system-concepts', 10, '第10章 关系查询处理和查询优化', 'db-system-concepts:10:47', '物理优化', '物理优化：基于启发式规则（如连接中若一无序则优先用索引）或基于代价估算（用统计信息估计 I/O、CPU 代价，选代价最小者）。', 'MEDIUM', 2, 47),
('db-system-concepts', 10, '第10章 关系查询处理和查询优化', 'db-system-concepts:10:48', '查询计划执行', '查询计划执行：以算子（scan/join/sort/aggregate）构成的树或流水线执行，可物化或流水线；理解 EXPLAIN 的输出是性能调优的前提。', 'MEDIUM', 2, 48),
('db-system-concepts', 11, '第11章 数据库恢复技术', 'db-system-concepts:11:49', '事务', '事务：用户定义的一个逻辑工作单元，具有 ACID——原子性（要么全做要么全不做）、一致性（从一个一致状态到另一个一致状态）、隔离性（并发事务互不干扰）、持久性（提交后永久生效）。这四个特性分别由恢复机制、完整性、并发控制、恢复机制保障。', 'MEDIUM', 2, 49),
('db-system-concepts', 11, '第11章 数据库恢复技术', 'db-system-concepts:11:50', '故障种类', '故障种类：事务内部故障（可预期/不可预期）、系统故障（软故障，内存丢失、磁盘未损）、介质故障（硬故障，磁盘损坏）、计算机病毒与人为误操作。', 'MEDIUM', 2, 50),
('db-system-concepts', 11, '第11章 数据库恢复技术', 'db-system-concepts:11:51', '恢复技术', '恢复技术：① 数据转储——定期把数据库复制到后备副本，分静态/动态转储与海量/增量转储，恢复时用副本 + 日志；② 登记日志文件——记录事务的开始、更新前后像、提交/中止，遵循"先写日志"（WAL）原则：日志必须先于数据写入稳定存储，否则无法撤销/重做。', 'MEDIUM', 2, 51),
('db-system-concepts', 11, '第11章 数据库恢复技术', 'db-system-concepts:11:52', '恢复策略', '恢复策略：事务故障反向扫描日志 UNDO；系统故障对未提交事务 UNDO、已提交未落盘事务 REDO；介质故障用后备副本 + 日志重做。', 'MEDIUM', 2, 52),
('db-system-concepts', 11, '第11章 数据库恢复技术', 'db-system-concepts:11:53', '检查点与镜像', '检查点与镜像：检查点技术记录检查点时刻的活动事务与日志位置，恢复时只需从最近检查点开始扫描，大幅缩短恢复时间；引入检查点后仍要保证日志规则（检查点记录写入前，相关日志已落盘）。数据库镜像是把主库实时复制到镜像盘，提供高可用。', 'MEDIUM', 2, 53),
('db-system-concepts', 12, '第12章 并发控制', 'db-system-concepts:12:54', '并发控制概述', '并发控制概述：多事务并行执行提高吞吐，但会产生丢失修改、不可重复读、读"脏"数据三类不一致，须由 DBMS 并发控制机制保证调度的可串行性。', 'EASY', 2, 54),
('db-system-concepts', 12, '第12章 并发控制', 'db-system-concepts:12:55', '隔离级别', '隔离级别：读未提交（Read Uncommitted）、读已提交（Read Committed）、可重复读（Repeatable Read）、串行化（Serializable）。级别越高一致性越强、并发度越低；SQL 标准允许各级别仍存在某些异常（如可重复读下的幻读）。', 'MEDIUM', 2, 55),
('db-system-concepts', 12, '第12章 并发控制', 'db-system-concepts:12:56', '封锁与协议', '封锁与协议：基本锁类型为排它锁 X（写锁）与共享锁 S（读锁），相容矩阵 X 与一切不相容、S 与 S 相容。封锁协议三级：一级（事务结束才释放 X 锁，防丢失修改）、二级（加 S 锁读完即放，防丢失修改与读脏数据）、三级（S 锁持有到事务结束，再加防不可重复读）。', 'MEDIUM', 2, 56),
('db-system-concepts', 12, '第12章 并发控制', 'db-system-concepts:12:57', '活锁与死锁', '活锁与死锁：活锁可通过先来先服务调度避免；死锁预防用一次封锁法、顺序封锁法，检测用超时法或等待图法，处理是选定牺牲者回滚。两段锁协议（2PL：增长阶段只加锁、收缩阶段只解锁）保证冲突可串行化，但可能死锁；严格两段锁要求 X 锁持有到事务结束以避免级联回滚。', 'MEDIUM', 2, 57),
('db-system-concepts', 12, '第12章 并发控制', 'db-system-concepts:12:58', '可串行化与多粒度', '可串行化与多粒度：冲突可串行化通过交换不相冲突操作化为串行调度来判定（优先图无环）。多粒度封锁把封锁对象组织成树（数据库→关系→元组），配合意向锁（IS/IX/SIX）快速判定上层能否加锁，减少开销。', 'MEDIUM', 2, 58),
('db-system-concepts', 12, '第12章 并发控制', 'db-system-concepts:12:59', 'MVCC', 'MVCC：多版本并发控制为每条记录保留多个版本，读操作读旧版本而不阻塞写操作，写操作创建新版本，从而在读多写少场景大幅提升并发；通过版本可见性规则（按事务开始时间戳/提交序号）实现快照隔离。', 'MEDIUM', 2, 59),
('db-system-concepts', 13, '第13章 数据库管理系统概述', 'db-system-concepts:13:60', '基本功能与结构', '基本功能与结构：DBMS 功能含数据定义、数据操纵、数据库的建立与维护（装载、备份、性能监控）、运行管理（事务、并发、恢复、安全）。其层次结构自顶向下为应用层→语言处理层（DDL/DML 编译器、查询优化）→数据存取层（存取路径、缓冲区）→存储管理层→操作系统/磁盘。', 'MEDIUM', 2, 60),
('db-system-concepts', 13, '第13章 数据库管理系统概述', 'db-system-concepts:13:61', '运行过程', '运行过程：用户经应用提交 SQL → 语法分析与查询优化 → 存取层依据数据字典选择存取路径、通过缓冲区与 OS 交互 → 结果回传。理解该过程有助于定位性能瓶颈在哪一层。', 'MEDIUM', 2, 61),
('db-system-concepts', 13, '第13章 数据库管理系统概述', 'db-system-concepts:13:62', '缓冲区管理', '缓冲区管理：DBMS 维护缓冲池，采用 LRU 等置换策略，配合预先读/延迟写提升 I/O 效率；缓冲区大小直接决定 page hit ratio。', 'MEDIUM', 2, 62),
('db-system-concepts', 13, '第13章 数据库管理系统概述', 'db-system-concepts:13:63', '物理组织', '物理组织：页（block）是最小读写单位，记录在页内的布局、空闲空间管理（PCTFREE）、行溢出与 TOAST 机制都会影响存储效率与查询性能。', 'MEDIUM', 2, 63),
('db-system-concepts', 14, '第14章 数据库发展概述', 'db-system-concepts:14:64', '三代演进', '三代演进：第一代（层次、网状，1960s）→ 第二代（关系数据库，1970s~，关系模型 + SQL + ACID）→ 关系数据库的扩展（对象关系、分布式、数据仓库）→ 大数据时代（NoSQL、NewSQL、云原生）。', 'MEDIUM', 2, 64),
('db-system-concepts', 14, '第14章 数据库发展概述', 'db-system-concepts:14:65', '支撑技术', '支撑技术：高速网络支撑分布式数据库（数据分片、分布透明性、两阶段提交）；新硬件（多核、GPU、SSD、持久内存）催生内存数据库与 GPU 数据库；AI 与数据库互相渗透（智能优化器、向量检索、Text-to-SQL）。', 'MEDIUM', 2, 65),
('db-system-concepts', 14, '第14章 数据库发展概述', 'db-system-concepts:14:66', '发展趋势', '发展趋势：多数据模型并存、云原生数据库（存算分离、弹性伸缩）、HTAP（混合事务分析处理）、面向 AI 的数据管理（向量数据库、AI4DB 与 DB4AI）。', 'MEDIUM', 2, 66),
('db-system-concepts', 15, '第15~18章 新技术简介', 'db-system-concepts:15:67', '大数据管理系统（第15章）', '大数据管理系统（第15章）：大数据特征 Volume/Velocity/Variety/Value（4V）；管理系统四类——键值对数据库（高可扩展、弱 schema，如 Redis/DynamoDB）、文档数据库（半结构化，如 MongoDB）、图数据库（实体与关系建模，Neo4j）、时序数据库（面向时间序列高写入，InfluxDB/TDengine）。', 'MEDIUM', 2, 67),
('db-system-concepts', 15, '第15~18章 新技术简介', 'db-system-concepts:15:68', '数据仓库与 OLAP（第16章）', '数据仓库与 OLAP（第16章）：数据仓库是面向主题、集成、相对稳定、随时间变化的数据集合；OLAP 以多维数据模型（星型/雪花模式）支持上卷、下钻、切片、切块、旋转；HTAP 尝试在同一系统同时支撑 OLTP 与 OLAP；现代新型数据仓库走向湖仓一体与云化。', 'MEDIUM', 2, 68),
('db-system-concepts', 15, '第15~18章 新技术简介', 'db-system-concepts:15:69', '内存数据库（第17章）', '内存数据库（第17章）：把数据常驻内存以消除磁盘 I/O 瓶颈；关键技术包括面向内存的数据存储布局（行存/列存、压缩）、高效查询处理与索引（哈希/T 树）、面向多核无锁的并发控制、基于 NVRAM 与非易失内存的恢复机制；实现方案有混合加速引擎、独立内存数据库、GPU 数据库。', 'MEDIUM', 2, 69),
('db-system-concepts', 15, '第15~18章 新技术简介', 'db-system-concepts:15:70', '区块链与数据库（第18章）', '区块链与数据库（第18章）：区块链是由区块（区块头含前一区块哈希）链式组成的分布式账本，靠共识机制（PoW/PoS/PBFT）与密码学保证不可篡改；与数据库相比，它牺牲了灵活查询与高性能换取去中心化与可审计性；融合方向是"区块链存证 + 数据库承载业务"。', 'MEDIUM', 2, 70)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('mysql-intro', 1, '第1章 数据库入门', 'mysql-intro:1:1', '数据管理发展', '数据管理发展：人工管理 → 文件系统 → 数据库系统，数据库系统的核心优势是有组织、共享、低冗余、由 DBMS 统一管理与控制。', 'MEDIUM', 2, 1),
('mysql-intro', 1, '第1章 数据库入门', 'mysql-intro:1:2', '基本术语', '基本术语：数据库、数据库管理系统、数据库系统；表、记录、字段；主键、外键、索引、视图。理解"型（结构）与值（实例）"的区别有助于读懂后续 DDL/DML。', 'MEDIUM', 2, 2),
('mysql-intro', 1, '第1章 数据库入门', 'mysql-intro:1:3', '数据模型', '数据模型：概念模型用 E-R 图描述（实体—矩形、属性—椭圆、联系—菱形，标 1:1 / 1:n / m:n）；逻辑模型用关系模型（二维表）落地。E-R 图转关系模式的规则是后续建表的依据。', 'MEDIUM', 2, 3),
('mysql-intro', 1, '第1章 数据库入门', 'mysql-intro:1:4', '常见产品与 SQL 简介', '常见产品与 SQL 简介：商业库（Oracle、SQL Server、DB2）、开源库（MySQL、PostgreSQL）、嵌入式库（SQLite）。SQL 集 DDL/DML/DQL/DCL 于一体，面向集合、高度非过程化。', 'EASY', 2, 4),
('mysql-intro', 1, '第1章 数据库入门', 'mysql-intro:1:5', '安装与配置', '安装与配置：Windows 下可用 installer 或 ZIP 解压版；关键配置文件 my.ini（Linux 为 my.cnf），常用参数含 port（默认 3306）、datadir、character-set-server=utf8mb4、max_connections、innodb_buffer_pool_size。安装后须完成初始化、注册服务（mysqld --install）、启动/停止服务、设置 root 密码与配置环境变量。', 'MEDIUM', 2, 5),
('mysql-intro', 1, '第1章 数据库入门', 'mysql-intro:1:6', '图形工具', '图形工具：SQLyog、Navicat、MySQL Workbench、DBeaver、phpMyAdmin。图形工具降低建库建表与调试门槛，但生产环境仍应以命令行 + 脚本为准，便于版本管理与自动化。', 'MEDIUM', 2, 6),
('mysql-intro', 1, '第1章 数据库入门', 'mysql-intro:1:7', '上机实践', '上机实践：完成图书管理系统的 E-R 图设计，把"读者、图书、借阅、管理员"等实体及联系画清，再转换为关系模式——这是全书项目的起点。', 'MEDIUM', 2, 7),
('mysql-intro', 2, '第2章 数据库和数据表的基本操作', 'mysql-intro:2:8', '库级操作', '库级操作：CREATE DATABASE [IF NOT EXISTS] dbname [CHARACTER SET utf8mb4]、SHOW DATABASES、USE dbname、ALTER DATABASE ... CHARACTER SET、DROP DATABASE。务必先 USE 再操作表，避免建错库。', 'MEDIUM', 2, 8),
('mysql-intro', 2, '第2章 数据库和数据表的基本操作', 'mysql-intro:2:9', '数据类型选择', '数据类型选择：数值型（INT/BIGINT/DECIMAL/DOUBLE，金额类必须用 DECIMAL 而非浮点）、日期时间型（DATE/TIME/DATETIME/TIMESTAMP/YEAR，TIMESTAMP 有 2038 年与时区问题，DATETIME 无范围限制）、字符串型（定长 CHAR、变长 VARCHAR、大文本 TEXT/LONGTEXT、二进制 BLOB，以及 4.1 起推荐的 utf8mb4 字符集）。', 'MEDIUM', 2, 9),
('mysql-intro', 2, '第2章 数据库和数据表的基本操作', 'mysql-intro:2:10', '表级操作', '表级操作：CREATE TABLE（列定义 + 约束 + 引擎与字符集选项）、SHOW TABLES、DESC tbl、SHOW CREATE TABLE tbl（查看真实定义的最佳手段）、修改表 ALTER TABLE ADD|MODIFY|CHANGE|DROP COLUMN、重命名 RENAME TABLE、删除 DROP TABLE（不可恢复）。', 'MEDIUM', 2, 10),
('mysql-intro', 2, '第2章 数据库和数据表的基本操作', 'mysql-intro:2:11', '四类约束', '四类约束：非空 NOT NULL、唯一 UNIQUE（一张表可有多个唯一约束，NULL 不参与唯一判定）、主键 PRIMARY KEY（每表只能一个，等价于唯一 + 非空）、默认值 DEFAULT。约束在定义时给出，也可后续 ALTER TABLE ADD CONSTRAINT。', 'MEDIUM', 2, 11),
('mysql-intro', 2, '第2章 数据库和数据表的基本操作', 'mysql-intro:2:12', '自动增长', '自动增长：AUTO_INCREMENT 只能用于整型且通常是主键，插入时不赋值即自增；TRUNCATE 会重置计数器而 DELETE 不会，这是常见差异点。', 'MEDIUM', 2, 12),
('mysql-intro', 2, '第2章 数据库和数据表的基本操作', 'mysql-intro:2:13', '易错点', '易错点：① 字符集与排序规则不统一导致乱码或比较异常；② 用 FLOAT/DOUBLE 存金额造成精度丢失；③ DROP/TRUNCATE 属危险操作，脚本中应谨慎使用。', 'HARD', 2, 13),
('mysql-intro', 3, '第3章 数据操作', 'mysql-intro:3:14', '插入', '插入：单行 INSERT INTO t(col1,col2) VALUES(...)；多行 VALUES (...),(...),(...) 一次插入效率高于逐条；INSERT ... SELECT 可从其他表批量导入。省略列名时值的顺序必须与表结构完全一致。', 'MEDIUM', 2, 14),
('mysql-intro', 3, '第3章 数据操作', 'mysql-intro:3:15', '更新', '更新：UPDATE t SET col=val [, ...] [WHERE ...]。忘记 WHERE 会更新全表，是高危语句；可先写 SELECT ... WHERE 确认影响范围再改写为 UPDATE。', 'MEDIUM', 2, 15),
('mysql-intro', 3, '第3章 数据操作', 'mysql-intro:3:16', '删除', '删除：DELETE FROM t [WHERE ...]（逐行删除、可回滚、重置不了自增），TRUNCATE TABLE t（重建表、快、不可回滚、重置自增）；二者语义完全不同。', 'MEDIUM', 2, 16),
('mysql-intro', 3, '第3章 数据操作', 'mysql-intro:3:17', '上机实践', '上机实践：对图书表完成初始化数据的批量插入与修订，体会批量 INSERT 与按条件 UPDATE/DELETE 的写法差异。', 'MEDIUM', 2, 17),
('mysql-intro', 4, '第4章 单表查询', 'mysql-intro:4:18', 'SELECT 结构', 'SELECT 结构：SELECT [DISTINCT] 列|表达式 [AS 别名] FROM 表 [WHERE 条件] [GROUP BY ...] [HAVING ...] [ORDER BY ... [ASC|DESC]] [LIMIT n[,m]]。执行顺序可记为 FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT，这决定了别名在何处可用、WHERE 为何不能引用聚合结果。', 'MEDIUM', 2, 18),
('mysql-intro', 4, '第4章 单表查询', 'mysql-intro:4:19', '简单查询', '简单查询：查所有字段 SELECT *（生产环境应列出具体列）、查指定列、DISTINCT 去重、用 AS 给表/列起别名提高可读性。', 'MEDIUM', 2, 19),
('mysql-intro', 4, '第4章 单表查询', 'mysql-intro:4:20', '条件查询', '条件查询：比较运算符（= <> > < >= <=）、逻辑运算符（AND/OR/NOT 及优先级 NOT > AND > OR）、区间 BETWEEN...AND、枚举 IN、模糊 LIKE（% 任意串、_ 单个字符）、空值 IS NULL/IS NOT NULL、正则 REGEXP。', 'MEDIUM', 2, 20),
('mysql-intro', 4, '第4章 单表查询', 'mysql-intro:4:21', '聚合与分组', '聚合与分组：COUNT/SUM/AVG/MAX/MIN；GROUP BY 分组后 SELECT 只能出现分组列与聚合函数，组内过滤用 HAVING 而不是 WHERE。例如统计每类图书数量：', 'MEDIUM', 2, 21),
('mysql-intro', 4, '第4章 单表查询', 'mysql-intro:4:22', '排序与限量', '排序与限量：ORDER BY 可多列排序（先按第一列、并列再按第二列）；LIMIT n OFFSET m 实现分页，深分页（大 offset）性能差，常改用"基于主键的范围分页"优化。', 'MEDIUM', 2, 22),
('mysql-intro', 4, '第4章 单表查询', 'mysql-intro:4:23', '内置函数', '内置函数：字符串（CONCAT/SUBSTRING/LENGTH/UPPER/LOWER/TRIM/REPLACE）、数值（ROUND/FLOOR/CEIL/MOD）、日期（NOW/CURDATE/DATE_FORMAT/DATEDIFF/YEAR/MONTH/DAY）、流程（IF/CASE WHEN/COALESCE/IFNULL）、类型转换（CAST）。', 'MEDIUM', 2, 23),
('mysql-intro', 4, '第4章 单表查询', 'mysql-intro:4:24', '易错点', '易错点：WHERE 与 HAVING 混用；COUNT(*) 与 COUNT(列) 对 NULL 的处理不同；LIKE 通配符在中文上的匹配单位；DISTINCT 作用域是所有选中列的组合。', 'HARD', 2, 24),
('mysql-intro', 5, '第5章 多表操作', 'mysql-intro:5:25', '连接查询', '连接查询：交叉连接（笛卡尔积，慎用）→ 内连接 JOIN ... ON（只保留匹配行）→ 外连接 LEFT/RIGHT JOIN（保留一侧全部行，另一侧补 NULL）→ 复合条件连接（ON 中叠加多个条件）。多表查询应始终显式写 JOIN ... ON，避免隐式逗号连接的笛卡尔积陷阱。', 'HARD', 2, 25),
('mysql-intro', 5, '第5章 多表操作', 'mysql-intro:5:26', '子查询', '子查询：IN（等价于"属于某集合"）、EXISTS（相关子查询，常用于判断存在性，配合 NOT EXISTS 可实现"全部/至少"语义）、ANY/ALL（需与比较运算符连用）、比较运算符直接接标量子查询。EXISTS 与 IN 在涉及 NULL 时结果可能不同，且 EXISTS 常可用连接改写。', 'MEDIUM', 2, 26),
('mysql-intro', 5, '第5章 多表操作', 'mysql-intro:5:27', '外键约束', '外键约束：FOREIGN KEY (col) REFERENCES parent(id)，要求外键列与被参照列类型一致、被参照列必须是主键或唯一键，且两表须为 InnoDB 引擎。它保证参照完整性，是"先插父表后插子表、先删子表后删父表"的强约束。', 'MEDIUM', 2, 27),
('mysql-intro', 5, '第5章 多表操作', 'mysql-intro:5:28', '关联表操作', '关联表操作：更新/删除时可声明 ON DELETE CASCADE / SET NULL、ON UPDATE CASCADE 让变更自动级联；不加则违约操作被拒绝（NO ACTION）。删除外键用 ALTER TABLE ... DROP FOREIGN KEY 外键名（SHOW CREATE TABLE 可查名字）。', 'MEDIUM', 2, 28),
('mysql-intro', 5, '第5章 多表操作', 'mysql-intro:5:29', '易错点', '易错点：① 外键列与被参照列类型/字符集不一致导致建约束失败；② 左连接后在 WHERE 中对右表字段加条件，会把外连接"打回"成内连接，条件应写在 ON 中；③ 多表查询字段同名时必须用表别名限定。', 'HARD', 2, 29),
('mysql-intro', 6, '第6章 索引和视图', 'mysql-intro:6:30', '索引概述', '索引概述：索引是帮助 MySQL 快速定位的数据结构，B+树为主，另有哈希（Memory 引擎）、全文、空间索引。它能加速 WHERE/JOIN/ORDER BY，但会增加写开销并占用空间，因此并非越多越好。', 'EASY', 2, 30),
('mysql-intro', 6, '第6章 索引和视图', 'mysql-intro:6:31', '创建与维护', '创建与维护：CREATE INDEX idx ON t(col)、ALTER TABLE t ADD INDEX、CREATE UNIQUE INDEX、DROP INDEX idx ON t；SHOW INDEX FROM t 查看索引与基数（Cardinality）。最左前缀原则决定联合索引 (a,b,c) 可被用于 a、a,b、a,b,c 的查询，跳过 a 用 b 则用不上。', 'MEDIUM', 2, 31),
('mysql-intro', 6, '第6章 索引和视图', 'mysql-intro:6:32', 'EXPLAIN 执行计划', 'EXPLAIN 执行计划：必看的列有 type（const > eq_ref > ref > range > index > ALL，尽量避免 ALL 全表扫描）、key（实际使用的索引）、rows（预估扫描行数）、Extra（Using index 覆盖索引最佳、Using filesort/Using temporary 需警惕）。通过它验证索引是否命中、是否需改写 SQL 或调整索引。', 'MEDIUM', 2, 32),
('mysql-intro', 6, '第6章 索引和视图', 'mysql-intro:6:33', '视图', '视图：CREATE VIEW v AS SELECT ...，是虚表，用于简化复杂查询、隐藏敏感列、提供逻辑独立性；ALTER VIEW 修改、DROP VIEW 删除。含 DISTINCT/GROUP BY/聚合/多表连接（非键保留表） 的视图通常不可更新；WITH CHECK OPTION 可限制插入必须满足视图条件。', 'MEDIUM', 2, 33),
('mysql-intro', 6, '第6章 索引和视图', 'mysql-intro:6:34', '视图操作', '视图操作：查询视图与查询表语法相同；对可更新视图做 INSERT/UPDATE/DELETE 会传导到基表，但要满足"视图列与基表列一一对应"等限制。', 'MEDIUM', 2, 34),
('mysql-intro', 6, '第6章 索引和视图', 'mysql-intro:6:35', '易错点', '易错点：① 对索引列使用函数或隐式类型转换会导致索引失效；② LIKE ''%x'' 前置通配符用不上 B+树索引；③ 联合索引列序选择不当，把高区分度但低频使用的列放前面；④ 在事务中大量建索引会锁表，应在低峰期或用在线 DDL。', 'HARD', 2, 35),
('mysql-intro', 7, '第7章 事务', 'mysql-intro:7:36', '事务概述', '事务概述：事务是一组不可分割的操作序列，具有 ACID——原子性（undo/redo 保证要么全做要么全不做）、一致性（完整性约束不被破坏）、隔离性（并发互不影响）、持久性（提交后崩溃不丢）。MySQL 中 InnoDB 支持完整 ACID，MyISAM 不支持事务。', 'EASY', 2, 36),
('mysql-intro', 7, '第7章 事务', 'mysql-intro:7:37', '基本操作', '基本操作：START TRANSACTION / BEGIN → 若干 DML → COMMIT 或 ROLLBACK。autocommit 默认为 1（每条 SQL 自动提交），显式事务前可 SET autocommit=0。DDL 语句会隐式提交当前事务，混用时要格外小心。', 'MEDIUM', 2, 37),
('mysql-intro', 7, '第7章 事务', 'mysql-intro:7:38', '保存点', '保存点：SAVEPOINT sp、ROLLBACK TO sp 支持回滚到事务中间位置，而无需整体撤销，适用于长事务中的局部容错。', 'MEDIUM', 2, 38),
('mysql-intro', 7, '第7章 事务', 'mysql-intro:7:39', '四种隔离级别', '四种隔离级别：READ UNCOMMITTED（可脏读）、READ COMMITTED（防脏读、仍有不可重复读）、REPEATABLE READ（InnoDB 默认，防不可重复读，并通过 MVCC + 间隙锁在很大程度上防幻读）、SERIALIZABLE（串行化，性能最低）。设置方式 SET [SESSION|GLOBAL] TRANSACTION ISOLATION LEVEL ...，用 SELECT @@transaction_isolation 查看。', 'MEDIUM', 2, 39),
('mysql-intro', 7, '第7章 事务', 'mysql-intro:7:40', '并发异常', '并发异常：脏读、不可重复读、幻读分别对应"读到未提交""同一行两次读不同""同一条件两次查询行数不同"；快照读（MVCC）与当前读（SELECT ... FOR UPDATE、LOCK IN SHARE MODE）行为不同，理解这一点才能解释 RR 级别下的现象。', 'MEDIUM', 2, 40),
('mysql-intro', 8, '第8章 数据库编程', 'mysql-intro:8:41', '存储过程', '存储过程：CREATE PROCEDURE p(IN a INT, OUT b INT) BEGIN ... END，用 CALL p(...) 调用，SHOW PROCEDURE STATUS 查看，ALTER/DROP PROCEDURE 修改删除。适合封装多步 SQL、减少网络往返、统一业务规则。', 'MEDIUM', 2, 41),
('mysql-intro', 8, '第8章 数据库编程', 'mysql-intro:8:42', '存储函数', '存储函数：CREATE FUNCTION f(x INT) RETURNS INT BEGIN ... RETURN ...; END，必须有返回值，可在 SQL 中当函数使用；与存储过程相比更强调"计算并返回"。', 'MEDIUM', 2, 42),
('mysql-intro', 8, '第8章 数据库编程', 'mysql-intro:8:43', '变量', '变量：系统变量（@@global.xxx / @@session.xxx，用 SET 修改）、用户变量（@var，会话级，赋值 SET @v=1 或 SELECT ... INTO @v）、局部变量（DECLARE v INT DEFAULT 0，仅存在于块内）。', 'MEDIUM', 2, 43),
('mysql-intro', 8, '第8章 数据库编程', 'mysql-intro:8:44', '流程控制', '流程控制：判断 IF ... THEN ... ELSEIF ... ELSE ... END IF、CASE ... WHEN ... END CASE；循环 WHILE ... DO ... END WHILE、REPEAT ... UNTIL ... END REPEAT、LOOP ... LEAVE/ITERATE ... END LOOP；跳转 LEAVE（退出，相当于 break）、ITERATE（继续下一轮，相当于 continue）。', 'MEDIUM', 2, 44),
('mysql-intro', 8, '第8章 数据库编程', 'mysql-intro:8:45', '错误处理', '错误处理：DECLARE CONTINUE|EXIT HANDLER FOR <条件> <动作>，条件可为 SQLSTATE ''xxxxx''、SQLEXCEPTION、NOT FOUND、错误码或自定义名称（SIGNAL/RESIGNAL 抛出自定义错误）。', 'MEDIUM', 2, 45),
('mysql-intro', 8, '第8章 数据库编程', 'mysql-intro:8:46', '游标', '游标：用于逐行处理结果集，流程固定为 DECLARE cur CURSOR FOR SELECT... → OPEN cur → 循环 FETCH cur INTO var 并处理 → CLOSE cur；必须配合 NOT FOUND 处理器退出循环，否则会死循环。', 'MEDIUM', 2, 46),
('mysql-intro', 8, '第8章 数据库编程', 'mysql-intro:8:47', '触发器', '触发器：CREATE TRIGGER tg BEFORE|AFTER INSERT|UPDATE|DELETE ON t FOR EACH ROW <语句>，通过 OLD/NEW 引用变更前后行，常用于审计、联动更新、强制约束；DROP TRIGGER 删除。注意触发器不可见的连锁反应与递归风险。', 'MEDIUM', 2, 47),
('mysql-intro', 8, '第8章 数据库编程', 'mysql-intro:8:48', '上机实践', '上机实践：综合运用存储过程 + 游标 + 流程控制实现批量业务（如逾期罚款计算、批量下架），体会"数据库内编程"与"应用层编程"的边界。', 'MEDIUM', 2, 48),
('mysql-intro', 9, '第9章 数据库的管理和维护', 'mysql-intro:9:49', '数据备份', '数据备份：逻辑备份 mysqldump -u root -p dbname > bak.sql（可加 --single-transaction 做一致性快照、--routines 含存储过程、--triggers 含触发器、--master-data 记录 binlog 位点）；物理/热备可用 Percona XtraBackup（增量备份 --incremental，恢复需先 prepare 再拷贝回 datadir）；也可用 SELECT ... INTO OUTFILE 或二进制日志做补充。备份策略要区分全量 + 增量 + 日志三层。', 'MEDIUM', 2, 49),
('mysql-intro', 9, '第9章 数据库的管理和维护', 'mysql-intro:9:50', '数据还原', '数据还原：mysql -u root -p dbname < bak.sql，或在客户端 SOURCE bak.sql；物理备份按"停库/替换文件/恢复权限/启动"流程操作。务必先在测试库验证备份可用性，并定期演练 PITR（基于时间点恢复）。', 'MEDIUM', 2, 50),
('mysql-intro', 9, '第9章 数据库的管理和维护', 'mysql-intro:9:51', '用户管理', '用户管理：用户信息存于 mysql.user 表，身份由"用户名 + 主机"共同确定（''u''@''localhost'' 与 ''u''@''%'' 是两个不同账户）。CREATE USER ''u''@''%'' IDENTIFIED BY ''pwd''、DROP USER、ALTER USER ... IDENTIFIED BY 或 SET PASSWORD 修改密码。', 'MEDIUM', 2, 51),
('mysql-intro', 9, '第9章 数据库的管理和维护', 'mysql-intro:9:52', '权限管理', '权限管理：权限分为全局、库、表、列四级，另有 WITH GRANT OPTION 允许转授权。GRANT SELECT,INSERT ON db.* TO ''u''@''%''、REVOKE ... FROM ...、SHOW GRANTS FOR ''u''@''%''。最小权限原则：应用账号只授予必要库的 SELECT/INSERT/UPDATE/DELETE，不给 ALL PRIVILEGES，root 不开放远程。', 'MEDIUM', 2, 52),
('mysql-intro', 9, '第9章 数据库的管理和维护', 'mysql-intro:9:53', '日志与监控（扩展要点）', '日志与监控（扩展要点）：错误日志 log_error、慢查询日志 slow_query_log、通用查询日志；通过 SHOW PROCESSLIST、SHOW ENGINE INNODB STATUS、performance_schema 观察运行状态。', 'MEDIUM', 2, 53),
('mysql-intro', 9, '第9章 数据库的管理和维护', 'mysql-intro:9:54', '主从复制（扩展要点）', '主从复制（扩展要点）：原理是主库写 binlog、从库 IO 线程拉取并由 SQL 线程重放。配置三步：主库开 server-id 与 log_bin 并建复制账号；从库设 server-id 并 CHANGE MASTER TO ...；START SLAVE。用 SHOW SLAVE STATUS 关注 Slave_IO_Running/Slave_SQL_Running/Seconds_Behind_Master。复制架构（一主多从、半同步、组复制 MGR）是读写分离与高可用的基础。', 'EASY', 2, 54),
('mysql-intro', 9, '第9章 数据库的管理和维护', 'mysql-intro:9:55', '引擎选型', '引擎选型：InnoDB vs MyISAM：InnoDB 支持事务、行级锁、外键、崩溃恢复（redo/undo）、聚簇索引与 MVCC，是默认且推荐引擎；MyISAM 只支持表锁、无事务、全文索引（老版本）性能好于简单读场景，但已不适合多数业务。选引擎就是选"要不要事务与并发安全"。', 'MEDIUM', 2, 55),
('mysql-intro', 10, '第10章 综合开发案例——图书借阅系统', 'mysql-intro:10:56', '系统分析', '系统分析：功能需求含登录/注销、新书推荐与借阅、图书检索与增删改、当前借阅与归还、借阅记录查询；用功能结构图表达模块划分，明确参与者与用例。', 'MEDIUM', 2, 56),
('mysql-intro', 10, '第10章 综合开发案例——图书借阅系统', 'mysql-intro:10:57', '数据库设计', '数据库设计：实体设计（读者、图书、分类、借阅记录、管理员）→ E-R 图（标注 1:n 与 m:n 联系，借阅联系通常独立成表并带借还时间属性）→ 逻辑结构设计（转关系模式并加主键、外键、约束）。这一步决定后期所有 SQL 的形态。', 'MEDIUM', 2, 57),
('mysql-intro', 10, '第10章 综合开发案例——图书借阅系统', 'mysql-intro:10:58', '开发准备', '开发准备：搭建 Web/桌面开发环境，完成数据库连接配置（连接串、连接池、字符集参数），准备好建库脚本与测试数据。', 'MEDIUM', 2, 58),
('mysql-intro', 10, '第10章 综合开发案例——图书借阅系统', 'mysql-intro:10:59', '模块开发要点', '模块开发要点：登录模块要防 SQL 注入（参数化查询/PreparedStatement）并对密码加密存储；新书推荐/借阅要处理超借与库存；借阅模块的"新增、编辑、删除、查询"四件套是最典型的 CRUD 训练；当前借阅与归还模块重点在事务（借书同时减库存、写借阅记录，必须同成功同失败）与逾期判断；借阅记录模块练习多表连接与分页。', 'MEDIUM', 4, 59),
('mysql-intro', 10, '第10章 综合开发案例——图书借阅系统', 'mysql-intro:10:60', '项目启示', '项目启示：真实系统 = 数据库设计 + 事务边界 + 索引调优 + 权限控制 + 备份策略的综合体，这也是把前 9 章知识串起来的最好方式。', 'MEDIUM', 2, 60)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('cpp-programming', 1, '第 1 章 C++的初步知识', 'cpp-programming:1:1', '核心概念', '核心概念：C++ 是 C 的超集，兼容面向过程的程序设计，并扩展了面向对象、模板等机制；程序的基本单位是函数，main 是入口。', 'MEDIUM', 2, 1),
('cpp-programming', 1, '第 1 章 C++的初步知识', 'cpp-programming:1:2', '最简单的 C++ 程序', '最简单的 C++ 程序：int main() { cout << "Hello, world!" << endl; return 0; }，输出流对象 cout 配合插入运算符 << 完成输出，endl 换行并刷新缓冲区。', 'MEDIUM', 2, 2),
('cpp-programming', 1, '第 1 章 C++的初步知识', 'cpp-programming:1:3', '程序构成与书写形式', '程序构成与书写形式：预处理指令（#include <iostream>）、using namespace std;、函数定义、注释（// 与 /* */）；标识符由字母、数字、下划线组成且不能以数字开头。', 'MEDIUM', 2, 3),
('cpp-programming', 1, '第 1 章 C++的初步知识', 'cpp-programming:1:4', '编写和实现', '编写和实现：经历"编辑源文件(.cpp) → 编译(.obj) → 链接(.exe) → 运行"四步；编译错误看行号，链接错误多半是函数未定义或重复定义。', 'MEDIUM', 2, 4),
('cpp-programming', 1, '第 1 章 C++的初步知识', 'cpp-programming:1:5', '易错点', '易错点：把 cout/cin 当成关键字（实为 std 命名空间中的对象）；漏写 return 0;（C++ 标准允许 main 省略，但教学环境建议写）；文件名与工程配置不一致导致链接失败。', 'HARD', 2, 5),
('cpp-programming', 2, '第 2 章 数据的存储、表示形式和基本运算', 'cpp-programming:2:6', '核心概念', '核心概念：C++ 数据类型分为基本类型（int、float、double、char、bool、void）、构造类型（数组、结构体、共用体、枚举）、指针类型和空类型；不同类型占字节数随平台而变（可用 sizeof 验证）。', 'MEDIUM', 2, 6),
('cpp-programming', 2, '第 2 章 数据的存储、表示形式和基本运算', 'cpp-programming:2:7', '常量', '常量：字面常量（整型、实型、字符、字符串）、const 常量（const int N = 10;）与符号常量；【补充】C++11 起可用 constexpr 表达编译期常量。', 'MEDIUM', 2, 7),
('cpp-programming', 2, '第 2 章 数据的存储、表示形式和基本运算', 'cpp-programming:2:8', '变量', '变量：先定义后使用，定义即分配存储；可在定义时初始化 int a = 3, b = a + 1;；变量名规则见第 1 章。', 'MEDIUM', 2, 8),
('cpp-programming', 2, '第 2 章 数据的存储、表示形式和基本运算', 'cpp-programming:2:9', '算术运算', '算术运算：优先级与结合性决定计算顺序；%（取余）只能用于整数；整数相除结果仍为整数（5/2 == 2），要得到小数须写 5.0/2 或强制转换；混合运算按"就高不就低"自动提升。', 'MEDIUM', 2, 9),
('cpp-programming', 2, '第 2 章 数据的存储、表示形式和基本运算', 'cpp-programming:2:10', '自增自减与赋值', '自增自减与赋值：++i（先加后用）与 i++（先用后加）在表达式中的差别是高频考点；复合赋值 +=、-= 等；赋值表达式的值等于左操作数，因此可连续赋值 a = b = c = 0;。', 'MEDIUM', 4, 10),
('cpp-programming', 2, '第 2 章 数据的存储、表示形式和基本运算', 'cpp-programming:2:11', '逗号运算符', '逗号运算符：, 优先级最低，逗号表达式的值取最右子表达式的值，常用于 for 的步进部分。', 'MEDIUM', 2, 11),
('cpp-programming', 3, '第 3 章 程序设计初步', 'cpp-programming:3:12', '算法与表示', '算法与表示：算法是解决问题的步骤描述，具有有穷性、确定性、可行性、有输入/输出；表示方法有自然语言、流程图、N-S 图、伪代码。', 'MEDIUM', 2, 12),
('cpp-programming', 3, '第 3 章 程序设计初步', 'cpp-programming:3:13', '三种基本结构', '三种基本结构：顺序结构、选择结构（分支）、循环结构；任何程序都可由这三种结构组合而成（结构化程序设计思想）。', 'MEDIUM', 2, 13),
('cpp-programming', 3, '第 3 章 程序设计初步', 'cpp-programming:3:14', '输入输出', '输入输出：C++ 用流 I/O——cout << 插入、cin >> 提取；也可用 C 风格 printf/scanf 与 getchar/putchar；用 setw(n)、setprecision(k) 控制宽度和精度（需 <iomanip>）。', 'MEDIUM', 2, 14),
('cpp-programming', 3, '第 3 章 程序设计初步', 'cpp-programming:3:15', '关系与逻辑运算', '关系与逻辑运算：&&、|| 具有短路求值特性——a && b 中若 a 为假则不再算 b；逻辑常量是 true/false（底层为 1/0）。', 'MEDIUM', 2, 15),
('cpp-programming', 3, '第 3 章 程序设计初步', 'cpp-programming:3:16', 'if 与 switch', 'if 与 switch：else 总是与最近的未配对 if 配对（缩进会骗人）；条件运算符 c ? a : b；switch 中 case 后须加 break 否则"穿透"，default 可省略。', 'MEDIUM', 2, 16),
('cpp-programming', 3, '第 3 章 程序设计初步', 'cpp-programming:3:17', '循环', '循环：while（先判断后执行）、do...while（先执行后判断，至少一次）、for（已知次数首选）；循环嵌套注意内层完整；break 跳出本层循环，continue 跳过本次剩余语句进入下一轮。', 'MEDIUM', 2, 17),
('cpp-programming', 4, '第 4 章 利用函数实现指定的功能', 'cpp-programming:4:18', '函数定义与调用', '函数定义与调用：函数 = 返回类型 + 函数名 + 形参表 + 函数体；调用时实参与形参"按位置一一对应"，函数可无参、无返回值（void）。', 'MEDIUM', 2, 18),
('cpp-programming', 4, '第 4 章 利用函数实现指定的功能', 'cpp-programming:4:19', '递归调用', '递归调用：函数直接或间接调用自身；必须有递推关系和终止条件，否则无限递归导致栈溢出。例：阶乘 f(n) = n * f(n-1), f(0)=1。', 'MEDIUM', 2, 19),
('cpp-programming', 4, '第 4 章 利用函数实现指定的功能', 'cpp-programming:4:20', '内置（内联）函数', '内置（内联）函数：用 inline 声明，编译时将函数体嵌入调用处以减少开销；仅适用于短小、频繁调用的函数，复杂函数即使声明也会被编译器忽略。', 'MEDIUM', 2, 20),
('cpp-programming', 4, '第 4 章 利用函数实现指定的功能', 'cpp-programming:4:21', '函数重载', '函数重载：同一作用域内多个同名函数，靠参数个数或类型不同区分（返回值不同不算重载）；调用时编译器按实参匹配最优版本。', 'MEDIUM', 2, 21),
('cpp-programming', 4, '第 4 章 利用函数实现指定的功能', 'cpp-programming:4:22', '函数模板', '函数模板：template <class T> T mymax(T a, T b) { return a > b ? a : b; }，用同一代码支持多类型——这是 STL 泛型编程的基础（详见"三、核心机制深挖"）。', 'EASY', 2, 22),
('cpp-programming', 4, '第 4 章 利用函数实现指定的功能', 'cpp-programming:4:23', '默认参数', '默认参数：声明时为形参指定默认值，调用时可省略；默认参数必须从右向左连续设置，且声明与定义不能重复赋值。', 'MEDIUM', 2, 23),
('cpp-programming', 4, '第 4 章 利用函数实现指定的功能', 'cpp-programming:4:24', '作用域与存储类别', '作用域与存储类别：局部变量（块内有效）、全局变量（全程有效）；存储类别 auto（默认）、register（建议寄存器）、static（静态局部，只初始化一次、记忆上次值）、extern（引用外部变量）；静态局部变量在程序结束时才销毁。', 'MEDIUM', 2, 24),
('cpp-programming', 4, '第 4 章 利用函数实现指定的功能', 'cpp-programming:4:25', '内部/外部函数与头文件', '内部/外部函数与头文件：static 修饰函数使其仅在本文件可见（内部函数）；用头文件（.h）声明、源文件（.cpp）定义实现分离，避免重复包含用 #ifndef/#define/#endif 或 #pragma once。', 'MEDIUM', 2, 25),
('cpp-programming', 5, '第 5 章 利用数组处理批量数据', 'cpp-programming:5:26', '一维数组', '一维数组：int a[10]; 定义 10 个元素，下标从 0 开始；可整体初始化 int a[5] = {1,2,3,4,5};（部分赋值时剩余为 0）；数组名代表首元素地址。', 'MEDIUM', 2, 26),
('cpp-programming', 5, '第 5 章 利用数组处理批量数据', 'cpp-programming:5:27', '二维数组', '二维数组：int a[3][4]; 按行优先存放；初始化可分行 {{..},{..}}；内存中仍是连续的一块，a[i][j] 等价于 *(a[i]+j)。', 'MEDIUM', 2, 27),
('cpp-programming', 5, '第 5 章 利用数组处理批量数据', 'cpp-programming:5:28', '数组作函数参数', '数组作函数参数：传递的是首地址（传址调用），形参 int a[] 或 int *a 等价；因此函数内无法用 sizeof(a) 得到元素个数，必须另传长度参数。', 'MEDIUM', 2, 28),
('cpp-programming', 5, '第 5 章 利用数组处理批量数据', 'cpp-programming:5:29', '字符数组与字符串', '字符数组与字符串：C 风格字符串以 ''\0'' 结尾；常用函数 strlen/strcpy/strcat/strcmp（<cstring>）；cin >> str 遇空白停止，含空格用 cin.getline(str, n)。', 'MEDIUM', 2, 29),
('cpp-programming', 5, '第 5 章 利用数组处理批量数据', 'cpp-programming:5:30', 'string 类', 'string 类：string s = "abc"; 支持 +、==、[]、s.length()、s.substr() 等，无需管理 ''\0''；字符串数组 string names[10];。', 'MEDIUM', 2, 30),
('cpp-programming', 5, '第 5 章 利用数组处理批量数据', 'cpp-programming:5:31', '易错点', '易错点：数组越界不会报错但会破坏内存；把 char s[5]="Hello" 当作能存 5 个字符是错的（还需 1 字节存 ''\0''）；混淆"数组名是地址常量，不能整体赋值"。', 'HARD', 2, 31),
('cpp-programming', 6, '第 6 章 善于使用指针与引用', 'cpp-programming:6:32', '指针概念', '指针概念：指针是存放地址的变量；取址 &、间接访问 *；int *p = &a; 表示 p 指向 a，*p 即 a 的别名。', 'MEDIUM', 2, 32),
('cpp-programming', 6, '第 6 章 善于使用指针与引用', 'cpp-programming:6:33', '指针与数组', '指针与数组：数组名即首地址，p + i 移动 i 个元素（按类型大小缩放）；*(p+i) 与 a[i] 完全等价；"指针退化"：数组作形参时退化为指针。', 'MEDIUM', 2, 33),
('cpp-programming', 6, '第 6 章 善于使用指针与引用', 'cpp-programming:6:34', '指针与字符串、函数', '指针与字符串、函数：char *p = "abc";（常量字符串，不可改）；函数指针 int (*fp)(int,int); 可用于回调；返回指针的函数要么返回全局/静态地址，要么返回堆上地址（不可返回局部变量地址）。', 'MEDIUM', 2, 34),
('cpp-programming', 6, '第 6 章 善于使用指针与引用', 'cpp-programming:6:35', '指针数组、指向指针的指针、void 与 const 指针：char *argv[', '指针数组、指向指针的指针、void 与 const 指针：char *argv[] 是指针数组；int **pp 二级指针；void * 可接收任意地址但不能直接解引用（须先转换）；const int *p（指向常量的指针，不能改值）与 int *const p（指针本身是常量，不能改指向）的区别是考试常客。', 'MEDIUM', 2, 35),
('cpp-programming', 6, '第 6 章 善于使用指针与引用', 'cpp-programming:6:36', '引用', '引用：引用是变量的别名，int &r = a; 定义时必须初始化且不能再改绑；引用作形参可实现"对实参的修改"（比指针更安全直观）；const int &r 可绑定常量/表达式结果，函数中常用作只读大对象参数（避免拷贝）。', 'MEDIUM', 2, 36),
('cpp-programming', 6, '第 6 章 善于使用指针与引用', 'cpp-programming:6:37', '易错点', '易错点：未初始化的指针（野指针）直接使用是严重错误；对空指针解引用会崩溃；指针加减的步长取决于基类型。', 'HARD', 2, 37),
('cpp-programming', 7, '第 7 章 用户自定义数据类型', 'cpp-programming:7:38', '结构体', '结构体：struct Student { int id; char name[20]; }; 把相关数据打包；定义变量 Student s;、初始化、成员访问 s.id、结构体数组、指向结构体的指针（p->id）、结构体作函数参数（建议传指针/引用避免整体拷贝）。', 'MEDIUM', 2, 38),
('cpp-programming', 7, '第 7 章 用户自定义数据类型', 'cpp-programming:7:39', '枚举类型', '枚举类型：enum Week { Mon, Tue, ..., Sun }; 常量默认从 0 开始递增，可显式赋值；枚举值可当整数用，增强可读性。', 'MEDIUM', 2, 39),
('cpp-programming', 7, '第 7 章 用户自定义数据类型', 'cpp-programming:7:40', 'typedef', 'typedef：typedef int Length; 给已有类型起别名，简化复杂声明（如 typedef struct {...} Node;），不产生新类型。', 'MEDIUM', 2, 40),
('cpp-programming', 7, '第 7 章 用户自定义数据类型', 'cpp-programming:7:41', '动态内存分配', '动态内存分配：int *p = new int; / int *q = new int[10];，用完必须 delete p; / delete [] q; 释放，否则内存泄漏；new 失败抛 std::bad_alloc 异常（【补充】C++11 起可用 new (std::nothrow)）。', 'MEDIUM', 2, 41),
('cpp-programming', 7, '第 7 章 用户自定义数据类型', 'cpp-programming:7:42', '易错点', '易错点：new[] 必须配 delete[]（配对错误导致未定义行为）；delete 后指针成为悬垂指针，应置 nullptr；结构体整体赋值在 C++ 中合法（逐成员复制）。', 'HARD', 2, 42),
('cpp-programming', 8, '第 8 章 类和对象的特性', 'cpp-programming:8:43', '面向对象概述', '面向对象概述：三大特性——封装（隐藏内部细节）、继承（复用并扩展）、多态（同一接口不同行为）；核心名词：类（类型）、对象（实例）、方法（成员函数）、属性（数据成员）。', 'EASY', 2, 43),
('cpp-programming', 8, '第 8 章 类和对象的特性', 'cpp-programming:8:44', '类的声明与对象定义', '类的声明与对象定义：class Point { public: double x, y; void move(double dx, double dy); };，public/private 控制访问权限；定义对象 Point p1, *p2 = &p1;，类外访问 p1.x。', 'MEDIUM', 2, 44),
('cpp-programming', 8, '第 8 章 类和对象的特性', 'cpp-programming:8:45', '成员函数', '成员函数：类内定义自动成为内联（inline）；类外定义须用作用域运算符 void Point::move(...) { ... }；同类对象成员函数共享代码、数据各自独立。', 'MEDIUM', 2, 45),
('cpp-programming', 8, '第 8 章 类和对象的特性', 'cpp-programming:8:46', '对象成员的引用', '对象成员的引用：. 用于对象、-> 用于指向对象的指针；this 指针隐式指向当前对象（第 9 章详述）。', 'MEDIUM', 2, 46),
('cpp-programming', 8, '第 8 章 类和对象的特性', 'cpp-programming:8:47', '封装性与信息隐藏', '封装性与信息隐藏：数据成员通常 private，通过 public 的成员函数读写（setter/getter）；"公用接口与私有实现的分离"降低耦合。', 'MEDIUM', 2, 47),
('cpp-programming', 8, '第 8 章 类和对象的特性', 'cpp-programming:8:48', '易错点', '易错点：类声明末尾的分号不能丢；private 成员不能在类外直接访问；同一个类定义可创建无数对象，但类本身不占对象级存储。', 'HARD', 2, 48),
('cpp-programming', 9, '第 9 章 怎样使用类和对象', 'cpp-programming:9:49', '构造函数', '构造函数：与类同名、无返回类型、可带参与重载、对象创建时自动调用以完成初始化；推荐使用成员初始化列表 Point(int x, int y) : x_(x), y_(y) {}（对 const/引用成员只能用初始化列表）；可用默认参数提供更灵活的构造。', 'MEDIUM', 2, 49),
('cpp-programming', 9, '第 9 章 怎样使用类和对象', 'cpp-programming:9:50', '析构函数', '析构函数：~Point()，无参无返回、不可重载；对象生命周期结束时自动调用，负责清理资源（如 delete 动态内存）。构造与析构顺序：先构造的后析构（栈式）。', 'MEDIUM', 2, 50),
('cpp-programming', 9, '第 9 章 怎样使用类和对象', 'cpp-programming:9:51', '对象数组、对象指针与 this', '对象数组、对象指针与 this：Point arr[3]; 会用默认构造逐个初始化；Point *p = new Point(1,2); 用完 delete p;；this 指向当前对象地址，用于区分同名成员与形参、返回自身引用以支持链式调用。', 'MEDIUM', 2, 51),
('cpp-programming', 9, '第 9 章 怎样使用类和对象', 'cpp-programming:9:52', 'const 与对象', 'const 与对象：常对象 const Point p; 只能调用常成员函数；常成员 int get() const; 承诺不改对象；指向常对象的指针不能通过它修改对象；常引用作形参是传大对象的推荐方式。', 'MEDIUM', 2, 52),
('cpp-programming', 9, '第 9 章 怎样使用类和对象', 'cpp-programming:9:53', '对象的动态建立与释放、赋值与复制', '对象的动态建立与释放、赋值与复制：new/delete 用于对象；对象赋值默认逐成员复制（浅拷贝）——当类含指针成员时会导致两个对象共享资源、析构时双重释放，必须自定义拷贝构造函数与赋值运算符实现深拷贝（并遵守三/五法则，【补充】见第三部分）。', 'MEDIUM', 2, 53),
('cpp-programming', 9, '第 9 章 怎样使用类和对象', 'cpp-programming:9:54', '静态成员', '静态成员：static 数据成员属于类而非对象，须在类外初始化 int Point::count = 0;；静态成员函数没有 this，只能访问静态成员。', 'MEDIUM', 2, 54),
('cpp-programming', 9, '第 9 章 怎样使用类和对象', 'cpp-programming:9:55', '友元', '友元：friend 让外部函数/其他类访问本类私有成员，是对封装的有控破坏，慎用；友元关系单向、不传递。', 'MEDIUM', 2, 55),
('cpp-programming', 9, '第 9 章 怎样使用类和对象', 'cpp-programming:9:56', '类模板', '类模板：template <class T> class Stack { T data[100]; ... }; 用同一代码生成不同类型的栈，是 STL 容器的实现范式（详见第三部分）。', 'MEDIUM', 2, 56),
('cpp-programming', 10, '第 10 章 运算符重载', 'cpp-programming:10:57', '概念', '概念：为自定义类型赋予运算符的新含义，本质是定义一个名为 operator@ 的函数，使 a + b 可读可写。', 'MEDIUM', 2, 57),
('cpp-programming', 10, '第 10 章 运算符重载', 'cpp-programming:10:58', '重载方法', '重载方法：可作为类的成员函数（左操作数必须是本类对象，a + b 中 a 是调用者）或友元函数（两侧操作数都可是别的类型，如 2 + obj 或 cout << obj）；需要访问私有成员又不是成员函数的场景用友元。', 'MEDIUM', 2, 58),
('cpp-programming', 10, '第 10 章 运算符重载', 'cpp-programming:10:59', '重载规则', '重载规则：不能重载 ::、.、.*、?:、sizeof、typeid、#、&（取址）等；不能改变优先级、结合性和操作数个数；运算符至少有一个操作数是类或枚举类型；保持原语义习惯（+ 不做减法）。', 'MEDIUM', 2, 59),
('cpp-programming', 10, '第 10 章 运算符重载', 'cpp-programming:10:60', '双目与单目重载', '双目与单目重载：Complex operator+(const Complex&) const;；++ 前置返回引用 T& operator++()、后置带哑参 T operator++(int) 返回旧值副本。', 'MEDIUM', 2, 60),
('cpp-programming', 10, '第 10 章 运算符重载', 'cpp-programming:10:61', '流运算符重载', '流运算符重载：ostream& operator<<(ostream& out, const Point& p) 与 istream& operator>>(istream& in, Point& p)，返回流引用以支持链式 cout << a << b；必须用友元（左操作数是流对象）。', 'MEDIUM', 2, 61),
('cpp-programming', 10, '第 10 章 运算符重载', 'cpp-programming:10:62', '类型转换', '类型转换：转换构造函数（单参构造实现其他类型→本类）；类型转换函数 operator double() const; 实现本类→其他类型；二者同时存在可能引发二义性。', 'MEDIUM', 2, 62),
('cpp-programming', 11, '第 11 章 继承与派生', 'cpp-programming:11:63', '概念', '概念：派生类继承基类的成员并加以扩展，是实现代码复用与层次建模的核心机制；class Derived : public Base { ... };。', 'MEDIUM', 2, 63),
('cpp-programming', 11, '第 11 章 继承与派生', 'cpp-programming:11:64', '派生类的构成', '派生类的构成：吸收基类成员、改造（重写/隐藏）基类成员、添加新成员；构造时先构造成员与基类部分，再执行自身构造体。', 'MEDIUM', 2, 64),
('cpp-programming', 11, '第 11 章 继承与派生', 'cpp-programming:11:65', '三种继承的访问属性', '三种继承的访问属性：public 继承——基类 public/protected 在派生类中原样保留（最常用，表示 is-a）；protected 继承——public 降级为 protected；private 继承——全部降为 private（表示"用...实现"）。基类 private 成员任何继承方式都不可直接访问。', 'MEDIUM', 2, 65),
('cpp-programming', 11, '第 11 章 继承与派生', 'cpp-programming:11:66', '多级派生', '多级派生：访问属性沿继承链逐层推导；派生类对象可赋值给基类对象/指针（向上转型，自动、安全），反之须显式强制（向下转型，危险）。', 'MEDIUM', 2, 66),
('cpp-programming', 11, '第 11 章 继承与派生', 'cpp-programming:11:67', '派生类的构造与析构', '派生类的构造与析构：构造函数用初始化列表调用基类构造 Derived(int a) : Base(a) { ... }；未显式调用时默认调用基类无参构造；析构顺序与构造相反。', 'MEDIUM', 2, 67),
('cpp-programming', 11, '第 11 章 继承与派生', 'cpp-programming:11:68', '多重继承与虚基类', '多重继承与虚基类：一个类可从多个基类派生；共同基类被继承多次会产生二义性与数据冗余，用virtual 虚基类 class D : public virtual B {...} 保证共同部分只存一份。', 'MEDIUM', 2, 68),
('cpp-programming', 11, '第 11 章 继承与派生', 'cpp-programming:11:69', '继承与组合', '继承与组合：优先使用对象组合（has-a）而非深度继承，降低耦合。', 'MEDIUM', 2, 69),
('cpp-programming', 12, '第 12 章 多态性与虚函数', 'cpp-programming:12:70', '多态概念', '多态概念：同一接口在不同对象上表现出不同行为；分编译时多态（重载、模板）与运行时多态（虚函数）。', 'MEDIUM', 2, 70),
('cpp-programming', 12, '第 12 章 多态性与虚函数', 'cpp-programming:12:71', '虚函数实现动态多态', '虚函数实现动态多态：基类用 virtual void speak() const; 声明，派生类重写（override）同名同参函数；用基类指针/引用调用时才发生动态绑定，调用哪个版本取决于对象的实际类型。', 'MEDIUM', 2, 71),
('cpp-programming', 12, '第 12 章 多态性与虚函数', 'cpp-programming:12:72', '静态关联与动态关联', '静态关联与动态关联：普通成员函数在编译期按指针类型确定（静态绑定）；虚函数在运行期按对象实际类型确定（动态绑定），代价是每个多态对象多一个虚指针。', 'MEDIUM', 2, 72),
('cpp-programming', 12, '第 12 章 多态性与虚函数', 'cpp-programming:12:73', '使用条件', '使用条件：只有通过基类指针/引用调用、且函数为虚函数时才多态；派生类重写时函数签名须完全一致（【补充】C++11 用 override 关键字让编译器帮你检查）；析构函数应声明为虚函数（虚析构），否则通过基类指针 delete 派生对象会造成资源泄漏。', 'MEDIUM', 2, 73),
('cpp-programming', 12, '第 12 章 多态性与虚函数', 'cpp-programming:12:74', '纯虚函数与抽象类', '纯虚函数与抽象类：virtual double area() const = 0; 纯虚函数使类成为抽象类，不能实例化，只作接口；派生类必须实现所有纯虚函数才能实例化。', 'MEDIUM', 2, 74),
('cpp-programming', 12, '第 12 章 多态性与虚函数', 'cpp-programming:12:75', 'vtable 原理【补充】', 'vtable 原理【补充】：含虚函数的类有一个虚函数表（vtable），对象内藏指向它的指针（vptr）；调用虚函数即经 vptr 查表跳转，这是动态绑定的底层机制。', 'MEDIUM', 2, 75),
('cpp-programming', 13, '第 13 章 输入输出流', 'cpp-programming:13:76', '概念', '概念：C++ I/O 以"流"为核心，<</>> 类型安全、可扩展；相比 C 的 printf/scanf 更不易因格式串不匹配而出错。', 'MEDIUM', 2, 76),
('cpp-programming', 13, '第 13 章 输入输出流', 'cpp-programming:13:77', '标准输出流', '标准输出流：cout（有缓冲，标准输出）、cerr（无缓冲，错误）、clog（有缓冲，日志）；可用 setw/setprecision/fixed/showpoint/left/right 控制格式；put() 输出单个字符。', 'MEDIUM', 2, 77),
('cpp-programming', 13, '第 13 章 输入输出流', 'cpp-programming:13:78', '标准输入流', '标准输入流：cin >> 变量 遇空白（空格/Tab/换行）停止，留下换行符在缓冲区——混用 cin >> 与 getline 时要用 cin.ignore() 清掉残留换行；成员函数 get()、getline()、read() 可处理含空格输入与定长读取。', 'MEDIUM', 2, 78),
('cpp-programming', 13, '第 13 章 输入输出流', 'cpp-programming:13:79', '文件流', '文件流：ifstream（读）、ofstream（写）、fstream（读写）；open(文件名, 打开模式) / close()；打开失败要检查 is_open() 或 fail()；可用 <</>> 做 ASCII 文本读写，或用 read()/write() 配合 ios::binary 做二进制读写（注意 sizeof(对象) 与字节序，含指针/虚表的对象不可直接二进制持久化）。', 'MEDIUM', 2, 79),
('cpp-programming', 13, '第 13 章 输入输出流', 'cpp-programming:13:80', '字符串流', '字符串流：istringstream/ostringstream/stringstream（<sstream>）把内存字符串当流用，常用于类型与字符串的相互转换、格式化拼接。', 'MEDIUM', 2, 80),
('cpp-programming', 14, '第 14 章 C++工具', 'cpp-programming:14:81', '异常处理', '异常处理：用 try { ... throw e; } catch (T& e) { ... } 分离正常逻辑与错误处理；throw 可抛出任意类型；匹配按 catch 顺序进行，建议捕获常引用以避免切片；可嵌套与重新抛出（throw;）；函数可用异常说明（【补充】C++11 起用 noexcept 替代动态异常规格）。栈解旋保证抛出路径上的局部对象被正确析构。', 'MEDIUM', 2, 81),
('cpp-programming', 14, '第 14 章 C++工具', 'cpp-programming:14:82', '命名空间', '命名空间：namespace MyLib { ... } 解决全局名字冲突；using namespace std;、using std::cout;、std::cout << 三种使用方式；匿名命名空间等价于 C 的 static；:: 表示全局。', 'MEDIUM', 2, 82),
('cpp-programming', 14, '第 14 章 C++工具', 'cpp-programming:14:83', '使用早期函数库', '使用早期函数库：C 头文件在 C++ 中改为 <cxxx>（如 <cmath>、<cstring>），函数位于 std 命名空间，类型更严格（如 sqrt 重载）。', 'MEDIUM', 2, 83),
('cpp-programming', 14, '第 14 章 C++工具', 'cpp-programming:14:84', '现代 C++ 补充【C++11/14/17】', '现代 C++ 补充【C++11/14/17】：auto 自动类型推导（auto it = v.begin();）；范围 for（for (auto& x : vec)）；nullptr 替代 NULL；lambda 表达式 auto f = [](int a, int b){ return a + b; };；智能指针 unique_ptr（独占）、shared_ptr（共享计数）、weak_ptr（打破循环引用）自动管理资源，替代裸 new/delete；右值引用与 move 语义（std::move）用移动替代深拷贝，提升性能；override/final、初始化列表、=default/=delete。', 'MEDIUM', 2, 84)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('python-programming', 1, '第 1 章 基础知识', 'python-programming:1:1', '版本选择与环境搭建', '版本选择与环境搭建：选 Python 3.x（3.9+ 主流），官网或 Anaconda 安装；python --version 验证；IDLE、VS Code、PyCharm 均可作为开发环境，掌握"写 .py → 运行 → 看报错"闭环。', 'MEDIUM', 2, 1),
('python-programming', 1, '第 1 章 基础知识', 'python-programming:1:2', 'pip 与虚拟环境', 'pip 与虚拟环境：pip install 包名 管理扩展库；不同项目用 python -m venv venv 建独立环境，激活后 pip install 互不干扰（【补充】重点：避免全局环境污染）。', 'MEDIUM', 4, 2),
('python-programming', 1, '第 1 章 基础知识', 'python-programming:1:3', 'Python 对象模型', 'Python 对象模型：一切皆对象，变量是对象的引用（名字绑定）；id()/type()/is 可查看身份、类型与同一性；可变对象与不可变对象的区别决定参数传递语义（赋值传递的是引用）。', 'MEDIUM', 2, 3),
('python-programming', 1, '第 1 章 基础知识', 'python-programming:1:4', '数字与字符串', '数字与字符串：整数任意精度；float 为双精度（有精度误差，金额用 Decimal）；complex 复数；str 是不可变序列，支持索引、切片与丰富方法。', 'MEDIUM', 2, 4),
('python-programming', 1, '第 1 章 基础知识', 'python-programming:1:5', '运算符与表达式', '运算符与表达式：算术（// 整除、** 幂、% 取余）、比较、成员（in/not in）、身份（is/is not）、逻辑（and/or/not，短路求值）；赋值增强 += 等。', 'MEDIUM', 2, 5),
('python-programming', 1, '第 1 章 基础知识', 'python-programming:1:6', '常用内置函数与 I/O', '常用内置函数与 I/O：print()（sep/end/file/flush）、input() 返回字符串；len/abs/max/min/sum/sorted/round/eval 等；print 格式化与 f-string（f"结果是 {x:.2f}"，【补充】f-string 为 Python 3.6+ 首选格式方案）。', 'MEDIUM', 2, 6),
('python-programming', 1, '第 1 章 基础知识', 'python-programming:1:7', '模块导入、代码规范与打包', '模块导入、代码规范与打包：import math、from math import sqrt、import numpy as np；PEP 8 规范（4 空格缩进、命名习惯、行长）；__name__ == "__main__" 的作用；if __name__ == "__main__": main() 让文件既可被导入又可独立运行。', 'MEDIUM', 2, 7),
('python-programming', 2, '第 2 章 Python可迭代对象', 'python-programming:2:8', '列表 list', '列表 list：有序可变序列；增删改查（append/pop/remove/insert/sort/reverse/clear）；切片 a[1:5:2] 含头不含尾，负步长反向；* 解包与拼接。', 'MEDIUM', 2, 8),
('python-programming', 2, '第 2 章 Python可迭代对象', 'python-programming:2:9', '列表推导式', '列表推导式：[x*x for x in range(10) if x % 2 == 0]——一行完成过滤+变换，比循环更简洁高效；嵌套推导可生成二维结构（如矩阵转置 [[row[i] for row in m] for i in range(n)]）。', 'MEDIUM', 2, 9),
('python-programming', 2, '第 2 章 Python可迭代对象', 'python-programming:2:10', '元组 tuple 与序列解包', '元组 tuple 与序列解包：元组有序不可变，可作为字典键、函数多返回值，(x,) 单元素必须带逗号，与列表互转 tuple(lst)/list(tup)；序列解包 a, b = b, a 实现交换、first, *rest = lst 拆分首尾，函数返回多值本质就是元组。', 'MEDIUM', 2, 10),
('python-programming', 2, '第 2 章 Python可迭代对象', 'python-programming:2:11', '生成器表达式', '生成器表达式：(x*x for x in range(10)) 惰性求值、省内存，适合大数据流；只能用一次（一次性迭代器）。', 'MEDIUM', 2, 11),
('python-programming', 2, '第 2 章 Python可迭代对象', 'python-programming:2:12', '字典 dict', '字典 dict：键值对映射，键必须可哈希（不可变）；d[k]、get()、keys()/values()/items()、update()、pop()；字典推导式 {k: v for k, v in ...}；查找 O(1)。', 'MEDIUM', 2, 12),
('python-programming', 2, '第 2 章 Python可迭代对象', 'python-programming:2:13', '集合 set', '集合 set：无序不重复；交并差 & | - ^、子集判断；去重首选 set(lst)；集合推导式；冻结集合 frozenset 可作字典键。', 'MEDIUM', 2, 13),
('python-programming', 2, '第 2 章 Python可迭代对象', 'python-programming:2:14', '复杂数据结构', '复杂数据结构：用列表实现栈（append/pop）、队列（collections.deque 的 popleft）、链表、二叉树（嵌套列表或类节点）与有向图（字典存邻接表）。', 'MEDIUM', 2, 14),
('python-programming', 2, '第 2 章 Python可迭代对象', 'python-programming:2:15', '易错点', '易错点：循环中修改正在遍历的列表会漏元素（应遍历副本或倒序删除）；把可变对象放入 set/dict 键会报 TypeError。', 'HARD', 2, 15),
('python-programming', 3, '第 3 章 选择与循环', 'python-programming:3:16', '条件表达式', '条件表达式：条件成立时的值 if 条件 else 否则的值，可读性优于短路 and/or 写法。', 'MEDIUM', 2, 16),
('python-programming', 3, '第 3 章 选择与循环', 'python-programming:3:17', '选择结构', '选择结构：单分支 if、双分支 if...else、嵌套 if、多分支 if...elif...else；Python 用缩进表示隶属关系，缩进错误直接导致逻辑错误或 IndentationError；条件可以是关系/逻辑/成员表达式，非 0/非空即真。', 'MEDIUM', 2, 17),
('python-programming', 3, '第 3 章 选择与循环', 'python-programming:3:18', 'while 与 for', 'while 与 for：for 变量 in 可迭代对象 是 Python 的主力循环（计数用 range(start, stop, step)，含头不含尾）；while 用于条件循环；循环同样支持 else 子句——循环正常结束（未被 break 打断）才执行。', 'MEDIUM', 2, 18),
('python-programming', 3, '第 3 章 选择与循环', 'python-programming:3:19', '循环优化', '循环优化：能在循环外算的不要放循环内；优先推导式/map/filter；减少属性查找（把 len 提到局部变量）。', 'MEDIUM', 2, 19),
('python-programming', 3, '第 3 章 选择与循环', 'python-programming:3:20', 'break 与 continue', 'break 与 continue：break 终止本层循环，continue 跳过本次剩余语句；均可与 else 配合，else 只在没有 break 时执行。', 'MEDIUM', 2, 20),
('python-programming', 3, '第 3 章 选择与循环', 'python-programming:3:21', '易错点', '易错点：range(5) 是 0~4；死循环常因忘记更新循环变量；== 与 = 混用；浮点数相等比较应用误差范围。', 'HARD', 2, 21),
('python-programming', 4, '第 4 章 字符串与正则表达式', 'python-programming:4:22', '字符串格式化', '字符串格式化：str.format 的位置/关键字参数、格式 Specification（"{:.2f}".format(x)、"{:>10}".format(s)）；【补充】f-string（f"{x:.2f}"）简洁直观，是推荐写法。', 'MEDIUM', 2, 22),
('python-programming', 4, '第 4 章 字符串与正则表达式', 'python-programming:4:23', '常用方法', '常用方法：split/rsplit、join（" ".join(lst) 是拼接首选）、strip/lstrip/rstrip、replace、startswith/endswith、find/index、count、upper/lower/title、zfill、center；判断类 isdigit/isalpha/isalnum/isspace。', 'MEDIUM', 2, 23),
('python-programming', 4, '第 4 章 字符串与正则表达式', 'python-programming:4:24', '字符串常量与其他', '字符串常量与其他：三引号多行串、原始串 r"C:\path"、转义符；中文分词与拼音处理借助第三方库（如 jieba）；字符串不可变，"修改"实为新建。', 'MEDIUM', 2, 24),
('python-programming', 4, '第 4 章 字符串与正则表达式', 'python-programming:4:25', '正则表达式语法', '正则表达式语法：元字符 . * + ? ^ $ [] () {} | \；预定义字符类 \d \w \s（及取反 \D \W \S）；量词 {n} {n,} {n,m}；分组 () 与 | 选择；贪婪/非贪婪（.*?）。', 'MEDIUM', 2, 25),
('python-programming', 4, '第 4 章 字符串与正则表达式', 'python-programming:4:26', 're 模块应用', 're 模块应用：re.match（从头匹配）、re.search（任意位置）、re.findall/finditer、re.sub（替换）、re.split、编译复用 re.compile(pattern)； flags 如 re.I（忽略大小写）、re.M（多行模式）。', 'MEDIUM', 2, 26),
('python-programming', 4, '第 4 章 字符串与正则表达式', 'python-programming:4:27', '子模式与 Match 对象', '子模式与 Match 对象：用括号分组后 m.group(n) 取子组、m.groups()、m.groupdict()（命名组 (?P<name>...)）；匹配失败返回 None，须先判空再用。', 'MEDIUM', 2, 27),
('python-programming', 4, '第 4 章 字符串与正则表达式', 'python-programming:4:28', '易错点', '易错点：正则中的 \ 在普通字符串里要先转义或用原始串；match 不等于"完全匹配"，需要 ^...$；. 默认不匹配换行。', 'HARD', 2, 28),
('python-programming', 5, '第 5 章 函数设计与使用', 'python-programming:5:29', '函数定义与调用', '函数定义与调用：def 函数名(形参): + 文档字符串 + 返回值（可返回多值=元组）；调用方式含位置实参与关键字实参；形参只在调用期间存在。', 'MEDIUM', 2, 29),
('python-programming', 5, '第 5 章 函数设计与使用', 'python-programming:5:30', '参数类型', '参数类型：默认值参数（定义时给默认值，调用可省略；默认值只初始化一次，不要用可变对象作默认值，应 def f(a, lst=None)）；关键（关键字）参数；可变长度参数 *args（多余位置参数收为元组）与 **kwargs（多余关键字参数收为字典）——两者同时出现顺序固定 *args 在前。', 'MEDIUM', 2, 30),
('python-programming', 5, '第 5 章 函数设计与使用', 'python-programming:5:31', '参数传递与解包', '参数传递与解包：传的是对象引用；对不可变对象"相当于值传递"、对可变对象"相当于址传递"；调用时用 *lst/**d 解包实参；函数定义/调用两侧都可解包。', 'MEDIUM', 2, 31),
('python-programming', 5, '第 5 章 函数设计与使用', 'python-programming:5:32', 'return 与作用域', 'return 与作用域：return 提前结束并可返回多值；局部变量优先于全局变量（LEGB：Local→Enclosing→Global→Built-in）；函数内要修改全局变量用 global，修改外层嵌套变量用 nonlocal。', 'MEDIUM', 2, 32),
('python-programming', 5, '第 5 章 函数设计与使用', 'python-programming:5:33', 'lambda 表达式', 'lambda 表达式：lambda 参数: 表达式 创建匿名函数，常作 sorted(key=lambda x: x[1])、max/min/map/filter 的实参，不能包含多条语句。', 'MEDIUM', 2, 33),
('python-programming', 5, '第 5 章 函数设计与使用', 'python-programming:5:34', '高级话题', '高级话题：闭包（内层函数记住外层变量）、装饰器（@decorator，在不改原函数代码前提下增强功能）、生成器函数（yield 惰性产出，等价于返回迭代器）、可调用对象与偏函数；【补充】类型注解 def add(a: int, b: int) -> int: 提升可读性与静态检查能力（配合 mypy），运行时不强制。', 'MEDIUM', 2, 34),
('python-programming', 5, '第 5 章 函数设计与使用', 'python-programming:5:35', '递归', '递归：函数自调用，需递推式 + 终止条件；深度过大可用 sys.setrecursionlimit，但更应改写为循环。', 'MEDIUM', 2, 35),
('python-programming', 6, '第 6 章 面向对象程序设计', 'python-programming:6:36', '类的定义与使用', '类的定义与使用：class Student:，__init__(self, ...) 构造方法在创建对象时自动调用，self 代表实例自身；属性与方法；cls 用于类方法 @classmethod 与静态方法 @staticmethod。', 'MEDIUM', 2, 36),
('python-programming', 6, '第 6 章 面向对象程序设计', 'python-programming:6:37', '类成员与实例成员', '类成员与实例成员：实例属性在各对象中独立（通常在 __init__ 中用 self.x 定义）；类属性被所有实例共享，修改要用 类名.属性；实例方法第一个参数是 self，类方法第一个是 cls。', 'MEDIUM', 2, 37),
('python-programming', 6, '第 6 章 面向对象程序设计', 'python-programming:6:38', '私有与公有', '私有与公有：_x 约定内部使用；__x 触发名称改写（name mangling _类名__x）实现"伪私有"；鸭子类型——"像鸭子就是鸭子"，不依赖继承体系。', 'MEDIUM', 2, 38),
('python-programming', 6, '第 6 章 面向对象程序设计', 'python-programming:6:39', '特殊方法与运算符重载', '特殊方法与运算符重载：__str__/__repr__（打印）、__len__、__eq__/__lt__（比较）、__getitem__/__setitem__（下标）、__add__（加法）、__enter__/__exit__（with 上下文）；让自定义类表现得像内置类型。', 'MEDIUM', 2, 39),
('python-programming', 6, '第 6 章 面向对象程序设计', 'python-programming:6:40', '继承', '继承：class Sub(Base): 获得父类成员；super().__init__() 调用父类构造；方法重写（override）实现特化；多重继承时属性查找遵循 MRO（C3 线性化），可用 类名.__mro__ 查看（【补充】重点）。', 'MEDIUM', 4, 40),
('python-programming', 6, '第 6 章 面向对象程序设计', 'python-programming:6:41', '多态', '多态：同一方法在不同子类中有不同实现，调用时按对象实际类型分派（动态绑定）；抽象基类可用 abc.ABC + @abstractmethod 定义接口。', 'MEDIUM', 2, 41),
('python-programming', 6, '第 6 章 面向对象程序设计', 'python-programming:6:42', '易错点', '易错点：self 必须显式写出（与 C++ 的 this 不同）；忘记 super().__init__() 导致父类属性缺失；实例属性与类属性同名时互相遮蔽。', 'HARD', 2, 42),
('python-programming', 7, '第 7 章 文件操作', 'python-programming:7:43', '文件对象', '文件对象：open(path, mode, encoding=''utf-8'')；mode 含 r/w/a/x 与 b/t、+；with open(...) as f: 自动关闭，是最推荐写法；常用方法 read/readline/readlines/write/writelines/seek/tell。', 'MEDIUM', 2, 43),
('python-programming', 7, '第 7 章 文件操作', 'python-programming:7:44', '文本与二进制', '文本与二进制：文本模式按编码读写字符串；二进制模式读写 bytes，encoding 参数在二进制模式下不能用；大文件用 for line in f 逐行读，避免一次性载入。', 'MEDIUM', 2, 44),
('python-programming', 7, '第 7 章 文件操作', 'python-programming:7:45', '对象序列化', '对象序列化：pickle.dump(obj, f) / pickle.load(f) 保存任意 Python 对象（注意安全风险，勿加载不可信数据）；struct.pack/unpack 处理 C 风格二进制结构；【补充】json.dump/json.load 跨语言文本序列化最常用，ensure_ascii=False 保留中文。', 'MEDIUM', 2, 45),
('python-programming', 7, '第 7 章 文件操作', 'python-programming:7:46', '文件级与目录操作', '文件级与目录操作：os.path.join/basename/dirname/splitext/exists/isfile/getsize 处理路径；shutil.copy/move/rmtree 复制移动删除；os.listdir/glob.glob 枚举文件；os.remove/rename/mkdir/makedirs 增删改名。', 'MEDIUM', 2, 46),
('python-programming', 7, '第 7 章 文件操作', 'python-programming:7:47', '实用案例', '实用案例：批量重命名、文件夹大小统计（递归累加 getsize）、增量备份（比较 mtime）、删除指定类型文件、Office 文件操作（openpyxl/python-docx 等第三方库）。', 'MEDIUM', 2, 47),
('python-programming', 7, '第 7 章 文件操作', 'python-programming:7:48', '易错点', '易错点：Windows 路径反斜杠要转义或用原始串/正斜杠；写文件后未 flush/close 可能丢数据；相对路径随运行目录变化。', 'HARD', 2, 48),
('python-programming', 8, '第 8 章 异常处理结构与程序调试、测试', 'python-programming:8:49', '基本概念', '基本概念：异常是程序运行时的错误信号；抛出→查找处理→若无人处理则终止并打印 traceback；内置异常类层次 BaseException → Exception → (ValueError/TypeError/KeyError/IndexError/FileNotFoundError/ZeroDivisionError...)。', 'MEDIUM', 2, 49),
('python-programming', 8, '第 8 章 异常处理结构与程序调试、测试', 'python-programming:8:50', '自定义异常', '自定义异常：class MyError(Exception): pass，用语义化异常表达业务错误。', 'MEDIUM', 2, 50),
('python-programming', 8, '第 8 章 异常处理结构与程序调试、测试', 'python-programming:8:51', '四种处理结构', '四种处理结构：try...except（捕获并处理）；try...except...else（无异常才执行 else）；try...except...except（多类型分别处理，子类在前）；try...except...else...finally（finally 无论是否异常都执行，常用于释放资源）；raise 主动抛出、raise ... from ... 保留链。', 'MEDIUM', 2, 51),
('python-programming', 8, '第 8 章 异常处理结构与程序调试、测试', 'python-programming:8:52', '断言与上下文管理', '断言与上下文管理：assert 条件, 提示 用于开发期不变量检查（注意 -O 优化会禁用）；with 语句配合上下文管理器自动管理资源。', 'MEDIUM', 2, 52),
('python-programming', 8, '第 8 章 异常处理结构与程序调试、测试', 'python-programming:8:53', '调试与测试', '调试与测试：IDLE 调试器单步执行；pdb 常用命令 n(next)/s(step)/c(continue)/p 变量/l(list)/q(quit)/b(break)；单元测试 unittest（TestCase + assert 方法 + 测试发现）；文档测试 doctest；性能测试可用 timeit。', 'MEDIUM', 2, 53),
('python-programming', 8, '第 8 章 异常处理结构与程序调试、测试', 'python-programming:8:54', '易错点', '易错点：except: 裸捕获会吞掉所有异常（含 KeyboardInterrupt），应指定类型；捕获后不处理等于掩盖 bug；finally 中 return 会覆盖 try 的返回值。', 'HARD', 2, 54),
('python-programming', 9, '第 9 章 tkinter应用开发', 'python-programming:9:55', '基础', '基础：import tkinter as tk；主窗口 tk.Tk()、消息循环 mainloop()；常用组件 Label/Button/Entry/Text/Listbox/Radiobutton/Checkbutton/Scale；布局管理器 pack/grid/place（grid 最常用）。', 'EASY', 2, 55),
('python-programming', 9, '第 9 章 tkinter应用开发', 'python-programming:9:56', '事件驱动', '事件驱动：按钮 command=回调函数；bind("<Button-1>", handler) 绑定鼠标/键盘事件；回调里通过 StringVar 等变量对象同步界面与数据。', 'MEDIUM', 2, 56),
('python-programming', 9, '第 9 章 tkinter应用开发', 'python-programming:9:57', '案例', '案例：登录界面、选择类组件、简单文本编辑器、画布绘图（Canvas 画直线/圆/多边形并响应拖动）、电子时钟（after 定时刷新）、简易计算器、抽奖/猜数游戏、图片查看器（Pillow 配合）、日期选择组件。', 'MEDIUM', 2, 57),
('python-programming', 9, '第 9 章 tkinter应用开发', 'python-programming:9:58', '要点', '要点：tkinter 是标准库自带，无需安装；界面与逻辑分离、把重复组件生成写成循环，可显著减少代码量。', 'MEDIUM', 2, 58),
('python-programming', 10, '第 10 章 网络程序设计', 'python-programming:10:59', '网络基础', '网络基础：IP/端口/协议分层；socket 是网络编程统一接口；URL 与域名处理（urllib.parse）。', 'EASY', 2, 59),
('python-programming', 10, '第 10 章 网络程序设计', 'python-programming:10:60', 'UDP 编程', 'UDP 编程：无连接、报文传输；服务器 bind → recvfrom/sendto，客户端直接收发；实现简单但有丢包/乱序风险，适合查询、广播类应用。', 'MEDIUM', 2, 60),
('python-programming', 10, '第 10 章 网络程序设计', 'python-programming:10:61', 'TCP 编程', 'TCP 编程：面向连接、可靠字节流；服务器 socket → bind → listen → accept，客户端 connect；注意粘包问题（用定长/分隔符/长度前缀解决）；sendall 保证完整发送。', 'MEDIUM', 2, 61),
('python-programming', 10, '第 10 章 网络程序设计', 'python-programming:10:62', '网络编程案例', '网络编程案例：网络嗅探器、多进程端口扫描器、查看本机联网程序、IP 与 MAC 对应关系（arp 表）、局域网服务器自动发现、多线程 + socket 实现素数远程查询、TCP 长连接心跳。', 'MEDIUM', 2, 62),
('python-programming', 10, '第 10 章 网络程序设计', 'python-programming:10:63', '网页读取与爬虫', '网页读取与爬虫：requests.get(url, params=..., headers=...) 获取网页（【补充】重点库，简洁易用；配合超时、会话与异常处理）；BeautifulSoup/lxml 解析 HTML；遵守 robots.txt、控制频率、伪装 User-Agent；处理编码 r.encoding 与 JSON 接口 r.json()。', 'MEDIUM', 4, 63),
('python-programming', 10, '第 10 章 网络程序设计', 'python-programming:10:64', '易错点', '易错点：端口被占用导致 bind 失败；TCP recv 拿到的是字节流而非"一条消息"；未设置超时可能永久阻塞。', 'HARD', 2, 64),
('python-programming', 11, '第 11 章 安卓平台的Python编程', 'python-programming:11:65', 'QPython 简介', 'QPython 简介：安卓上的 Python 运行环境，内置解释器与 pip，可运行脚本、使用 SL4A 调用系统能力。', 'EASY', 2, 65),
('python-programming', 11, '第 11 章 安卓平台的Python编程', 'python-programming:11:66', '安卓应用开发案例', '安卓应用开发案例：用 QPython3/Pydroid3 编写小程序（如传感器读取、通知、二维码扫描调用），理解"移动端 Python"的适用边界（性能、权限、打包 APK 的限制）。', 'MEDIUM', 2, 66),
('python-programming', 11, '第 11 章 安卓平台的Python编程', 'python-programming:11:67', '要点', '要点：移动端以验证算法与原型为主，正式产品仍建议原生或 Kivy/ BeeWare 等框架。', 'MEDIUM', 2, 67),
('python-programming', 12, '第 12 章 Windows系统编程', 'python-programming:12:68', '注册表编程', '注册表编程：winreg 打开/创建/读写键值，操作 HKEY_CURRENT_USER/HKEY_LOCAL_MACHINE；示例：开机启动项管理、软件配置持久化。', 'MEDIUM', 2, 68),
('python-programming', 12, '第 12 章 Windows系统编程', 'python-programming:12:69', '创建可执行文件', '创建可执行文件：用 PyInstaller 打包 pyinstaller -F xxx.py 生成单文件 exe，注意隐藏控制台 -w 与图标 --icon；打包体积与启动速度权衡。', 'MEDIUM', 2, 69),
('python-programming', 12, '第 12 章 Windows系统编程', 'python-programming:12:70', '调用外部程序', '调用外部程序：os.system、subprocess.run/Popen（推荐，可捕获输出、设置超时）。', 'MEDIUM', 2, 70),
('python-programming', 12, '第 12 章 Windows系统编程', 'python-programming:12:71', '创建窗口/GUI', '创建窗口/GUI：除 tkinter 外了解 ctypes/Win32 API 调用思路（pywin32 事件查看器案例）。', 'MEDIUM', 2, 71),
('python-programming', 12, '第 12 章 Windows系统编程', 'python-programming:12:72', '系统运维', '系统运维：platform 判断操作系统版本；psutil 获取 CPU/内存/磁盘/进程信息；切换用户登录身份、计划任务与日志读取，服务化部署脚本。', 'MEDIUM', 2, 72),
('python-programming', 12, '第 12 章 Windows系统编程', 'python-programming:12:73', '易错点', '易错点：注册表路径反斜杠与 winreg 常量名；打包后路径用 sys._MEIPASS 获取资源目录；32/64 位 API 调用差异。', 'HARD', 2, 73),
('python-programming', 13, '第 13 章 多线程与多进程编程', 'python-programming:13:74', 'threading 模块', 'threading 模块：Thread(target=f, args=(...)) 创建线程，start() 启动、join() 等待；线程共享进程内存，适合 I/O 密集型任务（受 GIL 限制，CPU 密集型并行差）。', 'MEDIUM', 2, 74),
('python-programming', 13, '第 13 章 多线程与多进程编程', 'python-programming:13:75', 'Thread 对象', 'Thread 对象：daemon 守护线程随主线程退出而终止；name 便于调试。', 'MEDIUM', 2, 75),
('python-programming', 13, '第 13 章 多线程与多进程编程', 'python-programming:13:76', '线程同步', '线程同步：Lock/RLock 互斥锁保护临界区；Condition 生产者-消费者；queue.Queue 线程安全队列（生产者-消费者首选）；Event 事件通知、Semaphore/BoundedSemaphore 限流、Barrier 齐步屏障；GIL 与死锁概念。', 'MEDIUM', 2, 76),
('python-programming', 13, '第 13 章 多线程与多进程编程', 'python-programming:13:77', '多进程', '多进程：multiprocessing.Process 真并行（绕过 GIL），Pool 进程池 map 分发任务；Queue/Pipe 进程间数据交换；共享内存 Value/Array；同步原语跨进程同样可用。', 'MEDIUM', 2, 77),
('python-programming', 13, '第 13 章 多线程与多进程编程', 'python-programming:13:78', 'subprocess', 'subprocess：启动并管理外部进程（run/call/Popen），用于批量调用系统命令或可执行程序。', 'MEDIUM', 2, 78),
('python-programming', 13, '第 13 章 多线程与多进程编程', 'python-programming:13:79', '选择原则', '选择原则：I/O 密集用多线程、CPU 密集用多进程；能用队列解耦就不要手工加锁。', 'MEDIUM', 2, 79),
('python-programming', 14, '第 14 章 数据库编程', 'python-programming:14:80', 'SQLite 应用', 'SQLite 应用：sqlite3.connect(''db.sqlite3'') 建库；cursor.execute(sql, params) 参数化执行（防注入）、fetchone/fetchall/fetchmany 取结果、executemany 批处理、commit 提交事务、with conn: 自动提交/回滚；Connection 与 Cursor 对象、Row 对象按列名访问。', 'MEDIUM', 2, 80),
('python-programming', 14, '第 14 章 数据库编程', 'python-programming:14:81', '访问其他数据库', '访问其他数据库：Access（pyodbc）、MS SQL Server（pymssql/pyodbc）、MySQL（pymysql/mysql-connector）；连接方式均为"驱动 + 连接串 + 游标"三步曲；用 ORM（SQLAlchemy）可进一步解耦 SQL 与对象。', 'MEDIUM', 2, 81),
('python-programming', 14, '第 14 章 数据库编程', 'python-programming:14:82', '易错点', '易错点：拼接 SQL 字符串易注入，务必参数化；忘记 commit 导致修改丢失；游标用完要 close 或用上下文。', 'HARD', 2, 82),
('python-programming', 15, '第 15 章 多媒体编程', 'python-programming:15:83', '图形编程', '图形编程：PyOpenGL 创建窗口、绘制文字/图形、纹理映射、处理键鼠事件；理解顶点/片元着色器基本概念。', 'MEDIUM', 2, 83),
('python-programming', 15, '第 15 章 多媒体编程', 'python-programming:15:84', '图像处理 Pillow', '图像处理 Pillow：打开/裁剪/缩放/旋转/滤波/通道操作；计算椭圆中心、按比例生成饼图、生成验证码图片。', 'MEDIUM', 2, 84),
('python-programming', 15, '第 15 章 多媒体编程', 'python-programming:15:85', '音乐与语音', '音乐与语音：pygame 播放、WAV 波形处理；speech 做语音识别与合成调用。', 'MEDIUM', 2, 85),
('python-programming', 15, '第 15 章 多媒体编程', 'python-programming:15:86', '视频与摄像头', '视频与摄像头：OpenCV 读写视频、人脸检测；moviepy 剪辑拼接视频、提取音轨与生成 GIF。', 'MEDIUM', 2, 86),
('python-programming', 15, '第 15 章 多媒体编程', 'python-programming:15:87', '要点', '要点：第三方库均通过 pip 安装；处理前统一色彩空间（RGB/BGR）与尺寸。', 'MEDIUM', 2, 87),
('python-programming', 16, '第 16 章 逆向工程与软件分析', 'python-programming:16:88', '原理与边界', '原理与边界：逆向工程用于理解已有软件行为、漏洞分析与兼容性研究，应在授权范围内进行。', 'MEDIUM', 2, 88),
('python-programming', 16, '第 16 章 逆向工程与软件分析', 'python-programming:16:89', '主流项目与插件', '主流项目与插件：IDA Pro 静态反汇编/反编译；常用脚本插件自动化分析。', 'MEDIUM', 2, 89),
('python-programming', 16, '第 16 章 逆向工程与软件分析', 'python-programming:16:90', 'IDAPython 与 Immunity Debugger：IDAPython ', 'IDAPython 与 Immunity Debugger：IDAPython 编写脚本批量重命名、交叉引用分析、还原函数结构；Immunity Debugger 插件做动态调试。', 'MEDIUM', 2, 90),
('python-programming', 16, '第 16 章 逆向工程与软件分析', 'python-programming:16:91', 'Windows 调试原理', 'Windows 调试原理：调试接口、调试事件（断点、异常、加载 DLL）；进程调试、线程环境（TEB/寄存器）、硬件/软件断点实现。', 'MEDIUM', 2, 91),
('python-programming', 16, '第 16 章 逆向工程与软件分析', 'python-programming:16:92', '要点', '要点：先静态后动态、先宏观后微观；结合 PE 结构与反汇编阅读训练分析能力。', 'MEDIUM', 2, 92),
('python-programming', 17, '第 17 章 数据分析、科学计算与可视化', 'python-programming:17:93', 'NumPy', 'NumPy：ndarray 多维数组；向量化运算替代循环；广播机制、切片与布尔索引、轴（axis）概念、reshape/transpose、sum/mean/std；矩阵运算 dot/@、线性代数 linalg。', 'MEDIUM', 2, 93),
('python-programming', 17, '第 17 章 数据分析、科学计算与可视化', 'python-programming:17:94', 'SciPy 简单应用', 'SciPy 简单应用：常数与特殊函数、中值滤波去噪、多项式计算（拟合/求根）、数理统计与随机变量分布。', 'MEDIUM', 2, 94),
('python-programming', 17, '第 17 章 数据分析、科学计算与可视化', 'python-programming:17:95', 'Matplotlib 可视化', 'Matplotlib 可视化：折线图、散点图、饼图、柱状图、子图与图例、三维曲面/曲线、雷达图展示成绩；设置标题/坐标轴/注释/网格与保存图片。', 'MEDIUM', 2, 95),
('python-programming', 17, '第 17 章 数据分析、科学计算与可视化', 'python-programming:17:96', 'Pandas', 'Pandas：Series/DataFrame 为核心；读写 CSV/Excel；索引筛选（loc/iloc）、分组聚合 groupby、缺失值处理、merge/join 合并、时间序列重采样；配合 statistics 做描述统计与假设检验。', 'MEDIUM', 2, 96),
('python-programming', 17, '第 17 章 数据分析、科学计算与可视化', 'python-programming:17:97', '要点', '要点：数据分析标准流程——导入 → 清洗 → 探索（统计+可视化）→ 建模/结论；df.describe()/df.info() 快速摸底，先画图再算数。', 'MEDIUM', 2, 97),
('python-programming', 17, '第 17 章 数据分析、科学计算与可视化', 'python-programming:17:98', '易错点', '易错点：NumPy 切片是视图（共享内存），pandas 赋值链式索引告警要用 loc；浮点比较用近似；读入中文注意 encoding。', 'HARD', 2, 98),
('python-programming', 18, '第 18 章 密码学编程', 'python-programming:18:99', '安全哈希算法', '安全哈希算法：hashlib 计算 MD5/SHA 系列摘要（hashlib.sha256(data).hexdigest()）；摘要用于完整性校验、口令存储（加盐）、数字指纹。', 'MEDIUM', 2, 99),
('python-programming', 18, '第 18 章 密码学编程', 'python-programming:18:100', '对称密钥算法 DES/AES', '对称密钥算法 DES/AES：pycryptodome 的 AES.new(key, AES.MODE_ECB/CBC, iv)；加密模式（ECB/CBC/CTR）与填充、IV 的作用；对称加密速度快，适合大数据量，难点在密钥分发。', 'HARD', 2, 100),
('python-programming', 18, '第 18 章 密码学编程', 'python-programming:18:101', '非对称算法 RSA 与 DSA', '非对称算法 RSA 与 DSA：rsa 生成公私钥对、加密/解密、签名/验签；DSA 专做数字签名；非对称解决密钥交换与身份认证，速度慢故常与对称混合使用（混合加密）。', 'MEDIUM', 2, 101),
('python-programming', 18, '第 18 章 密码学编程', 'python-programming:18:102', '要点', '要点：哈希不可逆、签名抗抵赖；实际系统不要自造算法，优先使用成熟库并定期更新依赖。', 'MEDIUM', 2, 102)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('linux-ops', 1, '第 1 章 Linux 环境准备与基本操作', 'linux-ops:1:1', '实验环境与快照', '实验环境与快照：CentOS 7.x 最小化安装，2 核 CPU/2 GB 内存/20 GB 磁盘即可；动手前先打虚拟机快照，装坏了可整体回滚。统一关闭防火墙 systemctl stop firewalld && systemctl disable firewalld，并用 setenforce 0 临时、sed -i ''s/^SELINUX=enforcing/SELINUX=disabled/'' /etc/selinux/config 永久关闭 SELinux。', 'MEDIUM', 2, 1),
('linux-ops', 1, '第 1 章 Linux 环境准备与基本操作', 'linux-ops:1:2', '静态 IP 与主机名', '静态 IP 与主机名：编辑 /etc/NetworkManager/system-connections/ens33.nmconnection 写入 address1=192.168.126.101/24，执行 nmcli connection reload 与 nmcli connection up ens33 生效；再用 hostnamectl set-hostname mysql.lhp.cn 设置符合 FQDN 规范的主机名，完成后重启服务器。', 'MEDIUM', 2, 2),
('linux-ops', 1, '第 1 章 Linux 环境准备与基本操作', 'linux-ops:1:3', '目录规划与压缩解压', '目录规划与压缩解压：熟悉常见目录用途（/etc 配置、/var/lib 数据、/tmp 临时文件）；掌握 ls/cd/cp/mv/rm/mkdir 与 tar -xf，-xf 可同时解压 .tar.gz 与 .tar.xz 源码包。', 'MEDIUM', 2, 3),
('linux-ops', 2, '第 2 章 用户与权限管理【补充】', 'linux-ops:2:4', '创建系统账号', '创建系统账号：useradd -r -s /sbin/nologin mysql——-r 表示系统账号，-s 指定登录 shell；需交互登录的用 /bin/bash，仅运行服务的用 /sbin/nologin，并用 id mysql 核对 UID/GID 与所属组。', 'MEDIUM', 2, 4),
('linux-ops', 2, '第 2 章 用户与权限管理【补充】', 'linux-ops:2:5', '属主与权限位', '属主与权限位：chown -R mysql:mysql /export/server/mysql 递归修改拥有者与所属组（左用户右用户组）；权限位 rwx 对应数值 4/2/1，chmod、chgrp 用于日常授权与服务目录归属修正。', 'MEDIUM', 2, 5),
('linux-ops', 2, '第 2 章 用户与权限管理【补充】', 'linux-ops:2:6', 'root 凭据获取', 'root 凭据获取：初始化生成的临时 root 密码可用 grep password /tmp/mysqld.log | awk ''{print $NF}'' 提取保存；遗忘时借助 mysqld_safe --skip-grant-tables & 无授权模式进入重置（详见第 17 章）。', 'MEDIUM', 2, 6),
('linux-ops', 3, '第 3 章 软件包管理与 yum 源', 'linux-ops:3:7', '换源四步法', '换源四步法：先备份 mkdir -p /etc/yum.repos.d/bak && mv /etc/yum.repos.d/*.repo /etc/yum.repos.d/bak/；再 curl -o /etc/yum.repos.d/CentOS-Base.repo https://mirrors.aliyun.com/repo/Centos-7.repo 与 curl -o /etc/yum.repos.d/epel.repo https://mirrors.aliyun.com/repo/epel-7.repo；随后 yum clean all && yum makecache；最后 yum repolist 确认 base/extras/updates/epel 均为启用状态。', 'MEDIUM', 2, 7),
('linux-ops', 3, '第 3 章 软件包管理与 yum 源', 'linux-ops:3:8', 'rpm/dnf 卸载与 xargs', 'rpm/dnf 卸载与 xargs：rpm -qa | grep mariadb | xargs -r dnf remove -y——xargs -r 保证 grep 无匹配时不执行卸载；随后 [ -f /etc/my.cnf ] && rm -rf /etc/my.cnf 清理旧配置，避免冲突。', 'MEDIUM', 2, 8),
('linux-ops', 3, '第 3 章 软件包管理与 yum 源', 'linux-ops:3:9', 'Docker CE 安装五步', 'Docker CE 安装五步：yum -y install yum-utils device-mapper-persistent-data lvm2；yum-config-manager --add-repo http://mirrors.aliyun.com/docker-ce/linux/centos/docker-ce.repo；yum -y install docker-ce（生产可先 yum list docker-ce --showduplicates | sort -r 锁定版本）；systemctl enable --now docker；用 docker version、docker info 验证。', 'MEDIUM', 2, 9),
('linux-ops', 4, '第 4 章 进程与服务管理', 'linux-ops:4:10', 'systemctl 常用动作', 'systemctl 常用动作：start/stop/restart/status/enable/disable；systemctl enable --now docker 等价于启动并设为开机自启；新增或修改 unit 后必须先 systemctl daemon-reload 让 systemd 重读配置。', 'MEDIUM', 2, 10),
('linux-ops', 4, '第 4 章 进程与服务管理', 'linux-ops:4:11', 'mysqld.service 关键项', 'mysqld.service 关键项：[Unit] 中 After=network.target；[Service] 中 User=mysql Group=mysql Type=forking，ExecStart=/export/server/mysql/bin/mysqld --daemonize --pid-file=/export/server/mysql/data/mysqld.pid，TimeoutSec=600，Restart=on-failure RestartSec=5；[Install] 中 WantedBy=multi-user.target。', 'MEDIUM', 2, 11),
('linux-ops', 4, '第 4 章 进程与服务管理', 'linux-ops:4:12', '前台/后台与 kill', '前台/后台与 kill：命令后加 & 转后台，$! 取最近一个后台进程 PID，jobs 查看后台任务，kill %1 按任务序号终止；kill PID 等价 kill -15（正常结束），kill -9 强制杀死但有丢失数据的风险。', 'MEDIUM', 2, 12),
('linux-ops', 4, '第 4 章 进程与服务管理', 'linux-ops:4:13', '端口与连通排查', '端口与连通排查：用 ss -tnlp 或 netstat -tnlp 查看端口监听（如 3306）；出现 ERROR 2002 (HY000): Can''t connect to local MySQL server through socket ''/tmp/mysql.sock'' 时，依次 systemctl status mysqld、ls -l /tmp、systemctl start mysqld 定位。', 'MEDIUM', 2, 13),
('linux-ops', 5, '第 5 章 日志与磁盘管理【补充】', 'linux-ops:5:14', '服务日志与跟踪', '服务日志与跟踪：journalctl -u docker -f 实时跟踪指定服务日志；应用日志集中在 /var/log/nginx/access.log、error.log，排障时用 tail -f 边发请求边观察输出。', 'MEDIUM', 2, 14),
('linux-ops', 5, '第 5 章 日志与磁盘管理【补充】', 'linux-ops:5:15', '磁盘容量治理', '磁盘容量治理：df -h 看分区占用，du -sh 目录 定位大目录；Docker 默认存储目录 /var/lib/docker 若把根分区写满，可在 daemon.json 用 data-root 迁移到独立大盘或 LVM 逻辑卷。', 'MEDIUM', 2, 15),
('linux-ops', 5, '第 5 章 日志与磁盘管理【补充】', 'linux-ops:5:16', '日志轮转防写满', '日志轮转防写满：在 daemon.json 配置 log-opts 为 {"max-size":"100m","max-file":"3"}；MySQL 侧用 slow-query-log-file 记录慢查询 SQL，两者都是生产事故高发点的标准解法。', 'MEDIUM', 2, 16),
('linux-ops', 6, '第 6 章 Shell 脚本基础与三剑客【补充】', 'linux-ops:6:17', 'grep 检索', 'grep 检索：grep password /tmp/mysqld.log 按关键字过滤并配合管道；常用 -i 忽略大小写、-n 显示行号、-r 递归、-v 取反；支持基础正则表达式。', 'EASY', 2, 17),
('linux-ops', 6, '第 6 章 Shell 脚本基础与三剑客【补充】', 'linux-ops:6:18', 'awk 取列与 sed 替换', 'awk 取列与 sed 替换：awk ''{print $NF}'' 打印最后一列（-F 可指定分隔符）；sed -i ''s/old/new/'' file 原地替换，批量改配置时尤其高效。', 'MEDIUM', 2, 18),
('linux-ops', 6, '第 6 章 Shell 脚本基础与三剑客【补充】', 'linux-ops:6:19', '脚本骨架与退出码', '脚本骨架与退出码：首行 #!/bin/bash；if [ $? -ne 0 ];then echo 失败; exit 1; fi 做步骤校验；$() 取命令结果（如 docker rmi $(docker images -q) 批量删除镜像）；2>&1 将标准错误并入标准输出，配合 tee 同时落盘。', 'MEDIUM', 2, 19),
('linux-ops', 7, '第 7 章 网络配置与连通性排障', 'linux-ops:7:20', '网卡地址操作', '网卡地址操作：ip a 查看网卡与 IPv4/IPv6 地址；ifconfig ens32:1 192.168.229.140/24 添加子接口地址用于多站点实验；Docker 侧用 docker network create --subnet 172.20.0.0/16 --ip-range 172.20.240.0/20 zabbix-net 建自定义网桥。', 'MEDIUM', 2, 20),
('linux-ops', 7, '第 7 章 网络配置与连通性排障', 'linux-ops:7:21', 'IPv4 转发', 'IPv4 转发：容器创建报 WARNING: IPv4 forwarding is disabled. Networking will not work. 时，在 /etc/sysctl.conf 加入 net.ipv4.ip_forward = 1 并执行 sysctl -p 使转发生效。', 'MEDIUM', 2, 21),
('linux-ops', 7, '第 7 章 网络配置与连通性排障', 'linux-ops:7:22', 'OSI 与 TCP/IP 模型', 'OSI 与 TCP/IP 模型：OSI 七层为应用/表示/会话/传输/网络/数据链路/物理；TCP/IP 四层为应用（FTP、SMTP、DNS、TFTP）、传输（TCP/UDP）、网络（ICMP、IP、ARP）、网络接口。Nginx 默认工作在七层，编译加 --with-stream 后可由 stream {} 支持四层 TCP/UDP 代理。', 'MEDIUM', 2, 22),
('linux-ops', 7, '第 7 章 网络配置与连通性排障', 'linux-ops:7:23', '排障清单', '排障清单：先 ping 测连通，再 ss -tnlp 看端口监听，curl/浏览器验证服务，同时 docker logs 容器 或 tail -f access.log 看日志，逐层收敛定位。', 'MEDIUM', 2, 23),
('linux-ops', 8, '第 8 章 Docker 原理与三大核心概念', 'linux-ops:8:24', '容器的本质', '容器的本质：容器是宿主机上一组被隔离的进程。Namespace 隔离视野（PID/NET/MNT/UTS/IPC/USER/CGROUP），Cgroups 限制 CPU/内存/IO/进程数用量，UnionFS/overlay2 联合文件系统实现分层复用；容器共享宿主机内核，因此秒级启动、MB 级占用。', 'MEDIUM', 2, 24),
('linux-ops', 8, '第 8 章 Docker 原理与三大核心概念', 'linux-ops:8:25', '容器 vs 虚拟机', '容器 vs 虚拟机：启动秒级 vs 分钟级（VM 要 BIOS→引导→Guest OS）；资源几乎无损耗 vs 系统自身约 50%；硬盘 MB vs GB；单机可上千 vs 几十个；隔离性是 namespace+cgroups 的资源软隔离（内核漏洞可穿透），弱于 Hypervisor 硬件硬隔离，这是容器最大短板。', 'MEDIUM', 2, 25),
('linux-ops', 8, '第 8 章 Docker 原理与三大核心概念', 'linux-ops:8:26', '三核心概念', '三核心概念：镜像 image 是只读、分层、可复用的模板；容器 container 是镜像的运行实例，在最上层加可写层；仓库 repository 存放同一类镜像的多个版本（tag），registry 则是提供存储服务的注册服务器。', 'MEDIUM', 2, 26),
('linux-ops', 8, '第 8 章 Docker 原理与三大核心概念', 'linux-ops:8:27', '镜像名称全称', '镜像名称全称：[registry][:port]/[namespace]repo[:tag]——省略 registry 默认指向 Docker Hub，端口省略为 80，命名空间省略表示官方（library），标签省略为 latest；latest 只是默认标签名、不代表最新，生产应显式写 nginx:1.24 这类确定版本。', 'MEDIUM', 2, 27),
('linux-ops', 9, '第 9 章 Docker 安装验证与 daemon.json', 'linux-ops:9:28', 'daemon.json 四铁律', 'daemon.json 四铁律：文件是 JSON，不能写注释；最后一个字段后不能有尾逗号；改前先 cp /etc/docker/daemon.json /etc/docker/daemon.json.bak.$(date +%F) 备份；改后必须 systemctl daemon-reload + systemctl restart docker 才生效，改坏会导致 Docker 起不来。', 'MEDIUM', 2, 28),
('linux-ops', 9, '第 9 章 Docker 安装验证与 daemon.json', 'linux-ops:9:29', '高频配置字段', '高频配置字段：registry-mirrors 镜像加速器列表（最高频，解决 pull 超时）；insecure-registries 允许 HTTP/自签证书私有仓（如 ["192.168.90.250"]）；data-root 迁移镜像容器存储目录；storage-driver 选 overlay2；live-restore: true 使 dockerd 重启时容器不断；exec-opts: ["native.cgroupdriver=systemd"] 装 K8s 时必配。', 'MEDIUM', 4, 29),
('linux-ops', 9, '第 9 章 Docker 安装验证与 daemon.json', 'linux-ops:9:30', '安装后双重验证', '安装后双重验证：docker version 必须 Client 与 Server 两段都有内容；docker info 重点核对 Storage Driver、Cgroup Driver、Docker Root Dir、Registry Mirrors、Kernel Version（应与 uname -r 一致，印证共享内核）。', 'MEDIUM', 4, 30),
('linux-ops', 9, '第 9 章 Docker 安装验证与 daemon.json', 'linux-ops:9:31', '配置生效验证', '配置生效验证：执行 time docker pull nginx:alpine 实测加速；离线环境用 docker load -i busybox_latest.tgz 导入镜像后 docker images | grep busybox 确认。', 'MEDIUM', 2, 31),
('linux-ops', 10, '第 10 章 Docker 镜像管理命令', 'linux-ops:10:32', 'pull 拉取与原理', 'pull 拉取与原理：docker pull NAME[:TAG|@DIGEST]，--platform linux/amd64 可指定架构；工作原理是先从 registry 获取 manifest 清单，再按 layer 层 ID 与本地比对，只下载缺失层，输出中反复出现 Already exists 即层被复用。@DIGEST 内容摘要比 tag 可靠，但实际使用较少。', 'MEDIUM', 2, 32),
('linux-ops', 10, '第 10 章 Docker 镜像管理命令', 'linux-ops:10:33', 'images 与 tag 改名', 'images 与 tag 改名：docker images -q 只显示 IMAGE ID；列表 SIZE 是逻辑大小而非磁盘实占（多层共享会重复计入）；docker tag 源 目标 只改标签不改本体（IMAGE ID 相同），可为 push 打仓库全称、为版本管理打 prod/日期标签。', 'MEDIUM', 2, 33),
('linux-ops', 10, '第 10 章 Docker 镜像管理命令', 'linux-ops:10:34', 'inspect 查元数据', 'inspect 查元数据：docker inspect -f ''{{.Id}}'' 对象ID 查镜像内容摘要，-f ''{{.RepoTags}}'' 查所有标签；同类常用过滤还有 -f ''{{.Config.Image}}''、-f ''{{.HostConfig.RestartPolicy.Name}}''，用于批量排障。', 'MEDIUM', 2, 34),
('linux-ops', 10, '第 10 章 Docker 镜像管理命令', 'linux-ops:10:35', 'save/load 迁移镜像', 'save/load 迁移镜像：docker save -o nginx-1.24.tar nginx:1.24 导出时推荐 -o 而非 > 重定向，且引用镜像名:标签而非 IMAGE ID，否则 load 回来标签为 <none>；docker load -i nginx-1.24.tar 导入会恢复原名字与标签，同名同标签会被覆盖且不报错。', 'MEDIUM', 2, 35),
('linux-ops', 10, '第 10 章 Docker 镜像管理命令', 'linux-ops:10:36', 'rmi 删除规则', 'rmi 删除规则：镜像被容器占用（即使容器已停止）时删除报 conflict: unable to remove ... (must be forced)，需先 docker rm -f 容器 再删；一个 ID 有多个标签时按标签删只去掉标签，用 IMAGE ID 删除才是真删整个镜像；批量删除可 docker rmi $(docker images -q)。', 'MEDIUM', 2, 36),
('linux-ops', 10, '第 10 章 Docker 镜像管理命令', 'linux-ops:10:37', 'login/push/logout', 'login/push/logout：禁止匿名推送；成功推送三前置条件——已成功 login、镜像名必须是目标仓库全称（项目名/用户名+镜像名）、HTTP 私有仓需在 insecure-registries 注册；ACR 示例 echo 密码 | docker login --username=xxx registry.cn-hangzhou.cr.aliyuncs.com --password-stdin。', 'MEDIUM', 2, 37),
('linux-ops', 11, '第 11 章 Docker 容器操作命令', 'linux-ops:11:38', 'run 后台七步原理', 'run 后台七步原理：①检查本地有无该镜像，没有就自动 pull；②创建并启动容器；③分配文件系统并在镜像顶层加可写层；④从网桥接入虚拟接口对（veth pair）；⑤从地址池分配 IP；⑥执行容器入口程序；⑦程序结束容器即 Exited 状态。run = create + start。', 'MEDIUM', 2, 38),
('linux-ops', 11, '第 11 章 Docker 容器操作命令', 'linux-ops:11:39', '三个关键选项', '三个关键选项：-i 保持标准输入打开，-t 分配伪终端，-d 守护进程式后台运行（实际容器主进程是 /bin/bash）；容器主进程一结束容器就停止，因此 bash 类容器需靠 -it 持续交互维持。', 'MEDIUM', 2, 39),
('linux-ops', 11, '第 11 章 Docker 容器操作命令', 'linux-ops:11:40', '生命周期命令组', '生命周期命令组：create 仅创建需再 start；ps 看运行中容器、-a 看全部、-q 只列 ID、-l 看最后一次创建的；stop 优雅停止（Exited 137 常是超时后被强杀）、kill、restart；logs 查看输出、-f 持续跟踪。', 'MEDIUM', 2, 40),
('linux-ops', 11, '第 11 章 Docker 容器操作命令', 'linux-ops:11:41', 'exec 与 attach', 'exec 与 attach：docker exec -it 容器 /bin/bash 在运行中容器内起新进程，exit 后容器继续运行；Ctrl+p+q 退出交互但不停止容器；attach 直接连接容器主进程。', 'MEDIUM', 2, 41),
('linux-ops', 11, '第 11 章 Docker 容器操作命令', 'linux-ops:11:42', '导出导入与资源监控', '导出导入与资源监控：docker export 容器 > tar 导出文件系统（运行/停止均可），对端 cat tar | docker import - centos:exp 变成扁平的新镜像，丢失分层与标签；docker cp 本地 容器:/路径 双向拷贝；docker stats 动态资源、docker top 容器 静态进程；docker update --restart=always 容器 修改策略无需重建。', 'MEDIUM', 2, 42),
('linux-ops', 12, '第 12 章 Dockerfile 与镜像分层构建', 'linux-ops:12:43', '四段式结构', '四段式结构：FROM 基础镜像 → LABEL 维护者信息 → RUN 构建期操作（每条 RUN 一个独立层）→ CMD 容器运行时默认命令；docker build -t 名字:标签 . 末尾的 . 是构建上下文，改文件名不影响命令。', 'EASY', 2, 43),
('linux-ops', 12, '第 12 章 Dockerfile 与镜像分层构建', 'linux-ops:12:44', '分层实验结论', '分层实验结论：实验对比 v10～v14 版本得到——每个 RUN 各自成层时 yum 安装残留缓存层层保留，镜像膨胀到 791 MB；把 yum makecache && yum -y install && yum clean all 合并进同一条 RUN 后降到 539 MB，说明相关操作必须合层才能有效瘦身。', 'MEDIUM', 2, 44),
('linux-ops', 12, '第 12 章 Dockerfile 与镜像分层构建', 'linux-ops:12:45', 'history 分析', 'history 分析：docker history nginx:v14.5 的 CREATED BY 列完整展示每条指令及其对应层，SIZE 列看每层增量（0 B 多为 ENV/LABEL/EXPOSE 等元数据层），逐行排查哪一步引入了大文件。', 'MEDIUM', 2, 45),
('linux-ops', 12, '第 12 章 Dockerfile 与镜像分层构建', 'linux-ops:12:46', '实操要点', '实操要点：换源与装包写进同一 RUN——mkdir -p /etc/yum.repos.d/bak && curl -o /etc/yum.repos.d/CentOS-Base.repo https://mirrors.aliyun.com/repo/Centos-7.repo && curl -o /etc/yum.repos.d/epel.repo https://mirrors.aliyun.com/repo/epel-7.repo && yum makecache && yum -y install sl cowsay；&& 连接与续行保证缓存清理在同一层生效。', 'MEDIUM', 2, 46),
('linux-ops', 13, '第 13 章 Docker 网络与多容器编排', 'linux-ops:13:47', '自定义网络与容器互联', '自定义网络与容器互联：docker network create --subnet 172.20.0.0/16 --ip-range 172.20.240.0/20 zabbix-net；容器以 --network=zabbix-net 接入，同一网络内容器名即主机名，可直接用 DB_SERVER_HOST="mysql-server" 互相访问，无需记 IP。', 'MEDIUM', 2, 47),
('linux-ops', 13, '第 13 章 Docker 网络与多容器编排', 'linux-ops:13:48', 'Zabbix 五容器部署顺序', 'Zabbix 五容器部署顺序：①先起 mysql-server（设 MYSQL_DATABASE/USER/PASSWORD/ROOT_PASSWORD，字符集 utf8/utf8_bin，认证 mysql_native_password）→ ②zabbix-java-gateway → ③zabbix-server-mysql（暴露 10051，设 ZBX_JAVAGATEWAY=zabbix-java-gateway）→ ④zabbix-web-nginx-mysql（80 映射宿主 8080）→ ⑤zabbix-snmptraps；统一加 --restart unless-stopped。', 'MEDIUM', 2, 48),
('linux-ops', 13, '第 13 章 Docker 网络与多容器编排', 'linux-ops:13:49', '一致性要点', '一致性要点：四个 MYSQL_* 环境变量在各容器间必须完全一致，否则 server/web 连不上库；浏览器访问 http://宿主机IP（因 80 已映射到宿主 8080），容器命名建议带项目前缀便于区分与回收。', 'MEDIUM', 2, 49),
('linux-ops', 13, '第 13 章 Docker 网络与多容器编排', 'linux-ops:13:50', '端口映射格式', '端口映射格式：-p 10051:10051、-p 80:8080 均为 宿主端口:容器端口；自定义网络同时提供隔离边界，避免不同项目容器互相可达。', 'MEDIUM', 2, 50),
('linux-ops', 14, '第 14 章 Nginx 编译安装、虚拟主机与反向代理', 'linux-ops:14:51', '编译安装流程', '编译安装流程：yum -y install gcc gcc-c++ pcre pcre-devel openssl openssl-devel zlib；useradd -s /sbin/nologin nginx；wget http://nginx.org/download/nginx-1.24.0.tar.gz && tar xzf 解压；./configure --prefix=/usr/local/nginx --conf-path=/etc/nginx/nginx.conf --with-http_ssl_module --with-stream ...；make && make install；nginx -V 输出完整编译参数（-v 只显版本）。', 'MEDIUM', 2, 51),
('linux-ops', 14, '第 14 章 Nginx 编译安装、虚拟主机与反向代理', 'linux-ops:14:52', '配置文件三层结构', '配置文件三层结构：全局块（worker_processes 一般等于逻辑 CPU 数）、events 块（worker_connections 1024）、http 块（include mime.types、default_type application/octet-stream、sendfile on、keepalive_timeout 65）；http 中可配多个 server，server 中可配多个 location；指令与层级同级时次序无强制要求。', 'MEDIUM', 2, 52),
('linux-ops', 14, '第 14 章 Nginx 编译安装、虚拟主机与反向代理', 'linux-ops:14:53', '校验与启停', '校验与启停：nginx -t 测试语法、nginx -t -c 文件 指定待测文件；启动 nginx、重载 nginx -s reload、快速停止 -s stop、平滑停止 -s quit；源码安装无 systemd 单元，可用 chkconfig 管理软链 /etc/init.d/nginx（先 chmod +x，再 chkconfig --add nginx，然后 systemctl daemon-reload 重新识别）。', 'MEDIUM', 2, 53),
('linux-ops', 14, '第 14 章 Nginx 编译安装、虚拟主机与反向代理', 'linux-ops:14:54', '三种虚拟主机', '三种虚拟主机：基于域名（server_name web.yasuo.com，客户端 hosts 加 IP web.yasuo.com）；基于 IP（ifconfig ens32:1 192.168.229.140/24 建子接口后 server_name 指向该 IP）；基于端口（listen 8080，访问须带端口号）——一台机器对外提供多个站点。', 'MEDIUM', 2, 54),
('linux-ops', 14, '第 14 章 Nginx 编译安装、虚拟主机与反向代理', 'linux-ops:14:55', '反向代理配置', '反向代理配置：location / { proxy_pass http://192.168.229.140:80; proxy_set_header Host $http_host; proxy_set_header X-Real-Ip $remote_addr; proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for; proxy_connect_timeout 30; proxy_send_timeout 60; proxy_read_timeout 60; }；正向代理代理的是客户端（隐藏客户端），反向代理代理的是服务器（隐藏真实服务器集群）。', 'MEDIUM', 2, 55),
('linux-ops', 15, '第 15 章 Nginx 负载均衡、会话保持与动静分离', 'linux-ops:15:56', 'upstream 定义与算法', 'upstream 定义与算法：upstream tcpsiz { server 192.168.229.140:80 weight=1 max_fails=1 fail_timeout=60s; server ...; }，proxy_pass http://tcpsiz 中名字必须完全一致；默认轮询（ab ab）、加权 weight=2 得 abb abb、backup 标记热备机。', 'MEDIUM', 2, 56),
('linux-ops', 15, '第 15 章 Nginx 负载均衡、会话保持与动静分离', 'linux-ops:15:57', 'server 状态参数', 'server 状态参数：down 表示暂不参与转发，backup 表示仅在主节点全挂时启用，max_fails 失败次数上限（默认 1），fail_timeout 判定失败后的暂停时间并作为权重参考；健康检查靠超时计数实现。', 'MEDIUM', 2, 57),
('linux-ops', 15, '第 15 章 Nginx 负载均衡、会话保持与动静分离', 'linux-ops:15:58', '会话保持方案', '会话保持方案：ip_hash 简单但有缺陷——某后端宕机会丢失 session 且负载不均；更推荐 sticky_cookie_insert srv_id expires=1h domain=talk.yasuo.com path=/ 基于 cookie 路由，需额外编译 nginx-sticky-module，两者不可同时启用。', 'MEDIUM', 2, 58),
('linux-ops', 15, '第 15 章 Nginx 负载均衡、会话保持与动静分离', 'linux-ops:15:59', '动静分离 location', '动静分离 location：静态 location ~ .*\.(html|htm|gif|jpg|jpeg|png|bmp|swf|css|js)$ { root /zx70; proxy_pass http://jing; }，动态 location ~ .*\.(php|jsp)$ { proxy_pass http://dong; }；PHP-FPM 场景改用 fastcgi_pass 127.0.0.1:9000; fastcgi_index index.php; include fastcgi.conf; fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;。', 'MEDIUM', 2, 59),
('linux-ops', 16, '第 16 章 MySQL 8 二进制安装与配置', 'linux-ops:16:60', '二进制安装六步', '二进制安装六步：dnf -y install libaio 装异步 IO 依赖；tar -xf mysql-8.0.40-linux-glibc2.17-x86_64.tar.xz；useradd -r -s /sbin/nologin mysql；mv 到 /export/server/mysql；bin/mysqld --initialize --user=mysql --basedir=/export/server/mysql &> /tmp/mysqld.log 生成随机临时密码；bin/mysql_ssl_rsa_setup --datadir=/export/server/mysql/data 配置 SSL 加密传输。', 'MEDIUM', 2, 60),
('linux-ops', 16, '第 16 章 MySQL 8 二进制安装与配置', 'linux-ops:16:61', 'systemd 服务化', 'systemd 服务化：手写 /etc/systemd/system/mysqld.service，ExecStart 用 mysqld --daemonize --pid-file=/export/server/mysql/data/mysqld.pid，ExecStop 用 mysqladmin ... shutdown，TimeoutSec=600、Restart=on-failure；随后 systemctl daemon-reload && systemctl start mysqld && systemctl enable mysqld。', 'MEDIUM', 2, 61),
('linux-ops', 16, '第 16 章 MySQL 8 二进制安装与配置', 'linux-ops:16:62', 'my.cnf 与字符集', 'my.cnf 与字符集：[mysqld] 下配 basedir、datadir、socket=/tmp/mysql.sock、character_set_server=utf8、collation-server=utf8_unicode_ci；编码演进为 latin1→gb2312/gbk→big5→utf8→utf8mb4，中文环境务必选 utf8mb4，否则出现乱码。', 'MEDIUM', 2, 62),
('linux-ops', 16, '第 16 章 MySQL 8 二进制安装与配置', 'linux-ops:16:63', '客户端缺库处理', '客户端缺库处理：首次登录报 libncurses.so.5/libtinfo.so.5 不存在，用 ln -s /lib64/libncurses.so.6 /lib64/libncurses.so.5 和 ln -s /lib64/libtinfo.so.6 /lib64/libtinfo.so.5 建兼容软链；再把 export PATH=$PATH:/export/server/mysql/bin 写入 /etc/profile 并 source。', 'MEDIUM', 2, 63),
('linux-ops', 16, '第 16 章 MySQL 8 二进制安装与配置', 'linux-ops:16:64', '安全加固', '安全加固：执行 mysql_secure_installation 依次处理密码插件、root 密码、匿名账号、禁止 root 远程、删除 test 库、刷新权限；防火墙侧用 firewall-cmd 放行 3306/33060 后再开放业务访问。', 'MEDIUM', 2, 64),
('linux-ops', 17, '第 17 章 MySQL 账号权限、多实例与故障恢复', 'linux-ops:17:65', '账号创建与授权', '账号创建与授权：CREATE USER ''root''@''%'' IDENTIFIED BY ''123456''; GRANT ALL PRIVILEGES ON *.* TO ''root''@''%''; FLUSH PRIVILEGES;——% 代表任意主机；''root''@localhost 仅限本机；select user,host from mysql.user; 查看账号清单。', 'MEDIUM', 2, 65),
('linux-ops', 17, '第 17 章 MySQL 账号权限、多实例与故障恢复', 'linux-ops:17:66', '改密方式对比', '改密方式对比：交互式 ALTER USER ''root''@''localhost'' IDENTIFIED BY ''新密码''; flush privileges; 最安全；而 mysqladmin -uroot password ''123456'' -p 会把明文密码写入 history 日志，存在泄露风险，生产慎用。', 'MEDIUM', 2, 66),
('linux-ops', 17, '第 17 章 MySQL 账号权限、多实例与故障恢复', 'linux-ops:17:67', '登录与报错', '登录与报错：本地 mysql -uroot -p；远程 mysql -h192.168.126.101 -P3306 -uroot -p（需提前授权）；退出用 exit/quit/Ctrl+D；ERROR 1045 (28000) 为密码错误，ERROR 2002 (HY000) 为套接字/服务问题。', 'MEDIUM', 2, 67),
('linux-ops', 17, '第 17 章 MySQL 账号权限、多实例与故障恢复', 'linux-ops:17:68', '多实例部署', '多实例部署：一台服务器上跑多个端口、多个进程、多个 sock 文件；官方"单一配置文件+单一启动程序"耦合度高不推荐，实践采用"多配置文件+多启动程序"：/etc/mysql1.cnf 用 port=3306、/etc/mysql2.cnf 用 port=3307，各自独立 datadir/socket/pid-file/log-error/slow-query-log-file，innodb_buffer_pool_size=1G；连接时用 -S /export/server/mysqlN/mysqlN.sock 指定套接字。', 'MEDIUM', 2, 68),
('linux-ops', 17, '第 17 章 MySQL 账号权限、多实例与故障恢复', 'linux-ops:17:69', '忘记密码重置流程', '忘记密码重置流程：systemctl stop mysqld → mysqld_safe --skip-grant-tables &（该模式下 systemctl status 与端口均看不到属正常）→ UPDATE mysql.user SET authentication_string='''' WHERE user=''root''; FLUSH PRIVILEGES;（8.0 只允许置空）→ kill %1 → systemctl start mysqld → ALTER USER ''root''@''localhost'' IDENTIFIED BY ''新密码'';。', 'MEDIUM', 2, 69)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('secondhand-book-platform', 1, '第 1 章 项目背景与可行性分析', 'secondhand-book-platform:1:1', '痛点与目标', '痛点与目标：高校学生闲置教材与二手书存在交易需求，但缺少便捷可靠的校内渠道；本项目旨在为在校大学生提供一个方便、安全的二手书交易平台，盘活闲置资源、降低购书成本。', 'MEDIUM', 2, 1),
('secondhand-book-platform', 1, '第 1 章 项目背景与可行性分析', 'secondhand-book-platform:1:2', '价值定位', '价值定位：项目契合绿色、节约、环保的校园消费理念，既解决学生卖书难、买书贵的问题，也锻炼开发者综合运用计算机技术与软件工程技术解决实际问题的能力。', 'MEDIUM', 2, 2),
('secondhand-book-platform', 1, '第 1 章 项目背景与可行性分析', 'secondhand-book-platform:1:3', '可行性判断', '可行性判断：从市场需求（校内交易高频、跨专业跨年级流通）与技术可行性（成熟的 JavaEE 生态 + 前后端分离框架可快速落地）两方面论证，结论是项目具备实施价值，属于中小型 Web 应用范畴。', 'MEDIUM', 4, 3),
('secondhand-book-platform', 2, '第 2 章 技术选型与开发环境', 'secondhand-book-platform:2:4', '后端技术栈', '后端技术栈：以 JavaEE 企业级应用体系为核心，采用 Maven 管理依赖与构建，使用 Spring Boot 简化配置开发，SSM 中的 Spring MVC 负责 Web 层，MyBatis 作为持久层框架，运行于 JDK 1.8 与 Apache Tomcat 之上。', 'MEDIUM', 2, 4),
('secondhand-book-platform', 2, '第 2 章 技术选型与开发环境', 'secondhand-book-platform:2:5', '前端技术栈', '前端技术栈：前端三件套 HTML/CSS/JavaScript 打底，使用 Vue.js 构建单页应用，配合 Element UI、BootStrap 组件库快速搭建界面，实现前后端分离的独立开发与部署。', 'MEDIUM', 2, 5),
('secondhand-book-platform', 2, '第 2 章 技术选型与开发环境', 'secondhand-book-platform:2:6', '数据库与工具链', '数据库与工具链：数据存储选用 MySQL 8.0，图形化管理用 SQLyog；接口调试用 Apifox（兼容 Swagger/Knife4j 文档）；进阶部署涉及 CentOS + Docker + Nginx + Jenkins，监控可用 Prometheus + Grafana。', 'MEDIUM', 2, 6),
('secondhand-book-platform', 2, '第 2 章 技术选型与开发环境', 'secondhand-book-platform:2:7', '关键技术点解读', '关键技术点解读：Spring Framework 提供 IoC 容器与 AOP 面向切面能力；Spring Boot 以自动配置和起步依赖大幅降低搭建成本；MyBatis 通过映射配置把 JDBC 操作简化为接口方法调用；Maven 统一 jar 包版本与生命周期管理。', 'MEDIUM', 2, 7),
('secondhand-book-platform', 3, '第 3 章 系统架构与开发模式', 'secondhand-book-platform:3:8', '前后端分离模式', '前后端分离模式：前端 Vue 工程独立运行于 localhost:5173，后端 Spring Boot 工程运行于 localhost:8080，二者通过 HTTP 接口 + JSON 数据交互，开发、联调、部署均可解耦进行。', 'MEDIUM', 2, 8),
('secondhand-book-platform', 3, '第 3 章 系统架构与开发模式', 'secondhand-book-platform:3:9', 'MVC 与三层架构', 'MVC 与三层架构：表现层负责页面与接口接收（Vue 页面 + Controller），业务逻辑层处理规则校验与业务流程（Service），数据访问层负责与 MySQL 交互（Mapper/DAO），各层职责单一、便于维护与替换。', 'MEDIUM', 2, 9),
('secondhand-book-platform', 3, '第 3 章 系统架构与开发模式', 'secondhand-book-platform:3:10', '后端分层落地顺序', '后端分层落地顺序：标准开发路径为 实体类（Entity）→ Mapper（含 XML 映射）→ Service（业务接口与实现）→ Controller（REST 接口），自底向上逐层编写并用 Apifox 联调验证。', 'MEDIUM', 2, 10),
('secondhand-book-platform', 3, '第 3 章 系统架构与开发模式', 'secondhand-book-platform:3:11', '部署形态【补充】', '部署形态【补充】：Web 应用最终打成 jar/war 由 Tomcat 或内嵌容器承载，经 Nginx 反向代理对外提供访问，Docker 负责环境一致性封装，Jenkins 承担持续集成与自动化发布，构成完整的交付链路。', 'MEDIUM', 2, 11),
('secondhand-book-platform', 4, '第 4 章 功能模块设计', 'secondhand-book-platform:4:12', '用户身份主流程', '用户身份主流程：学生以用户身份注册并登录，登录后可浏览、搜索、查看二手书详细信息，也可发布或出售自己的闲置书籍，并在交易达成后生成订单，形成"注册→登录→浏览→发布→下单"的闭环。', 'MEDIUM', 2, 12),
('secondhand-book-platform', 4, '第 4 章 功能模块设计', 'secondhand-book-platform:4:13', '管理员端职责', '管理员端职责：管理员拥有用户管理与封禁权限，处理用户投诉与举报（含投诉类型、原因详情），并对违规内容做审核处置，保证平台内用户与商品合规。', 'MEDIUM', 2, 13),
('secondhand-book-platform', 4, '第 4 章 功能模块设计', 'secondhand-book-platform:4:14', '投诉反馈通道', '投诉反馈通道：系统提供投诉反馈机制，用户可对问题书籍或异常行为发起投诉，支持"是否允许显示投诉按钮""是否查看投诉按钮"等开关控制，实现后台可配置化处理。', 'MEDIUM', 2, 14),
('secondhand-book-platform', 4, '第 4 章 功能模块设计', 'secondhand-book-platform:4:15', '合规目标', '合规目标：通过实名认证式注册（手机号）、账号状态管理（正常/封禁）与事后监督（举报审核）相结合，确保用户身份可溯、交易过程可控、无违规内容泛滥。', 'MEDIUM', 2, 15),
('secondhand-book-platform', 5, '第 5 章 数据库设计', 'secondhand-book-platform:5:16', '用户表', '用户表：存放用户名、密码、手机号等注册凭据，并用账号状态字段区分"正常"与"封禁"，以角色字段区分普通用户与管理员，是所有业务的身份主表。', 'MEDIUM', 2, 16),
('secondhand-book-platform', 5, '第 5 章 数据库设计', 'secondhand-book-platform:5:17', '闲置二手物品表', '闲置二手物品表：存放图书名、图书价格、图书图片、图书类别、作者姓名、出版社、所属用户 id 等核心字段，支撑商品检索与详情展示；"用户 id"作为外键把商品归属到具体卖家。', 'MEDIUM', 2, 17),
('secondhand-book-platform', 5, '第 5 章 数据库设计', 'secondhand-book-platform:5:18', '订单信息表', '订单信息表：包含物品 id、订单金额、卖家 id、买家 id、收货地址、下单时间、支付时间等字段，并以订单状态标记待付款、待发货、待收货、已完成等阶段，同时记录浏览用户 id 用于行为追溯。', 'MEDIUM', 2, 18),
('secondhand-book-platform', 5, '第 5 章 数据库设计', 'secondhand-book-platform:5:19', '评论与投诉表', '评论与投诉表：二手书评论区表保存评论内容、评论时间与用户 id，实现围绕书籍的公开讨论；投诉举报管理表保存被投诉用户名、被投诉人账号状态、投诉类型、以及投诉相关按钮开关，服务于管理员审核处置。', 'MEDIUM', 2, 19),
('secondhand-book-platform', 5, '第 5 章 数据库设计', 'secondhand-book-platform:5:20', '建库实操', '建库实操：安装 MySQL 后登录，在 SQLyog 中创建名为 bookshopping 的数据库并导入上述表结构，作为整个项目持久层的起点。', 'MEDIUM', 2, 20),
('secondhand-book-platform', 6, '第 6 章 关键功能实现要点', 'secondhand-book-platform:6:21', '商品发布与上架', '商品发布与上架：用户在发布页填写图书名、价格、图片、类别、作者、出版社并关联当前登录用户 id 写入闲置二手物品表；上传图片后以 URL/路径字段存储，供列表页与详情页渲染。', 'MEDIUM', 2, 21),
('secondhand-book-platform', 6, '第 6 章 关键功能实现要点', 'secondhand-book-platform:6:22', '订单生成与状态机', '订单生成与状态机：下单时创建订单记录，写入物品 id、金额、买卖双方 id、收货地址与下单时间；后续通过支付动作回填支付时间，并沿"待付款→待发货→待收货→已完成"推进状态，状态流转需在 Service 层做校验防止跳变。', 'MEDIUM', 2, 22),
('secondhand-book-platform', 6, '第 6 章 关键功能实现要点', 'secondhand-book-platform:6:23', '多条件检索与排序', '多条件检索与排序：支持按书籍类别筛选、按价格升序/降序排序、按书名关键词模糊搜索，并支持多条件组合查询；后端一般映射为 SQL 的动态 where 条件（MyBatis <if> 标签或 Example 查询）。', 'MEDIUM', 2, 23),
('secondhand-book-platform', 6, '第 6 章 关键功能实现要点', 'secondhand-book-platform:6:24', '购物车与结算', '购物车与结算：用户可加入购物车再统一结算，结算时需做库存/在架校验并统计总价，避免对已下架或已售书籍重复下单。', 'MEDIUM', 2, 24),
('secondhand-book-platform', 6, '第 6 章 关键功能实现要点', 'secondhand-book-platform:6:25', '浏览记录与消息闭环【补充】', '浏览记录与消息闭环【补充】：系统记录浏览用户 id 用于还原"谁看过这本书"的行为轨迹；完整电商链路通常还会配套站内消息或评价提醒，把浏览、咨询、下单串成闭环。', 'MEDIUM', 2, 25),
('secondhand-book-platform', 7, '第 7 章 创新功能设计', 'secondhand-book-platform:7:26', '考研专区', '考研专区：面向考研学生设置研友评价留言、院校/专业榜单，支持点赞、收藏、分享，并在帖子中标注考研分数与个人简介描述，帮助同目标人群互相参考；同时支持发帖讨论交流。', 'EASY', 2, 26),
('secondhand-book-platform', 7, '第 7 章 创新功能设计', 'secondhand-book-platform:7:27', '专业公示模块', '专业公示模块：按专业与年级分类展示书籍信息，结合校区、毕业年份、专业名称等维度做公示，让学生快速判断某本书是否适配自己的培养方案。', 'MEDIUM', 2, 27),
('secondhand-book-platform', 7, '第 7 章 创新功能设计', 'secondhand-book-platform:7:28', '借阅与归还规则', '借阅与归还规则：在专业公示基础上扩展借阅/租赁场景，并配套归还规则管理（租期、逾期处理），用规则约束保障书籍循环使用。', 'EASY', 2, 28),
('secondhand-book-platform', 7, '第 7 章 创新功能设计', 'secondhand-book-platform:7:29', '吐槽中心', '吐槽中心：提供反馈表单，支持评分星级、分类标签、上传截图与在线提交，并可选择联系开发者，作为产品意见收集与问题上报入口。', 'MEDIUM', 2, 29),
('secondhand-book-platform', 7, '第 7 章 创新功能设计', 'secondhand-book-platform:7:30', '后台配置化创新', '后台配置化创新：管理员可在后台选择投诉类型（如违规书籍）、填写原因详情，并通过"是否允许显示投诉按钮""是否查看投诉按钮"等开关灵活控制功能，减少重复代码、提升系统复用性。', 'MEDIUM', 2, 30),
('secondhand-book-platform', 8, '第 8 章 开发流程与环境搭建', 'secondhand-book-platform:8:31', '总体开发流程', '总体开发流程：需求分析 → 系统设计 → 系统开发；开发阶段遵循"先实现基础功能、再实现高级功能"的策略，通过逐步迭代完善系统，避免一次性铺开导致进度失控。', 'EASY', 2, 31),
('secondhand-book-platform', 8, '第 8 章 开发流程与环境搭建', 'secondhand-book-platform:8:32', '数据库准备', '数据库准备：先安装并登录 MySQL，再用 SQLyog 创建 bookshopping 库并导入建表脚本，确认数据源可用后再进入编码阶段。', 'MEDIUM', 2, 32),
('secondhand-book-platform', 8, '第 8 章 开发流程与环境搭建', 'secondhand-book-platform:8:33', '后端环境准备', '后端环境准备：安装 JDK 8 → 配置 JAVA_HOME 等环境变量 → 在 IDEA 中关联该 JDK；安装 Maven → 修改 settings.xml 指向本地仓库 → 导入项目读取 pom.xml 自动下载依赖，等 IDEA 右侧依赖列表红色报错消失即就绪。', 'MEDIUM', 2, 33),
('secondhand-book-platform', 8, '第 8 章 开发流程与环境搭建', 'secondhand-book-platform:8:34', '前端环境准备', '前端环境准备：执行 npm install 安装 node_modules（前端工程没有自带依赖目录），再执行 npm run dev 启动开发服务器，浏览器访问 localhost:5173 验证页面；随后用 Apifox 导入接口文档进行前后端联调。', 'MEDIUM', 2, 34),
('secondhand-book-platform', 8, '第 8 章 开发流程与环境搭建', 'secondhand-book-platform:8:35', '编码推进顺序', '编码推进顺序：按照实体类 → Mapper → Service → Controller 自底向上实现，优先打通登录功能作为第一个纵向贯通的接口样例，再横向复制到其他业务模块。', 'MEDIUM', 2, 35),
('secondhand-book-platform', 9, '第 9 章 新手避坑、项目亮点与验收', 'secondhand-book-platform:9:36', '常见环境与依赖问题', '常见环境与依赖问题：pom.xml 依赖下载超时或失败时，改用 IDEA 自带 Maven 并配置国内镜像；前端工程报缺少模块错误时先补 npm install 生成 node_modules；后端启动报 Java 版本错误时，检查 JDK 是否为要求的 1.8。', 'MEDIUM', 2, 36),
('secondhand-book-platform', 9, '第 9 章 新手避坑、项目亮点与验收', 'secondhand-book-platform:9:37', '调试方法论', '调试方法论：修改任何配置后都要重启相应服务使配置生效；遇到崩溃先描述完整现象求助 AI 或查日志，再按"前端 → 接口 → 后端 → 数据库"逐层排查定位根因。', 'MEDIUM', 2, 37),
('secondhand-book-platform', 9, '第 9 章 新手避坑、项目亮点与验收', 'secondhand-book-platform:9:38', '复用而非照抄', '复用而非照抄：应避免盲目复制网络现成资源导致运行逻辑不清、耦合混乱；正确做法是先理解所用技术栈的运行机制，再按需裁剪整合到本项目中。', 'MEDIUM', 2, 38),
('secondhand-book-platform', 9, '第 9 章 新手避坑、项目亮点与验收', 'secondhand-book-platform:9:39', '项目亮点总结', '项目亮点总结：基于 Spring Boot + Vue 的前后端分离架构，功能完整覆盖校园二手书交易全流程，满足校园内二手书循环交易需求，契合绿色、节约、环保理念；考研专区、专业公示等特色模块形成差异化竞争力。', 'MEDIUM', 2, 39),
('secondhand-book-platform', 9, '第 9 章 新手避坑、项目亮点与验收', 'secondhand-book-platform:9:40', '验收视角【补充】', '验收视角【补充】：从需求覆盖度（功能清单逐项可演示）、数据一致性（表间外键与状态流转正确）、可用性（筛选排序与结算无误）三个维度验收，是课程设计答辩中最常被追问的方向。', 'MEDIUM', 2, 40)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('xuexitong-protocol', 1, '第 1 章 学习目标与授权边界', 'xuexitong-protocol:1:1', '先授权后研究', '先授权后研究：对任何线上系统做协议分析前，必须取得系统所有者的明确授权，并在约定的测试环境或范围内进行；未经授权抓取、复现生产环境接口，即使目的为学习也构成违规风险。', 'MEDIUM', 2, 1),
('xuexitong-protocol', 1, '第 1 章 学习目标与授权边界', 'xuexitong-protocol:1:2', '只学原理不做攻击', '只学原理不做攻击：目标是理解登录鉴权、签名校验、防重放等工作原理，从而在自建系统中正确实现同类防护，而不是复刻针对第三方的数据获取或绕过流程。', 'MEDIUM', 2, 2),
('xuexitong-protocol', 1, '第 1 章 学习目标与授权边界', 'xuexitong-protocol:1:3', '范围限定意识', '范围限定意识：把研究对象限定为自己开发或有书面授权的系统（如课程实验平台、演练靶场），形成"授权—隔离—留痕"三要素，避免触碰真实用户数据与生产业务。', 'MEDIUM', 2, 3),
('xuexitong-protocol', 2, '第 2 章 客户端—服务端鉴权基础【补充】', 'xuexitong-protocol:2:4', '账号密码与会话', '账号密码与会话：传统模式是服务端校验密码后创建 Session 并下发 SessionID（通常经 Cookie 传递），客户端后续请求凭此证明身份；会话应有超时失效与登出即废机制，防止长期有效导致被冒用。', 'MEDIUM', 2, 4),
('xuexitong-protocol', 2, '第 2 章 客户端—服务端鉴权基础【补充】', 'xuexitong-protocol:2:5', 'Token 与 JWT', 'Token 与 JWT：无状态方案把用户身份与有效期编码进 Token（JWT 由头部、载荷、签名三段 Base64URL 组成），服务端用密钥验签；其优势是无须集中存储会话，风险是签发后难以主动作废，故需配合短有效期与刷新机制。', 'MEDIUM', 2, 5),
('xuexitong-protocol', 2, '第 2 章 客户端—服务端鉴权基础【补充】', 'xuexitong-protocol:2:6', '传输安全前置', '传输安全前置：所有身份凭证必须经 HTTPS 传输，避免在明文 HTTP 中被中间人截获；App 端还应做证书绑定等加固，降低抓包分析的可行性。', 'MEDIUM', 2, 6),
('xuexitong-protocol', 2, '第 2 章 客户端—服务端鉴权基础【补充】', 'xuexitong-protocol:2:7', '凭证存储规范', '凭证存储规范：客户端不应把密码明文写入本地文件或日志，Token 应存放于受保护区域；日志输出与埋点上报都要对凭证脱敏，这是协议类项目最易忽视的泄露点。', 'MEDIUM', 2, 7),
('xuexitong-protocol', 3, '第 3 章 请求签名与防重放机制【补充】', 'xuexitong-protocol:3:8', '为什么需要签名', '为什么需要签名：仅靠账号密码只能证明"谁在请求"，无法保证报文在传输中未被篡改；签名把关键参数（路径、时间戳、请求体摘要等）与密钥一起计算，接收方验签即可发现篡改。', 'MEDIUM', 2, 8),
('xuexitong-protocol', 3, '第 3 章 请求签名与防重放机制【补充】', 'xuexitong-protocol:3:9', '常见签名构造', '常见签名构造：将参与字段按字典序拼接成串，附时间戳与随机数 nonce，再做 HMAC-SHA256 等带密钥哈希得到签名值随请求发送；服务端用同样规则重算比对，不一致即拒绝。', 'MEDIUM', 2, 9),
('xuexitong-protocol', 3, '第 3 章 请求签名与防重放机制【补充】', 'xuexitong-protocol:3:10', '时间戳防重放', '时间戳防重放：请求携带发起时刻的时间戳，服务端拒绝超出允许窗口（如 ±5 分钟）的请求，使被抓获的旧报文在窗口外失效，从时间维度阻断原样重发。', 'MEDIUM', 2, 10),
('xuexitong-protocol', 3, '第 3 章 请求签名与防重放机制【补充】', 'xuexitong-protocol:3:11', 'nonce 一次性随机数', 'nonce 一次性随机数：服务端缓存短时间内使用过的 nonce 并拒绝重复，配合时间戳使用可覆盖窗口内的重放场景；nonce 长度要足够，避免碰撞或被枚举。', 'MEDIUM', 2, 11),
('xuexitong-protocol', 3, '第 3 章 请求签名与防重放机制【补充】', 'xuexitong-protocol:3:12', '防重放的三件套', '防重放的三件套：时间戳管"过期"、nonce 管"复用"、签名管"篡改"，三者组合才能构成完整的请求完整性防护；缺一不可，单纯加签而不防重放仍可被回放。', 'MEDIUM', 2, 12),
('xuexitong-protocol', 4, '第 4 章 常见客户端接口风险【补充】', 'xuexitong-protocol:4:13', '水平越权与 IDOR', '水平越权与 IDOR：接口只按传入的用户 id、订单 id 查询数据而未校验归属关系，攻击者改一个数字就能读到他人数据；防御做法是在服务端依据会话身份二次校验资源归属。', 'MEDIUM', 2, 13),
('xuexitong-protocol', 4, '第 4 章 常见客户端接口风险【补充】', 'xuexitong-protocol:4:14', '参数篡改与逻辑绕过', '参数篡改与逻辑绕过：金额、数量、折扣等业务字段若在客户端组装且服务端不复核，极易被改；服务端必须重算关键业务值，不信任前端提交的结果。', 'MEDIUM', 2, 14),
('xuexitong-protocol', 4, '第 4 章 常见客户端接口风险【补充】', 'xuexitong-protocol:4:15', '敏感信息过度返回', '敏感信息过度返回：接口把内部字段、令牌、手机号全量返回给前端，既增加泄露面也便于攻击者理解协议；应遵循最小化返回原则并按需脱敏。', 'MEDIUM', 2, 15),
('xuexitong-protocol', 4, '第 4 章 常见客户端接口风险【补充】', 'xuexitong-protocol:4:16', '批量接口与枚举风险', '批量接口与枚举风险：分页、搜索、验证类接口若不限速，可被用于遍历与批量采集；需要通过频率限制、行为风控与异常告警加以约束。', 'MEDIUM', 2, 16),
('xuexitong-protocol', 5, '第 5 章 防护与检测机制', 'xuexitong-protocol:5:17', '分层限流', '分层限流：在网关层按 IP、账号、设备维度做速率限制（如令牌桶/滑动窗口），在业务层对高频动作加二次校验，避免单点被打爆或被脚本化枚举。', 'MEDIUM', 4, 17),
('xuexitong-protocol', 5, '第 5 章 防护与检测机制', 'xuexitong-protocol:5:18', '人机验证与风控', '人机验证与风控：对登录、短信、下载等敏感操作引入验证码、滑块或行为评分，提高自动化脚本的复用成本；同时以设备指纹、IP 归属地等信息辅助识别异常。', 'MEDIUM', 2, 18),
('xuexitong-protocol', 5, '第 5 章 防护与检测机制', 'xuexitong-protocol:5:19', '全链路审计', '全链路审计：记录关键接口的调用方、时间、参数摘要与结果，形成可追溯日志；一旦出现异常可快速定位影响范围，并为策略调优提供数据。', 'MEDIUM', 2, 19),
('xuexitong-protocol', 5, '第 5 章 防护与检测机制', 'xuexitong-protocol:5:20', '防御性设计原则', '防御性设计原则：默认拒绝（未带签名/凭证一律拒绝）、最小权限（仅开放必要接口与字段）、失败快速关闭（多次验签失败即临时封禁），把防线前移到协议入口。', 'MEDIUM', 2, 20),
('xuexitong-protocol', 6, '第 6 章 协议学习的标准方法【补充】', 'xuexitong-protocol:6:21', '先文档后抓包', '先文档后抓包：优先阅读官方开发文档或 OpenAPI 定义，建立接口清单与字段含义，再用抓包工具核对实际请求，做到"先理解再验证"，减少盲试。', 'MEDIUM', 2, 21),
('xuexitong-protocol', 6, '第 6 章 协议学习的标准方法【补充】', 'xuexitong-protocol:6:22', '抓包工具与观测点', '抓包工具与观测点：用 Charles/Fiddler/mitmproxy 等工具观察 HTTPS 请求，重点看请求头中的鉴权字段、时间戳、nonce 与签名字段，以及响应中的状态码与错误提示，归纳其变化规律。', 'MEDIUM', 4, 22),
('xuexitong-protocol', 6, '第 6 章 协议学习的标准方法【补充】', 'xuexitong-protocol:6:23', '自建的对照实验', '自建的对照实验：在自己实现的服务上复现同样的签名与防重放逻辑（如 HMAC 验签 + 时间戳窗口 + nonce 缓存），通过故意构造过期、重复、改参三类请求验证服务端是否正确拒绝，加深原理理解。', 'MEDIUM', 2, 23),
('xuexitong-protocol', 6, '第 6 章 协议学习的标准方法【补充】', 'xuexitong-protocol:6:24', '结论沉淀方式', '结论沉淀方式：以"字段—生成规则—校验逻辑—失败表现"四列表格整理每个关键接口，既可用于复习，也能直接转化为自建系统的安全需求清单。', 'MEDIUM', 2, 24),
('xuexitong-protocol', 7, '第 7 章 合规总结与学习产出', 'xuexitong-protocol:7:25', '三个明确禁止', '三个明确禁止：不抓取无授权系统、不复现针对第三方的数据获取流程、不在公共平台传播可用攻击细节；这是原文反复强调的安全底线。', 'MEDIUM', 2, 25),
('xuexitong-protocol', 7, '第 7 章 合规总结与学习产出', 'xuexitong-protocol:7:26', '可迁移的能力产出', '可迁移的能力产出：完成学习后应能说清"身份鉴别—完整性校验—防重放—访问控制—审计"这条主线，并能在自己的项目中落地签名、限流与越权校验。', 'MEDIUM', 2, 26),
('xuexitong-protocol', 7, '第 7 章 合规总结与学习产出', 'xuexitong-protocol:7:27', '能力边界认知', '能力边界认知：协议分析的目的是加固系统而非绕过系统；把学到的方法用于自查自建的客户端与服务端，才是该课程的正确产出形态。', 'MEDIUM', 2, 27)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:1', 'eNSP 软件组成', 'eNSP 软件组成：由客户端、服务端（执行引擎）、网卡、设备配置及拓扑四部分组成，设备图标有灰色（未启动）与彩色（已启动）两种状态，连线前需先启动设备。', 'MEDIUM', 2, 1),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:2', '安装与环境要求', '安装与环境要求：安装时组件可勾选；运行环境依赖 VMware 15.x 以下版本，VirtualBox 存在版本冲突需卸载；推荐 Win10/Win11；Cloud 接口用于连接真实网卡或 Wireshark。', 'MEDIUM', 2, 2),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:3', 'eNSP 工作模式', 'eNSP 工作模式：支持单机模式、网络连接模式和云模式；设备数量受 License 限制，AR/S/NE 系列、Client/Server 等节点类型不同；可通过“添加设备—连线—启动—保存”完成基本拓扑搭建。', 'MEDIUM', 2, 3),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:4', 'VRP 平台定位', 'VRP 平台定位：VRP（Versatile Routing Platform）是华为数据通信产品的统一操作系统，覆盖 AR/G/S 系列路由器与交换机，命令行采用“视图 + 命令”结构，支持分级操作与在线帮助 ?。', 'MEDIUM', 2, 4),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:5', 'VRP 三种视图', 'VRP 三种视图：用户视图 <Huawei> 用于监控与测试；系统视图 [Huawei] 用 system-view 进入，负责全局参数；接口视图用 interface GigabitEthernet 0/0/1 进入，负责接口参数；quit/return/Ctrl+Z 用于退出。', 'MEDIUM', 2, 5),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:6', '用户等级与权限', '用户等级与权限：默认 0 级（参观，仅 5 条 display 命令）、1 级（监控）、2 级（配置）、3～15 级（管理）；命令自身也带级别，可在 AAA 视图调整；未设置密码则不进行认证直接登录。', 'MEDIUM', 2, 6),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:7', '设备命名与提示符', '设备命名与提示符：sysname Huawei 修改主机名，提示符随名称改变，旧版本可能显示 <Quidway>；可通过 user-interface console 0 设置认证模式 aaa/password/simple/none 与空闲超时。', 'MEDIUM', 2, 7),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:8', '文件系统管理命令', '文件系统管理命令：pwd 查看当前目录，dir 查看文件，mkdir 建目录，copy、delete、move、rename、format 用于配置文件与系统文件的复制/删除/改名/格式化，VRP 文件系统基于 Flash。', 'MEDIUM', 2, 8),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:9', '常用维护命令', '常用维护命令：display version 看版本与 License，display current-configuration 看运行配置，display this 看当前视图配置，display interface brief 看接口状态，save 保存，reset saved-configuration 清除并重启生效。', 'MEDIUM', 2, 9),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:10', '重启与配置恢复', '重启与配置恢复：reboot 重启设备；忘记密码可在 BootROM 菜单按 B 选择 Bypass 跳过配置或清除 Console 口密码，属于带外应急手段。', 'MEDIUM', 2, 10),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:11', '网络连通性测试命令', '网络连通性测试命令：ping 支持 -c（次数）、-t（超时）、-s（报文长度）、-a（源地址）；tracert 跟踪路径；display ip interface brief 检查三层地址；display ip routing-table 检查路由表。', 'MEDIUM', 2, 11),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:12', 'DHCP 组网上机步骤', 'DHCP 组网上机步骤：在路由器接口配置 ip address dhcp-alloc 获取地址，客户端用 display dhcp lease 查看租约，常用验收命令为 display ip interface brief 与 display dhcp server statistics。', 'MEDIUM', 2, 12),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:13', 'Telnet 远程登录配置', 'Telnet 远程登录配置：telnet server enable 开启服务，AAA 视图下 local-user huawei password cipher pwd、service-type telnet、privilege level 3，再在 VTY 视图指定认证模式 aaa。', 'MEDIUM', 2, 13),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:14', 'STelnet/SSH 远程登录', 'STelnet/SSH 远程登录：ssh server-source -i 指定源接口，rsa local-key-pair create 生成本地密钥，ssh user huawei authentication-type rsa，客户端用 stelnet 192.168.1.1 首次交互指纹；只放行 SSH v2 更安全。', 'MEDIUM', 2, 14),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:15', 'Console 口默认参数', 'Console 口默认参数：速率 9600 bit/s、数据位 8、校验 None、停止位 1、流控无；eNSP 中 PC 使用 Terminal 选 COM 口连接，需注意串口号与本机映射一致。', 'MEDIUM', 2, 15),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:16', 'VRP 升级与备份', 'VRP 升级与备份：通过 FTP/TFTP/USB 上传系统文件，startup system-software xxx.cc 指定下次启动文件，升级前后均应 save 并备份配置文件，避免断电导致双文件不一致。', 'MEDIUM', 2, 16),
('hcna-ensp', 1, '第 1 章 eNSP 模拟器与 VRP 基础操作', 'hcna-ensp:1:17', '实验一验收口径', '实验一验收口径：能正确连线并启动设备、能用三种视图切换、能使用 display current-configuration 确认 sysname、ip address、Telnet/STelnet 相关配置已下发且客户端可登录。', 'MEDIUM', 2, 17),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:18', '以太网帧与编址', '以太网帧与编址：以太网使用 CSMA/CD 机制，MAC 地址 48 位（前 24 位厂商 OUI、后 24 位设备序号），帧分为单播、组播与广播；冲突域由物理介质决定，广播域由三层设备/VLAN 分割。', 'MEDIUM', 2, 18),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:19', 'VLAN 划分方式', 'VLAN 划分方式：基于端口、MAC 地址、IP 子网、协议、策略五种；工程中最常用基于端口的静态 VLAN，vlan batch 10 20 批量创建，undo vlan 10 删除。', 'MEDIUM', 2, 19),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:20', 'Access/Trunk/Hybrid 差异', 'Access/Trunk/Hybrid 差异：Access 口只属于一个 VLAN，收发不加 Tag；Trunk 口允许多个 VLAN 通过且除 PVID 外都打 Tag；Hybrid 可灵活设定 Tagged/Untagged，常用于连接终端或特殊服务器。', 'MEDIUM', 2, 20),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:21', 'VLAN 配置命令链', 'VLAN 配置命令链：vlan batch 10 20 → interface GigabitEthernet 0/0/1 → port link-type access → port default vlan 10；Trunk 侧为 port link-type trunk + port trunk allow-pass vlan 10 20；Hybrid 侧为 port hybrid tagged vlan 10 / port hybrid untagged vlan 10。', 'MEDIUM', 2, 21),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:22', 'VLAN 验收命令', 'VLAN 验收命令：display vlan 查看 VLAN 与成员端口，display port vlan 查看接口 PVID 与类型，display interface g0/0/1 查看链路 UP 与统计计数。', 'MEDIUM', 2, 22),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:23', '802.1Q Tag 结构', '802.1Q Tag 结构：在源 MAC 后插入 4 字节 Tag（TPID=0x8100，PRI 3 位、CFI 1 位、VID 12 位），VID 范围 1～4094；Access 口收到带 Tag 帧一般丢弃或与 PVID 不符时丢弃。', 'MEDIUM', 2, 23),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:24', 'STP 基本选举', 'STP 基本选举：桥 ID = 桥优先级 + 桥 MAC，先比优先级（步长 4096）再比 MAC；根桥选举完成后，非根桥选根端口（比较到根路径开销、发送者 BID、端口 ID），每个网段选指定端口。', 'MEDIUM', 2, 24),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:25', 'STP 端口角色与状态', 'STP 端口角色与状态：角色有 Root Port、Designated Port、Alternate Port；状态有 Blocking、Listening、Learning、Forwarding，Forward Delay 默认 15 秒，收敛慢是 STP 最大痛点。', 'MEDIUM', 2, 25),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:26', 'RSTP 改进', 'RSTP 改进：引入 Proposal/Agreement 快速握手，端口角色增加 Backup，边缘端口 stp edged-port enable 可直接进入转发；RSTP 向下兼容 STP，但全网必须统一模式 stp mode rstp。', 'MEDIUM', 2, 26),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:27', 'MSTP 多实例', 'MSTP 多实例：stp mode mstp 后进入 region-configuration 配置域名、修订级别 revision-level 1 与 instance 1 vlan 10、active region-configuration 激活，实现不同 VLAN 走不同生成树实例。', 'MEDIUM', 2, 27),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:28', 'STP 排障命令', 'STP 排障命令：display stp brief 查看根桥与端口角色，display stp interface g0/0/1 看状态/开销/优先级，stp root primary 指定根桥，stp priority 4096 调整优先级，stp bpdu-protection 防止边缘接入非法交换机。', 'MEDIUM', 2, 28),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:29', '链路聚合 Eth-Trunk', '链路聚合 Eth-Trunk：把多个物理口捆绑为一个逻辑口提升带宽与可靠性；手工模式 mode manual-load-balance，LACP 模式 mode lacp-static，成员口需同速率同双工；lacp preempt enable 开启抢占。', 'MEDIUM', 2, 29),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:30', 'Eth-Trunk 配置要点', 'Eth-Trunk 配置要点：interface Eth-Trunk 1 → port link-type trunk → port trunk allow-pass vlan 10 20 → 成员口 eth-trunk 1；display eth-trunk 1 查看成员端口状态，DOWN 的成员口不参与转发。', 'MEDIUM', 2, 30),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:31', 'VRRP 冗余网关', 'VRRP 冗余网关：vrrp vrid 1 virtual-ip 192.168.1.254，priority 120（默认 100），preempt-mode timer delay 5，track interface g0/0/1 reduced 30 上行链路跟踪；Master 故障时 Backup 在 Skew Time 后接管。', 'MEDIUM', 2, 31),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:32', 'DHCP Snooping', 'DHCP Snooping：dhcp snooping enable 全局开启，在信任上联口配置 dhcp snooping trusted，接入口可设 dhcp snooping max-user 1 与 dhcp snooping check dhcp-rate disable 之外的限制速率，形成绑定表供 DAI/IPSG 使用。', 'MEDIUM', 2, 32),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:33', 'GARP/GVRP 动态 VLAN', 'GARP/GVRP 动态 VLAN：全局 gvrp 开启 GVRP，接口 port gvrp 使能；注册模式 Fixed/Forbidden/Normal，可自动传播 VLAN，但现代工程更推荐静态配置以防环路。', 'MEDIUM', 2, 33),
('hcna-ensp', 2, '第 2 章 交换机基本配置与 VLAN', 'hcna-ensp:2:34', '项目二任务验收', '项目二任务验收：能完成 Telnet 配置、VLAN 划分、STP 基本配置与链路聚合四项任务；验收输出含 display vlan、display stp brief、display eth-trunk，且同一 VLAN 内 PC 可互相 ping 通。', 'MEDIUM', 2, 34),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:35', '路由器三大功能', '路由器三大功能：路由查找（构建路由表）、数据转发（最长前缀匹配）、隔广播域；接口分为 LAN 口（Ethernet/GE）与 WAN 口（Serial），带内管理走业务接口，带外管理走 Console/AUX。', 'MEDIUM', 2, 35),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:36', '静态路由配置', '静态路由配置：ip route-static 目的网段 掩码 下一跳，例如 ip route-static 10.2.1.0 255.255.255.0 10.1.1.2；缺省路由写作 ip route-static 0.0.0.0 0.0.0.0 下一跳，用于出口唯一场景。', 'MEDIUM', 2, 36),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:37', '路由优先级与管理距离', '路由优先级与管理距离：直连 0、OSPF 内部 10、IS-IS 15、静态 60、RIP 100、OSPF 外部 150；数值小者优先，可用 preference 手工调整用于浮动路由。', 'MEDIUM', 2, 37),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:38', '浮动静态路由', '浮动静态路由：同一目的网段配置两条静态路由且 preference 不同，主链路正常时只有高优先级生效；主链路失效后低优先级路由进入路由表，实现链路备份。', 'MEDIUM', 2, 38),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:39', '负载均衡前提', '负载均衡前提：多条等价路由要求目的网段与掩码完全相同、下一跳不同、优先级相同；若掩码不同则不会形成负载分担，只会形成路由分层。', 'MEDIUM', 2, 39),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:40', '路由表字段解读', '路由表字段解读：display ip routing-table 输出 Destination/Mask、Proto、Pre、Cost、NextHop、Interface；Proto 显示 Direct/Static/OSPF/RIP/BGP，NextHop 为 0.0.0.0 表示直连出接口。', 'MEDIUM', 2, 40),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:41', '最长匹配原则', '最长匹配原则：当多个表项都能匹配目的 IP 时，选择掩码最长的一条；因此缺省路由只在没有更精确路由时被使用，这是排查“明明有默认路由却不通”的关键。', 'MEDIUM', 2, 41),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:42', '单臂路由（Router-on-a-Stick）', '单臂路由（Router-on-a-Stick）：在路由器主接口下创建子接口 interface GigabitEthernet 0/0/0.1，dot1q termination vid 10，ip address 192.168.10.1 24，arp broadcast enable，实现不同 VLAN 间三层互通。', 'MEDIUM', 2, 42),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:43', '子接口验收命令', '子接口验收命令：display interface g0/0/0.1 查看子接口状态与 VLAN 终结，display ip interface brief 查看各 VLAN 网关地址，PC 网关指向对应 VLANIF/子接口地址。', 'MEDIUM', 2, 43),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:44', '基本 ACL 配置', '基本 ACL 配置：编号 2000～2999，只匹配源 IP；acl number 2000 → rule 5 permit source 192.168.1.0 0.0.0.255，rule 10 deny；通配符 0 表示严格匹配、1 表示忽略。', 'MEDIUM', 2, 44),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:45', '高级 ACL 配置', '高级 ACL 配置：编号 3000～3999，可匹配源/目的 IP、协议号、TCP/UDP 源目端口；rule permit tcp source 192.168.1.0 0.0.0.255 destination 10.1.1.0 0.0.0.255 destination-port eq 80。', 'MEDIUM', 2, 45),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:46', 'ACL 调用方向', 'ACL 调用方向：traffic-filter inbound acl 2000 与 traffic-filter outbound acl 2000 应用在接口入/出方向；标准 ACL 建议靠近目的，高级 ACL 建议靠近源以减少无效转发。', 'MEDIUM', 2, 46),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:47', 'NAT 地址池与 Easy IP', 'NAT 地址池与 Easy IP：nat address-group 1 202.1.1.1 202.1.1.10 定义地址段；Easy IP 直接在出口 nat outbound 2000（ACL 2000 匹配内网），无需地址池即可复用接口地址做 NAPT。', 'MEDIUM', 2, 47),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:48', '静态 NAT 与端口映射', '静态 NAT 与端口映射：nat static global 202.1.1.1 inside 192.168.1.10 做一对一映射；nat server protocol tcp global 202.1.1.1 8080 inside 192.168.1.10 80 发布内网 Web 服务。', 'MEDIUM', 2, 48),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:49', 'NAT 排障命令', 'NAT 排障命令：display nat session all 查看会话五元组与老化时间，display nat address-group 查看地址池利用率；内网能 ping 通外网地址但不通域名时优先检查 DNS 与 ACL 方向。', 'MEDIUM', 2, 49),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:50', 'DHCP 服务器配置', 'DHCP 服务器配置：dhcp enable → ip pool vlan10 → network 192.168.10.0 mask 24 → gateway-list 192.168.10.254 → dns-list 114.114.114.114 → excluded-ip-address 192.168.10.253 → lease day 1；接口 dhcp select global。', 'MEDIUM', 2, 50),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:51', 'DHCP 地址池验收', 'DHCP 地址池验收：display ip pool name vlan10 used 查看已分配/剩余地址比例；客户端 ipconfig /all 核对网关、DNS、租期是否与池内参数一致。', 'MEDIUM', 2, 51),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:52', 'DHCP 中继', 'DHCP 中继：跨网段场景在 VLANIF 接口 dhcp select relay，dhcp relay server-ip 10.1.1.1 指向中心 DHCP 服务器；三层设备转发 Discover 时会把giaddr 填为本接口地址。', 'MEDIUM', 2, 52),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:53', '策略路由/MQC 入门', '策略路由/MQC 入门：traffic classifier c1 + if-match acl 2000，traffic behavior b1 + redirect ip-nexthop 10.1.1.2，traffic policy p1 绑定后在接口调用，实现按源地址分流。', 'EASY', 2, 53),
('hcna-ensp', 3, '第 3 章 路由基本配置与静态路由', 'hcna-ensp:3:54', 'ICMP 与测试方法', 'ICMP 与测试方法：ping -c 4 -t 1000 目的 检查往返与丢包，tracert 目的 逐跳定位断点，display interface 看 input/output errors、CRC、 Giants，判断物理层问题。', 'MEDIUM', 2, 54),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:55', 'RIP 协议定位', 'RIP 协议定位：距离矢量路由协议，以跳数（Hop Count）为度量，最大有效跳数 15，16 视为不可达；适合小型网络，收敛速度慢于 OSPF。', 'MEDIUM', 2, 55),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:56', 'RIPv1 与 RIPv2 差异', 'RIPv1 与 RIPv2 差异：v1 是有类协议、广播更新（255.255.255.255）、不支持 VLSM/CIDR 与认证；v2 是无类协议、组播更新（224.0.0.9）、支持 VLSM/CIDR、明文/MD5 认证，实际工程统一用 version 2。', 'MEDIUM', 2, 56),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:57', 'RIP 基本配置', 'RIP 基本配置：rip 1 → version 2 → network 10.0.0.0 → network 172.16.0.0；network 只能写主类网段，undo summary 关闭自动汇总以支持不连续子网。', 'MEDIUM', 2, 57),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:58', 'RIP 邻居与接口控制', 'RIP 邻居与接口控制：广播网络默认自动发现邻居；NBMA 网络可用 peer 192.168.1.2 指定单播邻居；silent-interface 抑制不需要发送更新的接口，提高安全性。', 'MEDIUM', 2, 58),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:59', 'RIP 认证配置', 'RIP 认证配置：接口视图 rip authentication-mode md5 usual cipher Huawei@123（usual 为 RFC 2453 标准格式，simple 为明文）；两端认证模式与密钥必须一致否则无法建立邻居。', 'MEDIUM', 2, 59),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:60', 'RIP 环路避免机制', 'RIP 环路避免机制：水平分割 Split Horizon 不再把从某接口学到的路由从该接口发回；毒性逆转 Poison Reverse 把回程路由以 16 跳发回并立即触发更新；配合最大跳数 15 与抑制计时器共同防环。', 'MEDIUM', 2, 60),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:61', 'RIP 定时器', 'RIP 定时器：Update 30 秒发送完整路由表、Invalid/Timeout 180 秒标记不可达、Garbage-Collect 120 秒删除；可用 rip timer update 10 timeout 60 garbage-collect 30 加快收敛，但会增大带宽占用。', 'MEDIUM', 2, 61),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:62', 'RIP 默认路由下发', 'RIP 默认路由下发：在边界路由器 rip default-route originate 向 RIP 域内发布缺省路由；也可用 default-cost 5 调整种子度量值。', 'MEDIUM', 2, 62),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:63', 'RIP 引入与过滤', 'RIP 引入与过滤：import-route static cost 5 引入静态路由并指定开销；filter-policy export acl 2000 控制发布出去的路由，实现部分网段不外泄。', 'MEDIUM', 2, 63),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:64', 'RIP 路由汇总', 'RIP 路由汇总：在出接口 rip summary-address 10.0.0.0 255.255.0.0 对多条明细路由做 CIDR 汇总，减小对端路由表规模并降低抖动影响范围。', 'MEDIUM', 2, 64),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:65', 'RIP 排障命令', 'RIP 排障命令：display rip 1 route 查看路由来源与度量，display rip 1 database 查看数据库，display rip 1 interface 查看接口定时器与邻居，display rip 1 neighbor 确认对端。', 'MEDIUM', 2, 65),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:66', 'RIP 常见错因', 'RIP 常见错因：版本不一致（一端 v1 一端 v2）、network 声明遗漏导致接口未启用 RIP、认证密钥不一致、子网不连续且未关闭自动汇总、MTU/链路不通。', 'MEDIUM', 2, 66),
('hcna-ensp', 4, '第 4 章 RIP 路由协议', 'hcna-ensp:4:67', '实验三验收要点', '实验三验收要点：三台路由器两两可 ping 通；display rip 1 route 能看到非直连网段的 RIP 路由（Proto 为 RIP、Cost 为 1）；错误检查项包括 version 2、network 网段、authentication-mode。', 'MEDIUM', 2, 67),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:68', 'OSPF 协议定位', 'OSPF 协议定位：链路状态协议，每台路由器维护 LSDB 并用 SPF（Dijkstra）计算最短路径树；度量 Cost = 参考带宽/接口带宽，默认参考带宽 100 Mbps，bandwidth-reference 可整体调整。', 'MEDIUM', 2, 68),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:69', 'OSPF 区域与骨干', 'OSPF 区域与骨干：Area 0 为骨干区域，所有非骨干区域必须与 Area 0 直连并通过 ABR 交换 Type-3 汇总 LSA；区域划分可减少 LSDB 规模与 SPF 计算范围。', 'MEDIUM', 2, 69),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:70', 'OSPF 单区域配置', 'OSPF 单区域配置：ospf 1 router-id 1.1.1.1 → area 0 → network 10.1.1.0 0.0.0.255；router-id 需手工指定保证稳定，network 使用反掩码精确匹配接口。', 'MEDIUM', 2, 70),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:71', 'OSPF 报文类型', 'OSPF 报文类型：Hello 建立与维护邻居、DB Description 描述 LSDB 摘要、LS Request 请求缺失 LSA、LS Update 发送 LSA、LS Ack 确认；广播网络 Hello 间隔 10 s、Dead 间隔 40 s，必须两端一致。', 'MEDIUM', 2, 71),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:72', 'OSPF 邻居状态机', 'OSPF 邻居状态机：Down → Init → 2-Way → Exstart → Exchange → Loading → Full；DR/BDR 选举在 2-Way 后完成，只有 Full 状态才同步完整 LSDB。', 'MEDIUM', 2, 72),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:73', 'DR/BDR 选举规则', 'DR/BDR 选举规则：优先级范围 0～255（默认 1），0 表示不参与选举；优先级相同比较 Router ID；选举不抢占，因此调整优先级后需重置 OSPF 进程才能生效。', 'MEDIUM', 2, 73),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:74', 'DR/BDR 作用', 'DR/BDR 作用：广播与 NBMA 网络中，非 DR 路由器之间只建立 2-Way 邻接，减少 n(n-1)/2 条邻接关系为 n-1 条，降低 LSU 泛洪量。', 'MEDIUM', 2, 74),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:75', 'LSA 类型速记', 'LSA 类型速记：Type 1 Router-LSA 每台路由器产生并在区域内泛洪；Type 2 Network-LSA 由 DR 描述多路访问网段；Type 3 Summary-LSA 由 ABR 通告区域间路由；Type 4 ASBR-Summary 指向 ASBR；Type 5 External-LSA 由 ASBR 引入外部路由；Type 7 用于 NSSA。', 'MEDIUM', 2, 75),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:76', 'LSDB 查看命令', 'LSDB 查看命令：display ospf lsdb router、display ospf lsdb network、display ospf lsdb summary、display ospf lsdb asbr、display ospf lsdb ase，可按 Advertising Router 追踪路由来源。', 'MEDIUM', 2, 76),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:77', '多区域 OSPF 配置', '多区域 OSPF 配置：ABR 上同时属于 Area 0 与非骨干区域，例如 area 0 + network 10.0.12.0 0.0.0.255，area 1 + network 10.0.23.0 0.0.0.255；区域间路由以 Type-3 LSA 传递。', 'MEDIUM', 2, 77),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:78', '区域间路由汇总', '区域间路由汇总：在 ABR 执行 abr-summary 10.2.0.0 255.255.254.0 把多条区域内路由合并为一条 Type-3 LSA 发布到其他区域，减少 LSDB 与路由抖动。', 'MEDIUM', 2, 78),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:79', 'Stub 区域', 'Stub 区域：stub 阻止 Type 5 外部 LSA 进入，ABR 自动生成一条 Type 3 默认路由用于访问外部；Totally Stubby 用 stub no-summary 连 Type 3 明细也阻断，只保留默认路由。', 'MEDIUM', 2, 79),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:80', 'NSSA 区域', 'NSSA 区域：nssa 允许本区域 ASBR 引入外部路由并以 Type 7 LSA 表示，出区域时由 ABR 转换为 Type 5；default-route-advertise always type 1 向 NSSA 注入默认路由。', 'MEDIUM', 2, 80),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:81', 'Totally NSSA 配置组合', 'Totally NSSA 配置组合：nssa no-summary default-route-advertise type 1，同时阻断 Type 3 明细并由 ABR 发布默认路由；注意 Type 7 与 Type 5 转换只在 ABR 上发生。', 'MEDIUM', 2, 81),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:82', '虚链路 Virtual Link', '虚链路 Virtual Link：在 ABR 上 vlink-peer 10.0.134.3 用于修复断裂骨干或非骨干区域未直连 Area 0 的场景；虚链路属于临时方案，长期应改动物理拓扑。', 'MEDIUM', 2, 82),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:83', 'OSPF 路由引入与过滤', 'OSPF 路由引入与过滤：import-route static 引入静态路由成为外部路由；协议视图下 filter 2000 export 配合 ACL 控制对外发布的路由，filter-policy import 过滤进入路由表的域间/外部路由。', 'MEDIUM', 2, 83),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:84', 'OSPF 路由优先级与开销', 'OSPF 路由优先级与开销：preference 20 调整内部路由优先级，preference ase 50 调整外部路由优先级；接口 cost 20 type 1 手工设置开销，default-cost 10 设置 Stub 区域种子默认路由度量。', 'MEDIUM', 2, 84),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:85', 'ASBR 汇总', 'ASBR 汇总：asbr-summary 10.2.0.0 255.255.254.0 在 ASBR 上把多条外部路由汇总成一条 Type 5/Type 7 LSA 发布，降低其他区域 LSDB 体积。', 'MEDIUM', 2, 85),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:86', 'OSPF 认证', 'OSPF 认证：区域视图 authentication-mode simple cipher pwd 或 md5 1 cipher pwd；接口视图 ospf authentication-mode md5 1 cipher pwd；认证类型、密钥、密钥 ID 三要素必须两端一致。', 'MEDIUM', 2, 86),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:87', 'OSPF 排障命令', 'OSPF 排障命令：display ospf peer brief 看邻居状态与 DR 角色，display ospf error 看错误计数，display ospf interface 看网络类型/Hello/Dead/Cost，display ospf routing 看路由计算结果。', 'MEDIUM', 2, 87),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:88', '邻居无法建立的常见原因', '邻居无法建立的常见原因：Area ID 不一致、network 网段未覆盖接口、Hello/Dead 间隔不同、认证不匹配、Stub/NSSA 标志不一致、MTU 不一致、网络类型不匹配（broadcast vs P2P）。', 'MEDIUM', 2, 88),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:89', 'OSPF 选路原则', 'OSPF 选路原则：区域内路由（Intra-Area）优于区域间路由（Inter-Area），再优于 Type 1 外部路由，最后 Type 2 外部路由；同类型内按 Cost 最小选择。', 'MEDIUM', 2, 89),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:90', '官方样例配置速查（单区域）', '官方样例配置速查（单区域）：AR-1 配置 ospf 1 router-id 1.1.1.1 → area 0 → network 10.1.1.0 0.0.0.255；AR-2 配置 network 10.1.2.0 0.0.0.255 area 0，network 10.1.1.0 0.0.0.255 area 0，与真实 vrpcfg.zip 一致。', 'MEDIUM', 2, 90),
('hcna-ensp', 5, '第 5 章 OSPF 路由协议', 'hcna-ensp:5:91', '官方样例配置速查（多区域/特殊区域）', '官方样例配置速查（多区域/特殊区域）：AR-1 在 area 0 与 area 1 分别宣告；AR-3 作为 ABR 做 abr-summary 10.2.0.0 255.255.254.0；AR-5 所在区域 stub no-summary default-route-advertise type 1，用于验证 Totally Stubby。', 'MEDIUM', 2, 91),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:92', 'BGP 协议定位', 'BGP 协议定位：路径矢量（Path Vector）协议，运行于 TCP 179 端口，通过 AS_PATH、LOCAL_PREF、MED 等属性做策略路由；分为 IBGP（同 AS）与 EBGP（跨 AS）。', 'MEDIUM', 2, 92),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:93', 'BGP 邻居建立', 'BGP 邻居建立：两端均需配置 peer 对端IP as-number 对端AS，EBGP 默认要求直连且 TTL=1，非直连需 ebgp-max-hop 2；IBGP 通常用 LoopBack 接口建邻居并指定 connect-interface LoopBack0。', 'MEDIUM', 2, 93),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:94', 'BGP 基本配置模板', 'BGP 基本配置模板：bgp 65001 → router-id 1.1.1.1 → peer 1.1.1.2 as-number 65001 → ipv4-family unicast → undo synchronization → peer 1.1.1.2 enable；IBGP 向 EBGP 发路由时加 peer next-hop-local。', 'MEDIUM', 2, 94),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:95', '路由引入', '路由引入：network 10.0.0.0 255.255.255.0 精确发布一条路由（可加 exact-mask），import-route direct 引入直连，import-route ospf 引入 OSPF；BGP 只发布最优路由且不重复发布。', 'MEDIUM', 2, 95),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:96', 'BGP 路由聚合', 'BGP 路由聚合：aggregate 10.0.0.0 16 as-set detail-suppressed 生成聚合路由，as-set 保留被聚合路由的 AS 路径信息防环，detail-suppressed 抑制明细；可搭配 attribute-policy/origin-policy。', 'MEDIUM', 2, 96),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:97', 'BGP 属性分类', 'BGP 属性分类：公认强制（ORIGIN/AS_PATH/NEXT_HOP）、公认自决（LOCAL_PREF/ATOMIC_AGGREGATE）、可选过渡（AGGREGATOR/COMMUNITY）、可选非过渡（MED/CLUSTER_LIST）；LOCAL_PREF 仅在 IBGP 内有效，MED 用于影响入本 AS 的流量。', 'MEDIUM', 2, 97),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:98', 'BGP 选路规则', 'BGP 选路规则：Weight（Cisco）> LOCAL_PREF > 本地发起 > AS_PATH 长度短 > ORIGIN 类型 I < E < ? > MED 小 > EBGP 优于 IBGP > IGP 度量小 > 最老路由 > Router ID 小 > 邻居 IP 小。', 'MEDIUM', 2, 98),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:99', 'IBGP 水平分割与扩展', 'IBGP 水平分割与扩展：IBGP 内从某 IBGP 邻居学到的路由不再传给其他 IBGP 邻居，需全互连、路由反射器（Route Reflector）或联盟（Confederation）解决；课程重点掌握全互连与 RR 概念。', 'MEDIUM', 4, 99),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:100', 'BGP 定时器', 'BGP 定时器：Keepalive 60 秒、Hold Timer 180 秒，Hold 时间内未收到 Keepalive 或 Update 则断开；两端 Hold 不一致时取较小值。', 'MEDIUM', 2, 100),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:101', 'BGP 排障命令', 'BGP 排障命令：display bgp peer 查看 State 与收发报文计数，display bgp routing-table 查看 *（有效）与 >（最优）标记，display bgp routing-table statistics 看路由数量分布。', 'MEDIUM', 2, 101),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:102', '官方样例（3-1 BGP & EBGP）', '官方样例（3-1 BGP & EBGP）：R1 bgp 65001 与 R2 bgp 65002 建立 EBGP，R2/R3 之间建立 IBGP 并 peer connect-interface LoopBack0，体现“EBGP 跨 AS、IBGP 同 AS”的基本形态。', 'MEDIUM', 2, 102),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:103', '官方样例（3-2 BGP 路由聚合）', '官方样例（3-2 BGP 路由聚合）：在 ASBR/边界路由器上用 aggregate ... as-set detail-suppressed 将多条明细路由聚合成一条，验证聚合后 LSDB/路由表条目下降且明细被抑制。', 'MEDIUM', 2, 103),
('hcna-ensp', 6, '第 6 章 BGP 路由协议', 'hcna-ensp:6:104', '实验五验收要点', '实验五验收要点：R1 能 ping 通远端 PC（跨 AS）；display bgp peer 状态为 Established；display bgp routing-table 中存在带 *> 的聚合路由；若不通优先检查 peer 地址/AS 号、ipv4-family 下是否 peer enable。', 'MEDIUM', 2, 104),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:105', 'ACL 编号分段', 'ACL 编号分段：基本 ACL 2000～2999 匹配源 IP，高级 ACL 3000～3999 匹配源/目的 IP 与协议端口，二层 ACL 4000～4999 匹配 MAC/VLAN，用户自定义 ACL 5000～5999。', 'MEDIUM', 2, 105),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:106', 'ACL 规则匹配顺序', 'ACL 规则匹配顺序：按 rule ID 从小到大匹配，命中即执行；末尾隐含 deny any，需要放行流量时必须显式 rule permit；可用 step 调整步长便于插入新规则。', 'MEDIUM', 2, 106),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:107', 'ACL 应用位置', 'ACL 应用位置：traffic-filter inbound/outbound 挂在接口；也可在 VLAN 视图 traffic-filter vlan 10 outbound acl 3000；Qos/策略路由中通过 traffic classifier 引用 ACL。', 'MEDIUM', 2, 107),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:108', 'NAT 四种形态', 'NAT 四种形态：静态 NAT（一对一固定映射）、动态 NAT（地址池映射）、NAPT（多对一端口复用）、Easy IP（复用出口接口地址，无需地址池）；服务器对外发布使用 nat server。', 'MEDIUM', 2, 108),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:109', 'NAT ALG', 'NAT ALG：FTP/SIP 等协议在载荷中携带 IP/端口，需 ALG 解析并同步 NAT 映射；关闭 ALG 可能导致 FTP 数据通道无法建立，可用 display nat alg 或相应开关验证。', 'MEDIUM', 2, 109),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:110', 'AAA 体系', 'AAA 体系：Authentication（认证：local/Radius/HWTACACS）、Authorization（授权：权限级别）、Accounting（计费）；本地用户 local-user huawei password cipher pwd、privilege level 3、service-type ssh telnet terminal。', 'MEDIUM', 2, 110),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:111', '端口安全', '端口安全：port-security enable，port-security max-learn-num 1，port-security protect-action restrict，port-security mac-address sticky；违规时 restrict 告警、shutdown 端口需 error-down auto-recovery cause port-security interval 300 恢复。', 'MEDIUM', 2, 111),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:112', 'DHCP Snooping 与绑定表', 'DHCP Snooping 与绑定表：接入口非信任、上联口信任，只有信任口接受 DHCP Offer/ACK；display dhcp snooping 可查看绑定表，供 DAI/IPSG 使用，防私接小路由器与 ARP 欺骗。', 'MEDIUM', 2, 112),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:113', 'PPP 协议栈', 'PPP 协议栈：PPP 由 LCP（链路控制，协商 MRU/认证/PFC/ACFC）与 NCP（网络控制，如 IPCP 分配 IP）组成；封装对比 HDLC：HDLC 为 Cisco 私有默认封装，PPP 为标准多协议承载。', 'MEDIUM', 2, 113),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:114', 'PAP 与 CHAP 认证', 'PAP 与 CHAP 认证：PAP 两次握手、明文/密文传密码、安全性差；CHAP 三次握手、Challenge 随机挑战 + MD5 响应、周期性复验，工程默认选 CHAP。', 'MEDIUM', 2, 114),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:115', 'CHAP 配置命令', 'CHAP 配置命令：被验证端 ppp authentication-mode chap，AAA 视图 local-user hw password cipher pwd、service-type ppp；验证端 ppp chap user hw、ppp chap password cipher pwd，注意用户名/密码双向对应。', 'MEDIUM', 2, 115),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:116', 'PPPoE 会话阶段', 'PPPoE 会话阶段：Discovery 阶段包含 PADI/PADO/PADR/PADS 四步，Session 阶段承载 PPP 帧；VT 接口与 Dialer 接口配合，ip address ppp-negotiate 由 ISP 分配地址。', 'MEDIUM', 2, 116),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:117', 'PPPoE 配置命令', 'PPPoE 配置命令：aaa 下 pppoe-client dial-bundle-number 1，interface Dialer 1 → ppp chap user hw、ppp chap password cipher pwd、dialer user hw、dialer-group 1、dialer-rule 1 ip permit，物理口 pppoe-client dial-bundle-number 1。', 'MEDIUM', 2, 117),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:118', '广域网排障', '广域网排障：display ppp negotiation 看 LCP/IPCP 协商过程，display interface dialer 1 看虚拟接口状态；拨号失败常见原因包括用户名密码、拨号规则、物理口未 UP。', 'MEDIUM', 2, 118),
('hcna-ensp', 7, '第 7 章 网络安全技术与广域网技术', 'hcna-ensp:7:119', '项目六验收要点', '项目六验收要点：完成 AAA/PPP/PPPoE 配置后，客户端可通过拨号获得 IP 并访问外网；验收命令包括 display ppp negotiation、display interface dialer 1、display access-user。', 'MEDIUM', 2, 119),
('hcna-ensp', 8, '第 8 章 无线园区网与综合实训', 'hcna-ensp:8:120', 'WLAN 组网架构', 'WLAN 组网架构：FAT AP（胖 AP，独立工作）与 FIT AP + AC（瘦 AP，集中管理）两种形态；FIT AP 与 AC 之间通过 CAPWAP 隧道传输控制与数据报文，支持自动发现、配置下发与漫游。', 'MEDIUM', 2, 120),
('hcna-ensp', 8, '第 8 章 无线园区网与综合实训', 'hcna-ensp:8:121', 'SSID 与安全模板', 'SSID 与安全模板：wlan 视图下创建 ssid-profile（ssid office）、security-profile（security wpa2 psk pass-phrase Huawei@123 aes）、vap-profile（绑定 SSID/安全模板/VLAN），再在 ap-group 中按 radio 引用。', 'MEDIUM', 2, 121),
('hcna-ensp', 8, '第 8 章 无线园区网与综合实训', 'hcna-ensp:8:122', '射频与信道规划', '射频与信道规划：2.4G 常用 1/6/11 三个不重叠信道，5G 可用 36/40/44/149 等；radio-type 5G 与 channel 149 配置，AP 发射功率需与现场覆盖匹配避免同频干扰。', 'MEDIUM', 2, 122),
('hcna-ensp', 8, '第 8 章 无线园区网与综合实训', 'hcna-ensp:8:123', '直连式二层组网', '直连式二层组网：AP 与接入交换机直连，AP 管理与用户业务在同一广播域（或通过 VLAN 区分），AC 旁挂；适合小型园区，配置简单但 VLAN 数量受限。', 'MEDIUM', 2, 123),
('hcna-ensp', 8, '第 8 章 无线园区网与综合实训', 'hcna-ensp:8:124', '旁挂式三层组网', '旁挂式三层组网：AC 旁挂在汇聚/核心旁，AP 通过 CAPWAP 隧道跨三层注册（需配置 capwap source interface LoopBack0 与 Option 43/DNS 发现），实现跨网段大规模部署。', 'MEDIUM', 2, 124),
('hcna-ensp', 8, '第 8 章 无线园区网与综合实训', 'hcna-ensp:8:125', '企业网分层设计', '企业网分层设计：接入层做 VLAN 隔离与端口安全，汇聚层做 VLANIF 网关、STP 实例、链路聚合，核心层做高速转发与出口冗余；出口用 NAT+ACL 做安全与地址转换。', 'MEDIUM', 2, 125),
('hcna-ensp', 8, '第 8 章 无线园区网与综合实训', 'hcna-ensp:8:126', '冗余设计组合', '冗余设计组合：接入到汇聚双上行 + Eth-Trunk；网关用 VRRP；二层防环用 MSTP 多实例；出口双链路用浮动静态路由；任何单点故障都应能在秒级收敛。', 'MEDIUM', 2, 126),
('hcna-ensp', 8, '第 8 章 无线园区网与综合实训', 'hcna-ensp:8:127', '综合实训典型任务', '综合实训典型任务：按“核心—汇聚—接入”三层搭建拓扑，划分 VLAN 10/20/30，配置 MSTP 实例与 VRRP 主备，运行 OSPF 打通三层，边界配置 Easy IP/NAT 与高级 ACL，并开启 WLAN 放通无线用户。', 'MEDIUM', 2, 127),
('hcna-ensp', 8, '第 8 章 无线园区网与综合实训', 'hcna-ensp:8:128', '网络维护与日志', '网络维护与日志：info-center enable 与 info-center loghost 192.168.1.10 上传日志；display trapbuffer、display logbuffer 查看缓冲区；PC 端 terminal monitor/terminal debugging 打开屏幕调试输出。', 'MEDIUM', 2, 128),
('hcna-ensp', 8, '第 8 章 无线园区网与综合实训', 'hcna-ensp:8:129', '实验七验收要点', '实验七验收要点：有线 PC 与无线终端均能访问服务器与外网；验收命令包括 display vlan、display stp brief、display vrrp brief、display ospf peer brief、display nat session all 与 display capwap client 相关输出。', 'MEDIUM', 2, 129),
('hcna-ensp', 8, '第 8 章 无线园区网与综合实训', 'hcna-ensp:8:130', '考试高频记忆清单', '考试高频记忆清单：默认路由优先级 60 与静态路由比较；STP Forward Delay 15 秒；RIP 最大跳数 15；OSPF 广播 Hello 10 秒/Dead 40 秒、Cost 参考带宽 100 Mbps；BGP Keepalive 60 秒；VRRP 默认优先级 100；Trunk 两端 PVID 必须一致。', 'MEDIUM', 4, 130)
INSERT INTO study_point(course_code, chapter_no, chapter_title, point_key, title, body, difficulty, exam_weight, sort_no) VALUES
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:1', '学科定位', '学科定位：AI Systems Performance Engineering 研究模型、算法、编译器、Runtime、GPU、CPU、内存、网络、存储与调度如何协同，以更低成本稳定完成更多有效任务，而不是单个算子跑多快。', 'MEDIUM', 2, 1),
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:2', 'Goodput 定义', 'Goodput 定义：训练中只有真正推进有效进度且未因失败丢失的 Step 才算有效工作；推理中超过 SLO、失败或被取消的请求即使消耗 GPU 也不算业务 Goodput，可用 Goodput Ratio = 计算阶段时间 / 总时间近似。', 'MEDIUM', 2, 2),
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:3', 'SLO 约束容量', 'SLO 约束容量：有效容量应写成“在 P99 TTFT 与 P99 TPOT 均不超 SLO 时的最大吞吐”；原始吞吐 100 req/s 但仅 80 req/s 满足 P99 SLO 时，业务容量约 80 而非 100。', 'MEDIUM', 2, 3),
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:4', 'Little 定律', 'Little 定律：L = λW，平均在途请求数随到达率与停留时间增长；为吞吐拉长 W 会抬高 KV 占用、压缩并发并触发抢占，ρ = λ/μ 接近 1 时 P99 非线性上升。', 'MEDIUM', 2, 4),
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:5', '百分位口径', '百分位口径：在线系统报 P50（典型体验）、P90/P95（较慢请求）、P99/P99.9（尾延迟与 SLO 风险），Max 仅用于排障；99 个请求 100ms + 1 个请求 10s 的平均值约 199ms，平均值掩盖尾部。', 'MEDIUM', 2, 5),
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:6', 'Tokens/s 三种口径', 'Tokens/s 三种口径：输入吞吐反映 Prefill 工作量、输出吞吐衡量 Decode 容量、总吞吐 ≠ 输出吞吐；4096 输入/16 输出与 128 输入/512 输出的测试不可只比总数，也不能直接比较“单用户速度”“并发合计”“离线峰值”。', 'MEDIUM', 2, 6),
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:7', '训练吞吐公式', '训练吞吐公式：Training Tokens/s = B_global × S / T_step，其中 B_global = B_micro × N_data_parallel × N_grad_accumulation；TP/PP 切分的是同一模型/Batch，不能把所有 GPU 数都乘进全局样本数。', 'MEDIUM', 2, 7),
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:8', 'MFU 公式', 'MFU 公式：MFU = (F_model/token × Tokens/s) / (N_device × Peak FLOPs/device)；成立前提是 FLOPs 定义一致、Peak 对应实际主精度、稀疏/非稀疏口径一致、设备数正确、Tokens/s 为端到端稳态。', 'MEDIUM', 2, 8),
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:9', '容量规划硬数字', '容量规划硬数字：7B BF16 权重约 14GB，但全参数训练还需梯度、FP32 主权重、Adam 一阶/二阶状态与激活，混合精度 AdamW 静态状态约 104 GiB（十进制 112 GB），双 20GB 卡理想完全分片仍约 52 GiB/卡，因此双 20GB 不会被判为可行。', 'MEDIUM', 2, 9),
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:10', '平均利用率不是因果证据', '平均利用率不是因果证据：50% GPU 利用率可能来自数据加载不足、频繁小 Kernel、CPU launch gap、跨 NUMA、同步通信或采样窗口把“满载-空闲”周期平均了，必须先建跨层时间线再动参数。', 'MEDIUM', 2, 10),
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:11', '优化对象分层', '优化对象分层：内核级（Kernel、访存、Tensor Core）→ 运行时级（Python/Dispatcher/Launch、编译器、CUDA Graph）→ 服务级（批处理、KV Cache、调度）→ 集群级（拓扑、并行策略、通信重叠）→ 系统级（容量、成本、可靠性）。', 'MEDIUM', 2, 11),
('ai-perf-engineering', 1, '第 1 章 AI Systems 性能工程概述与指标体系', 'ai-perf-engineering:1:12', 'Benchmark 记录要素', 'Benchmark 记录要素：一份合格记录至少包含 GPU/CPU 型号、Compute Capability、显存、驱动/CUDA/PyTorch/Python 版本、模型与精度、Batch Size 与序列长度、输入分布、Warmup 次数、正式迭代数、同步方式、均值/中位数/P95/P99、吞吐与峰值显存。', 'MEDIUM', 2, 12),
('ai-perf-engineering', 2, '第 2 章 现代 AI 系统全栈架构与 DeepSeek 案例', 'ai-perf-engineering:2:13', '全栈五层', '全栈五层：硬件层（GPU/NVLink/网络/存储）→ 内核与库层（cuBLAS/cuDNN/FlashAttention/Triton）→ 运行时层（PyTorch/CUDA Graph/编译器）→ 框架与并行层（DP/TP/PP/ZeRO/FSDP/MoE）→ 服务与调度层（Gateway/Scheduler/KV Manager/Router）。', 'MEDIUM', 2, 13),
('ai-perf-engineering', 2, '第 2 章 现代 AI 系统全栈架构与 DeepSeek 案例', 'ai-perf-engineering:2:14', '控制面与数据面', '控制面与数据面：数据面决定单请求时延，控制面负责资源声明、调度、版本、健康检查、扩缩容与故障恢复；控制面不在每 token 热路径上，却决定系统能否稳定获得资源并维持 Goodput。', 'MEDIUM', 2, 14),
('ai-perf-engineering', 2, '第 2 章 现代 AI 系统全栈架构与 DeepSeek 案例', 'ai-perf-engineering:2:15', 'DeepSeek 五个优化动作', 'DeepSeek 五个优化动作：少算（稀疏注意力/MLA 等降低必要计算）、少存少搬（KV 压缩/复用）、算得便宜（低精度/融合）、藏起等待（通信与计算重叠）、不让最慢者拖全局（负载均衡）；本质是逐个消除瓶颈。', 'MEDIUM', 2, 15),
('ai-perf-engineering', 2, '第 2 章 现代 AI 系统全栈架构与 DeepSeek 案例', 'ai-perf-engineering:2:16', '557.6 万美元口径', '557.6 万美元口径：2.788M GPU-hours × $2/GPU-hour ≈ $5.576M，只是最终训练运行的 GPU 时间租金估算，不等于从研究到上线的完整组织成本，也不保证任何团队可按同价复现。', 'MEDIUM', 2, 16),
('ai-perf-engineering', 2, '第 2 章 现代 AI 系统全栈架构与 DeepSeek 案例', 'ai-perf-engineering:2:17', 'FlashAttention 思想', 'FlashAttention 思想：没有改变 Attention 的数学定义，只改变计算顺序与分块方式，让中间结果留在片上存储，减少 HBM 搬运——数学等价实现的真实硬件成本可以完全不同。', 'MEDIUM', 2, 17),
('ai-perf-engineering', 2, '第 2 章 现代 AI 系统全栈架构与 DeepSeek 案例', 'ai-perf-engineering:2:18', '模型规格示例', '模型规格示例：DeepSeek-V2/V3 系列采用 MLA 与 MoE，公开报告使用约 2788 万 GPU 小时完成最终训练；$R1$ 是基于 $V3$ 基座做推理 RL 与多阶段后训练的另一项工作，不能用 V3 的训练成本替代 R1。', 'MEDIUM', 2, 18),
('ai-perf-engineering', 2, '第 2 章 现代 AI 系统全栈架构与 DeepSeek 案例', 'ai-perf-engineering:2:19', '全栈瓶颈传导', '全栈瓶颈传导：Python 发不满、图频繁重编译、布局触发额外复制、cgroup 限流、PCIe 跨 NUMA、多卡通信走低带宽路径，都会让“Kernel 很快”不等于“系统很快”。', 'MEDIUM', 2, 19),
('ai-perf-engineering', 3, '第 3 章 GPU 架构深度解析', 'ai-perf-engineering:3:20', 'SM 与 Warp', 'SM 与 Warp：SM（Streaming Multiprocessor）是执行基本单位，线程块被分配到 SM 且不会拆分到多个 SM；NVIDIA 用 SIMT 组织线程，一个 Warp 通常 32 个线程共享指令流但各自拥有寄存器与控制流。', 'MEDIUM', 2, 20),
('ai-perf-engineering', 3, '第 3 章 GPU 架构深度解析', 'ai-perf-engineering:3:21', '内存层级', '内存层级：Register（线程私有，最快）→ Shared Memory/L1（单 SM、单 Block 协作，软件可控）→ L2（全 GPU 可见，跨 Block 复用与 DRAM 流量缓冲）→ GDDR/HBM（大容量高带宽但高延迟）→ Host Memory/存储。', 'MEDIUM', 2, 21),
('ai-perf-engineering', 3, '第 3 章 GPU 架构深度解析', 'ai-perf-engineering:3:22', 'Occupancy 上界', 'Occupancy 上界：忽略分配粒度时，可驻留块数的简化上界由每 SM 寄存器总数 R_SM、共享内存总量 S_SM、每线程 R_t 寄存器、每块 S_b 共享内存共同决定；最终应以 CUDA Occupancy API、编译器输出和 Nsight Compute 为准。', 'MEDIUM', 2, 22),
('ai-perf-engineering', 3, '第 3 章 GPU 架构深度解析', 'ai-perf-engineering:3:23', '资源限制诊断', '资源限制诊断：同一每块 64KB 共享内存在 100KB/SM 设备上通常只能驻留 1 块，在 164KB 或 228KB/SM 设备上可能驻留更多；nvcc --ptxas-options=-v 报告寄存器、共享内存与 spill。', 'MEDIUM', 2, 23),
('ai-perf-engineering', 3, '第 3 章 GPU 架构深度解析', 'ai-perf-engineering:3:24', '“压寄存器提 Occupancy”陷阱', '“压寄存器提 Occupancy”陷阱：从 96 个寄存器强行压到 64 个可能提高 Occupancy，但 spill 会把数据落入本地内存使 Kernel 更慢；资源调优必须以实测为裁判。', 'HARD', 2, 24),
('ai-perf-engineering', 3, '第 3 章 GPU 架构深度解析', 'ai-perf-engineering:3:25', '架构代际差异', '架构代际差异：Ampere（RTX 3080/3090、A100，CC 8.6/8.0，第三代 Tensor Core、TF32/BF16、异步全局到共享拷贝）；Hopper（H100/H200，CC 9.0，TMA、Thread Block Cluster、分布式共享内存、FP8）；Ada（RTX 4090 等）；Blackwell（FP4/NVFP4 路径）。', 'MEDIUM', 2, 25),
('ai-perf-engineering', 3, '第 3 章 GPU 架构深度解析', 'ai-perf-engineering:3:26', 'NVLink 拓扑解读', 'NVLink 拓扑解读：H100 SXM NVLink 总带宽 900 GB/s，H100 NVL 600 GB/s，GB200 NVL72 的 72-GPU 域聚合约 130 TB/s、单 GPU 量级约 1.8 TB/s；RTX 4090/RTX 5090 官方 NVLink 支持均为 No。', 'MEDIUM', 2, 26),
('ai-perf-engineering', 3, '第 3 章 GPU 架构深度解析', 'ai-perf-engineering:3:27', '拓扑命令', '拓扑命令：nvidia-smi topo -m 查看 GPU/GPU-NIC 连接类型（NV#/PIX/PXB/PHB/SYS），topo -mp 排除 NVLink 只看 PCIe 回退路径；SYS 表示跨 NUMA，单机内最需警惕。', 'MEDIUM', 2, 27),
('ai-perf-engineering', 3, '第 3 章 GPU 架构深度解析', 'ai-perf-engineering:3:28', 'NUMA 绑定', 'NUMA 绑定：GPU/NIC 挂在特定 PCIe Root/NUMA 下，DataLoader 线程在 NUMA 0 却从 NUMA 1 分配 Pinned 内存会导致跨 Socket；用 numactl --cpunodebind=0 --membind=0 python train.py 做 A/B，不要假设 NUMA 0 连 GPU 0。', 'MEDIUM', 2, 28),
('ai-perf-engineering', 4, '第 4 章 GPU Memory 体系优化', 'ai-perf-engineering:4:29', '有效带宽与算术强度', '有效带宽与算术强度：三个工程指标是有效带宽、内存访问效率和数据复用率；必须明确“相对哪个层级”计算 AI，一个对 HBM 高复用的 Kernel 仍可能受 Shared Memory 带宽或 Register 依赖限制。', 'MEDIUM', 2, 29),
('ai-perf-engineering', 4, '第 4 章 GPU Memory 体系优化', 'ai-perf-engineering:4:30', '合并访存模型', '合并访存模型：Warp 读取 32 个连续 FP32 共 128 字节，在 CC 6.0+ 常见模型中可由 4 个 32 字节事务覆盖；若每个 lane 间隔 32 字节（stride=8），会触及 32 个不同 32B 段，仍只用 128 字节却搬运 1024 字节，效率 12.5%。', 'MEDIUM', 2, 30),
('ai-perf-engineering', 4, '第 4 章 GPU Memory 体系优化', 'ai-perf-engineering:4:31', '对齐影响', '对齐影响：对连续 FP32 地址增加 4 字节偏移，可能从 4 个 segment 增至 5 个，说明对齐会改变事务数量；访存优化先保证连续与对齐，再谈并发与流水。', 'MEDIUM', 2, 31),
('ai-perf-engineering', 4, '第 4 章 GPU Memory 体系优化', 'ai-perf-engineering:4:32', 'Bank Conflict', 'Bank Conflict：Shared Memory 通常组织为 32 个 Bank，相邻 32-bit word 映射到相邻 Bank；多个 lane 访问同一 Bank 的不同地址会被拆成多次请求，多 lane 读取完全相同地址可广播。', 'MEDIUM', 2, 32),
('ai-perf-engineering', 4, '第 4 章 GPU Memory 体系优化', 'ai-perf-engineering:4:33', 'Padding 消冲突', 'Padding 消冲突：按列访问 [32][32] 时相邻线程地址相差 32 个 float，Bank 取模后可能都落到同一 Bank（32-way 冲突）；改为 [32][33] 使步长从 32 变 33，重新均匀映射到 32 个 Bank，通常可消除冲突，但会增加 Shared Memory 占用。', 'MEDIUM', 2, 33),
('ai-perf-engineering', 4, '第 4 章 GPU Memory 体系优化', 'ai-perf-engineering:4:34', 'L1/L2 策略', 'L1/L2 策略：L1/L2 由硬件管理，命中率取决于工作集、访问模式与竞争；若数据只流式读取一次，追求高 L2 命中率没有意义，此时更重要的是合并、并发和减少总字节数。', 'MEDIUM', 2, 34),
('ai-perf-engineering', 4, '第 4 章 GPU Memory 体系优化', 'ai-perf-engineering:4:35', '显存三口径', '显存三口径：memory_allocated()（存活 Tensor）≤ memory_reserved()（allocator 保留池）≤ nvidia-smi 可见占用（还含 CUDA Context、库 Workspace），三者不必相等，排查 OOM 时要同时看。', 'MEDIUM', 2, 35),
('ai-perf-engineering', 4, '第 4 章 GPU Memory 体系优化', 'ai-perf-engineering:4:36', 'Tile 大小权衡', 'Tile 大小权衡：Tile 过小复用不足，Tile 过大则 Shared Memory 与 Register 压力降低 Occupancy；最佳值需按架构、dtype、形状和 Kernel 流水扫参，不存在跨架构通用最优值。', 'MEDIUM', 2, 36),
('ai-perf-engineering', 4, '第 4 章 GPU Memory 体系优化', 'ai-perf-engineering:4:37', 'spill 与本地内存', 'spill 与本地内存：寄存器不足时编译器把值 spill 到 local memory，表现为 local load/store 增多；看到 Occupancy 上升但耗时变长，优先查 nvcc -Xptxas -v 的 spill 报告。', 'MEDIUM', 2, 37),
('ai-perf-engineering', 5, '第 5 章 Tensor Core 与低精度计算', 'ai-perf-engineering:5:38', 'Tensor Core 分工', 'Tensor Core 分工：普通 CUDA Core 处理标量/向量，Tensor Core 面向矩阵块执行 MMA（Matrix Multiply-Accumulate）；大 GEMM 被切成 Tile 层级（Thread Block Tile → Warp Tile → MMA Tile），不是一条指令完成任意大小矩阵。', 'MEDIUM', 2, 38),
('ai-perf-engineering', 5, '第 5 章 Tensor Core 与低精度计算', 'ai-perf-engineering:5:39', '低精度格式表', '低精度格式表：FP32 为 1+8+23；TF32 为 1+8+10（仅计算路径，数据仍以 FP32 存储）；BF16 为 1+8+7；FP16 为 1+5+10；FP8 E4M3 为 1+4+3、E5M2 为 1+5+2；INT8/INT4 用于量化推理。', 'MEDIUM', 2, 39),
('ai-perf-engineering', 5, '第 5 章 Tensor Core 与低精度计算', 'ai-perf-engineering:5:40', 'GEMM FLOPs', 'GEMM FLOPs：一次 M×K 乘 K×N 的浮点运算量为 2MNK；评估 Tensor Core 收益时必须先确认 GEMM 在一步中的占比，若 GEMM 只占 50%，即使 GEMM 理想加速 4 倍，Amdahl 上界也只有 1/(0.5+0.5/4) ≈ 1.6 倍。', 'MEDIUM', 2, 40),
('ai-perf-engineering', 5, '第 5 章 Tensor Core 与低精度计算', 'ai-perf-engineering:5:41', '混合精度累加', '混合精度累加：FP16/BF16 输入可使用 FP32 累加器，既提高乘法吞吐又降低长点积累计误差；不要只看 Tensor 存储 dtype，库实际选择的 MMA 指令与 accumulation mode 才决定计算路径。', 'MEDIUM', 2, 41),
('ai-perf-engineering', 5, '第 5 章 Tensor Core 与低精度计算', 'ai-perf-engineering:5:42', 'GradScaler', 'GradScaler：动态损失缩放初始 S 常取 2^16，每步检查梯度 inf/nan，溢出则 S 减半并跳过本轮更新，连续无溢出则 S 倍增；最佳实践是浮点异常次占比控制在 0.5% 以下，大 batch 建议 0.1% 以下。', 'MEDIUM', 2, 42),
('ai-perf-engineering', 5, '第 5 章 Tensor Core 与低精度计算', 'ai-perf-engineering:5:43', '精度敏感操作', '精度敏感操作：Loss 计算、Softmax（尤其 attention 内）、LayerNorm/BatchNorm、优化器更新必须保持 FP32，可用 autocast(enabled=False) 包裹；裁剪必须先 unscale_() 再裁剪。', 'MEDIUM', 2, 43),
('ai-perf-engineering', 5, '第 5 章 Tensor Core 与低精度计算', 'ai-perf-engineering:5:44', 'TF32 零改动加速', 'TF32 零改动加速：torch.backends.cuda.matmul.allow_tf32 = True 可在 Ampere+ 上加速 FP32 GEMM/Conv，A100 上对 FP32 可提速 10–20 倍，但它不省显存，只改变计算路径。', 'MEDIUM', 2, 44),
('ai-perf-engineering', 5, '第 5 章 Tensor Core 与低精度计算', 'ai-perf-engineering:5:45', 'FP8 不是简单 .to(float8)', 'FP8 不是简单 .to(float8)：FP8 有限范围要求缩放与 Amax 管理，前向/反向可能使用 E4M3/E5M2 不同格式；Transformer Engine 为受支持模块管理配方、scale、量化缓存与高性能 Kernel。', 'MEDIUM', 2, 45),
('ai-perf-engineering', 5, '第 5 章 Tensor Core 与低精度计算', 'ai-perf-engineering:5:46', 'FlashAttention 收益', 'FlashAttention 收益：标准 Attention 的 IO 复杂度为 O(N²) HBM 读写，FlashAttention 通过分块与在线 Softmax 降低约 M 倍（M 为 SRAM 大小），seq 1K–4K 端到端 2.4 倍、GPT-2 上 3 倍；v2 优化非 MatMul 开销，v3 为 Hopper 专用利用 TMA/WGMMA。', 'MEDIUM', 2, 46),
('ai-perf-engineering', 6, '第 6 章 NVLink/NVSwitch 与 AI 集群互联', 'ai-perf-engineering:6:47', 'NVLink vs PCIe', 'NVLink vs PCIe：PCIe Gen5 x16 单向上行约 64 GB/s，而 H100 SXM NVLink 聚合带宽 900 GB/s，量级差十倍以上；TP 每层都有 All-Reduce，无 NVLink 时 Decode 小粒度同步会显著伤害 TPOT。', 'MEDIUM', 2, 47),
('ai-perf-engineering', 6, '第 6 章 NVLink/NVSwitch 与 AI 集群互联', 'ai-perf-engineering:6:48', 'NVSwitch 直连域', 'NVSwitch 直连域：H100 8-GPU 系统中 4 个第二代 NVSwitch 把 GPU 两两全互连，任意一对最大双向链路带宽 900 GB/s；GB200 NVL72 用 5 代 NVSwitch 的 72-GPU 域聚合单向带宽约 130 TB/s。', 'MEDIUM', 2, 48),
('ai-perf-engineering', 6, '第 6 章 NVLink/NVSwitch 与 AI 集群互联', 'ai-perf-engineering:6:49', '消费卡现实', '消费卡现实：RTX 4090 官方 NVLink = No，双 4090 做 TP 的 All-Reduce 只能走 PCIe，通信占比高；RTX 3090 存在特定双卡 NVLink 配置，但不可假定，必须 nvidia-smi topo -m 实测。', 'MEDIUM', 2, 49),
('ai-perf-engineering', 6, '第 6 章 NVLink/NVSwitch 与 AI 集群互联', 'ai-perf-engineering:6:50', '拓扑路径语义', '拓扑路径语义：topo -m 中 NV# = 经 NVSwitch 直连（最佳）；PIX = 同 PCIe Bridge、PXB = 跨 Bridge 但不跨 Root Complex、PHB = 跨 Root/NUMA、SYS = 最慢跨 Socket；NVLink 优先于 PCIe，拓扑决定 NCCL 选路。', 'MEDIUM', 2, 50),
('ai-perf-engineering', 6, '第 6 章 NVLink/NVSwitch 与 AI 集群互联', 'ai-perf-engineering:6:51', '多机网络选型', '多机网络选型：InfiniBand NDR 单端口 400 Gb/s、四端口聚合 1600 Gb/s；RoCE v2 可在融合以太网承载 RDMA 但需无损 PFC/ECN 配置；CPU 侧 PCIe Gen5 x16 理论 128 GB/s、实测单向约 110–120 GB/s，应用吞吐受 NIC/Counterpart/协议栈共同影响。', 'MEDIUM', 2, 51),
('ai-perf-engineering', 6, '第 6 章 NVLink/NVSwitch 与 AI 集群互联', 'ai-perf-engineering:6:52', '控制面扩展性', '控制面扩展性：从 8 到 64 GPU 常遇到 Node/Pod 数量、NIC/QoS、etcd/API 延迟、网关、DNS、监控写入、故障检测和参数更新互相牵制；先定 SLO、可接受变更窗口和失败域，再谈机器数。', 'MEDIUM', 2, 52),
('ai-perf-engineering', 6, '第 6 章 NVLink/NVSwitch 与 AI 集群互联', 'ai-perf-engineering:6:53', '不要静态切分容量', '不要静态切分容量：大 Batch 期望收益高但预热慢、扰动大，多任务竞争同一批资源时应按优先级/期限调度，冷启动需要单独容量池；固定比例预留只在稳定任务下成立。', 'MEDIUM', 2, 53),
('ai-perf-engineering', 7, '第 7 章 Linux、Docker 与 Kubernetes GPU 性能优化', 'ai-perf-engineering:7:54', '内核与固件', '内核与固件：先记录内核版本、NVIDIA 驱动、CUDA、IOMMU/VT-d、Above 4G Decoding、Resizable BAR、ECC 状态与 BIOS 版本；生产内禁用所有非必要内核模块，关闭 watchdog/kdump/审计，BIOS 设性能模式并禁用 C-state/P-state。', 'MEDIUM', 2, 54),
('ai-perf-engineering', 7, '第 7 章 Linux、Docker 与 Kubernetes GPU 性能优化', 'ai-perf-engineering:7:55', 'GPU 常驻与 ECC', 'GPU 常驻与 ECC：nvidia-smi -pm 1 开启 Persistence Mode，减少反复初始化 GPU 的开销；若数据为唯一副本或日志未归档，应关闭 ECC；若训练数据来自分布式对象存储等可靠来源且结果丢失代价大于一次重跑，可开 ECC 换可靠性。', 'MEDIUM', 2, 55),
('ai-perf-engineering', 7, '第 7 章 Linux、Docker 与 Kubernetes GPU 性能优化', 'ai-perf-engineering:7:56', '时钟看有效频率', '时钟看有效频率：高请求功率不等于 Kernel 更快，温度墙、电压/功耗限制会触达持续降频；A/B 比较必须同时报告请求功率、稳态温度、每 SM 频率、应用/SM 活动、dram 频率与有效带宽，按有效带宽校正后再比每步时间。', 'MEDIUM', 2, 56),
('ai-perf-engineering', 7, '第 7 章 Linux、Docker 与 Kubernetes GPU 性能优化', 'ai-perf-engineering:7:57', 'NUMA 绑定证据链', 'NUMA 绑定证据链：当多个 Kernel 共享 Cache 流量时，即使请求功率略高也可能用更少时间完成；绑定前后必须给出每步时间差、GPU/Kernel 时间差、HBM 或 L2 流量差、Host→GPU Pinned 内存分配位置与 Socket/NIC/GPU PCIe 拓扑差。', 'MEDIUM', 2, 57),
('ai-perf-engineering', 7, '第 7 章 Linux、Docker 与 Kubernetes GPU 性能优化', 'ai-perf-engineering:7:58', '中断与页缓存', '中断与页缓存：cat /proc/interrupts 看分布，irqbalance 排除目标 CPU，用 smp_affinity_list 绑定 GPU NIC MSI-X；内存用 ulimit -l unlimited、alwaysmadvise 或 Explicit HugeTLB，禁止 THP defer+defrag 引起停顿。', 'MEDIUM', 2, 58),
('ai-perf-engineering', 7, '第 7 章 Linux、Docker 与 Kubernetes GPU 性能优化', 'ai-perf-engineering:7:59', '透明大页', '透明大页：THP madvise/defer+defrag 会把部分停顿换成分配延迟、锁竞争与碎片；对延迟敏感负载建议关闭 THP、预分配显式大页并把绑定前后 Kernel 时间差写入报告。', 'MEDIUM', 2, 59),
('ai-perf-engineering', 7, '第 7 章 Linux、Docker 与 Kubernetes GPU 性能优化', 'ai-perf-engineering:7:60', '容器隔离项', '容器隔离项：Docker/Kubernetes 至少隔离 GPU、CPU 核、内存上限、PCIe 带宽、磁盘 IOPS/带宽、网络 QoS；不要同时叠加 K8s limits、cgroup quota 与应用信号量，三层分别限流会造成“三层互相抵消”。', 'MEDIUM', 2, 60),
('ai-perf-engineering', 7, '第 7 章 Linux、Docker 与 Kubernetes GPU 性能优化', 'ai-perf-engineering:7:61', '多任务 GPU 隔离手段', '多任务 GPU 隔离手段：MIG 把 A100/H100 切成最多 7 个硬件隔离实例，配合 Device Plugin + SingleRootIOVirtualizationSupport/DynamicResourceAllocation 暴露给 K8s；多个可空间复用的任务可用 Time Slicing，按时间片轮转而非独占。', 'MEDIUM', 2, 61),
('ai-perf-engineering', 7, '第 7 章 Linux、Docker 与 Kubernetes GPU 性能优化', 'ai-perf-engineering:7:62', '资源模型陷阱', '资源模型陷阱：K8s 一个 Pod 声明 2 张卡、节点共 8 张时，未必能同时部署 4 个该 Pod，因为显存、NVLink、CPU、NIC 可能先耗尽；容量核算必须把并行度、CPU 预留、GPU-NIC 亲和写进约束。', 'HARD', 2, 62),
('ai-perf-engineering', 7, '第 7 章 Linux、Docker 与 Kubernetes GPU 性能优化', 'ai-perf-engineering:7:63', '可观测性口径', '可观测性口径：常用 DCGM 指标含 SM Clock、SM Active、DRAM Active、Tx/Rx、PCIe Replay Counter、GPU Util、Memory Used、Tensor Active；DCGM_FI_PROF_* 用于 profile 阶段 SM Activity/Tensor/Precision Active、L2 Cache/DRAM Throughput，不能拿 Profiling Counter 直接汇总成长任务均值。', 'MEDIUM', 2, 63),
('ai-perf-engineering', 7, '第 7 章 Linux、Docker 与 Kubernetes GPU 性能优化', 'ai-perf-engineering:7:64', '文件系统与元数据', '文件系统与元数据：本地 NVMe 做热数据、NFS/Ceph 做冷数据/检查点；使用 noatime, nodiratime；Ceph 挂载在 Tune Pod Profile 中避免 dirty pages 失控，Checkpoint 合并小文件会引发元数据风暴。', 'MEDIUM', 2, 64),
('ai-perf-engineering', 8, '第 8 章 CUDA 编程模型', 'ai-perf-engineering:8:65', '线程层级', '线程层级：Thread（最小执行单元）→ Warp（通常 32 线程，SIMT 执行，分歧会序列化）→ Block（可协作，分配到同一 SM，含 blockDim/blockIdx）→ Grid（所有 Block，含 gridDim）；Kernel 以 __global__ 定义并用 kernel<<<grid, block>>>(...) 启动。', 'MEDIUM', 2, 65),
('ai-perf-engineering', 8, '第 8 章 CUDA 编程模型', 'ai-perf-engineering:8:66', '访存层级编程', '访存层级编程：Register/Shared Memory 由程序员显式管理（__shared__、__syncthreads()），Global Memory 用 cudaMalloc/cudaMemcpy 或异步 cudaMemcpyAsync，Unified Memory 用 cudaMallocManaged 由运行时迁移页面。', 'MEDIUM', 2, 66),
('ai-perf-engineering', 8, '第 8 章 CUDA 编程模型', 'ai-perf-engineering:8:67', 'Warp 分歧', 'Warp 分歧：同一 Warp 内 if/else 分支不同会导致两条路径串行执行（mask），避免按 lane 走完全不同路径；循环长度不一致也会造成尾部分歧。', 'MEDIUM', 2, 67),
('ai-perf-engineering', 8, '第 8 章 CUDA 编程模型', 'ai-perf-engineering:8:68', '原子操作', '原子操作：atomicAdd 等可用于无锁累加，但同一地址高争用会序列化；应先在 Shared Memory 聚合再每 Block 一次 atomic。', 'MEDIUM', 2, 68),
('ai-perf-engineering', 8, '第 8 章 CUDA 编程模型', 'ai-perf-engineering:8:69', 'Stream 与 Event', 'Stream 与 Event：同一 Stream 内顺序执行，多 Stream 可并发；cudaEventRecord/cudaEventSynchronize/cudaEventElapsedTime 测 GPU 时间；用 cudaStreamWaitEvent 做依赖而不阻塞 Host。', 'MEDIUM', 2, 69),
('ai-perf-engineering', 8, '第 8 章 CUDA 编程模型', 'ai-perf-engineering:8:70', '零拷贝与锁页', '零拷贝与锁页：cudaHostAlloc(..., cudaHostAllocMapped) 支持映射主机内存供 GPU 直接访问（PCIe 上带宽有限）；cudaHostAllocDefault | cudaHostAllocPortable 锁页内存让 cudaMemcpyAsync 真正异步。', 'MEDIUM', 2, 70),
('ai-perf-engineering', 8, '第 8 章 CUDA 编程模型', 'ai-perf-engineering:8:71', 'CUDA Graph 基础', 'CUDA Graph 基础：先用 Stream Capture 捕获一段 Kernel/内存操作序列，cudaGraphInstantiate 生成可重放实例，cudaGraphLaunch 一次提交；将多次 Launch 的 CPU 开销从微秒级降到亚微秒，要求输入输出指针稳定并使用独立内存池。', 'EASY', 2, 71),
('ai-perf-engineering', 8, '第 8 章 CUDA 编程模型', 'ai-perf-engineering:8:72', '错误处理', '错误处理：每次调用后检查 cudaError_t，用 cudaGetLastError() 取 Kernel 启动错误；cudaDeviceSynchronize() 后的错误才代表异步 Kernel 执行失败。', 'MEDIUM', 2, 72),
('ai-perf-engineering', 8, '第 8 章 CUDA 编程模型', 'ai-perf-engineering:8:73', 'Kernel 设计原则', 'Kernel 设计原则：让相邻线程读相邻地址、减少 Bank Conflict、控制每线程寄存器与 Shared 用量以提高 Occupancy、用 Tile 复用减少 HBM 字节数，最后用 Nsight Compute 验证而非凭直觉调优。', 'MEDIUM', 2, 73),
('ai-perf-engineering', 8, '第 8 章 CUDA 编程模型', 'ai-perf-engineering:8:74', 'CUDA Kernel 优化实验口径', 'CUDA Kernel 优化实验口径：对比 vectorAdd 与 sgemm，固定网格规模、矩阵大小、数据类型与迭代次数，报告耗时、GFLOPS、问题规模、HBM/L2 带宽；每个候选实现都要有多次迭代分布、峰值 SM 时钟、散热状态与与基线的差异百分比。', 'MEDIUM', 2, 74),
('ai-perf-engineering', 9, '第 9 章 GPU Memory 访问优化', 'ai-perf-engineering:9:75', '有效带宽定义', '有效带宽定义：有效带宽 = 算法在单位时间内必须从该层级搬运的最小字节数 ÷ 达到的时间；必须先区分算法与 Kernel 实现真正搬了多少字节，用“假设连续、对齐”估算理想字节数，再看实测有效带宽是否接近峰值。', 'MEDIUM', 2, 75),
('ai-perf-engineering', 9, '第 9 章 GPU Memory 访问优化', 'ai-perf-engineering:9:76', 'Bank Conflict 量化', 'Bank Conflict 量化：按列访问 [32][32] 使相邻线程地址相差 32 个 float，Bank 取模后落入同一 Bank，32-way 冲突把 Shared Memory 访问放大 32 倍；改为 [32][33] 后步长 33 与 32 互质，通常消除冲突。', 'MEDIUM', 2, 76),
('ai-perf-engineering', 9, '第 9 章 GPU Memory 访问优化', 'ai-perf-engineering:9:77', '合并访问量化', '合并访问量化：Warp 读取 32 个连续 FP32（128B）在 CC 6.0+ 由 4 个 32B 事务覆盖；stride=8（间隔 32B）触及 32 个不同段、搬运 1024B 只用 128B，效率 12.5%，是访存优化最典型的坏模式。', 'MEDIUM', 2, 77),
('ai-perf-engineering', 9, '第 9 章 GPU Memory 访问优化', 'ai-perf-engineering:9:78', 'Hopper 异步拷贝', 'Hopper 异步拷贝：TMA/cp.async.bulk 可在 Global→Shared 传输时让线程继续计算，双缓冲流水线隐藏延迟；写 Kernel 时要保证 TMA 描述符、Swizzle 布局与 Sync Barrier 正确，否则会比同步拷贝更慢。', 'MEDIUM', 2, 78),
('ai-perf-engineering', 9, '第 9 章 GPU Memory 访问优化', 'ai-perf-engineering:9:79', '带宽与并行度', '带宽与并行度：单个线程难以打满 HBM 带宽，需要足够多的并发请求；提高 Occupancy、向量化加载（float4/int4）、多个 outstanding load 都是手段，但需权衡寄存器压力。', 'MEDIUM', 2, 79),
('ai-perf-engineering', 9, '第 9 章 GPU Memory 访问优化', 'ai-perf-engineering:9:80', '减少搬运量的手段', '减少搬运量的手段：数据复用（Tile/分块）、压缩（INT8/FP8/FP4）、驻留（KV Cache/Prefix Cache）、缓存（Prefix Caching）、减少 Padding 与重算（Chunked Prefill）——本质都是降低必须经过内存系统的字节数。', 'MEDIUM', 2, 80),
('ai-perf-engineering', 9, '第 9 章 GPU Memory 访问优化', 'ai-perf-engineering:9:81', 'AI 诊断', 'AI 诊断：算术强度 AI = FLOPs / Bytes；当 AI 小于峰值 FLOPs 与峰值带宽之比时为 memory-bound，此时再提升算力无效，只有降低字节数或提高实际带宽才有收益。', 'MEDIUM', 2, 81),
('ai-perf-engineering', 9, '第 9 章 GPU Memory 访问优化', 'ai-perf-engineering:9:82', 'Roofline 使用', 'Roofline 使用：把 Kernel 的 AI 与实测性能画在 Roofline 上，落在带宽屋顶下方说明带宽受限，落在计算屋顶附近说明算力受限；报告时必须标明所用峰值是理论值还是 microbenchmark 实测值。', 'MEDIUM', 2, 82),
('ai-perf-engineering', 9, '第 9 章 GPU Memory 访问优化', 'ai-perf-engineering:9:83', '实验二验收要点', '实验二验收要点：vectorAdd 的 GFLOPS 很低属正常（AI≈2），重点看是否合并访存；sgemm 要报告 tile 大小、shared memory 复用策略与 bank conflict 处理，且所有候选实现都在相同 warmup/迭代数下测量。', 'MEDIUM', 4, 83),
('ai-perf-engineering', 10, '第 10 章 GPU 性能分析方法与 Kernel Fusion、Triton', 'ai-perf-engineering:10:84', '三件套工具链', '三件套工具链：Nsight Systems 看端到端时间线、Kernel/通信/CPU Gap；Nsight Compute 看单 Kernel 指令吞吐、Warp Stall、Memory Workload Analysis；PyTorch Profiler + TensorBoard 负责算子级归因与 NVTX 区间。', 'MEDIUM', 2, 84),
('ai-perf-engineering', 10, '第 10 章 GPU 性能分析方法与 Kernel Fusion、Triton', 'ai-perf-engineering:10:85', '采集纪律', '采集纪律：基线与候选保持输入形状、随机种子、精度和正确性标准一致；设置 Warmup、迭代次数、功率/温度窗口、采集范围；一次只改一个变量，并注明 OS、GPU/驱动、CUDA、PyTorch/Python、编译参数与环境变量。', 'MEDIUM', 2, 85),
('ai-perf-engineering', 10, '第 10 章 GPU 性能分析方法与 Kernel Fusion、Triton', 'ai-perf-engineering:10:86', '五步定位法', '五步定位法：①以 Step 为单位找长 Operator/Gap；②按 Module 与 Kernel Name 聚合，判断长 Gap 是否在 DataLoader/Copy/Prefetch/Save；③看 CUDA API Launch 分布与 CPU 时间；④用 NCU 核对数据指标而非只看代码逻辑；⑤排除尾部采样与突发初始化噪声后给出复现结论。', 'MEDIUM', 2, 86),
('ai-perf-engineering', 10, '第 10 章 GPU 性能分析方法与 Kernel Fusion、Triton', 'ai-perf-engineering:10:87', '指标优先级', '指标优先级：先看 SM Busy / SM Occupancy / Memory Throughput / DRAM Throughput，再看 Duration、Warp Cycles Per Issued Instruction、Stall Breakdown；NCU 中的 Tensor Core Pipe 只有在 Hopper/Ada/Blackwell 上才有物理意义，Volta/Turing 报告不要把 Tensor Pipe 当主指标。', 'MEDIUM', 2, 87),
('ai-perf-engineering', 10, '第 10 章 GPU 性能分析方法与 Kernel Fusion、Triton', 'ai-perf-engineering:10:88', 'Phase 划分', 'Phase 划分：训练中通过 NVTX/Span 明确 Split Data、Fetch Batch、Forward、Backward、Optimizer、Checkpoint 等阶段；GPU Queue 只反映任务提交是否及时，不揭示 Forward/Backward 内部哪些 Kernel 在等待、被重复计算或被调度延迟打断。', 'MEDIUM', 2, 88),
('ai-perf-engineering', 10, '第 10 章 GPU 性能分析方法与 Kernel Fusion、Triton', 'ai-perf-engineering:10:89', '融合收益评估', '融合收益评估：以 Transformer 的 elementwise 链为例，3 个小 Kernel 各读一次输入产生约 6×M×B 字节流量，融合为 1 个 Kernel 只产生约 2×M×B 字节（减少约 2/3）；但融合不能自动带来并行、寄存器和 Tensor Core 流水改善，需专门写清原逐元素算子、融后等效算子、支持的最大 batch 及实测曲线。', 'MEDIUM', 2, 89),
('ai-perf-engineering', 10, '第 10 章 GPU 性能分析方法与 Kernel Fusion、Triton', 'ai-perf-engineering:10:90', 'cuBLASLt/Tile Kernel 策略', 'cuBLASLt/Tile Kernel 策略：减少 Python 调度与 Dispatcher 时间，同时保留 Tensor Core 优势；对比 cuBLASLt、cutlass 2.x Tile Kernel 与 cutlass 3.x/CuTe 的执行范围、约束条件与实测边界，检查 TF32/BF16/FP16、M/N/K 与 L2/MMA Sync 特性。', 'MEDIUM', 2, 90),
('ai-perf-engineering', 10, '第 10 章 GPU 性能分析方法与 Kernel Fusion、Triton', 'ai-perf-engineering:10:91', 'Triton 入门结构', 'Triton 入门结构：@triton.jit Kernel 用 tl.load/tl.store 操作 Tile，pid = tl.program_id(axis=0) 索引程序块，通过 num_warps、BLOCK 大小控制并行与占用率；它不解决全局架构瓶颈，但能把调度空隙转成低控制开销的常驻或融合任务。', 'EASY', 2, 91),
('ai-perf-engineering', 10, '第 10 章 GPU 性能分析方法与 Kernel Fusion、Triton', 'ai-perf-engineering:10:92', 'Persistent Kernel 风险', 'Persistent Kernel 风险：Persistent Kernel 让一个 Kernel 常驻处理多批工作，减少 Launch 与同步，但容易造成占用率不均、与 Temporal 推理服务的资源竞争；仅在 Nsight/手工计数证明小 Kernel 调度损失占比足够高时使用。', 'MEDIUM', 2, 92),
('ai-perf-engineering', 10, '第 10 章 GPU 性能分析方法与 Kernel Fusion、Triton', 'ai-perf-engineering:10:93', 'AI Workbench 实验口径', 'AI Workbench 实验口径：训练态报告 Tokens/s、显存、MFU、Step Time；编译态报告 Stable Step、Cold Start、Compile Time、Step P50/P95/P99、编译后回归保护；推理态报告 Tokens/s、RPS、TTFT、TPOT、Batch、Queue/OOM/P99 与 P/D Worker 分配；跨 Run 汇总只能作为相对基线的参考，不能替代峰值能力。', 'MEDIUM', 2, 93),
('ai-perf-engineering', 11, '第 11 章 大模型分布式训练体系：DP/TP/PP/ZeRO/EP', 'ai-perf-engineering:11:94', '并行分类', '并行分类：数据并行（Data Parallel，复制模型切样本）、算子/序列并行（Operator/Sequence）、张量并行（Tensor Parallel，层内切分）、流水并行（Pipeline Parallel，按层切分）、专家并行（Expert Parallel）；混合并行常为 DP × TP × PP。', 'MEDIUM', 2, 94),
('ai-perf-engineering', 11, '第 11 章 大模型分布式训练体系：DP/TP/PP/ZeRO/EP', 'ai-perf-engineering:11:95', 'DDP 通信量', 'DDP 通信量：Ring AllReduce 每步通信量约 2(N−1)/N × S（S 为梯度总字节），与卡数近似无关；梯度按桶（bucket）组织并与反向计算重叠，PyTorch DDP 默认 bucket_cap_mb=25，gradient_as_bucket_view=True 减少一次拷贝。', 'MEDIUM', 2, 95),
('ai-perf-engineering', 11, '第 11 章 大模型分布式训练体系：DP/TP/PP/ZeRO/EP', 'ai-perf-engineering:11:96', 'DP 显存公式', 'DP 显存公式：16P 来自 FP16 参数 2P + FP16 梯度 2P + FP32 Master 参数 4P + Adam 动量 4P + 方差 4P = 16P；常见 DDP 优化还有关闭冗余梯度同步、bf16 主副本、分片 Optimizer。', 'MEDIUM', 2, 96),
('ai-perf-engineering', 11, '第 11 章 大模型分布式训练体系：DP/TP/PP/ZeRO/EP', 'ai-perf-engineering:11:97', 'ZeRO 三阶段公式', 'ZeRO 三阶段公式：ZeRO1 M≈4P_local+12P_local/D（分片优化器状态）、ZeRO2 M≈2P_local+14P_local/D（再分片梯度）、ZeRO3 M≈16P_local/D（再分片参数）；注意 P_local 在逐步推导中等价于 P/N，不要混用总参数量与单卡参数量。', 'MEDIUM', 2, 97),
('ai-perf-engineering', 11, '第 11 章 大模型分布式训练体系：DP/TP/PP/ZeRO/EP', 'ai-perf-engineering:11:98', 'TP 原理', 'TP 原理：列并行把权重矩阵按列切成 [K, N/n]，行并行按行切成 [K/n, N]，两层配合后只在后做 All-Reduce；通信次数固定为两次，但消息粒度小、对带宽敏感，每层都引入同步点。', 'MEDIUM', 2, 98),
('ai-perf-engineering', 11, '第 11 章 大模型分布式训练体系：DP/TP/PP/ZeRO/EP', 'ai-perf-engineering:11:99', 'PP 气泡', 'PP 气泡：朴素 GPipe 的 Bubble Ratio = (p−1)/(m+p−1)；1F1B 把峰值激活从 O(p) 降到 O(m)，Interleaved 1F1B 进一步把气泡降到约 (p−1)/(m×v)；代价是通信次数增加与实现复杂。', 'MEDIUM', 2, 99),
('ai-perf-engineering', 11, '第 11 章 大模型分布式训练体系：DP/TP/PP/ZeRO/EP', 'ai-perf-engineering:11:100', 'EP 通信', 'EP 通信：All-to-All 把 Token Dispatch 到各 Expert 所在卡，再 Combine 回来；平均消息量相同时最忙 Rank 决定尾延迟，负载不均会直接放大尾延迟，因此需要 Capacity Factor、Token Drop 或 Aux Loss 平衡。', 'MEDIUM', 2, 100),
('ai-perf-engineering', 11, '第 11 章 大模型分布式训练体系：DP/TP/PP/ZeRO/EP', 'ai-perf-engineering:11:101', '并行选择稳健顺序', '并行选择稳健顺序：①单卡能放下先 DDP → ②模型状态 OOM 试激活重计算/混合精度/FSDP → ③单层放不下才 TP → ④层数多跨节点 PP → ⑤超长上下文 CP/SP → ⑥MoE 专家 EP → ⑦最后按拓扑重排 rank、调重叠/Bucket/微批次。', 'MEDIUM', 2, 101),
('ai-perf-engineering', 11, '第 11 章 大模型分布式训练体系：DP/TP/PP/ZeRO/EP', 'ai-perf-engineering:11:102', '通信与计算重叠', '通信与计算重叠：目标公式 T_step = T_c + T_m − T_h + T_other，让隐藏时间 T_h 尽量接近通信时间 T_m；手段包括 RS 与反向重叠、下一层参数 AG 与当前层计算预取、梯度分桶排序。', 'MEDIUM', 2, 102),
('ai-perf-engineering', 11, '第 11 章 大模型分布式训练体系：DP/TP/PP/ZeRO/EP', 'ai-perf-engineering:11:103', '恒等关系', '恒等关系：AllReduce = ReduceScatter + AllGather，这是 FSDP 使用分片 Collective 的原因；Ring AllReduce 每 rank 上传下载各 (N−1)/N·S，总线上行/下行各约 (N−1)/N·S。', 'MEDIUM', 2, 103),
('ai-perf-engineering', 11, '第 11 章 大模型分布式训练体系：DP/TP/PP/ZeRO/EP', 'ai-perf-engineering:11:104', 'DeepSpeed ZeRO 配置', 'DeepSpeed ZeRO 配置：zero_optimization.stage=1/2/3、offload_optimizer、zero_force_ds_cpu_adam；运行前用 deepspeed estimate_memory_usage 估算激活+参数+CUDA/MPI 缓冲，未开启异步参数聚合时所有设备需累加完整副本。', 'MEDIUM', 2, 104),
('ai-perf-engineering', 12, '第 12 章 NCCL 深度优化与 GPU 通信性能优化', 'ai-perf-engineering:12:105', 'Ring AllReduce 公式', 'Ring AllReduce 公式：带宽项耗时 t_comm = 2(N−1)/N × S/BW，N 越大通信效率越接近 1；Busbw = Algbw × 2(N−1)/N，报告时必须区分 algbw 与 busbw 口径。', 'MEDIUM', 2, 105),
('ai-perf-engineering', 12, '第 12 章 NCCL 深度优化与 GPU 通信性能优化', 'ai-perf-engineering:12:106', 'NCCL 调优实验方法', 'NCCL 调优实验方法：用 NCCL_ALGO=Ring/Tree/NVLS/CollNet 与 NCCL_PROTO=Simple/LL/LL128 做 A/B，每次只改一个变量并保留完整命令、拓扑、消息大小、带宽、总线带宽和正确性摘要。', 'MEDIUM', 2, 106),
('ai-perf-engineering', 12, '第 12 章 NCCL 深度优化与 GPU 通信性能优化', 'ai-perf-engineering:12:107', '环境变量清单', '环境变量清单：NCCL_DEBUG=INFO/WARN、NCCL_SOCKET_IFNAME、NCCL_IB_HCA、NCCL_NET_GDR_LEVEL、NCCL_P2P_LEVEL、NCCL_SHM_DISABLE、NCCL_CUMEM_ENABLE、NCCL_BUFFSIZE 是排查第一步；先收集 nvidia-smi topo -m 与 NCCL flight recorder 再调参。', 'MEDIUM', 2, 107),
('ai-perf-engineering', 12, '第 12 章 NCCL 深度优化与 GPU 通信性能优化', 'ai-perf-engineering:12:108', '跨节点 vs 节点内', '跨节点 vs 节点内：NCCL 的 Bus Factor 与环构建逻辑依赖拓扑，NVLink 域内优先走 NV#，跨机走 IB/RoCE；同一算法在不同拓扑下可能选出不同路径，不能拿节点内 microbenchmark 外推多机。', 'MEDIUM', 2, 108),
('ai-perf-engineering', 12, '第 12 章 NCCL 深度优化与 GPU 通信性能优化', 'ai-perf-engineering:12:109', '小消息与大消息', '小消息与大消息：小消息受延迟与协议开销支配（LL/LL128 有优势），大消息受带宽支配（Simple 常占优）；最优算法与消息大小强相关，报告必须注明 size 区间。', 'MEDIUM', 2, 109),
('ai-perf-engineering', 12, '第 12 章 NCCL 深度优化与 GPU 通信性能优化', 'ai-perf-engineering:12:110', '通信内核融合', '通信内核融合：把 Scale/Add/Cast 融进 ReduceScatter/AllGather 可减少 Kernel 启动与额外 HBM 往返；判断收益前先确认原实现确实存在逐元素操作且其耗时占比足够大。', 'MEDIUM', 2, 110),
('ai-perf-engineering', 12, '第 12 章 NCCL 深度优化与 GPU 通信性能优化', 'ai-perf-engineering:12:111', '网络观测指标', '网络观测指标：只看 NIC 端口计数器（tx/rx bytes、errors）无法区分 RDMA 与 TCP；还需 RoCE 的 PFC pause 帧、ECN 标记、CNP、retransmit、out-of-sequence、QP state 与 GPUDirect RDMA 是否真正启用。', 'MEDIUM', 2, 111),
('ai-perf-engineering', 12, '第 12 章 NCCL 深度优化与 GPU 通信性能优化', 'ai-perf-engineering:12:112', 'QoS 反直觉现象', 'QoS 反直觉现象：关闭 PFC 的 RoCE 在高突发流量下可能比有 PFC 更高 P99，因为 PFC 反压会把拥塞向上游传播；应记录两种配置的 Goodput 与尾延迟而非只看平均带宽。', 'MEDIUM', 2, 112),
('ai-perf-engineering', 12, '第 12 章 NCCL 深度优化与 GPU 通信性能优化', 'ai-perf-engineering:12:113', '通信优化验收', '通信优化验收：任何 NCCL 改动都要在相同 world size/拓扑/消息分布下验证 allreduce 结果一致，并比较 Busbw 提升与端到端 step time 缩短是否一致；只有 busbw 提升而 step time 不变说明瓶颈不在该通信。', 'MEDIUM', 2, 113),
('ai-perf-engineering', 12, '第 12 章 NCCL 深度优化与 GPU 通信性能优化', 'ai-perf-engineering:12:114', '算力与通信解耦趋势', '算力与通信解耦趋势：H 系列相对 A 系列的算力增长远快于 NVLink 带宽增长，导致计算/通信比变差，PPO/Actor-Critic 等同步点更容易被通信拖慢；选并行策略时必须用实测 busbw 而非标称值。', 'MEDIUM', 2, 114),
('ai-perf-engineering', 13, '第 13 章 FSDP 与超大模型训练优化', 'ai-perf-engineering:13:115', 'FSDP 本质', 'FSDP 本质：把参数、梯度、优化器状态都切片到不同 rank，计算某层前 All-Gather 临时拼回完整参数，算完释放只留分片；反向得完整梯度后 Reduce-Scatter 只留本 rank 梯度片——用更频繁的参数通信换显存容量。', 'MEDIUM', 2, 115),
('ai-perf-engineering', 13, '第 13 章 FSDP 与超大模型训练优化', 'ai-perf-engineering:13:116', '常驻与峰值公式', '常驻与峰值公式：M_sharded ≈ M_state/N，但 M_peak ≈ M_state/N + M_active_group + M_prefetch + M_act + M_comm + M_fragment；激活、临时张量和当前计算层完整参数不会被除以 N，这是“分片后仍 OOM”的根源。', 'MEDIUM', 2, 116),
('ai-perf-engineering', 13, '第 13 章 FSDP 与超大模型训练优化', 'ai-perf-engineering:13:117', '一次 FSDP 迭代通信', '一次 FSDP 迭代通信：以 Transformer Block 为分片组、reshard_after_forward=True 时为 2 次 All-Gather + 1 次 Reduce-Scatter，V_FSDP ≈ 3·(N−1)/N · P·b_comm；前向后立即 Reshard 峰值低但通信高，保留完整参数则相反。', 'MEDIUM', 2, 117),
('ai-perf-engineering', 13, '第 13 章 FSDP 与超大模型训练优化', 'ai-perf-engineering:13:118', 'FSDP1 vs FSDP2', 'FSDP1 vs FSDP2：FSDP2 把通信分组显式化，每次 fully_shard 对应一个通信组；只包根模块会形成巨大组、几乎没有层间重叠空间，Bottom-up 逐层调用才能形成逐层参数组。', 'MEDIUM', 2, 118),
('ai-perf-engineering', 13, '第 13 章 FSDP 与超大模型训练优化', 'ai-perf-engineering:13:119', '混合精度策略', '混合精度策略：MixedPrecisionPolicy 分别控制参数与梯度归约 dtype；常见做法是常驻分片参数与优化器状态 FP32、AG 后计算参数 BF16、RS 用 BF16 减通信或 FP32 保稳定。', 'MEDIUM', 2, 119),
('ai-perf-engineering', 13, '第 13 章 FSDP 与超大模型训练优化', 'ai-perf-engineering:13:120', 'CPU Offload', 'CPU Offload：能救 OOM 但 PCIe 传输与 CPU optimizer step 显著降吞吐；检查 CPU 内存总量、锁页内存、GPU 是否等 H2D/D2H、NUMA 绑定；双 3080 优先级为 BF16 → FSDP2 → 激活重计算 → 调小 micro-batch → 最后才 Offload。', 'MEDIUM', 2, 120),
('ai-perf-engineering', 13, '第 13 章 FSDP 与超大模型训练优化', 'ai-perf-engineering:13:121', 'Distributed Checkpoint', 'Distributed Checkpoint：不要 rank 0 聚合完整模型再 save（OOM/停顿），使用分片 state dict 保存并支持跨 world size 重分片；Checkpoint 需单独压测保存时长、恢复时长、峰值 CPU 内存与训练暂停，能保存≠能在故障窗口内恢复。', 'MEDIUM', 2, 121),
('ai-perf-engineering', 13, '第 13 章 FSDP 与超大模型训练优化', 'ai-perf-engineering:13:122', '四组验收指标', '四组验收指标：容量（peak allocated/reserved、OOM 点）、速度（step time、tokens/s）、通信（AG/RS 时长、暴露尾部）、正确性（loss、梯度范数、恢复验证）；最小实验法为 DDP 基线 → FSDP2 只改并行 → 按 Block 分组 → 再分别加 BF16/Checkpoint/累积/Offload，每次只改一个变量。', 'MEDIUM', 2, 122),
('ai-perf-engineering', 13, '第 13 章 FSDP 与超大模型训练优化', 'ai-perf-engineering:13:123', 'FSDP 仍 OOM 排查顺序', 'FSDP 仍 OOM 排查顺序：初始化整模先落卡、只包根模块、最大 Block 本身超显存、激活更大、预取保留多组、累积期间留完整参数；对照逐项消除而不是同时调多个开关。', 'MEDIUM', 2, 123),
('ai-perf-engineering', 13, '第 13 章 FSDP 与超大模型训练优化', 'ai-perf-engineering:13:124', '模型能否放单卡的判据', '模型能否放单卡的判据：若 16P/D + 激活 + 通信缓冲仍大于单卡可用显存，再考虑 TP/PP；不要一上来就 FSDP，模型太小时 FSDP 通信开销可能反而比 DDP 慢。', 'MEDIUM', 2, 124),
('ai-perf-engineering', 14, '第 14 章 PyTorch 性能分析体系', 'ai-perf-engineering:14:125', 'Profiler 三段数据', 'Profiler 三段数据：Host 侧 CPU op/aten 算子耗时、CUDA 侧 Kernel 耗时、联系两者的 Correlate Events；只看 CPU 时间会误判 GPU 已异步执行的算子，只看 Kernel 时间会漏掉 launch gap 与数据加载。', 'MEDIUM', 2, 125),
('ai-perf-engineering', 14, '第 14 章 PyTorch 性能分析体系', 'ai-perf-engineering:14:126', '典型采集代码', '典型采集代码：torch.profiler.profile(activities=[ProfilerActivity.CPU, ProfilerActivity.CUDA], schedule=torch.profiler.schedule(wait=1, warmup=3, active=5), on_trace_ready=torch.profiler.tensorboard_trace_handler(''./log''), record_shapes=True, with_stack=True)，配 torch.autograd.profiler.emit_nvtx() 可把 aten 算子映射到 Nsight 时间线。', 'MEDIUM', 2, 126),
('ai-perf-engineering', 14, '第 14 章 PyTorch 性能分析体系', 'ai-perf-engineering:14:127', '关键输出表', '关键输出表：key_averages() 给 Self CUDA Total / Self CPU Total / # Calls；chrome://tracing 或 TensorBoard 看时间线；with_flops=True 可统计 FLOPs 用于核对 MFU。', 'MEDIUM', 2, 127),
('ai-perf-engineering', 14, '第 14 章 PyTorch 性能分析体系', 'ai-perf-engineering:14:128', '瓶颈判读顺序', '瓶颈判读顺序：先看 Data Loading Gap（GPU idle 等 batch）、再看 Launch Overhead（大量短 Kernel 与 cudaLaunchKernel 密集）、然后看大 Kernel 的 NCU 指标、最后看通信与同步（NCCL Kernel 占比与等待）。', 'MEDIUM', 2, 128),
('ai-perf-engineering', 14, '第 14 章 PyTorch 性能分析体系', 'ai-perf-engineering:14:129', 'PyTorch Profiler 实验口径', 'PyTorch Profiler 实验口径：单卡 GPT-2 训练循环，对比 torch.backends.cudnn.benchmark、DataLoader worker/pin_memory、AMP、set_to_none、梯度累积；报告必须包含 CPU/GPU 时间分解、最慢 Top-K 算子、MFU 与 tokens/s 随配置变化曲线。', 'MEDIUM', 2, 129),
('ai-perf-engineering', 14, '第 14 章 PyTorch 性能分析体系', 'ai-perf-engineering:14:130', '算子级优化常识', '算子级优化常识：避免在循环里创建临时 Tensor、尽量用 torch.no_grad()/inference_mode()、合并小算子、用 nn.functional 替代逐元素 Python 运算、避免 item()/.cpu() 造成的隐式同步。', 'MEDIUM', 2, 130),
('ai-perf-engineering', 14, '第 14 章 PyTorch 性能分析体系', 'ai-perf-engineering:14:131', '内存分析', '内存分析：torch.cuda.memory_summary() 与 memory_snapshot() 定位 allocator 碎片；峰值不等于常驻，降低峰值可通过梯度检查点、及时释放中间变量、复用 buffer。', 'MEDIUM', 2, 131),
('ai-perf-engineering', 14, '第 14 章 PyTorch 性能分析体系', 'ai-perf-engineering:14:132', '分布式场景', '分布式场景： profiler 只在 rank0 采集会漏掉其它 rank 的通信等待；应在所有 rank 开启并用 torch.distributed.barrier() 对齐起止，导出时按 rank 命名文件。', 'MEDIUM', 2, 132),
('ai-perf-engineering', 15, '第 15 章 torch.compile、CUDA Graph 与 AI Runtime', 'ai-perf-engineering:15:133', 'torch.compile 三层架构', 'torch.compile 三层架构：TorchDynamo 捕获 Python 字节码并生成 FX Graph，AOTAutograd 生成前向/反向图并处理 autograd，TorchInductor 做图级调度、算子融合并生成 Triton/C++ 代码；三段都可能成为编译时间与运行时间瓶颈。', 'MEDIUM', 2, 133),
('ai-perf-engineering', 15, '第 15 章 torch.compile、CUDA Graph 与 AI Runtime', 'ai-perf-engineering:15:134', '编译收益上限', '编译收益上限：设原执行时间 T_c、编译后 T_e、编译耗时 T_s，则 N* = T_s/(T_e−T_s)；当 N < N* 时重编译开销大于收益。例：编译 30s、单步由 600ms 降至 300ms，则 N* = 30/0.3 = 100 步才回本，因此必须静态形状与 warmup。', 'MEDIUM', 2, 134),
('ai-perf-engineering', 15, '第 15 章 torch.compile、CUDA Graph 与 AI Runtime', 'ai-perf-engineering:15:135', 'Graph Break 代价', 'Graph Break 代价：一个动态控制流/data-dependent 分支可能把大图切成两段，中间退回 eager；用 torch._dynamo.explain()/TORCH_LOGS=recompiles 定位，减少动态 shape 与 .item()、打印、外部函数调用。', 'MEDIUM', 2, 135),
('ai-perf-engineering', 15, '第 15 章 torch.compile、CUDA Graph 与 AI Runtime', 'ai-perf-engineering:15:136', '三种 mode', '三种 mode：default（只做基本图优化）、reduce-overhead（启用 CUDA Graph，适合 Kernel launch 受限的小步长训练/推理）、max-autotune（自动搜索 matmul/conv 模板，编译时间长）；生产建议从 default 起步，收益不够再用 reduce-overhead。', 'MEDIUM', 2, 136),
('ai-perf-engineering', 15, '第 15 章 torch.compile、CUDA Graph 与 AI Runtime', 'ai-perf-engineering:15:137', 'CUDA Graph 原理', 'CUDA Graph 原理：Stream Capture 记录一段 GPU 操作生成图，实例化后一次 cudaGraphLaunch 提交，把多次 cudaLaunchKernel 的 CPU 开销从微秒降到亚微秒；要求输入输出地址稳定（静态 buffer）并使用 graph 私有内存池。', 'MEDIUM', 2, 137),
('ai-perf-engineering', 15, '第 15 章 torch.compile、CUDA Graph 与 AI Runtime', 'ai-perf-engineering:15:138', 'CUDA Graph 适用边界', 'CUDA Graph 适用边界：只适合计算图结构固定的片段；遇到动态形状、CPU 逻辑分支、随机数状态变化需重新捕获或使用 Graph 更新 API；捕获期间不能有 CPU 同步。', 'MEDIUM', 2, 138),
('ai-perf-engineering', 15, '第 15 章 torch.compile、CUDA Graph 与 AI Runtime', 'ai-perf-engineering:15:139', 'AI Runtime 设计目标', 'AI Runtime 设计目标：面向多实例、多任务共享 GPU，提供隔离、优先级、抢占和可观测性；核心抽象包括实例（Instance）、队列（Queue）、内存（Memory）、Kernel/图执行与事件，用 Stream 表达 DAG 并用 Event 表达依赖。', 'MEDIUM', 2, 139),
('ai-perf-engineering', 15, '第 15 章 torch.compile、CUDA Graph 与 AI Runtime', 'ai-perf-engineering:15:140', '多实例隔离', '多实例隔离：MIG 提供硬件级分区（SM/显存/L2 切片），Time Slicing 提供时间片轮转；前者适合强隔离与配额保障，后者适合可空间复用任务，两者都不等于“每任务独占整卡”。', 'MEDIUM', 2, 140),
('ai-perf-engineering', 15, '第 15 章 torch.compile、CUDA Graph 与 AI Runtime', 'ai-perf-engineering:15:141', '编译与 Runtime 联合验收', '编译与 Runtime 联合验收：报告 compile 前后 step P50/P95/P99、compile 时长、冷启动 token 延迟、重复运行方差；在 TensorRT-LLM 类引擎中比较 Engine Build、Context/Loop 延迟、Batch/Graph capture 差异，不能只用首次推理结果代表性能。', 'MEDIUM', 2, 141),
('ai-perf-engineering', 16, '第 16 章 LLM 推理系统架构与 Continuous Batching', 'ai-perf-engineering:16:142', '请求全链路', '请求全链路：Gateway → Tokenizer → Admission Controller → Scheduler → Model Executor（Prefill/Decode）→ Sampler → Detokenizer → 流式返回；API Server 管协议、Scheduler 管时间、KV Manager 管空间、Executor 管计算，不能把所有职责塞进一个同步 Python 循环。', 'MEDIUM', 2, 142),
('ai-perf-engineering', 16, '第 16 章 LLM 推理系统架构与 Continuous Batching', 'ai-perf-engineering:16:143', 'Prefill 与 Decode 差异', 'Prefill 与 Decode 差异：Prefill 一次处理整段 Prompt，计算密集（Compute-bound），指标是 Prompt Tokens/s 与 TTFT；Decode 每步只生成一个 Token，受限于 KV Cache 读带宽（Memory-bound），指标是 TPOT/ITL 与 Generation Tokens/s。', 'MEDIUM', 2, 143),
('ai-perf-engineering', 16, '第 16 章 LLM 推理系统架构与 Continuous Batching', 'ai-perf-engineering:16:144', '延迟公式', '延迟公式：T_TTFT = T_gateway + T_tokenize + T_queue + T_schedule + T_prefill + T_sample + T_stream；T_E2E ≈ T_TTFT + (N_out−1) × TPOT；平均 TPOT 掩盖停顿，在线服务应报 ITL 的 P50/P95/P99。', 'MEDIUM', 2, 144),
('ai-perf-engineering', 16, '第 16 章 LLM 推理系统架构与 Continuous Batching', 'ai-perf-engineering:16:145', '静态 Batch 浪费示例', '静态 Batch 浪费示例：4 个请求输出 8/16/32/64 Token，有效槽位 120，静态分配 4×64=256，效率仅 46.9%；Continuous Batching 不减少每个有效 Token 的计算，但减少凑批等待、最长序列空槽、队头阻塞、取消后无效 Decode 与低负载 Padding。', 'MEDIUM', 2, 145),
('ai-perf-engineering', 16, '第 16 章 LLM 推理系统架构与 Continuous Batching', 'ai-perf-engineering:16:146', '连续批处理调度', '连续批处理调度：iteration-level scheduling 让新请求在任何解码迭代后插入，长请求不再拖住短请求；代价是需要更复杂的 KV 管理与抢占（Preemption）策略。', 'MEDIUM', 2, 146),
('ai-perf-engineering', 16, '第 16 章 LLM 推理系统架构与 Continuous Batching', 'ai-perf-engineering:16:147', 'Chunked Prefill', 'Chunked Prefill：C_i = min(PromptRemaining_i, BudgetRemaining)，把大 Prompt 切成若干 Chunk 与 Decode 共存于相邻周期，控制 ITL 尖峰；代价是更多迭代、小 Chunk GEMM 效率下降、TTFT 可能增加，Chunk Size 是 TTFT/ITL/吞吐之间的旋钮，无跨硬件通用最优值。', 'MEDIUM', 2, 147),
('ai-perf-engineering', 16, '第 16 章 LLM 推理系统架构与 Continuous Batching', 'ai-perf-engineering:16:148', '优先级冲突诊断', '优先级冲突诊断：TTFT 高而 ITL 正常多为 Decode 过度优先或 Token Budget 太小；TTFT 正常而 ITL 尖峰多为 Prefill 未切片；GPU 低利用率队列有请求指向 Scheduler/Tokenizer 慢；GPU 高利用率但 Goodput 低指向并发过高无背压；KV 满频繁抢占指向 max_num_seqs 过高或长上下文混跑。', 'MEDIUM', 2, 148),
('ai-perf-engineering', 16, '第 16 章 LLM 推理系统架构与 Continuous Batching', 'ai-perf-engineering:16:149', '容量按在途 Token 规划', '容量按在途 Token 规划：以 vLLM/SGLang 的 max_num_batched_tokens、max_num_seqs、gpu_memory_utilization、watermark 共同约束在途 Token 总数；单请求输出长度上限由预留块决定，多轮对话与 Embedding/Rerank 共享池时必须单独压测。', 'MEDIUM', 2, 149),
('ai-perf-engineering', 16, '第 16 章 LLM 推理系统架构与 Continuous Batching', 'ai-perf-engineering:16:150', 'DP vs TP 部署选择', 'DP vs TP 部署选择：模型能放入单卡时，双 3080 上两个副本做 DP 通常比跨 PCIe 的 TP 更适合作为吞吐基线；TP 适合单卡放不下的模型，无 NVLink 时 Decode 小粒度 All-Reduce 会显著伤害 TPOT。', 'MEDIUM', 2, 150),
('ai-perf-engineering', 16, '第 16 章 LLM 推理系统架构与 Continuous Batching', 'ai-perf-engineering:16:151', '推理侧并行度', '推理侧并行度：TP 度数应与 KV Head 数、GQA/MQA 组数匹配；张量并行与流水并行都会引入 All-Reduce/点对点通信，PP 在 Decode 阶段气泡明显，一般只在模型过大时使用。', 'MEDIUM', 2, 151),
('ai-perf-engineering', 16, '第 16 章 LLM 推理系统架构与 Continuous Batching', 'ai-perf-engineering:16:152', '诊断三步', '诊断三步：①固定模型/精度/长度分布/Sampling，分开测单请求、固定并发和开环到达率；②记录阶段级指标（Queue Time、TTFT、每个 ITL）；③GPU 因 CPU/通信/显存不足而空闲时下钻 Nsight。开环压测才能看到队列崩溃点，闭环客户端会自动降速掩盖过载。', 'MEDIUM', 2, 152),
('ai-perf-engineering', 17, '第 17 章 KV Cache 优化与 PagedAttention', 'ai-perf-engineering:17:153', '容量公式', '容量公式：M_total ≈ 2（K/V）× N_layer × N_KV_head × D_head × MaxSeqLen × B_dtype 字节；合并 K/V 与 MQA/GQA 配置后 N_KV_head 会远小于 N_head，必须以实际配置重新推导。', 'MEDIUM', 2, 153),
('ai-perf-engineering', 17, '第 17 章 KV Cache 优化与 PagedAttention', 'ai-perf-engineering:17:154', '具体数字锚点', '具体数字锚点：按 32 层、8 个 KV head、head_dim=128、BF16、单条 4096 token 计算，M_token = 128 KiB/token，总 KV = 512 MiB/request；若保持 32 个 4096-token 请求则在途 KV 约 16 GiB，占 24GB 卡的 66.7%——这就是并发上限的算术来源。', 'MEDIUM', 2, 154),
('ai-perf-engineering', 17, '第 17 章 KV Cache 优化与 PagedAttention', 'ai-perf-engineering:17:155', 'KV Cache 边界', 'KV Cache 边界：保留全部历史会 O(N²) 增长，丢弃会造成重复计算；常见折中包括 Sliding Window（仅保留窗口内）、Token Eviction（按 Attention 分数/累计权重淘汰）、量化 KV（KV8/KV4，误差受边界、稀疏注意力与算子实现影响）。', 'MEDIUM', 2, 155),
('ai-perf-engineering', 17, '第 17 章 KV Cache 优化与 PagedAttention', 'ai-perf-engineering:17:156', 'PagedAttention 核心', 'PagedAttention 核心：把 KV 切成固定大小物理块（如 16 token/块），用 Block Table 维护逻辑块到物理块的映射；按需分配、前缀可共享、接近零内部碎片，显著降低传统连续缓存的预留浪费与外部碎片。', 'MEDIUM', 2, 156),
('ai-perf-engineering', 17, '第 17 章 KV Cache 优化与 PagedAttention', 'ai-perf-engineering:17:157', 'vLLM 收益', 'vLLM 收益：PagedAttention 让相同 GPU 下并发批大小提升数倍，吞吐随之上升；它主要提高“可容纳的请求数/有效并发”，不会凭空消除长上下文的 KV 读取带宽，也不会自动修复 Prefill 拥塞或 Prefix Cache 未命中。', 'MEDIUM', 2, 157),
('ai-perf-engineering', 17, '第 17 章 KV Cache 优化与 PagedAttention', 'ai-perf-engineering:17:158', 'SGLang RadixAttention', 'SGLang RadixAttention：把请求前缀组织成 Radix Tree，自动复用公共前缀（System Prompt/Few-shot/多轮上下文），命中前缀避免重复 Prefill；模板微改、Tokenizer 变化或 Adapter 切换都可能让命中率骤降，需单独监控 hit rate。', 'MEDIUM', 2, 158),
('ai-perf-engineering', 17, '第 17 章 KV Cache 优化与 PagedAttention', 'ai-perf-engineering:17:159', 'Prefix Cache 判据', 'Prefix Cache 判据：命中率高但收益低往往说明命中太短、Hash/调度成本占比高；命中异常低先查 Template/Tokenizer/Adapter 是否一致，再看调度策略是否把同前缀请求打散。', 'MEDIUM', 2, 159),
('ai-perf-engineering', 17, '第 17 章 KV Cache 优化与 PagedAttention', 'ai-perf-engineering:17:160', '量化 KV 实操', '量化 KV 实操：KV8 令容量与读取字节约减半，但取决于 Kernel 原生支持、Scale 粒度、量化/反量化成本、HBM 是否真是瓶颈与长上下文质量；CLI 接受 --kv-cache-dtype fp8 不等于当前 GPU 走高效原生路径。', 'MEDIUM', 2, 160),
('ai-perf-engineering', 17, '第 17 章 KV Cache 优化与 PagedAttention', 'ai-perf-engineering:17:161', '显存水位管理', '显存水位管理：gpu_memory_utilization 抬高会增加预留，Watermark 过低会在高并发时触发抢占；典型故障链为并发上升 OOM（容量漏项/Watermark 太高）→ TPOT 随上下文增长（KV 读取受带宽限制）→ TTFT 波动（Cache Thrash）。', 'MEDIUM', 2, 161),
('ai-perf-engineering', 17, '第 17 章 KV Cache 优化与 PagedAttention', 'ai-perf-engineering:17:162', '取消与引用泄漏', '取消与引用泄漏：请求被取消后 KV 必须立即释放，否则表现为“KV 明明有空闲却申请失败”；实现上要区分连续预留与外部碎片，并在取消路径传播引用计数。', 'MEDIUM', 2, 162),
('ai-perf-engineering', 17, '第 17 章 KV Cache 优化与 PagedAttention', 'ai-perf-engineering:17:163', '实验六验收', '实验六验收：运行 vLLM 并开启 PagedAttention/Prefix Caching，对比 max_num_seqs、gpu_memory_utilization 对吞吐、TPOT、P99 与 KV 命中率的影响；报告须包含 KV 容量估算与实测占用两条曲线。', 'MEDIUM', 2, 163),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:164', '投机解码原理', '投机解码原理：草稿模型一次生成 K 个候选 Token，目标模型一次前向并行验证；接受前缀后直接提交多个 Token，用一次大模型计算换多轮采样，理想情况下显著降低 Decode 延迟。', 'MEDIUM', 2, 164),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:165', '收益上限', '收益上限：草稿器再准但太慢也不会加速；K 增大同时增加潜在提交数与草稿/验证成本；大 Batch 下目标 GPU 已饱和，t_V(K) 接近线性增长，收益消失——投机解码适合低/中 QPS、小 Batch、内存带宽受限的 Decode。', 'MEDIUM', 2, 165),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:166', '诊断四步', '诊断四步：①确认基线适合（Decode 占主导、内存受限；Continuous Batching 已填满 GPU 时收益有限）；②分解一轮时间（draft/verify/sampling/rewind 加 NVTX 标记）；③画 acceptance × K 二维表（K=1/2/4/6/8，真实 prompt、不同温度/并发）；④正确性（Greedy 逐 token 相等、Sampling 分布统计、被拒绝 Token 的 KV 不得污染后续输出）。', 'MEDIUM', 2, 166),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:167', '常见失败原因', '常见失败原因：开启后变慢多为 Batch 大/草稿过重/K 过大/接受率低/CPU 调度占比高；接受率接近零多为 tokenizer/词表/chat template/模型家族/量化方式不兼容；第二张卡没收益常因草稿结果 PCIe 同步超过省下的轮次。', 'MEDIUM', 2, 167),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:168', 'PD 分离动机', 'PD 分离动机：Prefill 是计算密集的大 GEMM，Decode 是小批量高内存带宽的小 GEMM，两者对 Batch、并行度与 Kernel 的需求相反；解耦后可分别为 P/D 选择 TP 度、Batch 策略与硬件（P 可用高算力卡，D 可用大显存/高带宽卡）。', 'MEDIUM', 2, 168),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:169', '传输量公式', '传输量公式：KV_bytes = 2 × L_layers × N_heads_kv × D_head × T_tokens × B_dtype，再按 world_size 切分；例：Llama-2-7B（32 层×32 head×128 dim）在 BF16、4096 token 时约 1.0 GiB，8 路 TP 后每卡约 128 MiB。', 'MEDIUM', 2, 169),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:170', '链路带宽下限', '链路带宽下限：BW_required ≥ B_KV / (T_budget − T_setup − T_sync)；TTFT_disagg = Q_P + T_P + T_xfer + Q_D + T_first_decode，E2E = TTFT_disagg + N_out × TPOT_D，据此可判断一条链路是否满足 SLO。', 'MEDIUM', 2, 170),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:171', 'KV 传输后端选择', 'KV 传输后端选择：NVLink > GPUDirect RDMA（需 IOMMU/VFIO、pinned memory、NIC-GPU NUMA 对齐、两端口做负载均衡）> PCIe P2P 拷贝；同机双 3080 无 NVLink 时走 PCIe，PCIe 128 KiB 写+读约 8 µs，吞吐可达 GB/s 量级。', 'MEDIUM', 2, 171),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:172', '一致性硬约束', '一致性硬约束：D Worker 接管前必须校验每层 K/V 数据与有效 token 数、block 布局/dtype/head 配置、RoPE 位置与滑动窗口状态、tokenizer/权重版本/量化格式/Adapter 标识、采样与随机数状态、TP rank 与 KV shard 映射；P 与 D TP 度不同时 KV 需重分片。', 'MEDIUM', 2, 172),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:173', '故障矩阵示例', '故障矩阵示例：Ctrl 找不到实例导致提交失败（注册 TTL/反注册）、KV 迁移超时（降级本机重算或重试、隔离坏节点）、权重加载失败（保留旧权重并排空该实例）、背压饱和（拒绝新请求、上限=可迁移 KV+重算预算）、D 崩溃（通知 Ctrl 重分配并重算）、KV 地址错位（一致性校验拒绝并告警）。', 'MEDIUM', 2, 173),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:174', 'API 契约要点', 'API 契约要点：POST /v1/disagg/completions 接受 model/prompt/max_tokens/temperature 及 bootstrap 字段；响应流式 SSE 含 choices/delta/finish_reason/usage；错误对象固定为 {"error":{"code","message","type"}}，HTTP 语义为 400/401/404/409/422/429/500/503，且 503 与 409 响应头带 Retry-After。', 'MEDIUM', 2, 174),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:175', '容量规划方法', '容量规划方法：Level 0 用容量规划脚本输入模型层数/head/head_dim/dtype、TP 度、最大上下文、KV 块大小与 SLO 预算，输出最小 P/D 实例数与预估 TTFT/E2E；随后 Level 1 用 run_sweeps.sh 实测并回填误差。', 'MEDIUM', 2, 175),
('ai-perf-engineering', 18, '第 18 章 投机解码、MoE 推理与 Disaggregated Inference', 'ai-perf-engineering:18:176', 'MoE 推理要点', 'MoE 推理要点：EP 扩大后每 Rank 专家批量变小、All-to-All 占比上升；Prefill 求吞吐（连续布局、高吞吐 All-to-All），Decode 求低延迟（轻量 Dispatch、固定/掩码布局、CUDA Graph、低延迟通信），同一套 MoE Kernel 很难同时覆盖，这正是 PD 解耦与阶段专用 Runtime 的价值。', 'MEDIUM', 2, 176),
('ai-perf-engineering', 19, '第 19 章 Benchmark、成本测算与综合实践', 'ai-perf-engineering:19:177', 'Benchmark 四阶段', 'Benchmark 四阶段：准备（固定版本/精度/形状/输入分布）→ 运行（warmup 3～10 次、正式迭代 100+ 次、记录功率/频率/内存）→ 分析（均值/P50/P95/P99/MFU/峰值显存）→ 结论（区分脚本模型推导、本机观察与可推广结论）。', 'MEDIUM', 2, 177),
('ai-perf-engineering', 19, '第 19 章 Benchmark、成本测算与综合实践', 'ai-perf-engineering:19:178', '训练基准口径', '训练基准口径：报告 Tokens/s、MFU、Step Time、Peak Memory、通信占比；输入输出形状、Batch、序列长度、随机种子必须与基线一致，否则对比无效。', 'MEDIUM', 2, 178),
('ai-perf-engineering', 19, '第 19 章 Benchmark、成本测算与综合实践', 'ai-perf-engineering:19:179', '成本换算', '成本换算：GPU-hours × 单价得到训练直接成本；DeepSeek 案例为 2.788M GPU-hours × $2 ≈ $5.576M，但该数字不含研究试错、后训练、人力与机会成本，也不等于复现报价。', 'MEDIUM', 2, 179),
('ai-perf-engineering', 19, '第 19 章 Benchmark、成本测算与综合实践', 'ai-perf-engineering:19:180', '推理成本口径', '推理成本口径：区分单请求成本（元/千 token）、吞吐成本（元/百万 token）与 Goodput 成本（元/有效百万 token）；超 SLO 的请求按 Goodput 口径应计入损失，因此优化目标应是单位有效 token 成本最低。', 'MEDIUM', 2, 180),
('ai-perf-engineering', 19, '第 19 章 Benchmark、成本测算与综合实践', 'ai-perf-engineering:19:181', '容量规划实验', '容量规划实验：Level 0 脚本推算最小 P/D 实例数与 TTFT/E2E 预算，Level 1 通过 run_sweeps.sh 扫描 max_num_seqs/gpu_memory_utilization/TP 度，验证“模型能放下”不等于“SLO 能满足”。', 'MEDIUM', 2, 181),
('ai-perf-engineering', 19, '第 19 章 Benchmark、成本测算与综合实践', 'ai-perf-engineering:19:182', '项目四（7B Benchmark）要求', '项目四（7B Benchmark）要求：完整记录 7B BF16 权重约 14GB、混合精度 AdamW 静态状态约 104 GiB 的容量账；输出基准不能只报“最快一次”，需给迭代分布与尾部指标。', 'MEDIUM', 2, 182),
('ai-perf-engineering', 19, '第 19 章 Benchmark、成本测算与综合实践', 'ai-perf-engineering:19:183', '综合实验验收清单', '综合实验验收清单：操作系统、Python、框架、CUDA、驱动、GPU 与完整命令全部入档；基线与候选方案保持输入形状、随机种子、精度和正确性标准一致；不支持的 GPU 专项记为 skipped 而非伪造等价结果。', 'MEDIUM', 2, 183),
('ai-perf-engineering', 19, '第 19 章 Benchmark、成本测算与综合实践', 'ai-perf-engineering:19:184', '论文级边界', '论文级边界：不得把服务吞吐写成硬件峰值 FLOPs 利用率，也不得把只适用于特定集群/模型/会话分布的数值改写成通用上限；每个性能数字都要能回溯到原始 trace 与采集条件。', 'MEDIUM', 2, 184),
('ai-perf-engineering', 19, '第 19 章 Benchmark、成本测算与综合实践', 'ai-perf-engineering:19:185', '故障排查顺序', '故障排查顺序：先证明“测量可信”（工具链/频率/温度/warmup），再证明“输入可比”（形状/分布/精度一致），然后才谈“改动有效”（单次改动+回归），最后才讨论“可推广性”（跨卡型/跨拓扑是否仍成立）。', 'MEDIUM', 2, 185),
('ai-perf-engineering', 19, '第 19 章 Benchmark、成本测算与综合实践', 'ai-perf-engineering:19:186', '最终交付形态', '最终交付形态：性能报告应包含容量结果、架构文档、API 契约、故障矩阵、部署模板与 validation_report.md，并用 P50/P95 或项目规定的尾部指标而非单次最快结果作为结论依据。', 'MEDIUM', 2, 186)
