-- ============================================================
-- OPS-17：学习中心 / 课程知识库（OPS-17）
-- ============================================================
-- 原则：
--   1. 目录语料（course / point）运行期只读，由本迁移一次性灌入，前端不写入；
--   2. 个人掌握度按用户隔离存 study_point_progress，只记录"掌握 + 备注"这种有意义的状态；
--   3. 网络实验与 AI 性能工程实验作为同一目录下的两门课接入，不另建体系。
-- 全部语句幂等（目录行用 INSERT ... ON DUPLICATE KEY UPDATE）。

CREATE TABLE IF NOT EXISTS study_course (
  code     VARCHAR(64)  NOT NULL COMMENT '课程编码，前端路由用',
  title    VARCHAR(200) NOT NULL COMMENT '课程名',
  category VARCHAR(64)  NOT NULL COMMENT '分类：编程基础/数据库/Java/网络/AI',
  summary  VARCHAR(500) NOT NULL DEFAULT '' COMMENT '一句话简介',
  source   VARCHAR(500) NOT NULL DEFAULT '' COMMENT '原始资料出处',
  icon     VARCHAR(32)  NOT NULL DEFAULT 'book' COMMENT '前端图标键',
  sort_no  INT          NOT NULL DEFAULT 0,
  PRIMARY KEY (code),
  KEY idx_study_course_category (category, sort_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学习中心课程目录';

CREATE TABLE IF NOT EXISTS study_point (
  id            BIGINT       NOT NULL AUTO_INCREMENT,
  course_code   VARCHAR(64)  NOT NULL,
  chapter_no    INT          NOT NULL DEFAULT 0 COMMENT '章节序号，0 表示跨章专题',
  chapter_title VARCHAR(200) NOT NULL DEFAULT '',
  point_key     VARCHAR(128) NOT NULL COMMENT '课程内稳定标识，幂等键',
  title         VARCHAR(300) NOT NULL,
  body          TEXT         NOT NULL COMMENT '知识点正文（Markdown 片段）',
  difficulty    VARCHAR(16)  NOT NULL DEFAULT 'MEDIUM' COMMENT 'EASY/MEDIUM/HARD',
  exam_weight   TINYINT      NOT NULL DEFAULT 1 COMMENT '1~5，用于排序与重点标记',
  sort_no       INT          NOT NULL DEFAULT 0,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_study_point (course_code, point_key),
  KEY idx_study_point_course (course_code, chapter_no, sort_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学习中心知识点';

CREATE TABLE IF NOT EXISTS study_point_progress (
  user_id    BIGINT      NOT NULL,
  point_id   BIGINT      NOT NULL,
  mastered   TINYINT(1)  NOT NULL DEFAULT 0,
  note       VARCHAR(500) NULL COMMENT '错题/记忆点备注',
  updated_at DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id, point_id),
  KEY idx_study_progress_point (point_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学习中心个人掌握度';

-- ---------- 课程目录（语料由蒸馏后的 Markdown 生成，见 knowledge/reference/ops-knowledge-rag/课程教材知识总纲） ----------
ON DUPLICATE KEY UPDATE title=VALUES(title), category=VALUES(category), summary=VALUES(summary),
                        source=VALUES(source), icon=VALUES(icon), sort_no=VALUES(sort_no);
